def _activity_family(activity: str | None) -> str:
    if not activity:
        return ""
    a = str(activity).strip()
    return a.rsplit(".", 1)[-1]


def _session_modal_or_crash(d: u2.Device) -> bool:
    for frag in (
        "Unfortunately",
        "isn't responding",
        "is not responding",
        "has stopped",
        "Close app",
        "Fermer l",
    ):
        try:
            if d(textContains=frag).wait(timeout=0.03):
                return True
        except Exception:
            continue
    return False


def instagram_warm_session_eligible(d: u2.Device, pkg: str | None = None) -> tuple[bool, str]:
    """Skip force-stop when IG is foreground and UI looks healthy."""
    pkg = pkg or config.INSTAGRAM_PACKAGE
    try:
        if _session_modal_or_crash(d):
            return False, "modal_or_crash"
        cur = d.app_current()
        if (cur or {}).get("package", "") != pkg:
            return False, "wrong_package"
        try:
            d.window_size()
        except Exception:
            return False, "broken_ui"
        return True, "ok"
    except Exception as e:
        return False, str(e)


def invalidate_search_surface_cache(reason: str = "") -> None:
    global _LAST_SEARCH_SURFACE_OK
    _LAST_SEARCH_SURFACE_OK = False
    log("debug", "search_surface_cache_invalidated", reason=reason)


def is_lightweight_search_screen(d: u2.Device, pkg: str | None = None) -> bool:
    """
    True if IG search entry is likely active: foreground, top-band EditText, optional search tab selected.
    No XML / dump.
    """
    pkg = pkg or config.INSTAGRAM_PACKAGE
    try:
        cur = d.app_current()
        if (cur or {}).get("package", "") != pkg:
            return False
        if _session_modal_or_crash(d):
            return False
        ed = d(className="android.widget.EditText")
        if not ed.wait(timeout=0.08):
            return False
        try:
            b = ed.info["bounds"]
            _w, h = d.window_size()
            if int(b["bottom"]) > int(h * 0.38):
                return False
        except Exception:
            pass
        for suffix in _SEARCH_TAB_RID_SUFFIXES:
            try:
                sel = d(resourceIdMatches=f".*:id/{suffix}")
                if not sel.wait(timeout=0.04):
                    continue
                info = sel.info or {}
                if info.get("selected") is True:
                    return True
            except Exception:
                continue
        for rid_hint in (
            "com.instagram.android:id/action_bar_search_edit_text",
            "com.instagram.android:id/search_bar",
        ):
            try:
                if d(resourceId=rid_hint).wait(timeout=0.04):
                    return True
            except Exception:
                continue
        return True
    except Exception:
        return False


def apply_search_surface_reuse_metrics(
    d: u2.Device,
    pkg: str,
    reason: str,
    *,
    source_profile_username: str = "",
) -> bool:
    """Set perf + log search_surface_reused when EditText is ready (no nav click)."""
    global _perf
    t_ed = time.perf_counter()
    ed_reuse = _wait_search_edittext(d)
    if ed_reuse is None:
        return False
    strict_ok, strict_why = instagram_search_surface_strict_ok(
        d,
        ed_reuse,
        pkg=pkg,
        source_profile_username=source_profile_username,
    )
    if not strict_ok:
        invalidate_search_surface_cache(f"surface_reuse_strict_failed:{strict_why}")
        log(
            "info",
            "wrong_search_surface_detected",
            phase="apply_search_surface_reuse_metrics",
            detail=strict_why,
            reuse_reason=reason,
            foreground_package=_current_foreground_package(d),
            edittext_package=_edittext_package_name(ed_reuse),
        )
        return False
    _perf["search_field_ready_ms"] = (time.perf_counter() - t_ed) * 1000
    _perf["search_click_ms"] = 0.0
    _perf["search_surface_reused"] = True
    _perf["search_open_skipped_ms"] = float(
        getattr(config, "SEARCH_OPEN_SKIP_CREDIT_MS", 2800.0)
    )
    log(
        "info",
        "search_surface_reused",
        reason=reason,
        package=pkg,
        search_field_ready_ms=round(_perf["search_field_ready_ms"], 2),
        search_open_skipped_ms=_perf["search_open_skipped_ms"],
    )
    log(
        "info",
        "open_search_timing",
        search_click_ms=0.0,
        search_field_ready_ms=round(float(_perf["search_field_ready_ms"]), 2),
        selector=f"surface_reuse:{reason}",
        ok=True,
    )
    log(
        "info",
        "instagram_search_surface_verified",
        phase="apply_search_surface_reuse_metrics",
        detail=reason,
    )
    return True


def return_to_search_from_profile(d: u2.Device, pkg: str | None = None) -> bool:
    """
    One back + poll for lightweight search. Sets search_back_to_search_ms.
    On success applies search surface reuse metrics (skip open_search).
    """
    global _perf
    pkg = pkg or config.INSTAGRAM_PACKAGE
    t0 = time.perf_counter()
    try:
        d.press("back")
    except Exception as e:
        log("warning", "search_back_press_failed", error=str(e))
        _perf["search_back_to_search_ms"] = (time.perf_counter() - t0) * 1000
        return False
    deadline = time.monotonic() + float(getattr(config, "BACK_TO_SEARCH_MAX_WAIT_S", 3.0))
    while time.monotonic() < deadline:
        if is_lightweight_search_screen(d, pkg):
            _perf["search_back_to_search_ms"] = (time.perf_counter() - t0) * 1000
            log(
                "info",
                "search_back_to_search_ok",
                search_back_to_search_ms=round(_perf["search_back_to_search_ms"], 2),
            )
            return apply_search_surface_reuse_metrics(
                d, pkg, "back_from_profile", source_profile_username=""
            )
        time.sleep(0.08)
    _perf["search_back_to_search_ms"] = (time.perf_counter() - t0) * 1000
    log(
        "warning",
        "search_back_to_search_timeout",
        search_back_to_search_ms=round(_perf["search_back_to_search_ms"], 2),
    )
    return False


def should_reuse_search_surface(d: u2.Device, pkg: str) -> bool:
    if not _LAST_SEARCH_SURFACE_OK:
        return False
    if time.time() - _LAST_SEARCH_SURFACE_TS > float(
        getattr(config, "SEARCH_SURFACE_CACHE_TTL_S", 600.0)
    ):
        invalidate_search_surface_cache("ttl")
        return False
    if _LAST_SEARCH_SURFACE_PKG != pkg:
        return False
    try:
        cur = d.app_current()
        if (cur or {}).get("package", "") != pkg:
            return False
        act_f = _activity_family((cur or {}).get("activity"))
        if act_f != _LAST_SEARCH_SURFACE_ACTIVITY_FAMILY:
            return False
        if _session_modal_or_crash(d):
            return False
        ed = d(className="android.widget.EditText")
        if not ed.wait(timeout=0.12):
            return False
        return True
    except Exception:
        return False


def _mark_search_surface_ok(d: u2.Device, pkg: str) -> None:
    global _LAST_SEARCH_SURFACE_TS, _LAST_SEARCH_SURFACE_OK
    global _LAST_SEARCH_SURFACE_PKG, _LAST_SEARCH_SURFACE_ACTIVITY_FAMILY
    try:
        cur = d.app_current()
        _LAST_SEARCH_SURFACE_OK = True
        _LAST_SEARCH_SURFACE_TS = time.time()
        _LAST_SEARCH_SURFACE_PKG = pkg
        _LAST_SEARCH_SURFACE_ACTIVITY_FAMILY = _activity_family((cur or {}).get("activity"))
    except Exception:
        _LAST_SEARCH_SURFACE_OK = False


def _instagram_package_candidates(d: u2.Device) -> list[str]:
    """Packages to build full resource ids (current app + config + common variants)."""
    out: list[str] = []
    try:
        cur = d.app_current()
        p = (cur or {}).get("package", "") or ""
        if p and p not in out:
            out.append(p)
    except Exception:
        pass
    for p in (
        config.INSTAGRAM_PACKAGE,
        "com.instagram.android",
        "com.instagram.androii",
    ):
        if p and p not in out:
            out.append(p)
    return out


def _row_search_username_resource_id_list(d: u2.Device) -> list[str]:
    """Full resource-id strings for row_search_user_username."""
    ids: list[str] = []
    for pkg in _instagram_package_candidates(d):
        rid = f"{pkg}:id/{ROW_SEARCH_USER_USERNAME_RES_NAME}"
        if rid not in ids:
            ids.append(rid)
    return ids


def _clear_pending_fused_fast_ime_row() -> None:
    global _PENDING_FUSED_FAST_IME_ROW, _PENDING_FUSED_FAST_IME_USERNAME
    _PENDING_FUSED_FAST_IME_ROW = False
    _PENDING_FUSED_FAST_IME_USERNAME = ""


def _set_pending_fused_fast_ime_row(username: str) -> None:
    global _PENDING_FUSED_FAST_IME_ROW, _PENDING_FUSED_FAST_IME_USERNAME
    _PENDING_FUSED_FAST_IME_ROW = True
    _PENDING_FUSED_FAST_IME_USERNAME = username


def _peek_pending_fused_fast_ime_row(username: str) -> bool:
    return _PENDING_FUSED_FAST_IME_ROW and _PENDING_FUSED_FAST_IME_USERNAME == username


def _collect_raw_row_search_elements(
    d: u2.Device,
    *,
    trace_context: dict[str, Any] | None = None,
) -> list[tuple[object, str]]:
    """
    Ordered candidates: exact com.instagram.android:id/row_search_user_username,
    then resourceIdMatches .*/id/row_search_user_username, then per-package ids,
    then legacy .* :id pattern. No XPath/XML.
    """
    raw: list[tuple[object, str]] = []
    seen_el: set[int] = set()
    target = _normalize_handle(str((trace_context or {}).get("username") or ""))
    trace_state = (
        trace_context.get("trace_state")
        if isinstance(trace_context, dict)
        else None
    )
    if not isinstance(trace_state, dict):
        trace_state = {}
    trace_follow_ct = isinstance(trace_context, dict) and bool(trace_context.get("follow_ct"))
    expected_package = (
        str((trace_context or {}).get("expected_package") or "").strip()
        if isinstance(trace_context, dict)
        else ""
    ) or str(getattr(config, "INSTAGRAM_PACKAGE", "") or "").strip()

    def _selector_trace_enabled() -> bool:
        return isinstance(trace_context, dict) and bool(trace_context.get("follow_ct"))

    def _element_text_matches_target(el: object) -> bool:
        if not target:
            return False
        try:
            return _normalize_handle(str(el.get_text() or "")) == target
        except Exception:
            return False

    def _emit_selector_trace(
        *,
        selector_name: str,
        selector_source: str,
        started_at: float,
        candidate_count: int,
        exact_match_found: bool,
        package_name: str = "",
        used_hardcoded_android_rid: bool = False,
        used_clone_rid: bool = False,
        used_resource_id_matches: bool = False,
    ) -> None:
        if not _selector_trace_enabled():
            return
        try:
            trace_context["candidate_count"] = int(
                trace_context.get("candidate_count", 0) or 0
            ) + int(candidate_count)
            if exact_match_found:
                trace_context["exact_match_found"] = True
            first_raw_seen = bool(trace_state.get("first_raw_seen"))
            if candidate_count > 0 and not first_raw_seen:
                trace_state["first_raw_seen"] = True
                trace_state["first_raw_poll_index"] = trace_context.get("poll_index")
                log(
                    "info",
                    "ct_row_detect_first_raw_element_seen",
                    username=trace_context.get("username") or None,
                    poll_index=trace_context.get("poll_index"),
                    selector_name=selector_name,
                    selector_source=selector_source,
                    duration_ms=round((time.perf_counter() - started_at) * 1000.0, 2),
                    candidate_count=int(candidate_count),
                    exact_match_found=bool(exact_match_found),
                    fast_accept=bool(trace_context.get("fast_accept")),
                    package_name=package_name or None,
                    expected_package=trace_context.get("expected_package") or None,
                    used_hardcoded_android_rid=bool(used_hardcoded_android_rid),
                    used_clone_rid=bool(used_clone_rid),
                    used_resource_id_matches=bool(used_resource_id_matches),
                )
                first_raw_seen = True
            log(
                "info",
                "ct_row_detect_selector_completed",
                username=trace_context.get("username") or None,
                poll_index=trace_context.get("poll_index"),
                selector_name=selector_name,
                selector_source=selector_source,
                duration_ms=round((time.perf_counter() - started_at) * 1000.0, 2),
                candidate_count=int(candidate_count),
                exact_match_found=bool(exact_match_found),
                first_raw_seen=bool(first_raw_seen),
                fast_accept=bool(trace_context.get("fast_accept")),
                package_name=package_name or None,
                expected_package=trace_context.get("expected_package") or None,
                used_hardcoded_android_rid=bool(used_hardcoded_android_rid),
                used_clone_rid=bool(used_clone_rid),
                used_resource_id_matches=bool(used_resource_id_matches),
            )
        except Exception:
            pass

    def _emit_selector_short_circuit(
        *,
        selector_name: str,
        selector_source: str,
        candidate_count: int,
        exact_match_found: bool,
        saved_selector_count: int,
        saved_duration_ms_estimate: float,
    ) -> None:
        if not _selector_trace_enabled():
            return
        try:
            log(
                "info",
                "ct_row_detect_selector_short_circuited",
                username=trace_context.get("username") or None,
                poll_index=trace_context.get("poll_index"),
                selector_name=selector_name,
                selector_source=selector_source,
                candidate_count=int(candidate_count),
                exact_match_found=bool(exact_match_found),
                saved_selector_count=int(saved_selector_count),
                saved_duration_ms_estimate=round(float(saved_duration_ms_estimate), 2),
                expected_package=trace_context.get("expected_package") or None,
                fast_accept=bool(trace_context.get("fast_accept")),
            )
        except Exception:
            pass

    def _append_from_selector(sel, rid_hint: str) -> tuple[int, bool]:
        try:
            arr = sel.all() if hasattr(sel, "all") else list(sel)
        except Exception:
            arr = []
        added = 0
        exact = False
        for el in arr:
            oid = id(el)
            if oid in seen_el:
                continue
            seen_el.add(oid)
            raw.append((el, rid_hint))
            added += 1
            if _element_text_matches_target(el):
                exact = True
        return added, exact

    if trace_follow_ct and target and expected_package:
        rid = f"{expected_package}:id/{ROW_SEARCH_USER_USERNAME_RES_NAME}"
        t_selector = time.perf_counter()
        added = 0
        exact = False
        try:
            added, exact = _append_from_selector(d(resourceId=rid), rid)
        except Exception:
            pass
        _emit_selector_trace(
            selector_name=rid,
            selector_source="clone_exact_rid",
            started_at=t_selector,
            candidate_count=added,
            exact_match_found=exact,
            package_name=expected_package,
            used_hardcoded_android_rid=expected_package == "com.instagram.android",
            used_clone_rid=expected_package != "com.instagram.android",
        )
        if exact:
            _emit_selector_short_circuit(
                selector_name=rid,
                selector_source="clone_exact_rid",
                candidate_count=added,
                exact_match_found=True,
                saved_selector_count=4,
                saved_duration_ms_estimate=0.0,
            )
            return raw

    t_selector = time.perf_counter()
    added = 0
    exact = False
    try:
        added, exact = _append_from_selector(
            d(resourceId=ROW_SEARCH_USERNAME_EXACT_RES),
            ROW_SEARCH_USERNAME_EXACT_RES,
        )
    except Exception:
        pass
    _emit_selector_trace(
        selector_name=ROW_SEARCH_USERNAME_EXACT_RES,
        selector_source="exact_resource_id",
        started_at=t_selector,
        candidate_count=added,
        exact_match_found=exact,
        package_name="com.instagram.android",
        used_hardcoded_android_rid=True,
    )
    t_selector = time.perf_counter()
    added = 0
    exact = False
    try:
        added, exact = _append_from_selector(
            d(resourceIdMatches=r".*/id/row_search_user_username"),
            "",
        )
    except Exception:
        pass
    _emit_selector_trace(
        selector_name=".*/id/row_search_user_username",
        selector_source="resource_id_matches",
        started_at=t_selector,
        candidate_count=added,
        exact_match_found=exact,
        used_resource_id_matches=True,
    )

    if not raw:
        package_rids = _row_search_username_resource_id_list(d)
        for idx, rid in enumerate(package_rids):
            t_selector = time.perf_counter()
            added = 0
            exact = False
            pkg_name = rid.split(":id/", 1)[0] if ":id/" in rid else ""
            try:
                s2 = d(resourceId=rid)
                got = s2.all() if hasattr(s2, "all") else []
                if not got and s2.wait(timeout=0.06):
                    got = [s2]
                for el in got:
                    oid = id(el)
                    if oid in seen_el:
                        continue
                    seen_el.add(oid)
                    raw.append((el, rid))
                    added += 1
                    if _element_text_matches_target(el):
                        exact = True
            except Exception:
                pass
            _emit_selector_trace(
                selector_name=rid,
                selector_source="package_resource_id",
                started_at=t_selector,
                candidate_count=added,
                exact_match_found=exact,
                package_name=pkg_name,
                used_hardcoded_android_rid=pkg_name == "com.instagram.android",
                used_clone_rid=bool(pkg_name and pkg_name != "com.instagram.android"),
            )
            if trace_follow_ct and exact and pkg_name == expected_package:
                _emit_selector_short_circuit(
                    selector_name=rid,
                    selector_source=(
                        "package_resource_id_clone"
                        if pkg_name != "com.instagram.android"
                        else "package_resource_id_expected"
                    ),
                    candidate_count=added,
                    exact_match_found=True,
                    saved_selector_count=max(0, len(package_rids) - idx - 1) + 1,
                    saved_duration_ms_estimate=0.0,
                )
                return raw
            if raw:
                continue

    if not raw:
        t_selector = time.perf_counter()
        added = 0
        exact = False
        try:
            added, exact = _append_from_selector(
                d(resourceIdMatches=f".*:id/{ROW_SEARCH_USER_USERNAME_RES_NAME}"),
                "",
            )
        except Exception:
            pass
        _emit_selector_trace(
            selector_name=f".*:id/{ROW_SEARCH_USER_USERNAME_RES_NAME}",
            selector_source="legacy_resource_id_matches",
            started_at=t_selector,
            candidate_count=added,
            exact_match_found=exact,
            used_resource_id_matches=True,
        )

    return raw


def find_first_row_search_username_hot(
    d: u2.Device,
    username: str,
    *,
    trace_context: dict[str, Any] | None = None,
):
    """
    First exact-normalized match on resource-id row_search_user_username only.
    No avatar/parent/XPath/XML/ranking.
    """
    target = _normalize_handle(username)
    for el, _rid_hint in _collect_raw_row_search_elements(
        d,
        trace_context=trace_context,
    ):
        try:
            txt = el.get_text() or ""
            if _normalize_handle(txt) == target:
                return el
        except Exception:
            continue
    return None


def find_username_elements_by_resource_id(
    d: u2.Device,
    username: str,
    *,
    follow_ct_search_context: bool = False,
    trace_context: dict[str, Any] | None = None,
) -> list[tuple[object, str]]:
    """
    Strong signal: TextViews with id row_search_user_username matching exact handle.
    Returns [(element, matched_resource_id), ...].
    """
    target = _normalize_handle(username)
    seen: set[int] = set()
    matches: list[tuple[object, str]] = []
    _t_collect_raw = time.perf_counter()
    raw = _collect_raw_row_search_elements(d, trace_context=trace_context)
    if _follow_ct_search_active(explicit=follow_ct_search_context):
        try:
            log(
                "info",
                "follow_ct_search_collect_raw_ms",
                username=username,
                duration_ms=round((time.perf_counter() - _t_collect_raw) * 1000.0, 2),
            )
        except Exception:
            pass

    for el, rid_hint in raw:
        try:
            oid = id(el)
            if oid in seen:
                continue
            txt = el.get_text() or ""
            if _normalize_handle(txt) != target:
                continue
            try:
                info = el.info
                rid_full = (
                    info.get("resourceName")
                    or info.get("resourceId")
                    or rid_hint
                    or f":id/{ROW_SEARCH_USER_USERNAME_RES_NAME}"
                )
            except Exception:
                rid_full = rid_hint or f":id/{ROW_SEARCH_USER_USERNAME_RES_NAME}"
            seen.add(oid)
            matches.append((el, str(rid_full)))
        except Exception:
            continue

    return matches


def _normalize_handle(username: str) -> str:
    return username.strip().lstrip("@").lower()


def _account_row_search_texts(username: str) -> list[str]:
    """
    Priority: plain handle variants first, then @handle variants (exact UiSelector text).
    """
    u = username.strip().lstrip("@")
    if not u:
        return []
    cap = u[0].upper() + u[1:].lower() if len(u) > 1 else u.upper()
    plain: list[str] = []
    at_suffix: list[str] = []
    sp: set[str] = set()
    sa: set[str] = set()

    def add_plain(s: str) -> None:
        if s and s not in sp:
            sp.add(s)
            plain.append(s)

    def add_at(s: str) -> None:
        if s and s not in sa:
            sa.add(s)
            at_suffix.append(s)

    add_plain(u)
    add_plain(u.lower())
    add_plain(cap)
    add_at(f"@{u}")
    add_at(f"@{u.lower()}")
    add_at(f"@{cap}")
    return plain + at_suffix


def _text_matches_handle(visible: str, username: str) -> bool:
    return _normalize_handle(visible) == _normalize_handle(username)


def _ensure_debug_dirs() -> None:
    _SCREENSHOTS_DIR.mkdir(parents=True, exist_ok=True)
    _XML_DIR.mkdir(parents=True, exist_ok=True)


def _estimate_tab_strip_bottom_y(d: u2.Device, height: int) -> int:
    """Lower edge of horizontal search category chips (lightweight text lookup)."""
    labels = (
        "For you",
        "Pour toi",
        "Accounts",
        "Account",
        "Comptes",
        "Posts",
        "People",
        "Personnes",
        "Profils",
    )
    max_bottom = 0
    for lab in labels:
        try:
            o = d(className="android.widget.TextView", text=lab)
            if not o.wait(timeout=0.04):
                continue
            b = o.info["bounds"]
            if b["top"] > height * 0.38:
                continue
            max_bottom = max(max_bottom, b["bottom"])
        except Exception:
            continue
    return max_bottom + 10 if max_bottom > 0 else int(height * 0.14)


def _find_posts_section_top_y(d: u2.Device, tab_strip_bottom: int, height: int) -> int | None:
    try:
        o = d(className="android.widget.TextView", text="Posts")
        if not o.wait(timeout=0.12):
            return None
        top = int(o.info["bounds"]["top"])
        if top > tab_strip_bottom + 24:
            return top
    except Exception:
        pass
    return None


def _serp_y_band(d: u2.Device) -> tuple[int, int | None, int]:
    """Returns (tab_strip_bottom, posts_section_top_or_none, screen_height)."""
    _w, h = d.window_size()
    tab_b = _estimate_tab_strip_bottom_y(d, h)
    posts_t = _find_posts_section_top_y(d, tab_b, h)
    return tab_b, posts_t, h


def _cy_in_accounts_results_band(cy: int, tab_bottom: int, posts_top: int | None, height: int) -> bool:
    """Exclude search chrome and Posts/Reels block when possible."""
    if cy <= tab_bottom:
        return False
    margin = 6
    if posts_top is not None and cy >= posts_top - margin:
        return False
    # Ignore extreme bottom (often media / suggestions)
    if cy >= int(height * 0.92):
        return False
    return True


def _cy_in_mixed_results_band(
    cy: int, posts_top: int | None, height: int, search_bottom: int, width: int
) -> bool:
    """No Accounts-tab strip: allow results below search chrome; still skip Posts/media band."""
    if cy <= search_bottom + _scale_px(2, width):
        return False
    margin = 6
    if posts_top is not None and cy >= posts_top - margin:
        return False
    if cy >= int(height * 0.92):
        return False
    return True


def _iter_textviews_for_handle(d: u2.Device, username: str):
    """Every visible TextView whose text normalizes to the target handle (all on-screen matches)."""
    target = _normalize_handle(username)
    seen: set[int] = set()
    try:
        sel = d.xpath("//android.widget.TextView")
        nodes = sel.all() if hasattr(sel, "all") else list(sel)
    except Exception:
        return
    for el in nodes[:280]:
        try:
            oid = id(el)
            if oid in seen:
                continue
            txt = el.get_text() or ""
            if _normalize_handle(txt) != target:
                continue
            seen.add(oid)
            yield el
        except Exception:
            continue


def _scale_px(px_at_ref: int, width: int) -> int:
    return max(1, int(px_at_ref * width / config.REFERENCE_SCREEN_WIDTH))


def _overlap_y(a0: int, a1: int, b0: int, b1: int) -> bool:
    return not (a1 < b0 or b1 < a0)


def _find_recent_header_bottom_y(d: u2.Device, height: int) -> int | None:
    for label in ("Recent", "Récents", "Recent searches"):
        o = d(className="android.widget.TextView", text=label)
        if o.wait(timeout=0.06):
            try:
                return int(o.info["bounds"]["bottom"])
            except Exception:
                continue
    return None


def _chrome_bottom_y(d: u2.Device, height: int, tab_strip_bottom: int) -> int:
    bottom = tab_strip_bottom
    try:
        ed = d(className="android.widget.EditText")
        if ed.wait(timeout=0.08):
            b = ed.info["bounds"]
            bottom = max(bottom, int(b["bottom"]))
    except Exception:
        pass
    return bottom


def _row_avatar_vertical_overlap_fraction(row_top: int, row_bottom: int, av_top: int, av_bottom: int) -> float:
    ov = min(row_bottom, av_bottom) - max(row_top, av_top)
    if ov <= 0:
        return 0.0
    row_h = max(1, row_bottom - row_top)
    return ov / row_h


def _find_best_avatar_for_row(
    d: u2.Device, text_bounds: dict, width: int, height: int
) -> tuple[bool, int]:
    """
    Relaxed avatar: ImageView left of username, ≥30% vertical overlap with row,
    min side ≥ 28dp scaled, gap (username_left - avatar_right) in [0, max_gap_scaled].
    Returns (found, best_area_px2).
    """
    tl = int(text_bounds["left"])
    tt = int(text_bounds["top"])
    tb_b = int(text_bounds["bottom"])
    row_h = max(12, tb_b - tt)
    min_side = _scale_px(28, width)
    max_gap = _scale_px(config.AVATAR_TO_USERNAME_MAX_GAP_PX, width)
    edge_slop = _scale_px(12, width)

    best_area = 0
    try:
        sel = d.xpath("//android.widget.ImageView")
        nodes = sel.all() if hasattr(sel, "all") else list(sel)
    except Exception:
        return False, 0

    for el in nodes[:120]:
        try:
            b = el.info["bounds"]
            al, at, ar, ab = int(b["left"]), int(b["top"]), int(b["right"]), int(b["bottom"])
            iw, ih = ar - al, ab - at
            if min(iw, ih) < min_side:
                continue
            frac = _row_avatar_vertical_overlap_fraction(tt, tb_b, at, ab)
            if frac < 0.30:
                continue
            if ar > tl + edge_slop:
                continue
            gap = tl - ar
            if gap < -4 or gap > max_gap:
                continue
            area = iw * ih
            if area > best_area:
                best_area = area
        except Exception:
            continue

    return (best_area > 0), best_area


def _remove_button_same_row(d: u2.Device, text_bounds: dict, width: int, height: int) -> bool:
    tt = int(text_bounds["top"])
    tb = int(text_bounds["bottom"])
    y0, y1 = tt - 8, tb + 8
    x_edge = int(width * 0.70)
    for desc in ("Remove", "Clear", "Supprimer", "Effacer", "Close"):
        o = d(descriptionContains=desc)
        if not o.wait(timeout=0.02):
            continue
        try:
            b = o.info["bounds"]
            if b["left"] < x_edge - 60:
                continue
            if _overlap_y(y0, y1, int(b["top"]), int(b["bottom"])):
                return True
        except Exception:
            continue
    # Small clear icon on the far right (content-desc often empty; catch "X" text)
    try:
        x = d(text="×")
        if x.wait(timeout=0.02):
            b = x.info["bounds"]
            if b["left"] >= x_edge and _overlap_y(y0, y1, b["top"], b["bottom"]):
                return True
    except Exception:
        pass
    return False


def _candidate_payload(
    *,
    tb: dict,
    center_y: int,
    has_avatar: bool,
    has_remove_button: bool,
    reason: str | None,
    username: str,
    avatar_area: int = 0,
) -> dict:
    return {
        "username": username,
        "bounds": tb,
        "left": tb["left"],
        "top": tb["top"],
        "center_y": center_y,
        "has_avatar": has_avatar,
        "has_remove_button": has_remove_button,
        "avatar_area": avatar_area,
        "reason": reason,
    }


def evaluate_account_row_candidate(
    d: u2.Device, text_el, username: str, *, mixed_results: bool = False
) -> dict:
    """
    Full candidate evaluation for logging + ranking.
    Rows with avatar are never rejected as too_close_search; top suggestion is no-avatar-only.
    """
    w, h = d.window_size()
    target = _normalize_handle(username)
    try:
        txt = text_el.get_text()
        tb = {k: int(text_el.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
    except Exception:
        return {
            "accept": False,
            "reason": "bad_element",
            "el": text_el,
            "bounds": {},
            "center_y": 0,
            "has_avatar": False,
            "has_remove_button": False,
            "avatar_area": 0,
        }

    cy = (tb["top"] + tb["bottom"]) // 2
    if _normalize_handle(txt) != target:
        return {
            "accept": False,
            "reason": "text_mismatch",
            "el": text_el,
            "bounds": tb,
            "center_y": cy,
            "has_avatar": False,
            "has_remove_button": False,
            "avatar_area": 0,
        }

    tab_b, posts_t, hh = _serp_y_band(d)
    search_bottom = _chrome_bottom_y(d, hh, tab_b)

    if mixed_results:
        if not _cy_in_mixed_results_band(cy, posts_t, hh, search_bottom, w):
            return {
                "accept": False,
                "reason": "y_band",
                "el": text_el,
                "bounds": tb,
                "center_y": cy,
                "has_avatar": False,
                "has_remove_button": False,
                "avatar_area": 0,
            }
    else:
        if not _cy_in_accounts_results_band(cy, tab_b, posts_t, hh):
            return {
                "accept": False,
                "reason": "y_band",
                "el": text_el,
                "bounds": tb,
                "center_y": cy,
                "has_avatar": False,
                "has_remove_button": False,
                "avatar_area": 0,
            }

    lx_min = _scale_px(config.ACCOUNT_ROW_USERNAME_LEFT_X_MIN, w)
    lx_max = _scale_px(config.ACCOUNT_ROW_USERNAME_LEFT_X_MAX, w)
    if tb["left"] < lx_min or tb["left"] > lx_max:
        return {
            "accept": False,
            "reason": "layout_username_x",
            "el": text_el,
            "bounds": tb,
            "center_y": cy,
            "has_avatar": False,
            "has_remove_button": False,
            "avatar_area": 0,
        }

    has_av, av_area = _find_best_avatar_for_row(d, tb, w, hh)
    has_remove = _remove_button_same_row(d, tb, w, hh)

    suggest_cutoff = search_bottom + _scale_px(config.SUGGESTION_ZONE_PADDING_PX, w)
    in_top_suggestion_zone = tb["top"] < suggest_cutoff

    if not has_av and in_top_suggestion_zone:
        return {
            "accept": False,
            "reason": "top_suggestion_row",
            "el": text_el,
            "bounds": tb,
            "center_y": cy,
            "has_avatar": False,
            "has_remove_button": has_remove,
            "avatar_area": 0,
        }

    recent_bot = _find_recent_header_bottom_y(d, hh)
    if recent_bot is not None:
        depth = _scale_px(config.RECENT_BLOCK_DEPTH, hh)
        if recent_bot <= cy <= recent_bot + depth and not has_av:
            return {
                "accept": False,
                "reason": "recent_query",
                "el": text_el,
                "bounds": tb,
                "center_y": cy,
                "has_avatar": False,
                "has_remove_button": has_remove,
                "avatar_area": 0,
            }

    if has_remove:
        return {
            "accept": False,
            "reason": "remove_button",
            "el": text_el,
            "bounds": tb,
            "center_y": cy,
            "has_avatar": has_av,
            "has_remove_button": True,
            "avatar_area": av_area,
        }

    if not has_av:
        return {
            "accept": False,
            "reason": "no_avatar",
            "el": text_el,
            "bounds": tb,
            "center_y": cy,
            "has_avatar": False,
            "has_remove_button": False,
            "avatar_area": 0,
        }

    return {
        "accept": True,
        "reason": None,
        "el": text_el,
        "bounds": tb,
        "center_y": cy,
        "has_avatar": True,
        "has_remove_button": False,
        "avatar_area": av_area,
    }


def _element_resource_name(el) -> str:
    try:
        return str((el.info or {}).get("resourceName") or "")
    except Exception:
        return ""


def _exact_mixed_search_row_fast_accept_eligible(
    *,
    cy: int,
    posts_top: int | None,
    height: int,
    search_bottom: int,
    width: int,
    has_remove: bool,
) -> tuple[bool, str]:
    """Exact row_search_user_username in mixed SERP: skip slow posts_top stabilization."""
    if has_remove:
        return False, "remove_button"
    if cy <= search_bottom + _scale_px(2, width):
        return False, "above_search_results"
    if cy >= int(height * 0.92):
        return False, "bottom_media_band"
    if posts_top is not None and cy >= posts_top - _scale_px(6, width):
        return False, "posts_section_band"
    return True, "accepted"


def evaluate_row_search_username_element(
    d: u2.Device,
    text_el,
    username: str,
    *,
    mixed_results: bool,
    follow_ct_search_context: bool = False,
    resource_id_hint: str = "",
) -> dict:
    """
    row_search_user_username resource id: account SERP row; accept without avatar.
    No top_suggestion_row / layout_username_x / recent-without-avatar rejections.
    """
    w, h = d.window_size()
    target = _normalize_handle(username)
    try:
        txt = text_el.get_text()
        tb = {k: int(text_el.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
    except Exception:
        return {
            "accept": False,
            "reason": "bad_element",
            "el": text_el,
            "bounds": {},
            "center_y": 0,
            "has_avatar": False,
            "has_remove_button": False,
            "avatar_area": 0,
            "from_resource_id": True,
        }

    cy = (tb["top"] + tb["bottom"]) // 2
    if _normalize_handle(txt) != target:
        return {
            "accept": False,
            "reason": "text_mismatch",
            "el": text_el,
            "bounds": tb,
            "center_y": cy,
            "has_avatar": False,
            "has_remove_button": False,
            "avatar_area": 0,
            "from_resource_id": True,
        }

    follow_ct_active = _follow_ct_search_active(explicit=follow_ct_search_context)
    rid_hint = str(resource_id_hint or "").strip()
    remove_probe_ms = 0.0
    serp_band_ms = 0.0

    if (
        follow_ct_active
        and mixed_results
        and _is_exact_row_search_resource_id(rid_hint)
    ):
        element_rid = _element_resource_name(text_el)
        effective_rid = element_rid or rid_hint
        if rid_hint and not element_rid:
            try:
                log(
                    "info",
                    "follow_ct_search_evaluate_rid_mismatch",
                    username=username,
                    resource_id_hint=rid_hint,
                    element_resource_name=element_rid,
                    effective_rid=effective_rid,
                    follow_ct_active=True,
                )
            except Exception:
                pass
        is_exact_row_rid = True
        has_remove_early = False
        fast_ok, fast_block = _follow_ct_exact_row_light_serp_guard(
            cy=cy,
            height=h,
            width=w,
        )
        serp_band_skipped = bool(fast_ok)
        if serp_band_skipped:
            try:
                log(
                    "info",
                    "follow_ct_search_serp_band_skipped_exact_row",
                    username=username,
                    resource_id_hint=rid_hint,
                    effective_rid=effective_rid,
                    center_y=int(cy),
                    bounds=tb,
                )
            except Exception:
                pass
        else:
            _t_serp = time.perf_counter()
            tab_b, posts_t, hh, search_bottom = _follow_ct_cached_serp_y_band(d)
            serp_band_ms = round((time.perf_counter() - _t_serp) * 1000.0, 2)
            fast_ok, fast_block = _exact_mixed_search_row_fast_accept_eligible(
                cy=cy,
                posts_top=posts_t,
                height=hh,
                search_bottom=search_bottom,
                width=w,
                has_remove=has_remove_early,
            )
        try:
            log(
                "info",
                "follow_ct_search_exact_short_circuit_used",
                username=username,
                resource_id_hint=rid_hint,
                effective_rid=effective_rid,
                follow_ct_search_serp_band_ms=serp_band_ms,
                follow_ct_search_remove_probe_ms=remove_probe_ms,
                follow_ct_search_serp_band_skipped=serp_band_skipped,
                fast_ok=bool(fast_ok),
                fast_block=str(fast_block or "")[:80],
            )
        except Exception:
            pass
        if fast_ok and follow_ct_active:
            try:
                log(
                    "info",
                    "follow_ct_search_evaluate_context_snapshot",
                    username=username,
                    follow_ct_search_context=bool(follow_ct_search_context),
                    global_context_active=is_follow_ct_search_context_active(),
                    follow_ct_active=True,
                    fast_ok=True,
                    search_ui_mode=get_search_ui_mode(),
                    resource_id=effective_rid,
                )
            except Exception:
                pass
            _store_follow_ct_exact_row_tap_bounds(tb)
            try:
                log(
                    "info",
                    "follow_ct_exact_row_fast_accept_without_avatar_scan",
                    username=username,
                    resource_id=effective_rid,
                    bounds=tb,
                    center_y=cy,
                )
            except Exception:
                pass
            return {
                "accept": True,
                "reason": None,
                "el": text_el,
                "bounds": tb,
                "center_y": cy,
                "has_avatar": False,
                "has_remove_button": False,
                "avatar_area": 0,
                "from_resource_id": True,
                "fast_path": "follow_ct_exact_row_no_avatar_scan",
            }

    tab_b, posts_t, hh = _serp_y_band(d)
    search_bottom = _chrome_bottom_y(d, hh, tab_b)
    element_rid = _element_resource_name(text_el)
    effective_rid = element_rid or rid_hint
    if rid_hint and not element_rid and _is_exact_row_search_resource_id(rid_hint):
        try:
            log(
                "info",
                "follow_ct_search_evaluate_rid_mismatch",
                username=username,
                resource_id_hint=rid_hint,
                element_resource_name=element_rid,
                effective_rid=effective_rid,
                follow_ct_active=follow_ct_active,
            )
        except Exception:
            pass
    is_exact_row_rid = _is_exact_row_search_resource_id(effective_rid)

    if mixed_results and is_exact_row_rid:
        _t_remove = time.perf_counter()
        has_remove_early = _remove_button_same_row(d, tb, w, hh)
        remove_probe_ms = round((time.perf_counter() - _t_remove) * 1000.0, 2)
        if follow_ct_active:
            try:
                log(
                    "info",
                    "follow_ct_search_remove_probe_ms",
                    username=username,
                    duration_ms=remove_probe_ms,
                )
            except Exception:
                pass
        fast_ok, fast_block = _exact_mixed_search_row_fast_accept_eligible(
            cy=cy,
            posts_top=posts_t,
            height=hh,
            search_bottom=search_bottom,
            width=w,
            has_remove=has_remove_early,
        )
        if fast_ok:
            try:
                log(
                    "info",
                    "follow_ct_search_evaluate_context_snapshot",
                    username=username,
                    follow_ct_search_context=bool(follow_ct_search_context),
                    global_context_active=is_follow_ct_search_context_active(),
                    follow_ct_active=_follow_ct_search_active(
                        explicit=follow_ct_search_context
                    ),
                    fast_ok=True,
                    search_ui_mode=get_search_ui_mode(),
                    resource_id=effective_rid,
                )
            except Exception:
                pass
            if _follow_ct_search_active(explicit=follow_ct_search_context):
                _store_follow_ct_exact_row_tap_bounds(tb)
                try:
                    log(
                        "info",
                        "follow_ct_exact_row_fast_accept_without_avatar_scan",
                        username=username,
                        resource_id=effective_rid,
                        bounds=tb,
                        center_y=cy,
                    )
                except Exception:
                    pass
                return {
                    "accept": True,
                    "reason": None,
                    "el": text_el,
                    "bounds": tb,
                    "center_y": cy,
                    "has_avatar": False,
                    "has_remove_button": False,
                    "avatar_area": 0,
                    "from_resource_id": True,
                    "fast_path": "follow_ct_exact_row_no_avatar_scan",
                }
            has_av, av_area = _find_best_avatar_for_row(d, tb, w, hh)
            return {
                "accept": True,
                "reason": None,
                "el": text_el,
                "bounds": tb,
                "center_y": cy,
                "has_avatar": has_av,
                "has_remove_button": False,
                "avatar_area": av_area,
                "from_resource_id": True,
                "fast_path": "exact_row_resource_id_mixed",
            }
        log(
            "info",
            "exact_row_accept_blocked",
            username=username,
            reason=fast_block,
            center_y=cy,
            resource_id=effective_rid,
            bounds=tb,
        )

    if mixed_results:
        if not _cy_in_mixed_results_band(cy, posts_t, hh, search_bottom, w):
            if is_exact_row_rid:
                log(
                    "info",
                    "exact_row_accept_blocked",
                    username=username,
                    reason="y_band",
                    center_y=cy,
                    resource_id=effective_rid,
                    bounds=tb,
                )
            return {
                "accept": False,
                "reason": "y_band",
                "el": text_el,
                "bounds": tb,
                "center_y": cy,
                "has_avatar": False,
                "has_remove_button": False,
                "avatar_area": 0,
                "from_resource_id": True,
            }
    else:
        if not _cy_in_accounts_results_band(cy, tab_b, posts_t, hh):
            return {
                "accept": False,
                "reason": "y_band",
                "el": text_el,
                "bounds": tb,
                "center_y": cy,
                "has_avatar": False,
                "has_remove_button": False,
                "avatar_area": 0,
                "from_resource_id": True,
            }

    has_av, av_area = _find_best_avatar_for_row(d, tb, w, hh)
    has_remove = _remove_button_same_row(d, tb, w, hh)

    if has_remove:
        return {
            "accept": False,
            "reason": "remove_button",
            "el": text_el,
            "bounds": tb,
            "center_y": cy,
            "has_avatar": has_av,
            "has_remove_button": True,
            "avatar_area": av_area,
            "from_resource_id": True,
        }

    return {
        "accept": True,
        "reason": None,
        "el": text_el,
        "bounds": tb,
        "center_y": cy,
        "has_avatar": has_av,
        "has_remove_button": False,
        "avatar_area": av_area,
        "from_resource_id": True,
    }


def is_real_account_row(d: u2.Device, text_el, username: str) -> tuple[bool, str | None]:
    mixed = get_search_ui_mode() == "mixed_results"
    ev = evaluate_account_row_candidate(d, text_el, username, mixed_results=mixed)
    return ev["accept"], ev["reason"]


def _dump_no_real_account_row_debug(d: u2.Device, username: str) -> None:
    _ensure_debug_dirs()
    shot = _SCREENSHOTS_DIR / "no_real_account_row.png"
    xml_path = _XML_DIR / "no_real_account_row.xml"
    try:
        screenshot(d, str(shot))
    except Exception as e:
        log("warning", "no_real_account_row_screenshot_failed", error=str(e), username=username)
    try:
        try:
            hier = d.dump_hierarchy(compressed=False)
        except TypeError:
            hier = d.dump_hierarchy()
        xml_path.write_text(hier, encoding="utf-8")
        _bump_xml_fetch()
        log("info", "no_real_account_row_hierarchy_dumped", path=str(xml_path), username=username)
    except Exception as e:
        log("warning", "no_real_account_row_xml_failed", error=str(e), username=username)


def _iter_exact_text_match_elements(d: u2.Device, disp: str):
    """Yield all TextViews with exact text=disp (handles duplicates in list)."""
    sel = d(className="android.widget.TextView", text=disp)
    if hasattr(sel, "all"):
        try:
            found = sel.all()
            if found:
                for o in found:
                    yield o
                return
        except Exception:
            pass
    if sel.wait(timeout=0.05):
        yield sel


def find_real_account_text_element(
    d: u2.Device,
    username: str,
    *,
    dump_on_failure: bool = True,
    follow_ct_search_context: bool = False,
    trace_context: dict[str, Any] | None = None,
):
    """
    Resource-id row_search_user_username first (GramAddict/Propulse style), then XPath TextViews.
    Ranking: resource-id rows, then has_avatar, then smallest center_y, then largest avatar.
    """
    mixed = get_search_ui_mode() == "mixed_results"
    follow_ct_active = _follow_ct_search_active(explicit=follow_ct_search_context)
    accepted: list[dict] = []
    weak_rows: list[tuple[int, dict, object, str | None]] = []

    for el, rid in find_username_elements_by_resource_id(
        d,
        username,
        follow_ct_search_context=follow_ct_search_context,
        trace_context=trace_context,
    ):
        try:
            txt = el.get_text()
            tb = {k: int(el.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
            cy = (tb["top"] + tb["bottom"]) // 2
        except Exception:
            continue

        log(
            "info",
            "candidate_account_row_seen_resource_id",
            username=username,
            resource_id=rid,
            text=txt,
            bounds=tb,
            left=tb["left"],
            top=tb["top"],
            center_y=cy,
        )

        ev = evaluate_row_search_username_element(
            d,
            el,
            username,
            mixed_results=mixed,
            follow_ct_search_context=follow_ct_search_context,
            resource_id_hint=rid,
        )
        pl = _candidate_payload(
            tb=ev["bounds"],
            center_y=ev["center_y"],
            has_avatar=ev["has_avatar"],
            has_remove_button=ev["has_remove_button"],
            reason=ev["reason"] or "accepted",
            username=username,
            avatar_area=ev["avatar_area"],
        )
        pl["resource_id"] = rid
        pl["from_resource_id"] = True

        if ev["accept"]:
            ev["resource_id"] = rid
            if (
                follow_ct_active
                and str(ev.get("fast_path") or "")
                == "follow_ct_exact_row_no_avatar_scan"
            ):
                log(
                    "info",
                    "exact_account_row_fast_accept_used",
                    username=username,
                    resource_id=rid,
                    fast_path="follow_ct_exact_row_no_avatar_scan",
                )
                log("info", "real_account_row_accepted_resource_id", **pl)
                log(
                    "info",
                    "real_account_result_found",
                    username=username,
                    selected_y=ev["center_y"],
                    left=ev["bounds"]["left"],
                    candidates=1,
                    avatar_area=0,
                    search_ui_mode=get_search_ui_mode(),
                    via_resource_id=True,
                    resource_id=rid,
                    fast_path="follow_ct_exact_row_no_avatar_scan",
                )
                return el
            if mixed:
                settle_ms = float(
                    getattr(config, "EXACT_ACCOUNT_ROW_FAST_ACCEPT_SETTLE_MS", 120.0)
                )
                if settle_ms > 0:
                    time.sleep(max(0.0, settle_ms) / 1000.0)
                    ev_recheck = evaluate_row_search_username_element(
                        d,
                        el,
                        username,
                        mixed_results=mixed,
                        follow_ct_search_context=follow_ct_search_context,
                        resource_id_hint=rid,
                    )
                    if not ev_recheck.get("accept"):
                        log(
                            "warning",
                            "exact_account_row_fast_accept_recheck_failed",
                            username=username,
                            reason=str(ev_recheck.get("reason") or "")[:80],
                        )
                    else:
                        log(
                            "info",
                            "exact_account_row_fast_accept_used",
                            username=username,
                            resource_id=rid,
                        )
                        log("info", "real_account_row_accepted_resource_id", **pl)
                        log(
                            "info",
                            "real_account_result_found",
                            username=username,
                            selected_y=ev["center_y"],
                            left=ev["bounds"]["left"],
                            candidates=1,
                            avatar_area=ev["avatar_area"],
                            search_ui_mode=get_search_ui_mode(),
                            via_resource_id=True,
                            resource_id=rid,
                            fast_path="mixed_resource_id_fast_accept",
                        )
                        return el
                else:
                    log(
                        "info",
                        "exact_account_row_fast_accept_used",
                        username=username,
                        resource_id=rid,
                    )
                log("info", "real_account_row_accepted_resource_id", **pl)
                log(
                    "info",
                    "real_account_result_found",
                    username=username,
                    selected_y=ev["center_y"],
                    left=ev["bounds"]["left"],
                    candidates=1,
                    avatar_area=ev["avatar_area"],
                    search_ui_mode=get_search_ui_mode(),
                    via_resource_id=True,
                    resource_id=rid,
                    fast_path="mixed_resource_id_first",
                )
                return el
            accepted.append(ev)
            log("info", "real_account_row_accepted_resource_id", **pl)
        else:
            log("warning", "candidate_account_row_rejected", **pl)

    if accepted:
        accepted.sort(
            key=lambda e: (
                -int(e.get("from_resource_id", False)),
                -int(e["has_avatar"]),
                e["center_y"],
                -e["avatar_area"],
            )
        )
        best = accepted[0]
        log(
            "info",
            "real_account_result_found",
            username=username,
            selected_y=best["center_y"],
            left=best["bounds"]["left"],
            candidates=len(accepted),
            avatar_area=best["avatar_area"],
            search_ui_mode=get_search_ui_mode(),
            via_resource_id=best.get("from_resource_id", False),
            resource_id=best.get("resource_id"),
        )
        return best["el"]

    for o in _iter_textviews_for_handle(d, username):
        try:
            txt = o.get_text()
            tb = {k: int(o.info["bounds"][k]) for k in ("left", "top", "right", "bottom")}
            cy = (tb["top"] + tb["bottom"]) // 2
        except Exception:
            continue

        log(
            "info",
            "candidate_account_row_seen",
            **_candidate_payload(
                tb=tb,
                center_y=cy,
                has_avatar=False,
                has_remove_button=False,
                reason="evaluating",
                username=username,
            ),
        )

        ev = evaluate_account_row_candidate(d, o, username, mixed_results=mixed)
        ev["from_resource_id"] = False
        pl = _candidate_payload(
            tb=ev["bounds"],
            center_y=ev["center_y"],
            has_avatar=ev["has_avatar"],
            has_remove_button=ev["has_remove_button"],
            reason=ev["reason"] or "accepted",
            username=username,
            avatar_area=ev["avatar_area"],
        )

        if ev["accept"]:
            accepted.append(ev)
            log("info", "real_account_row_accepted", **pl)
        else:
            log("warning", "candidate_account_row_rejected", **pl)
            if ev["reason"] == "top_suggestion_row":
                log("info", "suggestion_row_rejected", **pl)

        if config.ALLOW_TEXT_ONLY_RECENT_RESULT and not ev["accept"] and ev["reason"] in (
            "no_avatar",
            "recent_query",
            "layout_username_x",
        ):
            weak_rows.append((ev["center_y"], ev["bounds"], ev["el"], ev["reason"]))

    if accepted:
        accepted.sort(
            key=lambda e: (
                -int(e.get("from_resource_id", False)),
                -int(e["has_avatar"]),
                e["center_y"],
                -e["avatar_area"],
            )
        )
        best = accepted[0]
        log(
            "info",
            "real_account_result_found",
            username=username,
            selected_y=best["center_y"],
            left=best["bounds"]["left"],
            candidates=len(accepted),
            avatar_area=best["avatar_area"],
            search_ui_mode=get_search_ui_mode(),
            via_resource_id=best.get("from_resource_id", False),
            resource_id=best.get("resource_id"),
        )
        return best["el"]

    if weak_rows:
        weak_rows.sort(key=lambda t: t[0], reverse=True)
        cy, tb, el, _r = weak_rows[0]
        log(
            "warning",
            "using_text_only_recent_fallback",
            username=username,
            selected_y=cy,
            allowed_by_config=True,
        )
        return el

    if dump_on_failure:
        _dump_no_real_account_row_debug(d, username)
    log("error", "no_real_account_row", username=username)
    return None


def wrong_surface_after_tap(d: u2.Device) -> str | None:
    """If still on search SERP or For You–style grid after a bad row tap."""
    w, h = d.window_size()
    try:
        ed = d(className="android.widget.EditText")
        if ed.wait(timeout=0.12):
            b = ed.info["bounds"]
            if int(b["bottom"]) <= int(h * 0.26):
                return "search_results"
    except Exception:
        pass

    for label in ("For you", "Pour toi"):
        o = d(text=label)
        if not o.wait(timeout=0.08):
            continue
        try:
            br = o.info["bounds"]
            if int(br["bottom"]) >= int(h * 0.22):
                continue
            ed2 = d(className="android.widget.EditText")
            has_top_search = ed2.wait(timeout=0.06) and int(ed2.info["bounds"]["bottom"]) <= int(h * 0.26)
            rv = d(className="androidx.recyclerview.widget.RecyclerView")
            has_rv = rv.wait(timeout=0.1)
            if has_rv and not has_top_search:
                return "for_you_grid"
        except Exception:
            continue
    return None


def _collect_top_visible_text_labels(d: u2.Device, *, max_y_ratio: float = 0.42, limit: int = 60) -> list[dict]:
    """Best-effort TextView texts in the upper window (for debugging)."""
    _w, h = d.window_size()
    y_max = int(h * max_y_ratio)
    rows: list[dict] = []
    nodes = []
    try:
        sel = d.xpath("//android.widget.TextView")
        if hasattr(sel, "all"):
            nodes = sel.all()
        else:
            nodes = list(sel)
    except Exception:
        try:
            sel2 = d(className="android.widget.TextView")
            nodes = sel2.all() if hasattr(sel2, "all") else []
        except Exception:
            return rows
    for el in nodes[:120]:
        try:
            b = el.info["bounds"]
            cy = (b["top"] + b["bottom"]) // 2
            if cy > y_max:
                continue
            txt = el.get_text() or ""
            if not txt.strip():
                continue
            rows.append({"text": txt[:120], "y": cy, "top": b["top"]})
        except Exception:
            continue
    rows.sort(key=lambda r: (r["top"], r["text"]))
    return rows[:limit]


def _dump_search_edittext_debug(d: u2.Device) -> None:
    _ensure_debug_dirs()
    shot = _SCREENSHOTS_DIR / "search_edittext_not_found.png"
    xml_path = _XML_DIR / "search_edittext_not_found.xml"
    try:
        screenshot(d, str(shot))
    except Exception as e:
        log("warning", "search_edittext_screenshot_failed", error=str(e))
    try:
        try:
            hier = d.dump_hierarchy(compressed=False)
        except TypeError:
            hier = d.dump_hierarchy()
        xml_path.write_text(hier, encoding="utf-8")
        _bump_xml_fetch()
        log("info", "search_edittext_hierarchy_dumped", path=str(xml_path))
    except Exception as e:
        log("warning", "search_edittext_xml_dump_failed", error=str(e))
    labels = _collect_top_visible_text_labels(d)
    log("warning", "search_edittext_top_text_labels", count=len(labels), labels=labels)


def _tap_search_bar_fallback(d: u2.Device) -> None:
    """Tap near top-center (IG search field) when EditText is not discovered."""
    w, h = d.window_size()
    x, y = int(w * 0.45), int(h * 0.08)
    d.click(x, y)
    log("info", "search_bar_fallback_tap", x=x, y=y, x_ratio=0.45, y_ratio=0.08)
    time.sleep(0.18)


