def _visual_profile_detected_after_back(
    d: u2.Device,
    *,
    pkg: str,
) -> bool:
    return bool(
        _try_profile_signals_once(d, "", pkg)
        or _guess_profile_screen(d, pkg, "")
        in ("likely_profile", "profile_header_rid", "action_bar_title")
    )


def _visual_wait_profile_after_back(
    d: u2.Device,
    *,
    pkg: str,
    initial_delay_s: float = _VISUAL_RETURN_PROFILE_POLL_INITIAL_S,
    poll_interval_s: float = _VISUAL_RETURN_PROFILE_POLL_INTERVAL_S,
    max_wait_s: float = _VISUAL_RETURN_PROFILE_POLL_MAX_S,
) -> dict[str, Any]:
    """Poll profile chrome after Back instead of a fixed post-back sleep."""
    t0 = time.perf_counter()
    poll_count = 0
    if initial_delay_s > 0:
        time.sleep(float(initial_delay_s))
    profile_detected = False
    while True:
        poll_count += 1
        profile_detected = _visual_profile_detected_after_back(d, pkg=pkg)
        elapsed_s = time.perf_counter() - t0
        if profile_detected:
            return {
                "profile_detected": True,
                "return_profile_poll_count": int(poll_count),
                "return_profile_fast_confirmed": bool(
                    poll_count <= 2 and elapsed_s < 0.55
                ),
                "return_profile_poll_wait_ms": round(elapsed_s * 1000.0, 2),
            }
        if elapsed_s >= float(max_wait_s):
            break
        time.sleep(min(float(poll_interval_s), float(max_wait_s) - elapsed_s))
    elapsed_s = time.perf_counter() - t0
    return {
        "profile_detected": False,
        "return_profile_poll_count": int(poll_count),
        "return_profile_fast_confirmed": False,
        "return_profile_poll_wait_ms": round(elapsed_s * 1000.0, 2),
    }


def _visual_wait_post_viewer_opened_after_tap(
    d: u2.Device,
    *,
    pkg: str,
    expected_follower_username: str,
    act_before: Any,
    poll_label: str = "first_tap",
    post_follow_fast: bool = False,
) -> dict[str, Any]:
    """Adaptive poll for post viewer after grid tap (replaces fixed 1.6s sleep)."""
    t0 = time.perf_counter()
    if post_follow_fast:
        initial_s = float(_POST_FOLLOW_VIEWER_OPEN_POLL_INITIAL_S)
        interval_s = float(_POST_FOLLOW_VIEWER_OPEN_POLL_INTERVAL_S)
        max_s = float(_POST_FOLLOW_VIEWER_OPEN_POLL_MAX_S)
        if str(poll_label or "").strip() == "retry_tap":
            max_s = float(_POST_FOLLOW_VIEWER_OPEN_POLL_RETRY_MAX_S)
        wall_cap_s = float(_POST_FOLLOW_VIEWER_OPEN_WALL_CAP_S)
    else:
        initial_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_INITIAL_S)
        interval_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_INTERVAL_S)
        max_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_MAX_S)
        if str(poll_label or "").strip() == "retry_tap":
            max_s = float(_VISUAL_POST_VIEWER_OPEN_POLL_RETRY_MAX_S)
        wall_cap_s = None

    poll_sleep_s = 0.0
    if initial_s > 0:
        time.sleep(initial_s)
        poll_sleep_s += initial_s

    poll_count = 0
    last_detect_ms = 0.0
    det: dict[str, Any] = {}
    while True:
        if wall_cap_s is not None and (time.perf_counter() - t0) >= wall_cap_s:
            break
        poll_count += 1
        t_detect0 = time.perf_counter()
        det = _visual_detect_post_viewer_opened_after_tap(
            d,
            pkg=pkg,
            expected_follower_username=expected_follower_username,
            act_before=act_before,
            post_follow_fast=bool(post_follow_fast),
        )
        last_detect_ms = (time.perf_counter() - t_detect0) * 1000.0
        if bool(det.get("post_detected")):
            elapsed_s = time.perf_counter() - t0
            detect_path = str(det.get("viewer_detect_path") or "")
            return {
                **det,
                "poll_count": int(poll_count),
                "viewer_open_poll_wait_ms": round(elapsed_s * 1000.0, 2),
                "viewer_open_poll_sleep_ms": round(poll_sleep_s * 1000.0, 2),
                "viewer_open_detect_call_ms": round(last_detect_ms, 2),
                "viewer_detect_like_unlike_ms": det.get("viewer_detect_like_unlike_ms"),
                "viewer_detect_action_bar_ms": det.get("viewer_detect_action_bar_ms"),
                "viewer_detect_header_ms": det.get("viewer_detect_header_ms"),
                "viewer_detect_profile_still_ms": det.get(
                    "viewer_detect_profile_still_ms"
                ),
                "viewer_detect_broad_chrome_ms": det.get("viewer_detect_broad_chrome_ms"),
                "viewer_detect_hierarchy_ms": det.get("viewer_detect_hierarchy_ms"),
                "viewer_detect_total_ms": det.get("viewer_detect_total_ms"),
                "viewer_detect_path": detect_path,
                "viewer_detect_exact_desc_ms": det.get("viewer_detect_exact_desc_ms"),
                "viewer_detect_exact_desc_signal": det.get(
                    "viewer_detect_exact_desc_signal"
                ),
                "viewer_detect_exact_desc_guard_result": det.get(
                    "viewer_detect_exact_desc_guard_result"
                ),
                "viewer_open_fast_path": bool(
                    detect_path
                    in (
                        "phase_a_like_unlike_fast",
                        "phase_a2_exact_like_desc_fast",
                    )
                    or (
                        poll_count == 1
                        and elapsed_s < initial_s + interval_s + 0.08
                    )
                ),
                "viewer_open_poll_label": str(poll_label or ""),
            }
        elapsed_s = time.perf_counter() - t0
        if elapsed_s >= max_s:
            break
        sleep_s = min(interval_s, max(0.0, max_s - elapsed_s))
        if sleep_s > 0:
            time.sleep(sleep_s)
            poll_sleep_s += sleep_s

    elapsed_s = time.perf_counter() - t0
    return {
        **det,
        "poll_count": int(poll_count),
        "viewer_open_poll_wait_ms": round(elapsed_s * 1000.0, 2),
        "viewer_open_poll_sleep_ms": round(poll_sleep_s * 1000.0, 2),
        "viewer_open_detect_call_ms": round(last_detect_ms, 2),
        "viewer_open_fast_path": False,
        "viewer_open_poll_label": str(poll_label or ""),
    }


def _already_liked_precheck_trusted_not_liked(
    precheck: dict[str, Any] | None,
) -> bool:
    if not isinstance(precheck, dict):
        return False
    if bool(precheck.get("already_liked")):
        return False
    state = str(precheck.get("semantic_like_state") or "")
    reason = str(precheck.get("already_liked_decision_reason") or "")
    if state == "like":
        return True
    return reason in (
        "semantic_like_confirmed_not_liked",
        "hierarchy_like_confirmed_not_liked",
    )


def _already_liked_precheck_requires_recheck(
    precheck: dict[str, Any] | None,
) -> tuple[bool, str]:
    if not isinstance(precheck, dict):
        return True, "no_precheck_supplied"
    if bool(precheck.get("already_liked")):
        return False, "precheck_already_liked_confirmed"
    if _already_liked_precheck_trusted_not_liked(precheck):
        return False, "precheck_trusted_not_liked"
    state = str(precheck.get("semantic_like_state") or "")
    if state == "unknown":
        return True, "precheck_unknown_requires_heart_bounds_recheck"
    return True, str(precheck.get("already_liked_decision_reason") or "precheck_inconclusive")


def _visual_grid_cell_tap_xy_device(
    x0: int,
    y0: int,
    cell_w: int,
    cell_h: int,
    *,
    iw: int,
    ih: int,
    ww: int,
    wh: int,
    offset_ix: int = 0,
    offset_iy: int = 0,
    tap_frac_x: float = _VISUAL_GRID_CELL_TAP_FRAC_X,
    tap_frac_y: float = _VISUAL_GRID_CELL_TAP_FRAC_Y,
) -> tuple[int, int]:
    """Inset tap inside grid cell (avoids Reel corner icon and cell edges)."""
    cx_img = x0 + int(cell_w * float(tap_frac_x)) + int(offset_ix)
    cy_img = y0 + int(cell_h * float(tap_frac_y)) + int(offset_iy)
    cx_img = max(x0 + 8, min(x0 + cell_w - 8, cx_img))
    cy_img = max(y0 + 8, min(y0 + cell_h - 8, cy_img))
    tap_x, tap_y = _visual_xy_image_to_device(cx_img, cy_img, iw, ih, ww, wh)
    return max(2, min(ww - 3, tap_x)), max(2, min(wh - 3, tap_y))


def _post_follow_likes_open_top_left_legacy_visual_safe(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    expected_follower_username: str,
    visual_candidate_id: str,
    post_index: int,
    likes_perf_phase_t0: float | None = None,
    strict_grid_proof_mode: str | None = None,
) -> dict[str, Any]:
    """
    Safe, targeted reuse of the emulator-era visual open path.
    It only considers row=0,col=0 below profile tabs and requires viewer confirmation.
    """
    t0 = time.perf_counter()
    strict_grid_proof_ok = False
    strict_grid_proof_source = ""
    strict_grid_mode = _post_follow_like_strict_grid_proof_mode(strict_grid_proof_mode)

    def _log_timing(event: str, started_at: float, **extra: Any) -> None:
        try:
            log(
                "info",
                event,
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                follower_username=expected_follower_username,
                post_index=int(post_index),
                duration_ms=round((time.perf_counter() - started_at) * 1000.0, 2),
                **extra,
            )
        except Exception:
            pass

    def _finish(reason: str, **extra: Any) -> dict[str, Any]:
        out = {
            "ok": False,
            "post_detected": False,
            "failure_reason": str(reason or "legacy_visual_top_left_failed"),
            "open_strategy": "vision_open_top_left_legacy_safe",
            "likes_perf_post_open": {
                "legacy_visual_top_left_total_ms": round(
                    (time.perf_counter() - t0) * 1000.0, 2
                ),
                "failure_reason": str(reason or "legacy_visual_top_left_failed"),
                "strict_grid_proof_ok": bool(strict_grid_proof_ok),
                "strict_grid_proof_source": str(strict_grid_proof_source or ""),
                **extra,
            },
            "strict_grid_proof_ok": bool(strict_grid_proof_ok),
            "strict_grid_proof_source": str(strict_grid_proof_source or ""),
            "strict_grid_proof_mode": strict_grid_mode,
            **extra,
        }
        try:
            log(
                "warning",
                "vision_open_top_left_legacy_safe_failed",
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                follower_username=expected_follower_username,
                post_index=int(post_index),
                failure_reason=out["failure_reason"],
                **extra,
            )
        except Exception:
            pass
        return out

    def _run_strict_grid_proof(trigger: str, *, ui_hints: dict[str, Any], ww: int, wh: int) -> dict[str, Any]:
        nonlocal strict_grid_proof_ok, strict_grid_proof_source
        is_fallback = str(trigger or "") != "always"
        if is_fallback:
            try:
                log(
                    "info",
                    "post_follow_like_strict_grid_proof_fallback_started",
                    visual_candidate_id=visual_candidate_id,
                    source_profile_username=source_profile_username,
                    follower_username=expected_follower_username,
                    post_index=int(post_index),
                    trigger=str(trigger or ""),
                    mode=str(strict_grid_mode),
                )
            except Exception:
                pass
        strict_grid_proof = _post_follow_likes_strict_top_left_xml_grid_proof(
            d,
            ui_hints=ui_hints,
            budget_deadline=time.perf_counter() + 1.2,
            ww=int(ww),
            wh=int(wh),
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
        )
        if bool(strict_grid_proof.get("ok")):
            strict_grid_proof_ok = True
            strict_grid_proof_source = str(strict_grid_proof.get("source") or "")
        elif not is_fallback:
            try:
                log(
                    "info",
                    "legacy_safe_strict_grid_proof_advisory_continue",
                    visual_candidate_id=visual_candidate_id,
                    source_profile_username=source_profile_username,
                    follower_username=expected_follower_username,
                    post_index=int(post_index),
                    strict_grid_proof_source=str(strict_grid_proof.get("source") or ""),
                    strict_grid_proof_failure_reason=str(
                        strict_grid_proof.get("failure_reason") or ""
                    ),
                    reason="strict_xml_proof_failed_continue_visual_dynamic_open",
                )
            except Exception:
                pass
        if is_fallback:
            try:
                log(
                    "info" if bool(strict_grid_proof.get("ok")) else "warning",
                    "post_follow_like_strict_grid_proof_fallback_result",
                    visual_candidate_id=visual_candidate_id,
                    source_profile_username=source_profile_username,
                    follower_username=expected_follower_username,
                    post_index=int(post_index),
                    trigger=str(trigger or ""),
                    mode=str(strict_grid_mode),
                    ok=bool(strict_grid_proof.get("ok")),
                    strict_grid_proof_source=str(strict_grid_proof.get("source") or ""),
                    strict_grid_proof_failure_reason=str(
                        strict_grid_proof.get("failure_reason") or ""
                    ),
                )
            except Exception:
                pass
        return strict_grid_proof

    try:
        meta0 = _followers_current_pkg_activity(d)
    except Exception:
        meta0 = {}
    try:
        log(
            "info",
            "vision_open_top_left_legacy_safe_started",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
            selection_policy=_VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR,
            allowed_row=0,
            allowed_col=0,
        )
    except Exception:
        pass

    stable_key = (
        f"{source_profile_username}\0{expected_follower_username}\0"
        f"{visual_candidate_id}\0{int(post_index)}"
    )
    try:
        attempt_index = int(_LEGACY_SAFE_ATTEMPT_COUNT_BY_KEY.get(stable_key, 0)) + 1
        _LEGACY_SAFE_ATTEMPT_COUNT_BY_KEY[stable_key] = attempt_index
    except Exception:
        attempt_index = 0
    previous_ui_hints = _LEGACY_SAFE_LAST_UI_HINTS_BY_KEY.get(stable_key, {})
    legacy_timing_ctx = {
        "visual_candidate_id": visual_candidate_id,
        "source_profile_username": source_profile_username,
        "follower_username": expected_follower_username,
        "post_index": int(post_index),
        "stable_key": stable_key,
        "attempt_index": attempt_index,
        "attempt_label": f"legacy_safe_attempt_{attempt_index}" if attempt_index else "",
        "known_previous_signals": previous_ui_hints,
    }

    _t_profile_lock = time.perf_counter()
    tv_open = visual_target_profile_lock_verify(
        d,
        source_profile_username=source_profile_username,
        action="vision_open_top_left_legacy_safe",
    )
    _log_timing(
        "legacy_safe_timing_profile_lock_completed",
        _t_profile_lock,
        ok=bool(tv_open.get("ok")),
        target_profile_lock_mismatch=not bool(tv_open.get("ok")),
    )
    if not bool(tv_open.get("ok")):
        return _finish("legacy_visual_top_left_failed", target_profile_lock_mismatch=True)
    legacy_timing_ctx["profile_lock_ok"] = True

    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2340
    _t_ui_hints = time.perf_counter()
    _prev_timing_ctx = _LEGACY_SAFE_TIMING_CONTEXT
    try:
        globals()["_LEGACY_SAFE_TIMING_CONTEXT"] = legacy_timing_ctx
        ui_hints = _post_follow_likes_grid_ui_surface_hints(d)
    except Exception:
        ui_hints = {}
    finally:
        globals()["_LEGACY_SAFE_TIMING_CONTEXT"] = _prev_timing_ctx
    try:
        _LEGACY_SAFE_LAST_UI_HINTS_BY_KEY[stable_key] = {
            "profile_tabs_visible": bool(ui_hints.get("profile_tabs_visible")),
            "suggested_for_you": bool(ui_hints.get("suggested_for_you")),
            "discover_people": bool(ui_hints.get("discover_people")),
        }
    except Exception:
        pass
    _log_timing(
        "legacy_safe_timing_ui_hints_completed",
        _t_ui_hints,
        profile_tabs_visible=bool(ui_hints.get("profile_tabs_visible")),
        suggested_for_you=bool(ui_hints.get("suggested_for_you")),
        discover_people=bool(ui_hints.get("discover_people")),
    )
    legacy_timing_ctx["profile_tabs_visible"] = bool(ui_hints.get("profile_tabs_visible"))
    _t_tabs_bottom = time.perf_counter()
    previous_tabs_bottom = _LEGACY_SAFE_LAST_TABS_BOTTOM_BY_KEY.get(stable_key)
    try:
        log(
            "info",
            "legacy_safe_tabs_bottom_probe_started",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            attempt_label=legacy_timing_ctx.get("attempt_label"),
            cached_possible=previous_tabs_bottom is not None,
            previous_tabs_bottom_y_px=previous_tabs_bottom,
        )
    except Exception:
        pass
    _prev_timing_ctx = _LEGACY_SAFE_TIMING_CONTEXT
    try:
        globals()["_LEGACY_SAFE_TIMING_CONTEXT"] = legacy_timing_ctx
        tabs_bt, _phase = _followers_profile_tabs_bottom_y_px(d, window_h=int(wh))
    except Exception:
        tabs_bt = None
        _phase = ""
    finally:
        globals()["_LEGACY_SAFE_TIMING_CONTEXT"] = _prev_timing_ctx
    try:
        log(
            "info",
            "legacy_safe_tabs_bottom_probe_completed",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            attempt_label=legacy_timing_ctx.get("attempt_label"),
            duration_ms=round((time.perf_counter() - _t_tabs_bottom) * 1000.0, 2),
            source=str(_phase or ""),
            tabs_bottom_y_px=int(tabs_bt) if tabs_bt is not None else None,
            cached_possible=previous_tabs_bottom is not None,
            stable_vs_previous=(
                previous_tabs_bottom is not None
                and tabs_bt is not None
                and int(previous_tabs_bottom) == int(tabs_bt)
            ),
        )
    except Exception:
        pass
    _log_timing(
        "legacy_safe_timing_tabs_bottom_completed",
        _t_tabs_bottom,
        tabs_bottom_found=tabs_bt is not None,
        profile_tabs_bottom_y_px=int(tabs_bt) if tabs_bt is not None else None,
        phase=str(_phase or ""),
    )
    if tabs_bt is None:
        return _finish("legacy_visual_top_left_candidate_ambiguous")
    margin = int(_POST_FOLLOW_PROFILE_TABS_GRID_MARGIN_PX)
    y_floor = int(tabs_bt) + margin
    if y_floor > int(wh * float(_POST_FOLLOW_LIKE_HIGHLIGHTS_BLOCKING_Y_MIN_RATIO)):
        return _finish(
            "legacy_visual_top_left_candidate_ambiguous",
            profile_tabs_bottom_y_px=int(tabs_bt),
            dynamic_first_row_search_y_min_px=int(y_floor),
        )

    if strict_grid_mode == "always":
        _run_strict_grid_proof("always", ui_hints=ui_hints, ww=int(ww), wh=int(wh))

    _ensure_debug_dirs()
    shot_path = str(
        _SCREENSHOTS_DIR
        / f"vision_open_top_left_legacy_safe_{int(time.time() * 1000)}.png"
    )
    try:
        _t_screenshot = time.perf_counter()
        screenshot(d, shot_path)
        _log_timing(
            "legacy_safe_timing_screenshot_capture_completed",
            _t_screenshot,
        )
        from PIL import Image

        _t_pil_open = time.perf_counter()
        im = Image.open(shot_path).convert("RGB")
        iw, ih = im.size
        _log_timing(
            "legacy_safe_timing_pil_open_completed",
            _t_pil_open,
            image_width=int(iw),
            image_height=int(ih),
        )
    except Exception as e:
        return _finish("legacy_visual_top_left_failed", error=str(e)[:160])

    _t_dynamic_scan = time.perf_counter()
    reusable_tabs_bottom: int | None = None
    reusable_tabs_source = ""
    if tabs_bt is not None:
        try:
            tabs_bt_i = int(tabs_bt)
        except (TypeError, ValueError):
            tabs_bt_i = -1
        if 0 < tabs_bt_i < int(ih):
            reusable_tabs_bottom = tabs_bt_i
            reusable_tabs_source = str(_phase or "")
    try:
        log(
            "info",
            "post_like_surface_context_reused",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            scope="legacy_safe_same_attempt_tabs_bottom",
            known_tabs_bottom_y_px=reusable_tabs_bottom,
            known_tabs_bottom_source=reusable_tabs_source,
            reused=reusable_tabs_bottom is not None,
            reason=(
                "same_attempt_post_scroll_tabs_bottom"
                if reusable_tabs_bottom is not None
                else "tabs_bottom_absent_or_invalid"
            ),
        )
    except Exception:
        pass
    (
        search_y_min_px,
        search_y_min_source,
        profile_tabs_bottom_y_px,
        profile_tabs_grid_margin_px,
    ) = _post_follow_dynamic_first_row_search_y_min_layout(
        d,
        int(ih),
        ui_hints,
        known_tabs_bottom_y_px=reusable_tabs_bottom,
        known_tabs_bottom_source=reusable_tabs_source,
    )
    if (
        str(search_y_min_source) != "profile_tabs_bottom"
        or profile_tabs_bottom_y_px is None
    ):
        return _finish(
            "legacy_visual_top_left_candidate_ambiguous",
            dynamic_first_row_search_y_min_source=str(search_y_min_source),
            suggested_for_you=bool(ui_hints.get("suggested_for_you")),
            discover_people=bool(ui_hints.get("discover_people")),
        )

    dyn = _dynamic_first_post_grid_row_from_image(
        im,
        int(iw),
        int(ih),
        var_thr=float(_POST_FOLLOW_LIKES_GRID_VAR_THR),
        search_y_min_px=int(search_y_min_px),
    )
    _log_timing(
        "legacy_safe_timing_dynamic_row_scan_completed",
        _t_dynamic_scan,
        ok=bool(dyn.get("ok")),
        dynamic_first_row_search_y_min_px=int(search_y_min_px),
        dynamic_first_row_search_y_min_source=str(search_y_min_source),
        profile_tabs_bottom_y_px=(
            int(profile_tabs_bottom_y_px)
            if profile_tabs_bottom_y_px is not None
            else None
        ),
        dynamic_first_row_top=dyn.get("first_row_top"),
        dynamic_first_row_solid_count=dyn.get("solid_count"),
    )
    if not bool(dyn.get("ok")):
        if strict_grid_mode == "fallback":
            _run_strict_grid_proof(
                "dynamic_row_scan_failed",
                ui_hints=ui_hints,
                ww=int(ww),
                wh=int(wh),
            )
        return _finish(
            "legacy_visual_top_left_variance_insufficient",
            screenshot_path=shot_path,
            dynamic_first_row_search_y_min_px=int(search_y_min_px),
        )
    _t_candidate_selection = time.perf_counter()
    cell_w = max(24, int(iw) // 3)
    cell_h = cell_w
    x0 = 0
    try:
        y0 = int(dyn.get("first_row_top"))
    except (TypeError, ValueError):
        return _finish("legacy_visual_top_left_candidate_ambiguous")
    if y0 < int(profile_tabs_bottom_y_px) + int(profile_tabs_grid_margin_px):
        return _finish(
            "legacy_visual_top_left_above_tabs",
            cell_top_y_px=int(y0),
            profile_tabs_bottom_y_px=int(profile_tabs_bottom_y_px),
            profile_tabs_grid_margin_px=int(profile_tabs_grid_margin_px),
        )
    if y0 + cell_h > int(ih) or y0 > int(ih * 0.82):
        return _finish(
            "legacy_visual_top_left_candidate_ambiguous",
            cell_top_y_px=int(y0),
            cell_h=int(cell_h),
        )
    try:
        variance = _visual_image_cell_luma_variance(im, x0, y0, cell_w, cell_h)
    except Exception:
        variance = 0.0
    if float(variance) < float(_POST_FOLLOW_LIKES_GRID_VAR_THR):
        if strict_grid_mode == "fallback":
            _run_strict_grid_proof(
                "variance_insufficient",
                ui_hints=ui_hints,
                ww=int(ww),
                wh=int(wh),
            )
        return _finish(
            "legacy_visual_top_left_variance_insufficient",
            selected_variance=round(float(variance), 2),
            variance_threshold=float(_POST_FOLLOW_LIKES_GRID_VAR_THR),
            screenshot_path=shot_path,
        )
    tap_x, tap_y = _visual_grid_cell_tap_xy_device(
        x0,
        y0,
        cell_w,
        cell_h,
        iw=int(iw),
        ih=int(ih),
        ww=int(ww),
        wh=int(wh),
        tap_frac_x=float(_POST_FOLLOW_GRID_CELL_TAP_FRAC_X),
        tap_frac_y=float(_POST_FOLLOW_GRID_CELL_TAP_FRAC_Y),
    )
    _log_timing(
        "legacy_safe_timing_candidate_selection_completed",
        _t_candidate_selection,
        selected_col=0,
        selected_row=0,
        selected_variance=round(float(variance), 2),
        tap_x=int(tap_x),
        tap_y=int(tap_y),
        dynamic_first_row_top=int(y0),
        dynamic_first_row_solid_count=dyn.get("solid_count"),
    )
    try:
        log(
            "info",
            "vision_open_top_left_legacy_safe_candidate_detected",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            selected_col=0,
            selected_row=0,
            selected_variance=round(float(variance), 2),
            tap_x=int(tap_x),
            tap_y=int(tap_y),
            cell_w=int(cell_w),
            cell_h=int(cell_h),
            dynamic_first_row_top=int(y0),
            dynamic_first_row_solid_count=dyn.get("solid_count"),
            screenshot_path=shot_path,
            selection_policy=_VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR,
        )
    except Exception:
        pass
    try:
        time.sleep(float(_POST_FOLLOW_RECENT_POST_OPEN_PRE_TAP_SETTLE_S))
    except Exception:
        pass
    try:
        log(
            "info",
            "like_post_open_attempted",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            tap_x=int(tap_x),
            tap_y=int(tap_y),
            action="legacy_visual_top_left_safe",
            cell_source="vision_open_top_left_legacy_safe",
            scroll_attempts=0,
            grid_exposure="legacy_visual_top_left",
        )
        d.click(int(tap_x), int(tap_y))
        log(
            "info",
            "vision_open_top_left_legacy_safe_tap_sent",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            tap_x=int(tap_x),
            tap_y=int(tap_y),
            selected_col=0,
            selected_row=0,
        )
    except Exception as e:
        return _finish("legacy_visual_top_left_failed", tap_x=int(tap_x), tap_y=int(tap_y), error=str(e)[:160])

    viewer = _visual_wait_post_viewer_opened_after_tap(
        d,
        pkg=pkg,
        expected_follower_username=str(expected_follower_username or "").strip().lstrip("@"),
        act_before=meta0.get("current_activity"),
        poll_label="legacy_top_left_tap",
        post_follow_fast=True,
    )
    try:
        log(
            "info",
            "vision_open_top_left_legacy_safe_viewer_poll_completed",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            post_detected=bool(viewer.get("post_detected")),
            detect_reason=viewer.get("detect_reason"),
            viewer_detect_path=viewer.get("viewer_detect_path"),
            viewer_open_poll_wait_ms=viewer.get("viewer_open_poll_wait_ms"),
            viewer_detect_total_ms=viewer.get("viewer_detect_total_ms"),
        )
    except Exception:
        pass
    if not bool(viewer.get("post_detected")):
        return _finish(
            "legacy_visual_top_left_viewer_not_confirmed",
            tap_x=int(tap_x),
            tap_y=int(tap_y),
            viewer_detect_path=viewer.get("viewer_detect_path"),
            detect_reason=viewer.get("detect_reason"),
        )
    _stash_post_follow_open_like_proof(
        dict(viewer),
        source_profile_username=source_profile_username,
        follower_username=expected_follower_username,
        proof_source="legacy_safe",
    )
    perf = {
        **dict(viewer),
        "legacy_visual_top_left_total_ms": round((time.perf_counter() - t0) * 1000.0, 2),
        "legacy_visual_top_left": True,
        "open_strategy": "vision_open_top_left_legacy_safe",
        "selected_col": 0,
        "selected_row": 0,
        "selected_variance": round(float(variance), 2),
        "screenshot_path": shot_path,
        "elapsed_from_phase_start_ms": _likes_perf_elapsed_ms(likes_perf_phase_t0),
    }
    try:
        log(
            "info",
            "vision_open_top_left_legacy_safe_success",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=expected_follower_username,
            post_index=int(post_index),
            tap_x=int(tap_x),
            tap_y=int(tap_y),
            detect_reason=viewer.get("detect_reason"),
            viewer_detect_path=viewer.get("viewer_detect_path"),
        )
    except Exception:
        pass
    return {
        "ok": True,
        "post_detected": True,
        "failure_reason": "",
        "open_strategy": "vision_open_top_left_legacy_safe",
        "tap_x": int(tap_x),
        "tap_y": int(tap_y),
        "strict_grid_proof_mode": strict_grid_mode,
        "strict_grid_proof_ok": bool(strict_grid_proof_ok),
        "strict_grid_proof_source": str(strict_grid_proof_source or ""),
        "detect_reason": viewer.get("detect_reason"),
        "viewer_detect_path": viewer.get("viewer_detect_path"),
        "post_open_snapshot_xml": viewer.get("post_open_snapshot_xml"),
        "post_open_snapshot_captured_at_monotonic": viewer.get(
            "post_open_snapshot_captured_at_monotonic"
        ),
        "post_open_snapshot_valid": bool(viewer.get("post_open_snapshot_valid")),
        "likes_perf_post_open": perf,
        "tap_to_viewer_detected_ms": viewer.get("viewer_detect_total_ms"),
    }


def _visual_select_profile_grid_cell(
    im: Any,
    *,
    iw: int,
    ih: int,
    grid_y0: int,
    grid_y1: int,
    selection_policy: str,
    var_thr: float = 120.0,
) -> tuple[tuple[int, int, int, int, float] | None, list[dict[str, Any]]]:
    cols = 3
    cell_w = max(24, iw // cols)
    cell_h = cell_w
    if selection_policy == _VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR:
        scan_order = [(0, 0), (1, 0), (2, 0)]
    else:
        scan_order = [(0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (2, 1)]

    ordered_candidates: list[dict[str, Any]] = []
    chosen: tuple[int, int, int, int, float] | None = None
    for col, row in scan_order:
        x0 = col * cell_w
        y0 = grid_y0 + row * cell_h
        if y0 + cell_h > grid_y1 or x0 + cell_w > iw:
            ordered_candidates.append(
                {
                    "col": col,
                    "row": row,
                    "eligible": False,
                    "variance": 0.0,
                    "reason": "out_of_grid_band",
                }
            )
            continue
        v = _visual_image_cell_luma_variance(im, x0, y0, cell_w, cell_h)
        eligible = bool(v >= var_thr)
        ordered_candidates.append(
            {
                "col": col,
                "row": row,
                "eligible": eligible,
                "variance": round(float(v), 2),
            }
        )
        if not eligible:
            continue
        if selection_policy == _VISUAL_POST_OPEN_SELECTION_FIRST_ROW_LTR:
            chosen = (col, row, x0, y0, v)
            break
        if chosen is None or v > chosen[4]:
            chosen = (col, row, x0, y0, v)
    return chosen, ordered_candidates


def _visual_detect_post_viewer_stage_ms(t0: float) -> float:
    return round((time.perf_counter() - t0) * 1000.0, 2)


