def visual_return_to_profile_from_post(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """Single Back from post/reel viewer toward profile; verify profile chrome. No scroll."""
    pkg = str(getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    meta0 = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_return_to_profile_started",
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
    )
    try:
        d.press("back")
    except Exception as e:
        meta = _followers_current_pkg_activity(d)
        log(
            "error",
            "visual_return_to_profile_failed",
            source_profile_username=source_profile_username or "",
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
            profile_detected=False,
            failure_reason=str(e),
        )
        return {
            "ok": False,
            "profile_detected": False,
            "current_activity": meta.get("current_activity"),
            "current_package": meta.get("current_package"),
            "source_profile_username": source_profile_username or "",
            "failure_reason": str(e),
        }

    poll_out = _visual_wait_profile_after_back(d, pkg=pkg)
    profile_detected = bool(poll_out.get("profile_detected"))
    meta = _followers_current_pkg_activity(d)
    if profile_detected:
        log(
            "info",
            "visual_return_to_profile_success",
            source_profile_username=source_profile_username or "",
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
            profile_detected=True,
            return_profile_poll_count=poll_out.get("return_profile_poll_count"),
            return_profile_fast_confirmed=poll_out.get("return_profile_fast_confirmed"),
            return_profile_poll_wait_ms=poll_out.get("return_profile_poll_wait_ms"),
        )
        return {
            "ok": True,
            "profile_detected": True,
            "current_activity": meta.get("current_activity"),
            "current_package": meta.get("current_package"),
            "source_profile_username": source_profile_username or "",
            "failure_reason": None,
            "return_profile_poll_count": poll_out.get("return_profile_poll_count"),
            "return_profile_fast_confirmed": poll_out.get(
                "return_profile_fast_confirmed"
            ),
            "return_profile_poll_wait_ms": poll_out.get("return_profile_poll_wait_ms"),
        }

    log(
        "error",
        "visual_return_to_profile_failed",
        source_profile_username=source_profile_username or "",
        current_activity=meta.get("current_activity"),
        current_package=meta.get("current_package"),
        profile_detected=False,
        failure_reason="profile_not_verified_after_back",
        return_profile_poll_count=poll_out.get("return_profile_poll_count"),
        return_profile_fast_confirmed=poll_out.get("return_profile_fast_confirmed"),
        return_profile_poll_wait_ms=poll_out.get("return_profile_poll_wait_ms"),
    )
    return {
        "ok": False,
        "profile_detected": False,
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "source_profile_username": source_profile_username or "",
        "failure_reason": "profile_not_verified_after_back",
        "return_profile_poll_count": poll_out.get("return_profile_poll_count"),
        "return_profile_fast_confirmed": poll_out.get("return_profile_fast_confirmed"),
        "return_profile_poll_wait_ms": poll_out.get("return_profile_poll_wait_ms"),
    }


def _visual_bounds_map_to_device(
    bd: dict[str, int], iw: int, ih: int, ww: int, wh: int
) -> dict[str, int]:
    if iw <= 0 or ih <= 0:
        return dict(bd)
    return {
        "left": max(0, int(bd["left"] * ww / iw)),
        "top": max(0, int(bd["top"] * wh / ih)),
        "right": max(1, int(bd["right"] * ww / iw)),
        "bottom": max(1, int(bd["bottom"] * wh / ih)),
    }


def _visual_blue_fill_ratio_in_bounds(im: Any, bd: dict[str, int]) -> float:
    l, t, r, b = int(bd["left"]), int(bd["top"]), int(bd["right"]), int(bd["bottom"])
    if r <= l + 2 or b <= t + 2:
        return 0.0
    crop = im.crop((l, t, r + 1, b + 1))
    n_blue = 0
    n = 0
    for rr, gg, bb in crop.getdata():
        n += 1
        if _ig_follow_button_blue_pixel(int(rr), int(gg), int(bb)):
            n_blue += 1
    return n_blue / max(n, 1)


def visual_detect_follow_button_on_profile(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Screenshot-based blue Follow pill in the profile header action row (upper-middle right).
    """
    meta_start = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_follow_button_detect_started",
        source_profile_username=source_profile_username or "",
        current_activity=meta_start.get("current_activity"),
        current_package=meta_start.get("current_package"),
    )
    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400

    _ensure_debug_dirs()
    shot = str(
        _SCREENSHOTS_DIR / f"visual_profile_follow_{int(time.time() * 1000)}.png"
    )
    try:
        screenshot(d, shot)
    except Exception as e:
        log(
            "info",
            "visual_follow_button_not_found",
            source_profile_username=source_profile_username or "",
            follow_button_bounds=None,
            confidence=0.0,
            current_activity=meta_start.get("current_activity"),
            current_package=meta_start.get("current_package"),
            reason=f"screenshot_failed:{e}",
        )
        return {
            "ok": False,
            "follow_button_bounds": None,
            "tap_x": None,
            "tap_y": None,
            "confidence": 0.0,
            "button_type": "follow",
            "failure_reason": f"screenshot_failed:{e}",
        }

    try:
        from PIL import Image

        im = Image.open(shot).convert("RGB")
    except Exception as e:
        log(
            "info",
            "visual_follow_button_not_found",
            source_profile_username=source_profile_username or "",
            follow_button_bounds=None,
            confidence=0.0,
            current_activity=meta_start.get("current_activity"),
            current_package=meta_start.get("current_package"),
            reason=f"pil_failed:{e}",
        )
        return {
            "ok": False,
            "follow_button_bounds": None,
            "tap_x": None,
            "tap_y": None,
            "confidence": 0.0,
            "button_type": "follow",
            "failure_reason": f"pil_failed:{e}",
        }

    iw, ih = im.size
    x0, x1 = int(iw * 0.40), iw - 2
    y0, y1 = int(ih * 0.10), int(ih * 0.36)
    tb = _visual_tight_blue_bounds(im, left=x0, top=y0, right=x1, bottom=y1)
    if tb is None or (tb["right"] - tb["left"]) > int(iw * 0.44):
        x1n = int(iw * 0.68)
        tb = _visual_tight_blue_bounds(im, left=x0, top=y0, right=x1n, bottom=y1)
    if tb is None:
        log(
            "info",
            "visual_follow_button_not_found",
            source_profile_username=source_profile_username or "",
            follow_button_bounds=None,
            confidence=0.0,
            current_activity=meta_start.get("current_activity"),
            current_package=meta_start.get("current_package"),
            reason="no_blue_pill_in_header_roi",
        )
        return {
            "ok": False,
            "follow_button_bounds": None,
            "tap_x": None,
            "tap_y": None,
            "confidence": 0.0,
            "button_type": "follow",
            "failure_reason": "no_blue_pill_in_header_roi",
        }

    ratio = _visual_blue_fill_ratio_in_bounds(im, tb)
    confidence = float(min(0.97, 0.35 + ratio * 1.15))
    bd_dev = _visual_bounds_map_to_device(tb, iw, ih, ww, wh)
    tap_x = (bd_dev["left"] + bd_dev["right"]) // 2
    tap_y = (bd_dev["top"] + bd_dev["bottom"]) // 2
    tap_x = max(2, min(ww - 3, tap_x))
    tap_y = max(2, min(wh - 3, tap_y))

    meta_end = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_follow_button_detected",
        source_profile_username=source_profile_username or "",
        follow_button_bounds=bd_dev,
        tap_x=tap_x,
        tap_y=tap_y,
        confidence=round(confidence, 4),
        button_type="follow",
        current_activity=meta_end.get("current_activity"),
        current_package=meta_end.get("current_package"),
    )
    return {
        "ok": True,
        "follow_button_bounds": bd_dev,
        "tap_x": tap_x,
        "tap_y": tap_y,
        "confidence": confidence,
        "button_type": "follow",
        "failure_reason": None,
    }


def _exists_follow_verify_ui_message(d: u2.Device) -> bool:
    try:
        return bool(d(textContains="Message").exists(timeout=0.08))
    except Exception:
        return False


def visual_profile_already_following_before_follow(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    True when profile header already shows Following / Requested (skip Follow tap).
    """
    meta = _followers_current_pkg_activity(d)
    base = {
        "already_following": False,
        "detection_method": "none",
        "confidence": 0.0,
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "source_profile_username": source_profile_username or "",
    }

    # Avoid textContains="Following" — it matches profile stats ("123 Following").
    ui_triples: list[tuple[str, Callable[[], object], float]] = [
        ("ui_text_following_exact", lambda: d(text="Following"), 0.9),
        ("ui_text_requested", lambda: d(textContains="Requested"), 0.91),
        ("ui_text_suivi_exact", lambda: d(text="Suivi(e)"), 0.88),
        ("ui_text_suivi_exact2", lambda: d(text="Suivi"), 0.86),
        ("ui_text_abonne", lambda: d(text="Abonné(e)"), 0.86),
        ("ui_text_abonne2", lambda: d(text="Abonné"), 0.84),
        ("ui_text_siguiendo", lambda: d(text="Siguiendo"), 0.86),
        ("ui_text_solicitado", lambda: d(textContains="Solicitado"), 0.88),
        ("ui_text_gefolgt", lambda: d(text="Gefolgt"), 0.84),
        ("ui_text_angefragt", lambda: d(textContains="Angefragt"), 0.88),
        ("ui_desc_following_btn", lambda: d(descriptionContains="Following button"), 0.87),
        ("ui_desc_requested", lambda: d(descriptionContains="Requested"), 0.89),
    ]
    for method, pred, conf in ui_triples:
        try:
            if pred().exists(timeout=0.12):
                out = dict(base)
                out["already_following"] = True
                out["detection_method"] = method
                out["confidence"] = conf
                return out
        except Exception:
            continue

    hier = ""
    try:
        hier = str(d.dump_hierarchy(compressed=False))
    except Exception:
        try:
            hier = str(d.dump_hierarchy())
        except Exception:
            hier = ""
    hl = hier.lower()
    if "requested" in hl:
        out = dict(base)
        out["already_following"] = True
        out["detection_method"] = "hierarchy_requested"
        out["confidence"] = 0.78
        return out
    # Narrow: stats row often contains lowercase "following"; require explicit button attrs.
    if (
        'content-desc="Following"' in hier
        or 'content-desc="Suivi' in hier
        or 'content-desc="Siguiendo"' in hier
    ):
        out = dict(base)
        out["already_following"] = True
        out["detection_method"] = "hierarchy_follow_button_content_desc"
        out["confidence"] = 0.76
        return out
    if "demande envoyée" in hl or "demandé" in hl or "suivi(e)" in hl:
        out = dict(base)
        out["already_following"] = True
        out["detection_method"] = "hierarchy_fr_requested_or_following"
        out["confidence"] = 0.72
        return out

    return base


def _visual_follow_request_pending_state(d: u2.Device) -> tuple[bool, str]:
    """
    True when the profile header shows a pending follow request (private account),
    not an established Following relationship.
    """
    try:
        if d(descriptionContains="Following button").exists(timeout=0.14):
            return False, "following_button_present"
    except Exception:
        pass
    try:
        if d(text="Following").exists(timeout=0.12):
            return False, "text_following_exact"
    except Exception:
        pass
    desc_checks: list[tuple[str, Callable[[], object]]] = [
        ("ui_descContains_requested", lambda: d(descriptionContains="Requested")),
        ("ui_descContains_request_sent", lambda: d(descriptionContains="Request sent")),
        (
            "ui_descContains_demande_envoyee",
            lambda: d(descriptionContains="Demande envoyée"),
        ),
        ("ui_descContains_solicitado", lambda: d(descriptionContains="Solicitado")),
    ]
    for name, pred in desc_checks:
        try:
            if pred().exists(timeout=0.12):
                return True, name
        except Exception:
            continue
    checks: list[tuple[str, Callable[[], object]]] = [
        ("ui_text_requested_exact", lambda: d(text="Requested")),
        ("ui_textContains_requested", lambda: d(textContains="Requested")),
        ("ui_textContains_request_sent", lambda: d(textContains="Request sent")),
        ("ui_textContains_request_pending", lambda: d(textContains="Request pending")),
        ("ui_textContains_demande_envoyee", lambda: d(textContains="Demande envoyée")),
        ("ui_textContains_demande_envoyee_plain", lambda: d(text="Demande envoyée")),
        ("ui_textContains_demande", lambda: d(textContains="Demandé")),
        ("ui_textContains_en_attente", lambda: d(textContains="En attente")),
        ("ui_textContains_solicitado", lambda: d(textContains="Solicitado")),
        (
            "ui_textContains_solicitud_enviada",
            lambda: d(textContains="Solicitud enviada"),
        ),
        ("ui_textContains_angefragt", lambda: d(textContains="Angefragt")),
        (
            "ui_textContains_anfrage_gesendet",
            lambda: d(textContains="Anfrage gesendet"),
        ),
        (
            "ui_textContains_richiesta_inviata",
            lambda: d(textContains="Richiesta inviata"),
        ),
    ]
    for name, pred in checks:
        try:
            if pred().exists(timeout=0.14):
                return True, name
        except Exception:
            continue
    try:
        hl = str(d.dump_hierarchy(compressed=False)).lower()
    except Exception:
        try:
            hl = str(d.dump_hierarchy()).lower()
        except Exception:
            hl = ""
    if "request sent" in hl or "request pending" in hl:
        return True, "hierarchy_request_sent_or_pending"
    if "demande envoyée" in hl or "demande envoyee" in hl:
        return True, "hierarchy_demande_envoyee"
    if "solicitud enviada" in hl or "solicitud pendiente" in hl:
        return True, "hierarchy_es_request"
    if "anfrage gesendet" in hl or "angefragt" in hl:
        return True, "hierarchy_de_request"
    if "richiesta inviata" in hl:
        return True, "hierarchy_it_request"
    return False, ""


def _visual_profile_header_blue_follow_pill_weak(
    im: Any, iw: int, ih: int
) -> tuple[bool, float]:
    """True when a strong blue Follow pill is absent or very faint (post-follow transition hint)."""
    x0, x1 = int(iw * 0.40), iw - 2
    y0, y1 = int(ih * 0.10), int(ih * 0.36)
    tb = _visual_tight_blue_bounds(im, left=x0, top=y0, right=x1, bottom=y1)
    if tb is None:
        return True, 0.74
    ratio = _visual_blue_fill_ratio_in_bounds(im, tb)
    if ratio < 0.072:
        return True, 0.62
    return False, 0.0


def visual_verify_profile_followed(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
    tap_x: int | None = None,
    tap_y: int | None = None,
    follow_button_bounds: dict[str, int] | None = None,
    detect_confidence: float | None = None,
) -> dict[str, Any]:
    """
    Poll after a real Follow tap: Following / Requested / hierarchy / header screenshot heuristics.
    """
    timeout_s = float(getattr(config, "VISUAL_FOLLOW_VERIFY_TIMEOUT_S", 3.0) or 3.0)
    deadline = time.time() + max(0.5, timeout_s)
    meta0 = _followers_current_pkg_activity(d)
    dc = float(detect_confidence) if detect_confidence is not None else 0.0
    log(
        "info",
        "visual_follow_profile_verify_started",
        tap_x=tap_x,
        tap_y=tap_y,
        follow_button_bounds=follow_button_bounds,
        confidence=round(dc, 4),
        verification_method="polling",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
        source_profile_username=source_profile_username or "",
    )

    def _ui_follow_state_ok() -> tuple[bool, str, float]:
        checks: list[tuple[str, Callable[[], object], float]] = [
            ("ui_following", lambda: d(textContains="Following"), 0.9),
            ("ui_requested", lambda: d(textContains="Requested"), 0.92),
            ("ui_suivi", lambda: d(textContains="Suivi"), 0.86),
            ("ui_siguiendo", lambda: d(textContains="Siguiendo"), 0.86),
            ("ui_message_near_row", lambda: d(textContains="Message"), 0.68),
            ("ui_desc_following", lambda: d(descriptionContains="Following"), 0.87),
        ]
        for method, pred, conf in checks:
            try:
                if pred().exists(timeout=0.14):
                    return True, method, conf
            except Exception:
                continue
        return False, "", 0.0

    def _hierarchy_follow_ok(hier_s: str) -> bool:
        h = hier_s.lower()
        if "requested" in h:
            return True
        if "following" in h and "content-desc=\"follow\"" not in h:
            return True
        if "suivi" in h or "siguiendo" in h or "demandé" in h:
            return True
        return False

    poll = 0.35
    attempt = 0
    while time.time() < deadline:
        attempt += 1
        meta_a = _followers_current_pkg_activity(d)
        log(
            "info",
            "visual_follow_profile_verify_attempt",
            attempt=attempt,
            tap_x=tap_x,
            tap_y=tap_y,
            follow_button_bounds=follow_button_bounds,
            confidence=round(dc, 4),
            verification_method="ui_hierarchy_visual",
            current_activity=meta_a.get("current_activity"),
            current_package=meta_a.get("current_package"),
            source_profile_username=source_profile_username or "",
        )

        ok_u, method_u, conf_u = _ui_follow_state_ok()
        if ok_u and method_u != "ui_message_near_row":
            meta = _followers_current_pkg_activity(d)
            log(
                "info",
                "visual_follow_profile_verify_success",
                tap_x=tap_x,
                tap_y=tap_y,
                follow_button_bounds=follow_button_bounds,
                verification_method=method_u,
                confidence=round(conf_u, 4),
                current_activity=meta.get("current_activity"),
                current_package=meta.get("current_package"),
                source_profile_username=source_profile_username or "",
            )
            return {
                "follow_verified": True,
                "verification_method": method_u,
                "confidence": conf_u,
            }
        if ok_u and method_u == "ui_message_near_row":
            hier_quick = ""
            try:
                hier_quick = str(d.dump_hierarchy(compressed=False))
            except Exception:
                try:
                    hier_quick = str(d.dump_hierarchy())
                except Exception:
                    hier_quick = ""
            if _hierarchy_follow_ok(hier_quick) or "following" in hier_quick.lower():
                meta = _followers_current_pkg_activity(d)
                conf_msg = 0.81
                log(
                    "info",
                    "visual_follow_profile_verify_success",
                    tap_x=tap_x,
                    tap_y=tap_y,
                    follow_button_bounds=follow_button_bounds,
                    verification_method="ui_message_plus_hierarchy",
                    confidence=conf_msg,
                    current_activity=meta.get("current_activity"),
                    current_package=meta.get("current_package"),
                    source_profile_username=source_profile_username or "",
                )
                return {
                    "follow_verified": True,
                    "verification_method": "ui_message_plus_hierarchy",
                    "confidence": conf_msg,
                }

        hier = ""
        try:
            hier = str(d.dump_hierarchy(compressed=False))
        except Exception:
            try:
                hier = str(d.dump_hierarchy())
            except Exception:
                hier = ""
        if _hierarchy_follow_ok(hier):
            meta = _followers_current_pkg_activity(d)
            conf_h = 0.77
            log(
                "info",
                "visual_follow_profile_verify_success",
                tap_x=tap_x,
                tap_y=tap_y,
                follow_button_bounds=follow_button_bounds,
                verification_method="hierarchy_follow_state",
                confidence=conf_h,
                current_activity=meta.get("current_activity"),
                current_package=meta.get("current_package"),
                source_profile_username=source_profile_username or "",
            )
            return {
                "follow_verified": True,
                "verification_method": "hierarchy_follow_state",
                "confidence": conf_h,
            }

        try:
            _ensure_debug_dirs()
            shot = str(
                _SCREENSHOTS_DIR
                / f"visual_follow_verify_{int(time.time() * 1000)}.png"
            )
            screenshot(d, shot)
            from PIL import Image

            im = Image.open(shot).convert("RGB")
            iw, ih = im.size
            gone, conf_v = _visual_profile_header_blue_follow_pill_weak(im, iw, ih)
            if gone and (
                _exists_follow_verify_ui_message(d)
                or _hierarchy_follow_ok(hier)
            ):
                conf_f = float(min(0.88, conf_v + 0.12))
                meta = _followers_current_pkg_activity(d)
                log(
                    "info",
                    "visual_follow_profile_verify_success",
                    tap_x=tap_x,
                    tap_y=tap_y,
                    follow_button_bounds=follow_button_bounds,
                    verification_method="visual_blue_follow_gone",
                    confidence=round(conf_f, 4),
                    current_activity=meta.get("current_activity"),
                    current_package=meta.get("current_package"),
                    source_profile_username=source_profile_username or "",
                )
                return {
                    "follow_verified": True,
                    "verification_method": "visual_blue_follow_gone",
                    "confidence": conf_f,
                }
        except Exception:
            pass

        time.sleep(poll)

    meta_f = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_follow_profile_verify_failed",
        tap_x=tap_x,
        tap_y=tap_y,
        follow_button_bounds=follow_button_bounds,
        verification_method="none",
        confidence=round(dc, 4),
        current_activity=meta_f.get("current_activity"),
        current_package=meta_f.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    return {
        "follow_verified": False,
        "verification_method": "none",
        "confidence": 0.0,
    }


def _visual_read_action_bar_username(d: u2.Device) -> str:
    try:
        ab = d(resourceIdMatches=r".*:id/action_bar_title.*")
        if ab.exists(timeout=0.18):
            return str(ab.get_text() or "").strip()
    except Exception:
        pass
    return ""


def _visual_profile_header_avatar_boxes(iw: int, ih: int) -> tuple[dict[str, int], dict[str, int]]:
    hl, ht, hr = 0, int(ih * 0.06), iw
    hb = int(ih * 0.28)
    header_bounds = {"left": hl, "top": ht, "right": hr, "bottom": hb}
    avatar_bounds = {
        "left": int(iw * 0.04),
        "top": int(ih * 0.10),
        "right": int(iw * 0.30),
        "bottom": int(ih * 0.24),
    }
    return header_bounds, avatar_bounds


def _visual_average_hash_64(im_rgb: Any) -> int:
    from PIL import Image

    g = im_rgb.resize((8, 8), Image.Resampling.LANCZOS).convert("L")
    pixels = list(g.getdata())
    avg = sum(pixels) / 64.0
    bits = 0
    for i, p in enumerate(pixels):
        if p >= avg:
            bits |= 1 << i
    return bits


def _visual_dominant_rgb_simple(im_rgb: Any) -> tuple[int, int, int]:
    from PIL import Image

    small = im_rgb.resize((12, 12), Image.Resampling.LANCZOS)
    r_sum = g_sum = b_sum = 0
    n = 144
    for px in small.getdata():
        r_sum += px[0]
        g_sum += px[1]
        b_sum += px[2]
    return (r_sum // n, g_sum // n, b_sum // n)


def _visual_header_structure_key(im_rgb: Any) -> str:
    from PIL import Image

    g = im_rgb.resize((4, 4), Image.Resampling.LANCZOS).convert("L")
    return "".join(f"{int(v) // 17:x}" for v in g.getdata())


def _visual_compute_profile_fingerprint(
    *,
    ahash_64: int,
    avatar_ahash_64: int,
    dominant_rgb: tuple[int, int, int],
    structure_key: str,
    username_norm: str,
) -> str:
    raw = (
        f"{ahash_64:016x}|{avatar_ahash_64:016x}|"
        f"{dominant_rgb[0]},{dominant_rgb[1]},{dominant_rgb[2]}|"
        f"{structure_key}|{username_norm}"
    )
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def visual_capture_profile_context(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Capture a lightweight visual fingerprint of the current Instagram screen (profile or post).
    Uses header crop average-hash, avatar ROI hash, dominant colour, coarse 4x4 structure,
    and action-bar title text when visible (no heavy OCR).
    """
    meta = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_profile_context_capture_started",
        current_activity=meta.get("current_activity"),
        current_package=meta.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    header_username = _visual_read_action_bar_username(d)
    username_norm = _normalize_handle(header_username)

    def _fail_payload(reason: str, shot: str = "") -> dict[str, Any]:
        log(
            "warning",
            "visual_profile_context_capture_failed",
            ok=False,
            failure_reason=reason,
            screenshot_path=shot,
            profile_fingerprint="",
            username_norm=username_norm,
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        return {
            "ok": False,
            "profile_context_id": "",
            "header_username_detected": header_username,
            "username_norm": username_norm,
            "avatar_bounds": {},
            "profile_header_bounds": {},
            "profile_visual_fingerprint": "",
            "profile_fingerprint": "",
            "screenshot_path": shot,
            "profile_screenshot_path": shot,
            "confidence": 0.0,
            "header_hash": 0,
            "avatar_hash": 0,
            "ahash_64": 0,
            "avatar_ahash_64": 0,
            "dominant_color": (0, 0, 0),
            "dominant_rgb": (0, 0, 0),
            "structure_key": "",
            "current_activity": meta.get("current_activity"),
            "current_package": meta.get("current_package"),
            "failure_reason": reason,
        }

    shot_path = ""
    try:
        _ensure_debug_dirs()
        shot_file = (
            _SCREENSHOTS_DIR
            / f"visual_profile_context_{int(time.time() * 1000)}.png"
        )
        screenshot(d, str(shot_file))
        shot_path = str(shot_file)
    except Exception as e:
        return _fail_payload(f"screenshot:{e}", shot="")

    from PIL import Image

    try:
        im = Image.open(shot_path).convert("RGB")
    except Exception as e:
        return _fail_payload(f"pil:{e}", shot=shot_path)

    iw, ih = im.size
    hb_b, av_b = _visual_profile_header_avatar_boxes(iw, ih)
    header_im = im.crop((hb_b["left"], hb_b["top"], hb_b["right"], hb_b["bottom"]))
    avatar_im = im.crop((av_b["left"], av_b["top"], av_b["right"], av_b["bottom"]))
    ahash_64 = _visual_average_hash_64(header_im)
    avatar_ahash_64 = _visual_average_hash_64(avatar_im)
    dom = _visual_dominant_rgb_simple(header_im)
    struct_key = _visual_header_structure_key(header_im)
    fp = _visual_compute_profile_fingerprint(
        ahash_64=ahash_64,
        avatar_ahash_64=avatar_ahash_64,
        dominant_rgb=dom,
        structure_key=struct_key,
        username_norm=username_norm,
    )
    ctx_id = fp[:16]
    cap_conf = 0.72 + (0.12 if username_norm else 0.0) + (
        0.06 if header_username else 0.0
    )
    cap_conf = float(min(0.93, cap_conf))

    log(
        "info",
        "visual_profile_context_captured",
        screenshot_path=shot_path,
        profile_fingerprint=fp,
        username_norm=username_norm,
        current_activity=meta.get("current_activity"),
        current_package=meta.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    return {
        "ok": True,
        "profile_context_id": ctx_id,
        "header_username_detected": header_username,
        "username_norm": username_norm,
        "avatar_bounds": dict(av_b),
        "profile_header_bounds": dict(hb_b),
        "profile_visual_fingerprint": fp,
        "profile_fingerprint": fp,
        "screenshot_path": shot_path,
        "profile_screenshot_path": shot_path,
        "confidence": round(cap_conf, 4),
        "header_hash": ahash_64,
        "avatar_hash": avatar_ahash_64,
        "ahash_64": ahash_64,
        "avatar_ahash_64": avatar_ahash_64,
        "dominant_color": dom,
        "dominant_rgb": dom,
        "structure_key": struct_key,
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "failure_reason": None,
    }


def _int_bit_count_compat(value: Any) -> int:
    try:
        return int(value).bit_count()
    except AttributeError:
        try:
            return bin(int(value)).count("1")
        except Exception:
            return 0
    except Exception:
        return 0


def _visual_hash_xor_hamming(exp_raw: Any, cur_raw: Any) -> int:
    """Hamming distance (popcount of XOR) for two 64-bit-ish hashes; invalid → worst case."""
    try:
        e = int(exp_raw)
        c = int(cur_raw)
    except Exception:
        return 64
    try:
        return min(64, max(0, _int_bit_count_compat(e ^ c)))
    except Exception:
        return 64


def visual_verify_same_profile_context(
    d: u2.Device,
    *,
    expected_context: dict[str, Any],
    source_profile_username: str | None = None,
    current_capture: dict[str, Any] | None = None,
) -> dict[str, Any]:
    meta = _followers_current_pkg_activity(d)
    exp_fp = str(
        expected_context.get("profile_visual_fingerprint")
        or expected_context.get("profile_fingerprint")
        or ""
    )
    exp_u = _normalize_handle(str(expected_context.get("header_username_detected") or ""))
    src_n = _normalize_handle(source_profile_username or "")
    base_log: dict[str, Any] = {
        "expected_profile_fingerprint": exp_fp,
        "current_profile_fingerprint": "",
        "confidence": 0.0,
        "same_profile": False,
        "verification_method": "",
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "source_profile_username": source_profile_username or "",
    }
    log("info", "visual_profile_context_verify_started", **base_log)

    min_c = float(
        getattr(config, "VISUAL_PROFILE_CONTEXT_MIN_MATCH_CONFIDENCE", 0.72) or 0.72
    )

    if current_capture is not None:
        cur = current_capture
    else:
        cur = visual_capture_profile_context(
            d, source_profile_username=source_profile_username
        )
    cur_fp = str(
        cur.get("profile_visual_fingerprint") or cur.get("profile_fingerprint") or ""
    )
    base_log["current_profile_fingerprint"] = cur_fp

    if cur.get("ok") is False or not cur_fp:
        verification_method = "current_capture_empty_or_failed"
        fail_reason = str(cur.get("failure_reason") or "empty_profile_fingerprint")
        log_payload = {
            **base_log,
            "same_profile": False,
            "confidence": 0.0,
            "verification_method": verification_method,
            "expected_profile_fingerprint": exp_fp,
            "current_profile_fingerprint": cur_fp,
            "current_capture_failure_reason": fail_reason,
            "current_capture_screenshot_path": str(
                cur.get("screenshot_path") or cur.get("profile_screenshot_path") or ""
            ),
        }
        log("info", "visual_profile_context_verify_failed", **log_payload)
        return {
            "same_profile": False,
            "confidence": 0.0,
            "verification_method": verification_method,
            "current_profile_fingerprint": cur_fp,
            "expected_profile_fingerprint": exp_fp,
            "username_conflict": False,
            "visual_similarity": 0.0,
            "current_capture_failure_reason": fail_reason,
            "current_capture_screenshot_path": log_payload[
                "current_capture_screenshot_path"
            ],
        }

    exp_h = expected_context.get("ahash_64")
    if exp_h is None:
        exp_h = expected_context.get("header_hash")
    cur_h = cur.get("ahash_64")
    if cur_h is None:
        cur_h = cur.get("header_hash")
    ham_h = (
        64
        if exp_h is None or cur_h is None
        else _visual_hash_xor_hamming(exp_h, cur_h)
    )

    exp_av = expected_context.get("avatar_ahash_64")
    if exp_av is None:
        exp_av = expected_context.get("avatar_hash")
    cur_av = cur.get("avatar_ahash_64")
    if cur_av is None:
        cur_av = cur.get("avatar_hash")
    ham_av = (
        64
        if exp_av is None or cur_av is None
        else _visual_hash_xor_hamming(exp_av, cur_av)
    )
    visual_sim = 1.0 - (ham_h + ham_av) / 128.0
    visual_sim = max(0.0, min(1.0, visual_sim))

    exp_struct = str(expected_context.get("structure_key") or "")
    cur_struct = str(cur.get("structure_key") or "")
    if exp_struct and cur_struct and exp_struct == cur_struct:
        visual_sim = min(1.0, visual_sim + 0.04)

    cur_u = _normalize_handle(str(cur.get("header_username_detected") or ""))

    username_conflict = bool(exp_u and cur_u and exp_u != cur_u)
    username_match = bool(exp_u and cur_u and exp_u == cur_u)
    src_cur_match = bool(src_n and cur_u and src_n == cur_u)
    src_exp_match = bool(src_n and exp_u and src_n == exp_u)

    verification_method = "visual_hamming"
    same_profile = False
    confidence = visual_sim

    if username_conflict:
        verification_method = "username_mismatch"
        same_profile = False
        confidence = min(0.22, visual_sim * 0.35)
    elif username_match or (src_cur_match and (not exp_u or exp_u == cur_u)):
        verification_method = "username_match+visual"
        same_profile = True
        confidence = max(visual_sim, 0.88 if username_match else 0.84)
    elif src_exp_match and not cur_u:
        verification_method = "source_expected_align+visual"
        confidence = max(visual_sim, 0.78)
        same_profile = bool(not username_conflict and visual_sim >= 0.42)
    else:
        verification_method = "visual_hamming"
        same_profile = bool(visual_sim >= min_c)
        confidence = visual_sim

    gate_ok = bool(
        same_profile and confidence >= min_c and not username_conflict
    )
    log_payload = {
        **base_log,
        "same_profile": same_profile,
        "confidence": round(float(confidence), 4),
        "verification_method": verification_method,
        "expected_profile_fingerprint": exp_fp,
        "current_profile_fingerprint": cur_fp,
    }
    if gate_ok:
        log("info", "visual_profile_context_verify_success", **log_payload)
    else:
        log("info", "visual_profile_context_verify_failed", **log_payload)

    return {
        "same_profile": same_profile,
        "confidence": round(float(confidence), 4),
        "verification_method": verification_method,
        "current_profile_fingerprint": cur_fp,
        "expected_profile_fingerprint": exp_fp,
        "username_conflict": username_conflict,
        "visual_similarity": round(float(visual_sim), 4),
    }


def visual_follow_profile_dry_run(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
    follow_detection: dict[str, Any] | None = None,
    expected_profile_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """
    Follow button from screenshot. Dry when ENABLE_REAL_VISUAL_FOLLOW is False and
    VISUAL_FOLLOW_MUTE_DRY_RUN is True (legacy). Real tap when ENABLE_REAL_VISUAL_FOLLOW is True;
    mute dryness is separate (VISUAL_FOLLOW_MUTE_DRY_RUN on visual_mute_after_follow_dry_run).
    """
    real_follow = bool(getattr(config, "ENABLE_REAL_VISUAL_FOLLOW", False))
    mute_dry = bool(getattr(config, "VISUAL_FOLLOW_MUTE_DRY_RUN", True))
    # Real Follow tap is gated only by ENABLE_REAL_VISUAL_FOLLOW. Mute dryness never blocks it.
    if real_follow:
        effective_dry = False
    else:
        effective_dry = mute_dry
    meta0 = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_follow_runtime_config",
        ENABLE_REAL_VISUAL_FOLLOW=real_follow,
        VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
        dry_effective=effective_dry,
        follow_button_detected=False,
        follow_button_bounds=None,
        tap_x=None,
        tap_y=None,
        already_following=False,
        skip_reason="",
        will_click_follow=False,
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    log(
        "info",
        "visual_follow_profile_started",
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
        dry_run=effective_dry,
        real_visual_follow=real_follow,
    )

    pre_af = visual_profile_already_following_before_follow(
        d, source_profile_username=source_profile_username
    )
    log(
        "info",
        "visual_follow_decision_debug",
        ENABLE_REAL_VISUAL_FOLLOW=real_follow,
        VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
        dry_effective=effective_dry,
        follow_button_detected=False,
        follow_button_bounds=None,
        tap_x=None,
        tap_y=None,
        already_following=bool(pre_af.get("already_following")),
        skip_reason="pre_profile_already_following_check",
        will_click_follow=False,
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    if pre_af.get("already_following"):
        meta_skip = _followers_current_pkg_activity(d)
        log(
            "info",
            "visual_follow_click_blocked_reason",
            reason="already_following_before_follow_detection",
            ENABLE_REAL_VISUAL_FOLLOW=real_follow,
            VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
            dry_effective=effective_dry,
            follow_button_detected=False,
            follow_button_bounds=None,
            tap_x=None,
            tap_y=None,
            already_following=True,
            skip_reason=pre_af.get("detection_method"),
            will_click_follow=False,
            current_activity=meta_skip.get("current_activity"),
            current_package=meta_skip.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        log(
            "info",
            "visual_follow_profile_skip_already_following",
            tap_x=None,
            tap_y=None,
            follow_button_bounds=None,
            verification_method=pre_af.get("detection_method"),
            confidence=round(float(pre_af.get("confidence") or 0.0), 4),
            current_activity=meta_skip.get("current_activity"),
            current_package=meta_skip.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        fr_rq, fr_rq_m = _visual_follow_request_pending_state(d)
        return {
            "ok": True,
            "follow_button_detected": False,
            "skip_already_following": True,
            "real_follow_tap_sent": False,
            "follow_verified": False,
            "follow_request_pending": fr_rq,
            "follow_request_pending_method": fr_rq_m,
            "tap_x": None,
            "tap_y": None,
            "follow_button_bounds": None,
            "confidence": 0.0,
            "current_activity": meta_skip.get("current_activity"),
            "current_package": meta_skip.get("current_package"),
            "source_profile_username": source_profile_username or "",
            "failure_reason": None,
            "dry_run": effective_dry,
        }

    det = follow_detection
    if det is None:
        det = visual_detect_follow_button_on_profile(
            d, source_profile_username=source_profile_username
        )
    det_ok = bool(det.get("ok"))
    f_bounds_dbg = det.get("follow_button_bounds")
    tap_x_dbg = det.get("tap_x")
    tap_y_dbg = det.get("tap_y")
    log(
        "info",
        "visual_follow_decision_debug",
        ENABLE_REAL_VISUAL_FOLLOW=real_follow,
        VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
        dry_effective=effective_dry,
        follow_button_detected=det_ok,
        follow_button_bounds=f_bounds_dbg,
        tap_x=tap_x_dbg,
        tap_y=tap_y_dbg,
        already_following=False,
        skip_reason="after_follow_button_detection",
        will_click_follow=bool(real_follow and det_ok and not effective_dry),
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    if not det.get("ok"):
        post_af = visual_profile_already_following_before_follow(
            d, source_profile_username=source_profile_username
        )
        if post_af.get("already_following"):
            meta_skip = _followers_current_pkg_activity(d)
            log(
                "info",
                "visual_follow_click_blocked_reason",
                reason="already_following_blue_follow_button_not_found",
                ENABLE_REAL_VISUAL_FOLLOW=real_follow,
                VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
                dry_effective=effective_dry,
                follow_button_detected=False,
                follow_button_bounds=det.get("follow_button_bounds"),
                tap_x=None,
                tap_y=None,
                already_following=True,
                skip_reason=post_af.get("detection_method"),
                will_click_follow=False,
                current_activity=meta_skip.get("current_activity"),
                current_package=meta_skip.get("current_package"),
                source_profile_username=source_profile_username or "",
            )
            log(
                "info",
                "visual_follow_profile_skip_already_following",
                tap_x=None,
                tap_y=None,
                follow_button_bounds=None,
                verification_method=post_af.get("detection_method"),
                confidence=round(float(post_af.get("confidence") or 0.0), 4),
                current_activity=meta_skip.get("current_activity"),
                current_package=meta_skip.get("current_package"),
                source_profile_username=source_profile_username or "",
            )
            fr_rq2, fr_rq_m2 = _visual_follow_request_pending_state(d)
            return {
                "ok": True,
                "follow_button_detected": False,
                "skip_already_following": True,
                "real_follow_tap_sent": False,
                "follow_verified": False,
                "follow_request_pending": fr_rq2,
                "follow_request_pending_method": fr_rq_m2,
                "tap_x": None,
                "tap_y": None,
                "follow_button_bounds": None,
                "confidence": 0.0,
                "current_activity": meta_skip.get("current_activity"),
                "current_package": meta_skip.get("current_package"),
                "source_profile_username": source_profile_username or "",
                "failure_reason": None,
                "dry_run": effective_dry,
            }
        log(
            "info",
            "visual_follow_click_blocked_reason",
            reason="follow_button_not_found",
            ENABLE_REAL_VISUAL_FOLLOW=real_follow,
            VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
            dry_effective=effective_dry,
            follow_button_detected=False,
            follow_button_bounds=det.get("follow_button_bounds"),
            tap_x=None,
            tap_y=None,
            already_following=False,
            skip_reason=det.get("failure_reason") or "follow_button_not_found",
            will_click_follow=False,
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        log(
            "error",
            "visual_follow_profile_failed",
            tap_x=None,
            tap_y=None,
            follow_button_bounds=det.get("follow_button_bounds"),
            confidence=0.0,
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
            source_profile_username=source_profile_username or "",
            failure_reason=det.get("failure_reason") or "follow_button_not_found",
        )
        return {
            "ok": False,
            "follow_button_detected": False,
            "skip_already_following": False,
            "real_follow_tap_sent": False,
            "follow_verified": False,
            "follow_request_pending": False,
            "follow_request_pending_method": "",
            "tap_x": None,
            "tap_y": None,
            "follow_button_bounds": det.get("follow_button_bounds"),
            "confidence": 0.0,
            "current_activity": meta0.get("current_activity"),
            "current_package": meta0.get("current_package"),
            "source_profile_username": source_profile_username or "",
            "failure_reason": det.get("failure_reason") or "follow_button_not_found",
            "dry_run": effective_dry,
        }

    tap_x = int(det["tap_x"])
    tap_y = int(det["tap_y"])
    confidence = float(det.get("confidence") or 0.0)
    f_bounds = det.get("follow_button_bounds")
    meta1 = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_follow_profile_target_verified",
        tap_x=tap_x,
        tap_y=tap_y,
        follow_button_bounds=f_bounds,
        confidence=round(confidence, 4),
        current_activity=meta1.get("current_activity"),
        current_package=meta1.get("current_package"),
        source_profile_username=source_profile_username or "",
        dry_run=effective_dry,
    )

    log(
        "info",
        "visual_follow_decision_debug",
        ENABLE_REAL_VISUAL_FOLLOW=real_follow,
        VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
        dry_effective=effective_dry,
        follow_button_detected=True,
        follow_button_bounds=f_bounds,
        tap_x=tap_x,
        tap_y=tap_y,
        already_following=False,
        skip_reason="before_dry_vs_real_branch",
        will_click_follow=bool(not effective_dry),
        current_activity=meta1.get("current_activity"),
        current_package=meta1.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    if effective_dry:
        log(
            "info",
            "visual_follow_click_blocked_reason",
            reason="dry_run_follow_tap_disabled",
            ENABLE_REAL_VISUAL_FOLLOW=real_follow,
            VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
            dry_effective=effective_dry,
            follow_button_detected=True,
            follow_button_bounds=f_bounds,
            tap_x=tap_x,
            tap_y=tap_y,
            already_following=False,
            skip_reason=(
                "ENABLE_REAL_VISUAL_FOLLOW_false_legacy_mute_dry_only"
                if not real_follow
                else "unexpected_effective_dry"
            ),
            will_click_follow=False,
            current_activity=meta1.get("current_activity"),
            current_package=meta1.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        log(
            "info",
            "visual_follow_profile_dry_run_complete",
            tap_x=tap_x,
            tap_y=tap_y,
            follow_button_bounds=f_bounds,
            confidence=round(confidence, 4),
            current_activity=meta1.get("current_activity"),
            current_package=meta1.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        return {
            "ok": True,
            "follow_button_detected": True,
            "skip_already_following": False,
            "real_follow_tap_sent": False,
            "follow_verified": False,
            "follow_request_pending": False,
            "follow_request_pending_method": "",
            "tap_x": tap_x,
            "tap_y": tap_y,
            "follow_button_bounds": f_bounds,
            "confidence": confidence,
            "current_activity": meta1.get("current_activity"),
            "current_package": meta1.get("current_package"),
            "source_profile_username": source_profile_username or "",
            "failure_reason": None,
            "dry_run": True,
        }

    tv_follow = visual_target_profile_lock_verify(
        d,
        source_profile_username=source_profile_username,
        action="visual_follow_profile_real",
    )
    if not tv_follow.get("ok"):
        meta_tv = _followers_current_pkg_activity(d)
        return {
            "ok": False,
            "follow_button_detected": True,
            "skip_already_following": False,
            "real_follow_tap_sent": False,
            "follow_verified": False,
            "follow_request_pending": False,
            "follow_request_pending_method": "",
            "target_profile_lock_mismatch": True,
            "tap_x": tap_x,
            "tap_y": tap_y,
            "follow_button_bounds": f_bounds,
            "confidence": confidence,
            "current_activity": meta_tv.get("current_activity"),
            "current_package": meta_tv.get("current_package"),
            "source_profile_username": source_profile_username or "",
            "failure_reason": "target_profile_lock_mismatch",
            "dry_run": effective_dry,
        }

    lock_pf = bool(getattr(config, "ENABLE_VISUAL_PROFILE_CONTEXT_LOCK", False))
    exp_pf = expected_profile_context or {}
    min_pf = float(
        getattr(config, "VISUAL_PROFILE_CONTEXT_MIN_MATCH_CONFIDENCE", 0.72) or 0.72
    )
    if lock_pf:
        exp_fp0 = str(
            exp_pf.get("profile_visual_fingerprint")
            or exp_pf.get("profile_fingerprint")
            or ""
        )
        if exp_pf.get("ok") is False or not exp_fp0:
            meta_pf = _followers_current_pkg_activity(d)
            log(
                "info",
                "visual_profile_context_mismatch_abort",
                action="visual_follow_profile_real",
                abort_reason="missing_expected_profile_context_baseline",
                expected_profile_fingerprint="",
                current_profile_fingerprint="",
                confidence=0.0,
                same_profile=False,
                verification_method="none",
                current_activity=meta_pf.get("current_activity"),
                current_package=meta_pf.get("current_package"),
                source_profile_username=source_profile_username or "",
            )
            return {
                "ok": False,
                "follow_button_detected": True,
                "skip_already_following": False,
                "real_follow_tap_sent": False,
                "follow_verified": False,
                "follow_request_pending": False,
                "follow_request_pending_method": "",
                "profile_context_mismatch": True,
                "tap_x": tap_x,
                "tap_y": tap_y,
                "follow_button_bounds": f_bounds,
                "confidence": confidence,
                "current_activity": meta_pf.get("current_activity"),
                "current_package": meta_pf.get("current_package"),
                "source_profile_username": source_profile_username or "",
                "failure_reason": "profile_context_mismatch",
                "dry_run": effective_dry,
            }
        vpc = visual_verify_same_profile_context(
            d,
            expected_context=exp_pf,
            source_profile_username=source_profile_username,
        )
        if (not vpc.get("same_profile")) or float(
            vpc.get("confidence") or 0.0
        ) < min_pf:
            meta_pf = _followers_current_pkg_activity(d)
            log(
                "info",
                "visual_profile_context_mismatch_abort",
                action="visual_follow_profile_real",
                abort_reason="verify_failed_or_low_confidence",
                expected_profile_fingerprint=vpc.get("expected_profile_fingerprint"),
                current_profile_fingerprint=vpc.get("current_profile_fingerprint"),
                confidence=float(vpc.get("confidence") or 0.0),
                same_profile=bool(vpc.get("same_profile")),
                verification_method=str(vpc.get("verification_method") or ""),
                current_activity=meta_pf.get("current_activity"),
                current_package=meta_pf.get("current_package"),
                source_profile_username=source_profile_username or "",
            )
            return {
                "ok": False,
                "follow_button_detected": True,
                "skip_already_following": False,
                "real_follow_tap_sent": False,
                "follow_verified": False,
                "follow_request_pending": False,
                "follow_request_pending_method": "",
                "profile_context_mismatch": True,
                "tap_x": tap_x,
                "tap_y": tap_y,
                "follow_button_bounds": f_bounds,
                "confidence": confidence,
                "current_activity": meta_pf.get("current_activity"),
                "current_package": meta_pf.get("current_package"),
                "source_profile_username": source_profile_username or "",
                "failure_reason": "profile_context_mismatch",
                "dry_run": effective_dry,
            }

    log(
        "info",
        "visual_follow_profile_real_before_tap",
        tap_x=tap_x,
        tap_y=tap_y,
        follow_button_bounds=f_bounds,
        confidence=round(confidence, 4),
        verification_method="pending",
        current_activity=meta1.get("current_activity"),
        current_package=meta1.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    log(
        "info",
        "visual_follow_decision_debug",
        ENABLE_REAL_VISUAL_FOLLOW=real_follow,
        VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
        dry_effective=effective_dry,
        follow_button_detected=True,
        follow_button_bounds=f_bounds,
        tap_x=tap_x,
        tap_y=tap_y,
        already_following=False,
        skip_reason="about_to_send_follow_click",
        will_click_follow=True,
        current_activity=meta1.get("current_activity"),
        current_package=meta1.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    try:
        d.click(tap_x, tap_y)
    except Exception as e:
        meta_e = _followers_current_pkg_activity(d)
        log(
            "info",
            "visual_follow_click_blocked_reason",
            reason="d_click_exception",
            ENABLE_REAL_VISUAL_FOLLOW=real_follow,
            VISUAL_FOLLOW_MUTE_DRY_RUN=mute_dry,
            dry_effective=effective_dry,
            follow_button_detected=True,
            follow_button_bounds=f_bounds,
            tap_x=tap_x,
            tap_y=tap_y,
            already_following=False,
            skip_reason=str(e),
            will_click_follow=False,
            current_activity=meta_e.get("current_activity"),
            current_package=meta_e.get("current_package"),
            source_profile_username=source_profile_username or "",
        )
        log(
            "error",
            "visual_follow_profile_failed",
            tap_x=tap_x,
            tap_y=tap_y,
            follow_button_bounds=f_bounds,
            confidence=round(confidence, 4),
            verification_method="none",
            current_activity=meta_e.get("current_activity"),
            current_package=meta_e.get("current_package"),
            source_profile_username=source_profile_username or "",
            failure_reason=str(e),
        )
        return {
            "ok": False,
            "follow_button_detected": True,
            "skip_already_following": False,
            "real_follow_tap_sent": False,
            "follow_verified": False,
            "follow_request_pending": False,
            "follow_request_pending_method": "",
            "tap_x": tap_x,
            "tap_y": tap_y,
            "follow_button_bounds": f_bounds,
            "confidence": confidence,
            "current_activity": meta_e.get("current_activity"),
            "current_package": meta_e.get("current_package"),
            "source_profile_username": source_profile_username or "",
            "failure_reason": str(e),
            "dry_run": False,
        }

    log(
        "info",
        "visual_follow_profile_real_tap_sent",
        tap_x=tap_x,
        tap_y=tap_y,
        follow_button_bounds=f_bounds,
        confidence=round(confidence, 4),
        verification_method="tap_dispatched",
        current_activity=meta1.get("current_activity"),
        current_package=meta1.get("current_package"),
        source_profile_username=source_profile_username or "",
    )
    time.sleep(1.2)
    post_shot = str(
        _SCREENSHOTS_DIR / f"visual_follow_after_tap_{int(time.time() * 1000)}.png"
    )
    try:
        screenshot(d, post_shot)
    except Exception:
        pass
    try:
        d.dump_hierarchy(compressed=False)
    except Exception:
        try:
            d.dump_hierarchy()
        except Exception:
            pass
    try:
        d.app_current()
    except Exception:
        pass

    verify_after = bool(getattr(config, "VISUAL_FOLLOW_VERIFY_AFTER_TAP", True))
    if verify_after:
        ver = visual_verify_profile_followed(
            d,
            source_profile_username=source_profile_username,
            tap_x=tap_x,
            tap_y=tap_y,
            follow_button_bounds=f_bounds,
            detect_confidence=confidence,
        )
        fv = bool(ver.get("follow_verified"))
        vmeth = str(ver.get("verification_method") or "none")
        vconf = float(ver.get("confidence") or 0.0)
    else:
        fv = True
        vmeth = "verify_disabled"
        vconf = 1.0

    meta_done = _followers_current_pkg_activity(d)
    fr_pending = False
    fr_pm = ""
    if fv:
        fr_pending, fr_pm = _visual_follow_request_pending_state(d)
        if fr_pending:
            log(
                "info",
                "visual_follow_request_sent_verified",
                follow_request_pending_method=fr_pm,
                verification_method=vmeth,
                tap_x=tap_x,
                tap_y=tap_y,
                source_profile_username=source_profile_username or "",
                current_activity=meta_done.get("current_activity"),
                current_package=meta_done.get("current_package"),
            )

    log(
        "info",
        "visual_follow_profile_real_complete",
        tap_x=tap_x,
        tap_y=tap_y,
        follow_button_bounds=f_bounds,
        verification_method=vmeth,
        confidence=round(vconf, 4),
        current_activity=meta_done.get("current_activity"),
        current_package=meta_done.get("current_package"),
        source_profile_username=source_profile_username or "",
        follow_verified=fv,
        follow_request_pending=fr_pending,
    )
    return {
        "ok": True,
        "follow_button_detected": True,
        "skip_already_following": False,
        "real_follow_tap_sent": True,
        "follow_verified": fv,
        "follow_request_pending": fr_pending,
        "follow_request_pending_method": fr_pm,
        "verification_method": vmeth,
        "verify_confidence": vconf,
        "tap_x": tap_x,
        "tap_y": tap_y,
        "follow_button_bounds": f_bounds,
        "confidence": confidence,
        "current_activity": meta_done.get("current_activity"),
        "current_package": meta_done.get("current_package"),
        "source_profile_username": source_profile_username or "",
        "failure_reason": None,
        "dry_run": False,
    }


def visual_detect_follow_post_actions(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Heuristic detection of follow confirmation sheet / mute rows (UiAutomator labels + bright sheet ROI).
    """
    meta0 = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_follow_actions_detect_started",
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
    )
    mute_posts_detected = False
    mute_stories_detected = False
    following_detected = False

    def _exists_text(pred: Callable[[], object], timeout: float = 0.12) -> bool:
        try:
            return bool(pred().exists(timeout=timeout))
        except Exception:
            return False

    if _exists_text(lambda: d(textContains="Mute posts")) or _exists_text(
        lambda: d(text="Mute posts")
    ):
        mute_posts_detected = True
    if _exists_text(lambda: d(textContains="Mute stories")) or _exists_text(
        lambda: d(text="Mute stories")
    ):
        mute_stories_detected = True
    if _exists_text(lambda: d(textContains="Following")) or _exists_text(
        lambda: d(text="Following")
    ):
        following_detected = True
    if not mute_posts_detected and _exists_text(lambda: d(descriptionContains="Mute")):
        try:
            if d(textContains="posts").exists(timeout=0.08):
                mute_posts_detected = True
        except Exception:
            pass
        try:
            if d(textContains="stories").exists(timeout=0.08):
                mute_stories_detected = True
        except Exception:
            pass

    _ensure_debug_dirs()
    shot = str(
        _SCREENSHOTS_DIR / f"visual_follow_actions_{int(time.time() * 1000)}.png"
    )
    popup_detected = False
    pil_conf = 0.25
    try:
        screenshot(d, shot)
        from PIL import Image

        im = Image.open(shot).convert("RGB")
        iw, ih = im.size
        roi = im.crop((0, int(ih * 0.48), iw, ih))
        lums = [(int(r) + int(g) + int(b)) / 3 for r, g, b in roi.getdata()]
        if lums:
            mu = sum(lums) / len(lums)
            var = sum((x - mu) ** 2 for x in lums) / len(lums)
            if mu > 210 and 120 < var < 8000:
                popup_detected = True
                pil_conf = 0.35
    except Exception:
        pass

    meta_after = _followers_current_pkg_activity(d)

    if mute_posts_detected or mute_stories_detected or following_detected:
        popup_detected = True
        pil_conf = max(pil_conf, 0.55)

    confidence = float(
        min(
            0.95,
            pil_conf
            + (0.12 if mute_posts_detected else 0)
            + (0.12 if mute_stories_detected else 0)
            + (0.1 if following_detected else 0),
        )
    )

    payload = {
        "mute_posts_detected": mute_posts_detected,
        "mute_stories_detected": mute_stories_detected,
        "following_detected": following_detected,
        "popup_detected": popup_detected,
        "confidence": round(confidence, 4),
        "current_activity": meta_after.get("current_activity"),
        "current_package": meta_after.get("current_package"),
        "source_profile_username": source_profile_username or "",
    }

    if popup_detected or mute_posts_detected or mute_stories_detected or following_detected:
        log("info", "visual_follow_actions_detected", **payload)
    else:
        log("info", "visual_follow_actions_not_detected", **payload)

    return payload


def visual_mute_after_follow_dry_run(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    """
    Estimate mute row tap points from typical bottom-sheet layout; never taps (dry-run only).
    """
    dry = bool(getattr(config, "VISUAL_FOLLOW_MUTE_DRY_RUN", True))
    if not dry:
        return {
            "ok": False,
            "failure_reason": "dry_run_disabled",
            "source_profile_username": source_profile_username or "",
        }

    want_posts = bool(getattr(config, "VISUAL_MUTE_POSTS_AFTER_FOLLOW", True))
    want_stories = bool(getattr(config, "VISUAL_MUTE_STORIES_AFTER_FOLLOW", True))

    tv_mute = visual_target_profile_lock_verify(
        d,
        source_profile_username=source_profile_username,
        action="visual_mute_after_follow_dry_run",
    )
    if not tv_mute.get("ok"):
        meta_tv = _followers_current_pkg_activity(d)
        log(
            "error",
            "visual_mute_after_follow_failed",
            ok=False,
            mute_posts_bounds=None,
            mute_stories_bounds=None,
            source_profile_username=source_profile_username or "",
            current_activity=meta_tv.get("current_activity"),
            current_package=meta_tv.get("current_package"),
            failure_reason="target_profile_lock_mismatch",
            dry_run=True,
        )
        return {
            "ok": False,
            "failure_reason": "target_profile_lock_mismatch",
            "mute_posts_bounds": None,
            "mute_stories_bounds": None,
            "source_profile_username": source_profile_username or "",
            "target_profile_lock_mismatch": True,
        }

    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400

    _ensure_debug_dirs()
    shot = str(
        _SCREENSHOTS_DIR / f"visual_mute_sheet_{int(time.time() * 1000)}.png"
    )
    try:
        screenshot(d, shot)
        from PIL import Image

        im = Image.open(shot).convert("RGB")
        iw, ih = im.size
    except Exception as e:
        meta_fail = _followers_current_pkg_activity(d)
        log(
            "error",
            "visual_mute_after_follow_failed",
            ok=False,
            mute_posts_bounds=None,
            mute_stories_bounds=None,
            source_profile_username=source_profile_username or "",
            current_activity=meta_fail.get("current_activity"),
            current_package=meta_fail.get("current_package"),
            failure_reason=f"screenshot_failed:{e}",
            dry_run=True,
        )
        return {
            "ok": False,
            "failure_reason": f"screenshot_failed:{e}",
            "mute_posts_bounds": None,
            "mute_stories_bounds": None,
            "source_profile_username": source_profile_username or "",
        }

    # Typical sheet row centers (image ratios); map to device.
    half_row = max(12, int(ih * 0.028))
    margin_x = max(2, int(iw * 0.02))
    posts_y_img = int(ih * 0.58)
    stories_y_img = int(ih * 0.665)
    tap_x_img = int(iw * 0.48)
    posts_tx, posts_ty = _visual_xy_image_to_device(
        tap_x_img, posts_y_img, iw, ih, ww, wh
    )
    stories_tx, stories_ty = _visual_xy_image_to_device(
        tap_x_img, stories_y_img, iw, ih, ww, wh
    )
    posts_row_img = {
        "left": margin_x,
        "top": posts_y_img - half_row,
        "right": iw - 2,
        "bottom": posts_y_img + half_row,
    }
    stories_row_img = {
        "left": margin_x,
        "top": stories_y_img - half_row,
        "right": iw - 2,
        "bottom": stories_y_img + half_row,
    }
    mute_posts_bounds = _visual_bounds_map_to_device(posts_row_img, iw, ih, ww, wh)
    mute_stories_bounds = _visual_bounds_map_to_device(stories_row_img, iw, ih, ww, wh)

    meta = _followers_current_pkg_activity(d)
    if want_posts:
        log(
            "info",
            "visual_mute_posts_target_detected",
            tap_x=posts_tx,
            tap_y=posts_ty,
            mute_posts_bounds=mute_posts_bounds,
            source_profile_username=source_profile_username or "",
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
            dry_run=True,
        )
    if want_stories:
        log(
            "info",
            "visual_mute_stories_target_detected",
            tap_x=stories_tx,
            tap_y=stories_ty,
            mute_stories_bounds=mute_stories_bounds,
            source_profile_username=source_profile_username or "",
            current_activity=meta.get("current_activity"),
            current_package=meta.get("current_package"),
            dry_run=True,
        )

    log(
        "info",
        "visual_mute_dry_run_complete",
        source_profile_username=source_profile_username or "",
        mute_posts_bounds=mute_posts_bounds if want_posts else None,
        mute_stories_bounds=mute_stories_bounds if want_stories else None,
        mute_posts_target=(want_posts, posts_tx, posts_ty),
        mute_stories_target=(want_stories, stories_tx, stories_ty),
        current_activity=meta.get("current_activity"),
        current_package=meta.get("current_package"),
        dry_run=True,
    )
    return {
        "ok": True,
        "mute_posts_tap": (posts_tx, posts_ty) if want_posts else None,
        "mute_stories_tap": (stories_tx, stories_ty) if want_stories else None,
        "mute_posts_bounds": mute_posts_bounds if want_posts else None,
        "mute_stories_bounds": mute_stories_bounds if want_stories else None,
        "current_activity": meta.get("current_activity"),
        "current_package": meta.get("current_package"),
        "source_profile_username": source_profile_username or "",
        "dry_run": True,
    }


# --- Visual real mute after follow: Following → options sheet → Mute → Posts/Stories toggles ---


def _visual_header_following_button_predicates() -> tuple[tuple[str, Callable[[u2.Device], Any]], ...]:
    return (
        ("ui_text_following_exact", lambda dd: dd(text="Following")),
        ("ui_text_suivi_e", lambda dd: dd(text="Suivi(e)")),
        ("ui_text_suivi", lambda dd: dd(text="Suivi")),
        ("ui_text_abonne_e", lambda dd: dd(text="Abonné(e)")),
        ("ui_text_abonne", lambda dd: dd(text="Abonné")),
        ("ui_text_siguiendo", lambda dd: dd(text="Siguiendo")),
        ("ui_text_gefolgt", lambda dd: dd(text="Gefolgt")),
    )


def _visual_pick_profile_header_following_button(
    d: u2.Device,
) -> tuple[Any, str]:
    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400
    for mid, pred in _visual_header_following_button_predicates():
        try:
            el = pred(d)
            if not el.exists(timeout=0.16):
                continue
            b = el.info.get("bounds") or {}
            cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
            if cy > int(wh * 0.42):
                continue
            rx = int(b.get("right", 0))
            if rx < int(ww * 0.22):
                continue
            return el, mid
        except Exception:
            continue
    try:
        el = d(descriptionContains="Following button")
        if el.exists(timeout=0.12):
            return el, "desc_following_btn"
    except Exception:
        pass
    return None, ""


def _visual_find_mute_row_first_sheet(d: u2.Device) -> tuple[Any, str]:
    for lab in (
        "Mute",
        "Silenciar",
        "Mettre en sourdine",
        "Sourdine",
    ):
        try:
            el = d(text=lab)
            if el.exists(timeout=0.14):
                return el, lab
        except Exception:
            continue
    try:
        el = d(textContains="sourdine")
        if el.exists(timeout=0.12):
            return el, "textContains_sourdine"
    except Exception:
        pass
    try:
        el = d(textContains="Mute")
        if el.exists(timeout=0.1):
            return el, "textContains_Mute"
    except Exception:
        pass
    return None, ""


def _mute_row_preferred_toggle_rid_fragment(label_el: Any) -> str | None:
    """Instagram mute sheet row: map label text to ``…_mute_setting_row_switch`` id fragment."""
    try:
        t = str(label_el.info.get("text") or "").strip().lower()
    except Exception:
        return None
    if t in ("posts", "publications") or t.startswith("publication"):
        return "posts_mute_setting_row_switch"
    if t in ("stories", "historias", "storie"):
        return "stories_mute_setting_row_switch"
    if "note" in t:
        return "notes_mute_setting_row_switch"
    return None


def _mute_row_toggle_resource_id(el: Any) -> str:
    try:
        inf = el.info
        return str(inf.get("resourceName") or inf.get("resourceId") or "")
    except Exception:
        return ""


def _mute_row_toggle_tier(el: Any, *, class_name: str, pref: str | None) -> int:
    """
    Lower tier = higher priority. 0 = Instagram mute row id match; 1 = Switch; 2 = other CompoundButton.
    """
    rid = _mute_row_toggle_resource_id(el)
    if pref and pref in rid:
        return 0
    if class_name == "android.widget.Switch":
        return 1
    return 2


def _mute_row_toggle_candidates_near_label(
    d: u2.Device, label_el: Any
) -> list[tuple[int, int, Any, str]]:
    """Switch + checkable CompoundButton within vertical band of label row center (dy <= 72)."""
    try:
        lb = label_el.info.get("bounds") or {}
        lcy = (int(lb["top"]) + int(lb["bottom"])) // 2
    except Exception:
        return []
    pref = _mute_row_preferred_toggle_rid_fragment(label_el)
    out: list[tuple[int, int, Any, str]] = []
    try:
        for el in d(className="android.widget.Switch").all():
            try:
                sb = el.info.get("bounds") or {}
                scy = (int(sb["top"]) + int(sb["bottom"])) // 2
                dy = abs(scy - lcy)
                if dy > 72:
                    continue
                tier = _mute_row_toggle_tier(el, class_name="android.widget.Switch", pref=pref)
                out.append((tier, dy, el, "android.widget.Switch"))
            except Exception:
                continue
        for el in d(className="android.widget.CompoundButton").all():
            try:
                inf = el.info
                if not bool(inf.get("checkable")):
                    continue
                sb = inf.get("bounds") or {}
                scy = (int(sb["top"]) + int(sb["bottom"])) // 2
                dy = abs(scy - lcy)
                if dy > 72:
                    continue
                tier = _mute_row_toggle_tier(
                    el, class_name="android.widget.CompoundButton", pref=pref
                )
                out.append((tier, dy, el, "android.widget.CompoundButton"))
            except Exception:
                continue
    except Exception:
        return out
    return out


def _mute_row_toggle_pick_best(
    cands: list[tuple[int, int, Any, str]],
) -> tuple[Any | None, dict[str, Any]]:
    diag: dict[str, Any] = {
        "matched_toggle_class": "",
        "matched_toggle_resource_id": "",
        "matched_toggle_checked": None,
    }
    if not cands:
        return None, diag
    best = min(cands, key=lambda x: (x[0], x[1]))
    el = best[2]
    cls = best[3]
    try:
        inf = el.info
        diag["matched_toggle_class"] = str(inf.get("className") or cls)[:160]
        diag["matched_toggle_resource_id"] = str(
            inf.get("resourceName") or inf.get("resourceId") or ""
        )[:200]
        raw = inf.get("checked")
        if isinstance(raw, bool):
            diag["matched_toggle_checked"] = raw
        else:
            diag["matched_toggle_checked"] = None
    except Exception:
        pass
    return el, diag


def _visual_switch_checked_near_row(
    d: u2.Device, label_el: Any, *, diag_meta: dict[str, Any] | None = None
) -> bool | None:
    cands = _mute_row_toggle_candidates_near_label(d, label_el)
    el, diag = _mute_row_toggle_pick_best(cands)
    if diag_meta is not None:
        diag_meta.update(diag)
    if el is None:
        return None
    try:
        return bool(el.info.get("checked"))
    except Exception:
        return None


def _visual_switch_probe_near_row(d: u2.Device, label_el: Any) -> dict[str, Any]:
    """
    Same row / band heuristics as ``_visual_switch_checked_near_row``; returns counts
    for mute toggle verify diagnostics (extra UiAutomator pass; verify path only).
    """
    out: dict[str, Any] = {
        "switches_in_band": 0,
        "nearest_dy": None,
        "checked_raw_on_nearest": None,
    }
    try:
        lb = label_el.info.get("bounds") or {}
        lcy = (int(lb["top"]) + int(lb["bottom"])) // 2
    except Exception:
        return out
    cands = _mute_row_toggle_candidates_near_label(d, label_el)
    out["switches_in_band"] = int(len(cands))
    el, _diag = _mute_row_toggle_pick_best(cands)
    if el is None:
        return out
    best_dy = None
    for tier, dy, cand_el, _cls in cands:
        if cand_el is el:
            best_dy = dy
            break
    if best_dy is not None:
        out["nearest_dy"] = int(best_dy)
    try:
        raw = el.info.get("checked")
        if isinstance(raw, bool):
            out["checked_raw_on_nearest"] = raw
        else:
            out["checked_raw_on_nearest"] = None
    except Exception:
        out["checked_raw_on_nearest"] = None
    return out


def _visual_tap_toggle_row_for_label(
    d: u2.Device,
    labels: tuple[str, ...],
    ww: int,
) -> tuple[bool, bool, str, Any | None]:
    """Returns (tapped, already_on, failure_reason, label_element)."""
    el: Any | None = None
    for lab in labels:
        try:
            cand = d(text=lab)
            if cand.wait(timeout=1.5):
                el = cand
                break
        except Exception:
            continue
    if el is None:
        return False, False, "toggle_label_not_found", None
    chk = _visual_switch_checked_near_row(d, el)
    if chk is True:
        return False, True, "", el
    try:
        b = el.info.get("bounds") or {}
        cy = (int(b["top"]) + int(b["bottom"])) // 2
        tap_x = min(ww - 6, max(int(ww * 0.88), int(b.get("right", 0)) + 72))
        d.click(int(tap_x), int(cy))
    except Exception as e:
        return False, False, f"tap_failed:{e}", el
    return True, False, "", el


def _visual_verify_toggle_on_for_labels_detailed(
    d: u2.Device,
    labels: tuple[str, ...],
    timeout_s: float,
) -> tuple[bool, dict[str, Any]]:
    """
    Poll until ``android.widget.Switch`` near the row reads ``checked`` or timeout.
    Returns (ok, meta) with probe stats for diagnostics (mute v2 logging on failure).
    """
    to = float(timeout_s)
    deadline = time.perf_counter() + to
    probe_cycles = 0
    inner_probes = 0
    meta: dict[str, Any] = {
        "verify_timeout_s": round(to, 4),
        "probe_cycles": 0,
        "inner_probes": 0,
        "last_label": "",
        "last_checked_signal": "none",
        "last_switches_in_band": 0,
        "last_nearest_dy": None,
        "checked_raw_on_nearest": None,
        "verify_ok": False,
        "matched_toggle_class": "",
        "matched_toggle_resource_id": "",
        "matched_toggle_checked": None,
    }
    while time.perf_counter() < deadline:
        probe_cycles += 1
        for lab in labels:
            try:
                el = d(text=lab)
                if not el.exists(timeout=0.1):
                    continue
                inner_probes += 1
                meta["last_label"] = str(lab)
                pr = _visual_switch_probe_near_row(d, el)
                meta["last_switches_in_band"] = int(pr.get("switches_in_band") or 0)
                meta["last_nearest_dy"] = pr.get("nearest_dy")
                meta["checked_raw_on_nearest"] = pr.get("checked_raw_on_nearest")
                _row_d: dict[str, Any] = {}
                c = _visual_switch_checked_near_row(d, el, diag_meta=_row_d)
                meta["matched_toggle_class"] = str(_row_d.get("matched_toggle_class") or "")[:160]
                meta["matched_toggle_resource_id"] = str(
                    _row_d.get("matched_toggle_resource_id") or ""
                )[:200]
                meta["matched_toggle_checked"] = _row_d.get("matched_toggle_checked")
                if c is True:
                    meta["last_checked_signal"] = "true"
                elif c is False:
                    meta["last_checked_signal"] = "false"
                else:
                    meta["last_checked_signal"] = "missing_switch"
                if c is True:
                    meta["probe_cycles"] = probe_cycles
                    meta["inner_probes"] = inner_probes
                    meta["verify_ok"] = True
                    return True, meta
            except Exception:
                continue
        time.sleep(0.14)
    meta["probe_cycles"] = probe_cycles
    meta["inner_probes"] = inner_probes
    meta["verify_ok"] = False
    return False, meta


_LIVE_TOGGLE_CANDIDATES_DIAG_MAX_COMPOUND_SAMPLES = 16
_LIVE_TOGGLE_CANDIDATES_DIAG_MAX_SWITCH_SAMPLES = 8
_LIVE_TOGGLE_CANDIDATES_DIAG_VERTICAL_BAND_DY = 72


def _mute_engine_v2_toggle_live_sample_node(
    el: Any, *, lcy: int | None, band_dy: int
) -> dict[str, Any]:
    row: dict[str, Any] = {}
    try:
        inf = el.info
    except Exception as e:
        row["sample_error"] = str(e)[:200]
        return row
    try:
        row["className"] = str(inf.get("className") or "")[:200]
    except Exception:
        row["className"] = ""
    sb = {}
    try:
        sb = inf.get("bounds") or {}
        row["bounds"] = {
            "left": int(sb["left"]),
            "top": int(sb["top"]),
            "right": int(sb["right"]),
            "bottom": int(sb["bottom"]),
        }
    except Exception:
        row["bounds"] = None
    try:
        row["resourceName"] = inf.get("resourceName")
        row["resourceId"] = inf.get("resourceId")
        row["resource_id"] = str(inf.get("resourceName") or inf.get("resourceId") or "")[:220]
    except Exception:
        row["resourceName"] = None
        row["resourceId"] = None
        row["resource_id"] = ""
    row["checkable_raw"] = inf.get("checkable")
    row["checked_raw"] = inf.get("checked")
    row["clickable_raw"] = inf.get("clickable")
    if lcy is not None and isinstance(sb, dict) and all(k in sb for k in ("top", "bottom")):
        try:
            scy = (int(sb["top"]) + int(sb["bottom"])) // 2
            dy = abs(scy - int(lcy))
            row["dy"] = int(dy)
            row["in_vertical_band"] = bool(dy <= int(band_dy))
        except Exception:
            row["dy"] = None
            row["in_vertical_band"] = None
    else:
        row["dy"] = None
        row["in_vertical_band"] = None
    return row


def _mute_engine_v2_toggle_live_candidates_diag(
    d: u2.Device,
    *,
    axis: str,
    vmeta: dict[str, Any],
    labels_tuple: tuple[str, ...],
    visual_candidate_id: str,
    source_profile_username: str,
) -> None:
    """
    Diagnostic-only: when verify failed with ``missing_switch`` and zero in-band
    candidates from the helper, log raw ``.all()`` counts and per-node ``info`` samples
    (does not change verify outcome or taps).
    """
    if bool(vmeta.get("verify_ok")):
        return
    if str(vmeta.get("last_checked_signal") or "") != "missing_switch":
        return
    if int(vmeta.get("last_switches_in_band") or 0) != 0:
        return

    band = int(_LIVE_TOGGLE_CANDIDATES_DIAG_VERTICAL_BAND_DY)
    label_text = str(vmeta.get("last_label") or "").strip()
    if not label_text:
        for lab in labels_tuple:
            if str(lab or "").strip():
                label_text = str(lab).strip()
                break

    label_bounds: dict[str, int] | None = None
    label_center_y: int | None = None
    label_found = False
    label_el: Any | None = None
    if label_text:
        try:
            cand = d(text=label_text)
            if bool(cand.exists(timeout=0.12)):
                label_el = cand
                label_found = True
        except Exception:
            label_el = None
    if label_el is not None:
        try:
            lb = label_el.info.get("bounds") or {}
            label_bounds = {
                "left": int(lb["left"]),
                "top": int(lb["top"]),
                "right": int(lb["right"]),
                "bottom": int(lb["bottom"]),
            }
            label_center_y = (label_bounds["top"] + label_bounds["bottom"]) // 2
        except Exception:
            label_bounds = None
            label_center_y = None

    lcy = label_center_y
    compound_button_live_count = 0
    switch_live_count = 0
    candidate_in_vertical_band_count = 0
    candidate_filtered_by_checkable_count = 0
    compound_samples: list[dict[str, Any]] = []
    switch_samples: list[dict[str, Any]] = []

    try:
        cb_all = d(className="android.widget.CompoundButton").all()
    except Exception:
        cb_all = []
    try:
        sw_all = d(className="android.widget.Switch").all()
    except Exception:
        sw_all = []

    compound_button_live_count = int(len(cb_all))
    switch_live_count = int(len(sw_all))

    for i, el in enumerate(cb_all):
        if lcy is not None:
            try:
                inf = el.info
                sb = inf.get("bounds") or {}
                scy = (int(sb["top"]) + int(sb["bottom"])) // 2
                dy = abs(scy - int(lcy))
                if dy <= band:
                    candidate_in_vertical_band_count += 1
                    if not bool(inf.get("checkable")):
                        candidate_filtered_by_checkable_count += 1
            except Exception:
                pass
        if i < _LIVE_TOGGLE_CANDIDATES_DIAG_MAX_COMPOUND_SAMPLES:
            compound_samples.append(_mute_engine_v2_toggle_live_sample_node(el, lcy=lcy, band_dy=band))

    for i, el in enumerate(sw_all):
        if i < _LIVE_TOGGLE_CANDIDATES_DIAG_MAX_SWITCH_SAMPLES:
            switch_samples.append(_mute_engine_v2_toggle_live_sample_node(el, lcy=lcy, band_dy=band))

    try:
        log(
            "warning",
            "mute_engine_v2_toggle_live_candidates_diag",
            axis=str(axis or "")[:32],
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            last_label=label_text or None,
            label_found=label_found,
            label_bounds=label_bounds,
            label_center_y=label_center_y,
            compound_button_live_count=compound_button_live_count,
            switch_live_count=switch_live_count,
            candidate_in_vertical_band_count=candidate_in_vertical_band_count,
            candidate_filtered_by_checkable_count=candidate_filtered_by_checkable_count,
            vertical_band_dy=band,
            compound_button_samples=compound_samples,
            switch_samples=switch_samples,
        )
    except Exception:
        pass


_MUTE_V2_XML_VERIFY_RID_FRAGMENTS: dict[str, str] = {
    "posts": "posts_mute_setting_row_switch",
    "stories": "stories_mute_setting_row_switch",
}


def _mute_engine_v2_verify_toggle_on_from_xml_dump(
    d: u2.Device,
    *,
    axis: str,
) -> tuple[bool | None, dict[str, Any]]:
    """
    Read-only: after live UiAutomator verify failed (no CompoundButton in ``.all()``),
    confirm mute toggle ``checked`` from ``dump_hierarchy`` XML by Instagram resource-id.

    Returns ``(True, diag)`` only when a matching node has ``checked`` attribute equal to
    ``true`` (case-insensitive). ``False`` when node found but clearly not on. ``None``
    when dump/parse failed or target node missing / ambiguous ``checked``.
    """
    ax = str(axis or "").strip().lower()
    frag = _MUTE_V2_XML_VERIFY_RID_FRAGMENTS.get(ax, "")
    diag: dict[str, Any] = {
        "target_resource_id_fragment": frag,
        "xml_node_found": False,
        "checked_value": "",
        "xml_verify_ok": False,
        "matched_toggle_resource_id": "",
        "matched_toggle_class": "",
    }
    if not frag:
        diag["xml_fallback_skip_reason"] = "unknown_axis"
        return None, diag

    hier = ""
    try:
        try:
            hier = str(d.dump_hierarchy(compressed=False))
        except TypeError:
            hier = str(d.dump_hierarchy())
    except Exception as e:
        diag["xml_fallback_skip_reason"] = f"dump_failed:{type(e).__name__}"
        return None, diag

    if not hier.strip():
        diag["xml_fallback_skip_reason"] = "empty_hierarchy"
        return None, diag

    try:
        root = ET.fromstring(hier)
    except Exception as e:
        diag["xml_fallback_skip_reason"] = f"parse_failed:{type(e).__name__}"
        return None, diag

    for node in root.iter():
        tg = str(node.tag)
        if tg != "node" and not tg.endswith("}node"):
            continue
        a = node.attrib
        rid = str(a.get("resource-id") or "")
        if frag not in rid:
            continue
        chk_raw = str(a.get("checked") or "").strip()
        diag["xml_node_found"] = True
        diag["checked_value"] = chk_raw
        diag["matched_toggle_resource_id"] = rid[:220]
        diag["matched_toggle_class"] = str(a.get("class") or "")[:160]
        cl = chk_raw.lower()
        if cl == "true":
            diag["xml_verify_ok"] = True
            return True, diag
        if cl == "false":
            diag["xml_verify_ok"] = False
            return False, diag
        diag["xml_verify_ok"] = False
        diag["xml_fallback_skip_reason"] = "checked_attr_not_boolean"
        return None, diag

    diag["xml_fallback_skip_reason"] = "resource_id_not_found"
    return None, diag


def _mute_engine_v2_toggle_verify_xml_fallback_maybe(
    d: u2.Device,
    *,
    axis: str,
    vmeta: dict[str, Any],
    visual_candidate_id: str,
    source_profile_username: str,
) -> bool:
    """
    If live mute toggle verify ended with ``missing_switch`` and zero in-band switches,
    try strict XML resource-id read. On success, mutates ``vmeta`` like a passing live verify.
    """
    if bool(vmeta.get("verify_ok")):
        return False
    if str(vmeta.get("last_checked_signal") or "") != "missing_switch":
        return False
    if int(vmeta.get("last_switches_in_band") or 0) != 0:
        return False

    res, fields = _mute_engine_v2_verify_toggle_on_from_xml_dump(
        d,
        axis=axis,
    )
    try:
        log(
            "warning",
            "mute_engine_v2_toggle_verify_xml_fallback_used",
            axis=str(axis or "")[:32],
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            **fields,
        )
    except Exception:
        pass

    if res is not True:
        return False

    vmeta["verify_ok"] = True
    vmeta["last_checked_signal"] = "true"
    vmeta["matched_toggle_class"] = str(fields.get("matched_toggle_class") or "")[:160]
    vmeta["matched_toggle_resource_id"] = str(fields.get("matched_toggle_resource_id") or "")[
        :220
    ]
    vmeta["matched_toggle_checked"] = True
    return True


def _mute_engine_v2_parse_bounds_attr(bounds_s: str) -> tuple[int, int, int, int] | None:
    s = (bounds_s or "").strip()
    m = re.match(r"^\[(\d+),(\d+)\]\[(\d+),(\d+)\]$", s)
    if not m:
        return None
    return int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4))


def _mute_engine_v2_toggle_verify_structure_diag(
    d: u2.Device,
    *,
    axis: str,
    labels_tuple: tuple[str, ...],
    vmeta: dict[str, Any],
    visual_candidate_id: str,
    source_profile_username: str,
) -> None:
    """
    Diagnostic-only: when Switch-based verify saw no ``android.widget.Switch`` near the row,
    dump hierarchy + screenshot and log nearby / right-side XML nodes (does not change verify outcome).
    """
    if bool(vmeta.get("verify_ok")):
        return
    if str(vmeta.get("last_checked_signal") or "") != "missing_switch":
        return
    if int(vmeta.get("last_switches_in_band") or 0) != 0:
        return

    _ensure_debug_dirs()
    sub_xml = _XML_DIR / "mute_toggle_verify_diag"
    try:
        sub_xml.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    stamp = int(time.time() * 1000)
    vshort = re.sub(r"[^A-Za-z0-9._-]+", "_", (visual_candidate_id or "na")[:20])
    base = f"mute_toggle_structure_{axis}_{stamp}_{vshort}"
    xml_path = sub_xml / f"{base}.xml"
    shot_path = _SCREENSHOTS_DIR / f"{base}.png"

    label = str(vmeta.get("last_label") or "").strip()
    if not label:
        for lab in labels_tuple:
            if str(lab or "").strip():
                label = str(lab).strip()
                break

    xml_dump_path = ""
    screenshot_path = ""
    nearby_node_count = 0
    right_side_node_count = 0
    sampled_classnames: list[str] = []
    sampled_checkable_nodes: list[str] = []
    label_bounds: dict[str, int] | None = None

    try:
        try:
            screenshot(d, str(shot_path))
            screenshot_path = str(shot_path)
        except Exception:
            pass

        try:
            try:
                hier = str(d.dump_hierarchy(compressed=False))
            except TypeError:
                hier = str(d.dump_hierarchy())
            xml_path.write_text(hier, encoding="utf-8")
            xml_dump_path = str(xml_path)
            _bump_xml_fetch()
        except Exception:
            hier = ""

        lcy = lcx = ltop = lbot = lleft = lright = 0
        if label:
            try:
                el = d(text=label)
                if el.exists(timeout=0.12):
                    lb = el.info.get("bounds") or {}
                    lleft = int(lb.get("left", 0))
                    ltop = int(lb.get("top", 0))
                    lright = int(lb.get("right", 0))
                    lbot = int(lb.get("bottom", 0))
                    lcx = (lleft + lright) // 2
                    lcy = (ltop + lbot) // 2
                    label_bounds = {
                        "left": lleft,
                        "top": ltop,
                        "right": lright,
                        "bottom": lbot,
                    }
            except Exception:
                pass

        if hier and label_bounds is None and label:
            try:
                _r = ET.fromstring(hier)
                for _node in _r.iter():
                    _tg = str(_node.tag)
                    if _tg != "node" and not _tg.endswith("}node"):
                        continue
                    _a = _node.attrib
                    if str(_a.get("text") or "").strip() != label:
                        continue
                    _pb = _mute_engine_v2_parse_bounds_attr(str(_a.get("bounds") or ""))
                    if _pb is None:
                        continue
                    gl, gt, gr, gb = _pb
                    lleft, ltop, lright, lbot = gl, gt, gr, gb
                    lcx = (lleft + lright) // 2
                    lcy = (ltop + lbot) // 2
                    label_bounds = {
                        "left": lleft,
                        "top": ltop,
                        "right": lright,
                        "bottom": lbot,
                    }
                    break
            except Exception:
                pass

        band_y = 140
        nearby_rows: list[dict[str, Any]] = []
        checkable_samples: list[str] = []
        class_set: list[str] = []

        if hier and label_bounds is not None:
            try:
                root = ET.fromstring(hier)
            except Exception:
                root = None
            if root is not None:
                for node in root.iter():
                    tg = str(node.tag)
                    if tg != "node" and not tg.endswith("}node"):
                        continue
                    a = node.attrib
                    pb = _mute_engine_v2_parse_bounds_attr(str(a.get("bounds") or ""))
                    if pb is None:
                        continue
                    gl, gt, gr, gb = pb
                    cx = (gl + gr) // 2
                    cy = (gt + gb) // 2
                    if abs(cy - lcy) > band_y:
                        continue
                    nearby_node_count += 1
                    cls = str(a.get("class") or "")
                    if cls and cls not in class_set:
                        class_set.append(cls)
                    txt = str(a.get("text") or "")[:48]
                    cd = str(a.get("content-desc") or "")[:80]
                    rid = str(a.get("resource-id") or "")[:80]
                    clk = str(a.get("clickable") or "")
                    chk = str(a.get("checkable") or "")
                    chd = str(a.get("checked") or "")
                    sel = str(a.get("selected") or "")
                    row = {
                        "className": cls[:120],
                        "text": txt,
                        "content_desc": cd,
                        "resource_id": rid,
                        "clickable": clk,
                        "checkable": chk,
                        "checked": chd,
                        "selected": sel,
                        "bounds": f"[{gl},{gt}][{gr},{gb}]",
                    }
                    if len(nearby_rows) < 24:
                        nearby_rows.append(row)
                    if chk.lower() == "true":
                        checkable_samples.append(
                            f"{cls[:48]}|c={chd}|s={sel}|clk={clk}|{gl},{gt},{gr},{gb}"
                        )
                    if cx > lright - 4:
                        right_side_node_count += 1

        sampled_classnames = class_set[:20]
        sampled_checkable_nodes = checkable_samples[:10]

        try:
            log(
                "warning",
                "mute_engine_v2_toggle_verify_structure_diag",
                axis=str(axis or "")[:16],
                label=label[:80],
                visual_candidate_id=str(visual_candidate_id or "")[:120],
                source_profile_username=str(source_profile_username or "")[:120],
                nearby_node_count=int(nearby_node_count),
                right_side_node_count=int(right_side_node_count),
                sampled_classnames=sampled_classnames,
                sampled_checkable_nodes=sampled_checkable_nodes,
                xml_dump_path=xml_dump_path[:400],
                screenshot_path=(screenshot_path or "")[:400],
                label_bounds=label_bounds,
                nearby_nodes_sample=nearby_rows[:8],
            )
        except Exception:
            pass
    except Exception as exc:
        try:
            log(
                "info",
                "mute_engine_v2_toggle_verify_structure_diag_failed",
                axis=str(axis or "")[:16],
                label=label[:80],
                error=str(exc)[:240],
            )
        except Exception:
            pass


def _visual_verify_toggle_on_for_labels(
    d: u2.Device,
    labels: tuple[str, ...],
    timeout_s: float,
) -> bool:
    deadline = time.perf_counter() + float(timeout_s)
    while time.perf_counter() < deadline:
        for lab in labels:
            try:
                el = d(text=lab)
                if not el.exists(timeout=0.1):
                    continue
                c = _visual_switch_checked_near_row(d, el)
                if c is True:
                    return True
            except Exception:
                continue
        time.sleep(0.14)
    return False


def visual_open_following_options_after_follow(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    meta0 = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_following_options_open_started",
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
    )
    tv = visual_target_profile_lock_verify(
        d,
        source_profile_username=source_profile_username,
        action="visual_open_following_options_after_follow",
    )
    if not tv.get("ok"):
        log(
            "info",
            "visual_following_options_open_failed",
            failure_reason="target_profile_lock_mismatch",
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": "target_profile_lock_mismatch",
            "target_profile_lock_mismatch": True,
            "following_detection_method": "",
            "mute_presence": False,
            "source_profile_username": source_profile_username or "",
        }

    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400

    btn, det_m = _visual_pick_profile_header_following_button(d)
    if btn is None:
        log(
            "info",
            "visual_following_options_open_failed",
            failure_reason="following_button_not_found",
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": "following_button_not_found",
            "following_detection_method": "",
            "mute_presence": False,
            "source_profile_username": source_profile_username or "",
        }

    try:
        bx = btn.info.get("bounds") or {}
        log(
            "info",
            "visual_following_options_following_button_detected",
            following_detection_method=det_m,
            bounds=dict(bx),
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )
    except Exception:
        log(
            "info",
            "visual_following_options_following_button_detected",
            following_detection_method=det_m,
            bounds={},
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )

    try:
        btn.click()
    except Exception as e:
        meta_e = _followers_current_pkg_activity(d)
        log(
            "info",
            "visual_following_options_open_failed",
            failure_reason=f"following_click_failed:{e}",
            source_profile_username=source_profile_username or "",
            current_activity=meta_e.get("current_activity"),
            current_package=meta_e.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": f"following_click_failed:{e}",
            "following_detection_method": det_m,
            "mute_presence": False,
            "source_profile_username": source_profile_username or "",
        }

    log(
        "info",
        "visual_following_options_tap_sent",
        following_detection_method=det_m,
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
    )
    time.sleep(0.85)

    mute_el, mute_lab = _visual_find_mute_row_first_sheet(d)
    meta1 = _followers_current_pkg_activity(d)
    if mute_el is None:
        log(
            "info",
            "visual_following_options_open_failed",
            failure_reason="mute_row_not_visible_in_sheet",
            following_detection_method=det_m,
            source_profile_username=source_profile_username or "",
            current_activity=meta1.get("current_activity"),
            current_package=meta1.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": "mute_row_not_visible_in_sheet",
            "following_detection_method": det_m,
            "mute_presence": False,
            "source_profile_username": source_profile_username or "",
        }

    log(
        "info",
        "visual_following_options_open_success",
        following_detection_method=det_m,
        mute_row_label=mute_lab,
        source_profile_username=source_profile_username or "",
        current_activity=meta1.get("current_activity"),
        current_package=meta1.get("current_package"),
    )
    return {
        "ok": True,
        "failure_reason": None,
        "following_detection_method": det_m,
        "mute_presence": True,
        "mute_row_label": mute_lab,
        "source_profile_username": source_profile_username or "",
        "window_w": ww,
        "window_h": wh,
    }


def visual_open_mute_sheet_from_following_options(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    meta0 = _followers_current_pkg_activity(d)
    log(
        "info",
        "visual_mute_options_open_started",
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
    )
    tv = visual_target_profile_lock_verify(
        d,
        source_profile_username=source_profile_username,
        action="visual_open_mute_sheet_from_following_options",
    )
    if not tv.get("ok"):
        log(
            "info",
            "visual_mute_options_open_failed",
            failure_reason="target_profile_lock_mismatch",
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": "target_profile_lock_mismatch",
            "target_profile_lock_mismatch": True,
            "mute_row_label": "",
            "posts_visible": False,
            "stories_visible": False,
            "source_profile_username": source_profile_username or "",
        }

    mute_el, mute_lab = _visual_find_mute_row_first_sheet(d)
    if mute_el is None:
        log(
            "info",
            "visual_mute_options_open_failed",
            failure_reason="mute_row_not_found",
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": "mute_row_not_found",
            "mute_row_label": "",
            "posts_visible": False,
            "stories_visible": False,
            "source_profile_username": source_profile_username or "",
        }

    try:
        mb = mute_el.info.get("bounds") or {}
        log(
            "info",
            "visual_mute_row_detected",
            mute_row_label=mute_lab,
            bounds=dict(mb),
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )
    except Exception:
        log(
            "info",
            "visual_mute_row_detected",
            mute_row_label=mute_lab,
            bounds={},
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )

    try:
        mute_el.click()
    except Exception as e:
        meta_e = _followers_current_pkg_activity(d)
        log(
            "info",
            "visual_mute_options_open_failed",
            failure_reason=f"mute_row_click_failed:{e}",
            mute_row_label=mute_lab,
            source_profile_username=source_profile_username or "",
            current_activity=meta_e.get("current_activity"),
            current_package=meta_e.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": f"mute_row_click_failed:{e}",
            "mute_row_label": mute_lab,
            "posts_visible": False,
            "stories_visible": False,
            "source_profile_username": source_profile_username or "",
        }

    log(
        "info",
        "visual_mute_row_tap_sent",
        mute_row_label=mute_lab,
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
    )
    time.sleep(0.9)

    posts_v = bool(d(text="Posts").exists(timeout=2.0))
    if not posts_v:
        posts_v = bool(d(text="Publications").exists(timeout=2.0))
    stories_v = bool(d(text="Stories").exists(timeout=2.0))
    meta1 = _followers_current_pkg_activity(d)
    if not posts_v or not stories_v:
        log(
            "info",
            "visual_mute_options_open_failed",
            failure_reason="posts_or_stories_labels_missing",
            mute_row_label=mute_lab,
            posts_visible=posts_v,
            stories_visible=stories_v,
            source_profile_username=source_profile_username or "",
            current_activity=meta1.get("current_activity"),
            current_package=meta1.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": "posts_or_stories_labels_missing",
            "mute_row_label": mute_lab,
            "posts_visible": posts_v,
            "stories_visible": stories_v,
            "source_profile_username": source_profile_username or "",
        }

    log(
        "info",
        "visual_mute_options_open_success",
        mute_row_label=mute_lab,
        posts_visible=True,
        stories_visible=True,
        source_profile_username=source_profile_username or "",
        current_activity=meta1.get("current_activity"),
        current_package=meta1.get("current_package"),
    )
    return {
        "ok": True,
        "failure_reason": None,
        "mute_row_label": mute_lab,
        "posts_visible": True,
        "stories_visible": True,
        "source_profile_username": source_profile_username or "",
    }


def visual_toggle_mute_posts_and_stories(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
) -> dict[str, Any]:
    meta0 = _followers_current_pkg_activity(d)
    want_posts = bool(getattr(config, "VISUAL_MUTE_POSTS_AFTER_FOLLOW", True))
    want_stories = bool(getattr(config, "VISUAL_MUTE_STORIES_AFTER_FOLLOW", True))
    verify_after = bool(getattr(config, "VISUAL_MUTE_VERIFY_AFTER_TAP", True))
    verify_to = float(getattr(config, "VISUAL_MUTE_VERIFY_TIMEOUT_S", 3.0) or 3.0)

    log(
        "info",
        "visual_mute_toggle_started",
        want_posts=want_posts,
        want_stories=want_stories,
        verify_after=verify_after,
        source_profile_username=source_profile_username or "",
        current_activity=meta0.get("current_activity"),
        current_package=meta0.get("current_package"),
    )

    tv = visual_target_profile_lock_verify(
        d,
        source_profile_username=source_profile_username,
        action="visual_toggle_mute_posts_and_stories",
    )
    if not tv.get("ok"):
        log(
            "info",
            "visual_mute_toggle_verify_failed",
            failure_reason="target_profile_lock_mismatch",
            posts_verified=False,
            stories_verified=False,
            source_profile_username=source_profile_username or "",
            current_activity=meta0.get("current_activity"),
            current_package=meta0.get("current_package"),
        )
        return {
            "ok": False,
            "failure_reason": "target_profile_lock_mismatch",
            "target_profile_lock_mismatch": True,
            "posts_verified": False,
            "stories_verified": False,
            "source_profile_username": source_profile_username or "",
        }

    try:
        ww, _wh = d.window_size()
    except Exception:
        ww = 1080

    posts_labels = ("Posts", "Publications")
    # Match Stories row only (avoid Notes / other rows sharing substring patterns).
    stories_labels = (
        "Stories",
        "Historias",
        "Storie",
    )

    posts_verified = not want_posts
    stories_verified = not want_stories
    posts_tapped = False
    stories_tapped = False

    def _meta_now() -> dict[str, Any]:
        return _followers_current_pkg_activity(d)

    if want_posts:
        tapped, skip_on, reason, _pel = _visual_tap_toggle_row_for_label(
            d, posts_labels, ww
        )
        m_p = _meta_now()
        if skip_on:
            posts_verified = True
            log(
                "info",
                "visual_mute_posts_toggle_detected",
                skipped_already_on=True,
                source_profile_username=source_profile_username or "",
                current_activity=m_p.get("current_activity"),
                current_package=m_p.get("current_package"),
            )
            if verify_after:
                posts_verified = _visual_verify_toggle_on_for_labels(
                    d, posts_labels, verify_to
                )
                if posts_verified:
                    log(
                        "info",
                        "visual_mute_posts_toggle_verify_success",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_p.get("current_activity"),
                        current_package=m_p.get("current_package"),
                    )
                else:
                    log(
                        "info",
                        "visual_mute_posts_toggle_verify_failed",
                        failure_reason="posts_toggle_not_verified_after_skip_on",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_p.get("current_activity"),
                        current_package=m_p.get("current_package"),
                    )
        elif tapped:
            posts_tapped = True
            log(
                "info",
                "visual_mute_posts_toggle_detected",
                skipped_already_on=False,
                source_profile_username=source_profile_username or "",
                current_activity=m_p.get("current_activity"),
                current_package=m_p.get("current_package"),
            )
            log(
                "info",
                "visual_mute_posts_toggle_tap_sent",
                source_profile_username=source_profile_username or "",
                current_activity=m_p.get("current_activity"),
                current_package=m_p.get("current_package"),
            )
            time.sleep(0.42)
            if verify_after:
                posts_verified = _visual_verify_toggle_on_for_labels(
                    d, posts_labels, verify_to
                )
                if posts_verified:
                    log(
                        "info",
                        "visual_mute_posts_toggle_verify_success",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_p.get("current_activity"),
                        current_package=m_p.get("current_package"),
                    )
                else:
                    log(
                        "info",
                        "visual_mute_posts_toggle_verify_failed",
                        failure_reason="posts_toggle_not_verified",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_p.get("current_activity"),
                        current_package=m_p.get("current_package"),
                    )
            else:
                posts_verified = True
        else:
            posts_verified = False
            log(
                "info",
                "visual_mute_posts_toggle_detected",
                skipped_already_on=False,
                tap_failed=True,
                failure_reason=reason,
                source_profile_username=source_profile_username or "",
                current_activity=m_p.get("current_activity"),
                current_package=m_p.get("current_package"),
            )
            log(
                "info",
                "visual_mute_posts_toggle_verify_failed",
                failure_reason=f"posts_toggle_tap_failed:{reason}",
                source_profile_username=source_profile_username or "",
                current_activity=m_p.get("current_activity"),
                current_package=m_p.get("current_package"),
            )

    if want_stories:
        tapped_s, skip_s, rs, _sel = _visual_tap_toggle_row_for_label(
            d, stories_labels, ww
        )
        m_s = _meta_now()
        if skip_s:
            stories_verified = True
            log(
                "info",
                "visual_mute_stories_toggle_detected",
                skipped_already_on=True,
                source_profile_username=source_profile_username or "",
                current_activity=m_s.get("current_activity"),
                current_package=m_s.get("current_package"),
            )
            if verify_after:
                stories_verified = _visual_verify_toggle_on_for_labels(
                    d, stories_labels, verify_to
                )
                if stories_verified:
                    log(
                        "info",
                        "visual_mute_stories_toggle_verify_success",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_s.get("current_activity"),
                        current_package=m_s.get("current_package"),
                    )
                else:
                    log(
                        "info",
                        "visual_mute_stories_toggle_verify_failed",
                        failure_reason="stories_toggle_not_verified_after_skip_on",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_s.get("current_activity"),
                        current_package=m_s.get("current_package"),
                    )
        elif tapped_s:
            stories_tapped = True
            log(
                "info",
                "visual_mute_stories_toggle_detected",
                skipped_already_on=False,
                source_profile_username=source_profile_username or "",
                current_activity=m_s.get("current_activity"),
                current_package=m_s.get("current_package"),
            )
            log(
                "info",
                "visual_mute_stories_toggle_tap_sent",
                source_profile_username=source_profile_username or "",
                current_activity=m_s.get("current_activity"),
                current_package=m_s.get("current_package"),
            )
            time.sleep(0.42)
            if verify_after:
                stories_verified = _visual_verify_toggle_on_for_labels(
                    d, stories_labels, verify_to
                )
                if stories_verified:
                    log(
                        "info",
                        "visual_mute_stories_toggle_verify_success",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_s.get("current_activity"),
                        current_package=m_s.get("current_package"),
                    )
                else:
                    log(
                        "info",
                        "visual_mute_stories_toggle_verify_failed",
                        failure_reason="stories_toggle_not_verified",
                        source_profile_username=source_profile_username or "",
                        current_activity=m_s.get("current_activity"),
                        current_package=m_s.get("current_package"),
                    )
            else:
                stories_verified = True
        else:
            stories_verified = False
            log(
                "info",
                "visual_mute_stories_toggle_detected",
                skipped_already_on=False,
                tap_failed=True,
                failure_reason=rs,
                source_profile_username=source_profile_username or "",
                current_activity=m_s.get("current_activity"),
                current_package=m_s.get("current_package"),
            )
            log(
                "info",
                "visual_mute_stories_toggle_verify_failed",
                failure_reason=f"stories_toggle_tap_failed:{rs}",
                source_profile_username=source_profile_username or "",
                current_activity=m_s.get("current_activity"),
                current_package=m_s.get("current_package"),
            )

    meta_f = _followers_current_pkg_activity(d)
    both_ok = (not want_posts or posts_verified) and (not want_stories or stories_verified)
    if both_ok:
        log(
            "info",
            "visual_mute_toggle_verify_success",
            posts_verified=not want_posts or posts_verified,
            stories_verified=not want_stories or stories_verified,
            posts_tapped=posts_tapped,
            stories_tapped=stories_tapped,
            source_profile_username=source_profile_username or "",
            current_activity=meta_f.get("current_activity"),
            current_package=meta_f.get("current_package"),
        )
    else:
        _fail_parts: list[str] = []
        if want_posts and not posts_verified:
            _fail_parts.append("posts_not_verified")
        if want_stories and not stories_verified:
            _fail_parts.append("stories_not_verified")
        _combo = "|".join(_fail_parts) if _fail_parts else "incomplete_verify_state"
        log(
            "info",
            "visual_mute_toggle_verify_failed",
            failure_reason=_combo,
            posts_verified=posts_verified,
            stories_verified=stories_verified,
            source_profile_username=source_profile_username or "",
            current_activity=meta_f.get("current_activity"),
            current_package=meta_f.get("current_package"),
        )

    try:
        d.press("back")
        time.sleep(0.45)
        d.press("back")
        time.sleep(0.35)
    except Exception:
        pass

    log(
        "info",
        "visual_mute_toggle_complete",
        ok=both_ok,
        posts_verified=not want_posts or posts_verified,
        stories_verified=not want_stories or stories_verified,
        source_profile_username=source_profile_username or "",
        current_activity=meta_f.get("current_activity"),
        current_package=meta_f.get("current_package"),
    )
    _fin_reason = None
    if not both_ok:
        _fp: list[str] = []
        if want_posts and not posts_verified:
            _fp.append("posts_not_verified")
        if want_stories and not stories_verified:
            _fp.append("stories_not_verified")
        _fin_reason = "|".join(_fp) if _fp else "mute_toggle_incomplete"

    return {
        "ok": both_ok,
        "failure_reason": _fin_reason,
        "posts_verified": not want_posts or posts_verified,
        "stories_verified": not want_stories or stories_verified,
        "posts_tapped": posts_tapped,
        "stories_tapped": stories_tapped,
        "source_profile_username": source_profile_username or "",
    }


def detect_followers_list_screen_visual_fallback(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
    screenshot_path: str | None = None,
) -> dict[str, Any]:
    """
    Screenshot-only followers list hint when XML is stale. Does not tap, scroll, or select rows.
    """
    out: dict[str, Any] = {
        "visual_match": False,
        "visual_confidence": 0.0,
        "visual_follow_button_count": 0,
        "visual_search_area_detected": False,
        "visual_user_rows_detected": 0,
        "visual_profile_tabs_absent": False,
        "visual_followers_title_hint": False,
        "visual_signals": [],
        "screenshot_path_used": None,
        "visual_error": None,
    }
    path = screenshot_path
    temp_shot: str | None = None
    if not path:
        try:
            _ensure_debug_dirs()
            temp_shot = str(
                _SCREENSHOTS_DIR / f"followers_visual_fallback_{int(time.time() * 1000)}.png"
            )
            screenshot(d, temp_shot)
            path = temp_shot
        except Exception as e:
            out["visual_error"] = f"screenshot_failed:{e}"
            return out
    out["screenshot_path_used"] = path
    try:
        from PIL import Image

        im = Image.open(path)
        im_rgb = _visual_downscale_rgb(im, max_w=420)
    except Exception as e:
        out["visual_error"] = f"pil_open_failed:{e}"
        return out

    follow_bands = _visual_count_right_column_blue_bands(im_rgb)
    search_ok = _visual_detect_search_strip(im_rgb)
    user_rows = _visual_count_left_column_row_bands(im_rgb)
    title_hint = _visual_header_dark_text_hint(im_rgb)
    tabs_absent = _visual_bottom_strip_tabs_heuristic(im_rgb, follow_bands)

    out["visual_follow_button_count"] = follow_bands
    out["visual_search_area_detected"] = search_ok
    out["visual_user_rows_detected"] = user_rows
    out["visual_profile_tabs_absent"] = tabs_absent
    out["visual_followers_title_hint"] = title_hint

    min_btns = int(getattr(config, "FOLLOWERS_VISUAL_MIN_FOLLOW_BUTTONS", 3))
    min_conf = float(getattr(config, "FOLLOWERS_VISUAL_FALLBACK_MIN_CONFIDENCE", 0.65))

    conf = 0.0
    sig: list[str] = []
    if follow_bands >= min_btns:
        conf += 0.38 + min(0.22, (follow_bands - min_btns) * 0.05)
        sig.append(f"right_blue_bands:{follow_bands}")
    if search_ok:
        conf += 0.22
        sig.append("search_strip")
    if user_rows >= 3:
        conf += 0.18
        sig.append(f"left_row_bands:{user_rows}")
    elif user_rows >= 2:
        conf += 0.10
        sig.append(f"left_row_bands:{user_rows}")
    if title_hint:
        conf += 0.10
        sig.append("header_dark_text")
    if tabs_absent:
        conf += 0.08
        sig.append("bottom_tabs_absent_heuristic")

    conf = min(1.0, conf)
    out["visual_confidence"] = conf
    out["visual_signals"] = sig
    out["visual_match"] = bool(
        follow_bands >= min_btns and conf >= min_conf and (search_ok or user_rows >= 2)
    )
    return out


def _followers_visual_fallback_log_payload(
    vf: dict[str, Any],
    xml_det: dict[str, Any],
    *,
    screenshot_path: str | None,
    source_profile_username: str | None,
) -> dict[str, Any]:
    return {
        "screenshot_path": screenshot_path or vf.get("screenshot_path_used"),
        "source_profile_username": source_profile_username,
        "visual_follow_button_count": vf.get("visual_follow_button_count"),
        "visual_search_area_detected": vf.get("visual_search_area_detected"),
        "visual_user_rows_detected": vf.get("visual_user_rows_detected"),
        "visual_profile_tabs_absent": vf.get("visual_profile_tabs_absent"),
        "visual_confidence": vf.get("visual_confidence"),
        "xml_current_screen_guess": xml_det.get("current_screen_guess"),
        "xml_candidate_username_count": xml_det.get("candidate_username_count"),
        "xml_scrollable_count": xml_det.get("scrollable_count"),
    }


def _followers_apply_visual_fallback_if_needed(
    d: u2.Device,
    det: dict[str, Any],
    screenshot_path: str | None,
    source_profile_username: str,
    *,
    phase: str,
) -> dict[str, Any]:
    if det.get("is_followers_list"):
        return det
    if not bool(getattr(config, "ENABLE_FOLLOWERS_VISUAL_FALLBACK", False)):
        return det

    log(
        "info",
        "followers_visual_fallback_started",
        phase=phase,
        screenshot_path=screenshot_path,
        source_profile_username=source_profile_username,
        xml_current_screen_guess=det.get("current_screen_guess"),
    )
    vf = detect_followers_list_screen_visual_fallback(
        d,
        source_profile_username=source_profile_username,
        screenshot_path=screenshot_path,
    )
    payload = {
        **_followers_visual_fallback_log_payload(
            vf, det, screenshot_path=screenshot_path, source_profile_username=source_profile_username
        ),
        "visual_match": bool(vf.get("visual_match")),
        "visual_signals": vf.get("visual_signals"),
        "visual_error": vf.get("visual_error"),
        "phase": phase,
    }
    log("info", "followers_visual_fallback_result", **payload)

    if not vf.get("visual_match"):
        log("warning", "followers_visual_fallback_failed", **payload)
        return det

    merged = dict(det)
    merged["is_followers_list"] = True
    merged["open_detection_method"] = "visual_fallback"
    merged["visual_fallback_detail"] = vf
    sigs = list(merged.get("signals") or [])
    sigs.append(f"visual_fallback:{','.join(vf.get('visual_signals') or [])}")
    merged["signals"] = sigs
    log("info", "followers_visual_fallback_match", **payload)
    return merged


def _followers_poll_hierarchy_refresh(d: u2.Device) -> None:
    """Force a fresh accessibility tree (best-effort) before detection."""
    try:
        try:
            d.dump_hierarchy(compressed=False)
        except TypeError:
            d.dump_hierarchy()
    except Exception:
        pass


def followers_force_hierarchy_refresh(
    d: u2.Device,
    source_profile_username: str | None = None,
) -> None:
    """
    Aggressive UiAutomator hierarchy refresh (no scroll/swipe/tap).
    Sequence: dump → sleep 0.5 → dump → sleep 0.5 → dump → app_current.
    """
    log(
        "info",
        "followers_force_refresh_started",
        source_profile_username=source_profile_username,
    )
    for i in range(1, 4):
        _followers_poll_hierarchy_refresh(d)
        pkg, act = _followers_pkg_activity_for_scroll_log(d)
        log(
            "info",
            "followers_force_refresh_dump",
            refresh_index=i,
            current_activity=act,
            current_package=pkg,
            source_profile_username=source_profile_username,
        )
        if i < 3:
            time.sleep(0.5)
    try:
        d.app_current()
    except Exception:
        pass
    pkg, act = _followers_pkg_activity_for_scroll_log(d)
    log(
        "info",
        "followers_force_refresh_done",
        refresh_index=3,
        current_activity=act,
        current_package=pkg,
        source_profile_username=source_profile_username,
    )


def followers_refresh_hierarchy_for_candidates(d: u2.Device) -> None:
    """Single dump (legacy); prefer followers_force_hierarchy_refresh for stale XML after visual open."""
    _followers_poll_hierarchy_refresh(d)


def _followers_after_tap_detect_log_payload(
    det: dict[str, Any],
    attempt_index: int,
) -> dict[str, Any]:
    """Structured payload for post-tap followers list detection logs."""
    return {
        "attempt_index": attempt_index,
        "current_activity": det.get("current_activity"),
        "current_package": det.get("current_package"),
        "action_bar_title": det.get("action_bar_title"),
        "recycler_present": det.get("recycler_present"),
        "listview_present": det.get("listview_present"),
        "scrollable_present": det.get("scrollable_present"),
        "scrollable_count": det.get("scrollable_count"),
        "candidate_username_count": det.get("candidate_username_count"),
        "visible_usernames_sample": det.get("visible_usernames_sample"),
        "profile_tabs_absent": det.get("profile_tabs_absent"),
        "current_screen_guess": det.get("current_screen_guess"),
        "is_followers_list": bool(det.get("is_followers_list")),
    }


def _followers_after_tap_immediate_capture_and_detect(
    d: u2.Device,
    source_profile_username: str,
    *,
    settle_seconds: float = 2.0,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """
    After followers stat tap: settle (no swipe), single dump_hierarchy to XML, screenshot,
    app_current, then detect_followers_list_screen (no extra hierarchy dumps on hot path).
    """
    _ss = float(settle_seconds)
    log(
        "info",
        "followers_after_tap_delayed_capture",
        settle_seconds=_ss,
        phase="before_single_dump_and_screenshot",
    )
    time.sleep(_ss)
    _ensure_debug_dirs()
    shot = _SCREENSHOTS_DIR / "followers_after_tap_immediate.png"
    xml_path = _XML_DIR / "followers_after_tap_immediate.xml"
    paths: dict[str, Any] = {"screenshot_path": str(shot), "xml_path": str(xml_path)}
    hier_text = ""
    try:
        screenshot(d, str(shot))
    except Exception as e:
        paths["screenshot_error"] = str(e)
    try:
        try:
            hier = d.dump_hierarchy(compressed=False)
        except TypeError:
            hier = d.dump_hierarchy()
        hier_text = hier if isinstance(hier, str) else str(hier or "")
        xml_path.write_text(hier_text, encoding="utf-8")
        _followers_store_detect_hierarchy_xml(hier_text, xml_path=str(xml_path))
        _bump_xml_fetch()
    except Exception as e:
        paths["xml_error"] = str(e)
    try:
        d.app_current()
    except Exception:
        pass
    pkg_meta = _followers_current_pkg_activity(d)
    log(
        "info",
        "followers_after_tap_immediate_capture",
        screenshot_path=paths.get("screenshot_path"),
        xml_path=paths.get("xml_path"),
        current_package=pkg_meta.get("current_package"),
        current_activity=pkg_meta.get("current_activity"),
        action_bar_title=None,
        recycler_present=None,
        listview_present=None,
        scrollable_present=None,
        scrollable_count=None,
        candidate_username_count=None,
        visible_usernames_sample=None,
        current_screen_guess=None,
        phase="before_first_detect",
    )
    det = detect_followers_list_screen(
        d,
        source_profile_username=source_profile_username,
        hierarchy_xml=hier_text or None,
    )
    det = _followers_apply_visual_fallback_if_needed(
        d,
        det,
        paths.get("screenshot_path"),
        source_profile_username,
        phase="immediate_after_capture",
    )
    global _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
    _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT += 1
    log(
        "info",
        "followers_after_tap_detect_attempt",
        **_followers_after_tap_detect_log_payload(
            det, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
        ),
        phase="immediate_after_capture",
    )
    log(
        "info",
        "followers_after_tap_immediate_snapshot",
        screenshot_path=paths.get("screenshot_path"),
        xml_path=paths.get("xml_path"),
        current_package=det.get("current_package"),
        current_activity=det.get("current_activity"),
        action_bar_title=det.get("action_bar_title"),
        recycler_present=det.get("recycler_present"),
        listview_present=det.get("listview_present"),
        scrollable_present=det.get("scrollable_present"),
        scrollable_count=det.get("scrollable_count"),
        candidate_username_count=det.get("candidate_username_count"),
        visible_usernames_sample=det.get("visible_usernames_sample"),
        current_screen_guess=det.get("current_screen_guess"),
        is_followers_list=bool(det.get("is_followers_list")),
    )
    _followers_mark_post_tap_immediate_capture_done()
    if det.get("is_followers_list"):
        log(
            "info",
            "followers_after_tap_detect_success",
            **_followers_after_tap_detect_log_payload(
                det, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
            ),
        )
    return paths, det


def _followers_surface_is_stable(
    d: u2.Device,
    *,
    first_xml: str | None,
    first_candidate_count: int | None,
    open_detection_method: str | None,
    candidate_username_count: int,
    current_screen_guess: str,
    source_profile_username: str,
) -> tuple[bool, dict[str, Any]]:
    """
    Light-weight followers/following surface stability check: short settle, re-detect,
    reject obvious UI transitions (counts collapsing, list flag flipping, screen guess
    regressing toward profile/unknown).
    """
    odm = str(open_detection_method or "") or None
    strict_mode = odm == "visual_fallback" and int(candidate_username_count or 0) == 0
    stability_mode: str = (
        "visual_fallback_zero_handles_strict" if strict_mode else "normal"
    )
    guess_before = str(current_screen_guess or "")
    cand_before = int(candidate_username_count or 0)
    ambiguous_guess = frozenset({"likely_profile", "unknown", ""})

    def _fresh_shot() -> str | None:
        try:
            _ensure_debug_dirs()
            p = _SCREENSHOTS_DIR / (
                f"followers_surface_stability_{int(time.perf_counter() * 1000)}.png"
            )
            screenshot(d, str(p))
            return str(p)
        except Exception:
            return None

    def _redetect(shot_fb: str | None) -> dict[str, Any]:
        det_r = detect_followers_list_screen(
            d, source_profile_username=str(source_profile_username or "")
        )
        if shot_fb:
            det_r = _followers_apply_visual_fallback_if_needed(
                d,
                det_r,
                shot_fb,
                str(source_profile_username or ""),
                phase="followers_surface_stability",
            )
        return det_r if isinstance(det_r, dict) else {}

    def _xml_snapshot() -> str | None:
        try:
            try:
                return str(d.dump_hierarchy(compressed=False))
            except TypeError:
                return str(d.dump_hierarchy())
        except Exception:
            return None

    def _pass_ok(
        det_a: dict[str, Any],
        *,
        cand_ref: int,
        guess_ref: str,
        xml_ref: str | None,
        second_xml_equal: bool | None,
    ) -> bool:
        if not bool(det_a.get("is_followers_list")):
            return False
        guess_a = str(det_a.get("current_screen_guess") or "")
        cand_a = int(det_a.get("candidate_username_count") or 0)
        if guess_ref not in ambiguous_guess and guess_a in ambiguous_guess:
            return False
        if first_candidate_count is not None and int(first_candidate_count) > 0:
            if cand_a < 1:
                return False
            if abs(cand_a - int(first_candidate_count)) > max(
                2, int(first_candidate_count) // 4
            ):
                return False
        elif strict_mode:
            if cand_a == 0 and guess_a in ambiguous_guess:
                return False
        if xml_ref is not None and second_xml_equal is not None:
            if not second_xml_equal:
                return False
        if cand_ref > 0:
            if abs(cand_a - cand_ref) > max(1, cand_ref // 5):
                return False
        return True

    meta: dict[str, Any] = {
        "candidate_count_before": cand_before,
        "current_screen_guess_before": guess_before,
        "open_detection_method": str(odm or ""),
        "stability_mode": stability_mode,
        "source_profile_username": str(source_profile_username or ""),
    }
    shot0 = _fresh_shot()

    if strict_mode:
        time.sleep(0.25)
        xml_between = _xml_snapshot()
        det1 = _redetect(shot0)
        xml1 = _xml_snapshot()
        xml_ok1 = True
        if first_xml is not None and xml1 is not None:
            xml_ok1 = xml1 == first_xml
        if not _pass_ok(
            det1,
            cand_ref=cand_before,
            guess_ref=guess_before,
            xml_ref=first_xml,
            second_xml_equal=xml_ok1,
        ):
            c1 = int(det1.get("candidate_username_count") or 0)
            meta.update(
                {
                    "candidate_count_after": c1,
                    "current_screen_guess_after": str(
                        det1.get("current_screen_guess") or ""
                    ),
                    "xml_stable_vs_first": xml_ok1,
                }
            )
            return False, meta
        time.sleep(0.25)
        shot1 = _fresh_shot()
        det2 = _redetect(shot1 or shot0)
        c1 = int(det1.get("candidate_username_count") or 0)
        c2 = int(det2.get("candidate_username_count") or 0)
        xml2 = _xml_snapshot()
        xml_ok2 = True
        if xml_between is not None and xml2 is not None:
            xml_ok2 = xml2 == xml_between
        if abs(c2 - c1) > max(1, max(c1, 1) // 5):
            meta.update(
                {
                    "candidate_count_after": c2,
                    "current_screen_guess_after": str(
                        det2.get("current_screen_guess") or ""
                    ),
                    "candidate_count_cycle1": c1,
                    "xml_stable_between_cycles": xml_ok2,
                }
            )
            return False, meta
        if not _pass_ok(
            det2,
            cand_ref=c1,
            guess_ref=guess_before,
            xml_ref=xml_between,
            second_xml_equal=xml_ok2,
        ):
            meta.update(
                {
                    "candidate_count_after": c2,
                    "current_screen_guess_after": str(
                        det2.get("current_screen_guess") or ""
                    ),
                    "candidate_count_cycle1": c1,
                    "xml_stable_between_cycles": xml_ok2,
                }
            )
            return False, meta
        meta.update(
            {
                "candidate_count_after": c2,
                "current_screen_guess_after": str(det2.get("current_screen_guess") or ""),
                "candidate_count_cycle1": c1,
                "xml_stable_between_cycles": xml_ok2,
            }
        )
        return True, meta

    time.sleep(0.15)
    det_n = _redetect(shot0)
    c_after = int(det_n.get("candidate_username_count") or 0)
    guess_after = str(det_n.get("current_screen_guess") or "")
    xml_after = _xml_snapshot()
    xml_ok = True
    if first_xml is not None and xml_after is not None:
        xml_ok = xml_after == first_xml
    ok_n = _pass_ok(
        det_n,
        cand_ref=cand_before,
        guess_ref=guess_before,
        xml_ref=first_xml,
        second_xml_equal=xml_ok,
    )
    meta.update(
        {
            "candidate_count_after": c_after,
            "current_screen_guess_after": guess_after,
            "xml_stable_vs_first": xml_ok,
        }
    )
    return bool(ok_n), meta


def _followers_poll_followers_list_opened_after_immediate(
    d: u2.Device,
    source_profile_username: str,
    *,
    first_det: dict[str, Any],
) -> tuple[bool, dict[str, Any], dict[str, Any], int]:
    """
    After immediate post-tap capture+detect failed: at most 3 recovery cycles (no scroll/swipe).
    Each cycle: sleep 0.8s, single dump_hierarchy, app_current, detect_followers_list_screen.
    """
    log(
        "info",
        "followers_list_post_tap_refresh_started",
        phase="recovery_after_immediate_miss_max_3",
    )
    first_det_return = first_det
    last_det = first_det
    global _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT

    def _detect_step(*, phase: str, screenshot_path: str | None) -> dict[str, Any]:
        nonlocal last_det
        global _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
        det = detect_followers_list_screen(
            d, source_profile_username=source_profile_username
        )
        det = _followers_apply_visual_fallback_if_needed(
            d,
            det,
            screenshot_path,
            source_profile_username,
            phase=phase,
        )
        last_det = det
        _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT += 1
        attempt_index = _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
        log(
            "info",
            "followers_after_tap_detect_attempt",
            **_followers_after_tap_detect_log_payload(det, attempt_index),
            phase=phase,
        )
        return det

    for recovery_i in range(1, 4):
        time.sleep(0.8)
        log(
            "info",
            "followers_after_tap_delayed_capture",
            settle_seconds=0.8,
            phase=f"recovery_dump_before_detect_{recovery_i}_of_3",
        )
        shot_path = str(
            _SCREENSHOTS_DIR / f"followers_post_tap_recovery_{recovery_i}.png"
        )
        try:
            screenshot(d, shot_path)
        except Exception:
            shot_path = None
        _followers_poll_hierarchy_refresh(d)
        try:
            d.app_current()
        except Exception:
            pass
        det = _detect_step(
            phase=f"recovery_poll_{recovery_i}_of_3",
            screenshot_path=shot_path,
        )
        if det.get("is_followers_list"):
            tap_diag_rd: dict[str, Any] = {
                "entry_v2_source_profile_username": str(source_profile_username or ""),
            }
            gate_shot = shot_path
            if _vision_validation_enabled() and not gate_shot:
                try:
                    _ensure_debug_dirs()
                    gate_shot = str(
                        _SCREENSHOTS_DIR
                        / f"followers_poll_recovery_vision_gate_{recovery_i}.png"
                    )
                    screenshot(d, gate_shot)
                except Exception:
                    gate_shot = None
            if _vision_validation_enabled() and not gate_shot:
                try:
                    log(
                        "warning",
                        "followers_poll_recovery_vision_gate_rejected",
                        source_profile_username=source_profile_username,
                        recovery_cycle=int(recovery_i),
                        reason="no_screenshot_for_vision_gate",
                    )
                except Exception:
                    pass
                continue
            v_ok, v_dict_r = _vision_validation_followers_list_open_gate(
                screenshot_path=str(gate_shot or ""),
                det=det,
                tap_diag=tap_diag_rd,
                source_profile_username=source_profile_username,
            )
            if not v_ok:
                try:
                    log(
                        "warning",
                        "followers_poll_recovery_vision_gate_rejected",
                        source_profile_username=source_profile_username,
                        recovery_cycle=int(recovery_i),
                        vision_validation_result=v_dict_r,
                    )
                except Exception:
                    pass
                continue
            f_xml: str | None = None
            try:
                try:
                    f_xml = str(d.dump_hierarchy(compressed=False))
                except TypeError:
                    f_xml = str(d.dump_hierarchy())
            except Exception:
                f_xml = None
            odm_fb = str(det.get("open_detection_method") or "") or None
            st_ok, st_meta = _followers_surface_is_stable(
                d,
                first_xml=f_xml,
                first_candidate_count=int(det.get("candidate_username_count") or 0),
                open_detection_method=odm_fb,
                candidate_username_count=int(det.get("candidate_username_count") or 0),
                current_screen_guess=str(det.get("current_screen_guess") or ""),
                source_profile_username=source_profile_username,
            )
            if not st_ok:
                try:
                    log(
                        "warning",
                        "followers_poll_recovery_surface_unstable",
                        recovery_cycle=int(recovery_i),
                        **st_meta,
                    )
                except Exception:
                    pass
                continue
            try:
                log(
                    "info",
                    "followers_poll_recovery_surface_stable",
                    recovery_cycle=int(recovery_i),
                    **st_meta,
                )
            except Exception:
                pass
            log(
                "info",
                "followers_after_tap_detect_success",
                **_followers_after_tap_detect_log_payload(
                    det, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
                ),
            )
            return True, first_det_return, last_det, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT

    log(
        "info",
        "followers_list_post_tap_refresh_done",
        phase="recovery_after_immediate_miss_max_3",
    )
    log(
        "info",
        "followers_after_tap_detect_failed",
        **_followers_after_tap_detect_log_payload(
            last_det, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
        ),
    )
    return False, first_det_return, last_det, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT


def _followers_run_followers_list_open_poll_phases(
    d: u2.Device,
    tap_diag: dict[str, Any],
    source_profile_username: str,
) -> tuple[bool, dict[str, Any], dict[str, Any], int]:
    """Immediate capture+detect (no scroll), then up to 3 recovery polls if needed."""
    log(
        "info",
        "followers_list_post_tap_scroll_blocked",
        attempt_index=0,
        post_tap_poll_path_no_programmatic_scroll=True,
        note="post_tap_2s_settle_single_dump_then_detect",
    )
    paths, det_imm = _followers_after_tap_immediate_capture_and_detect(
        d, source_profile_username=source_profile_username
    )
    tap_diag["followers_after_tap_immediate_screenshot_path"] = paths.get(
        "screenshot_path"
    )
    tap_diag["followers_after_tap_immediate_xml_path"] = paths.get("xml_path")
    tap_diag["followers_list_post_tap_capture_done"] = True
    if det_imm.get("is_followers_list"):
        return True, det_imm, det_imm, _FOLLOWERS_POST_TAP_DETECT_ATTEMPT_COUNT
    return _followers_poll_followers_list_opened_after_immediate(
        d, source_profile_username, first_det=det_imm
    )


def _log_followers_list_detect_failed(
    d: u2.Device,
    det: dict[str, Any],
    *,
    source_profile_username: str,
    stem: str,
    cap: dict[str, Any] | None = None,
) -> dict[str, Any]:
    c = cap if cap is not None else _followers_debug_capture(d, stem)
    log(
        "warning",
        "followers_list_detect_snapshot",
        source_profile_username=source_profile_username,
        is_followers_list=det.get("is_followers_list"),
        title_match=det.get("title_match"),
        action_bar_title=det.get("action_bar_title"),
        visible_header_texts=det.get("visible_header_texts"),
        recycler_present=det.get("recycler_present"),
        scrollable_present=det.get("scrollable_present"),
        scrollable_count=det.get("scrollable_count"),
        candidate_username_count=det.get("candidate_username_count"),
        visible_usernames_sample=det.get("visible_usernames_sample"),
        screenshot_path=c.get("screenshot_path"),
        xml_path=c.get("xml_path"),
    )
    return c


def _followers_open_build_failure_meta(
    *,
    source_profile_username: str,
    failure_reason: str,
    profile_verified: bool,
    pkg_meta: dict[str, Any],
    screen_guess: str,
    tap_diag: dict[str, Any] | None,
    after_tap_screen_snapshot: dict[str, Any] | None,
    last_poll_snapshot: dict[str, Any] | None,
    cap: dict[str, Any] | None,
    open_method: str,
    used_coord_fallback: bool | None = None,
) -> dict[str, Any]:
    td = tap_diag or {}
    ucf = used_coord_fallback
    if ucf is None:
        ucf = bool(td.get("followers_coord_fallback"))
    return {
        "failure_reason": failure_reason,
        "profile_verified": bool(profile_verified),
        "source_profile_username": source_profile_username,
        "stats_band_texts": list(td.get("stats_band_texts") or []),
        "followers_stat_text": td.get("followers_stat_text"),
        "followers_stat_bounds": td.get("followers_stat_bounds"),
        "stats_band_center_y_source": td.get("stats_band_center_y_source"),
        "tap_x": td.get("tap_x"),
        "tap_y": td.get("tap_y"),
        "tap_method": td.get("tap_method"),
        "open_method": open_method,
        "current_package": pkg_meta.get("current_package"),
        "current_activity": pkg_meta.get("current_activity"),
        "current_screen_guess": screen_guess,
        "after_tap_screen_snapshot": after_tap_screen_snapshot or {},
        "last_poll_snapshot": last_poll_snapshot or {},
        "debug_screenshot_path": (cap or {}).get("screenshot_path"),
        "debug_xml_path": (cap or {}).get("xml_path"),
        "followers_stat_found": td.get("followers_stat_found"),
        "used_coord_fallback": ucf,
        "profile_stats_visible": td.get("profile_stats_visible"),
        "followers_stat_text_detected": td.get("followers_stat_text_detected"),
        "followers_stat_text_bounds": td.get("followers_stat_text_bounds"),
        "followers_stat_tap_x": td.get("followers_stat_tap_x"),
        "followers_stat_tap_y": td.get("followers_stat_tap_y"),
        "followers_stat_tap_source": td.get("followers_stat_tap_source"),
        "followers_stat_text_dump": td.get("followers_stat_text_dump"),
        "followers_stat_coordinate_retry": td.get("followers_stat_coordinate_retry"),
        "profile_rescan_swiped": td.get("profile_rescan_swiped"),
        "debug_before_scan_screenshot_path": td.get("debug_before_scan_screenshot_path"),
        "debug_before_scan_xml_path": td.get("debug_before_scan_xml_path"),
        "debug_after_fallback_screenshot_path": td.get("debug_after_fallback_screenshot_path"),
        "debug_after_fallback_xml_path": td.get("debug_after_fallback_xml_path"),
    }


def _followers_open_emit_failure(
    meta: dict[str, Any],
) -> None:
    """Guaranteed full JSON line for agents / Supabase correlation (includes nulls)."""
    print(
        json.dumps(
            {"event": "followers_list_open_failed_debug", **meta},
            ensure_ascii=False,
            default=str,
        ),
        flush=True,
    )
    log("error", "followers_list_open_failed", _include_null_fields=True, **meta)


def _followers_scroll_list_forward(
    d: u2.Device,
    *,
    apply_exploratory_xml_override: bool = False,
    scroll_profile: str = "default",
    source_profile_username: str | None = None,
    scroll_reposition_meta: dict[str, Any] | None = None,
    bypass_post_tap_capture_gate: bool = False,
    bypass_scroll_xml_guards: bool = False,
    scroll_diag_out: dict[str, Any] | None = None,
    account_id: str = "",
    target_id: str = "",
    run_id: str = "",
    previous_actual_overlap: int | None = None,
) -> bool:
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE
    global _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON

    def _sd(key: str, val: Any) -> None:
        if scroll_diag_out is None:
            return
        scroll_diag_out[key] = val

    if _followers_abort_scroll_if_post_tap_lock("_followers_scroll_list_forward"):
        _sd("failure_reason", "post_tap_lock_active")
        _sd("whether_physical_swipe_attempted", False)
        return False
    if not bypass_post_tap_capture_gate and not _followers_post_tap_capture_gate_ok():
        log(
            "info",
            "followers_post_tap_scroll_prevented",
            source="_followers_scroll_list_forward",
            reason="post_tap_immediate_capture_not_done",
        )
        _sd("failure_reason", "post_tap_immediate_capture_not_done")
        _sd("whether_physical_swipe_attempted", False)
        _sd("bypass_post_tap_capture_gate", False)
        return False
    if bypass_post_tap_capture_gate:
        _sd("bypass_post_tap_capture_gate", True)
    use_exploratory = bool(apply_exploratory_xml_override) and bool(
        _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE
    )
    profile_req = str(scroll_profile or "default").strip() or "default"
    if profile_req not in (
        "default",
        "micro_reposition",
        "zero_follow_spans_soft",
        "accelerated_skip_streak",
        "soft_initial",
        "soft_retry",
        "canonical_adaptive",
        "canonical_controlled",
    ):
        profile_req = "default"
    micro_reposition = bool(use_exploratory) and profile_req == "micro_reposition"
    zero_follow_spans_soft = bool(use_exploratory) and profile_req == "zero_follow_spans_soft"
    accelerated_skip_streak = profile_req == "accelerated_skip_streak"
    soft_followers_scroll = profile_req in {"soft_initial", "soft_retry", "welcome_soft"}
    canonical_controlled = profile_req == "canonical_controlled"
    canonical_adaptive = profile_req == "canonical_adaptive"
    exhausted_was = False
    fallback_guard_would_block = False
    permit_reason_snapshot = ""
    if use_exploratory:
        exhausted_was = bool(_FOLLOWERS_VISUAL_XML_STALE_EXHAUSTED)
        fallback_guard_would_block = (
            _FOLLOWERS_LAST_OPEN_DETECTION_METHOD == "visual_fallback"
            and _FOLLOWERS_LAST_ITER_CANDIDATE_COUNT == 0
            and not _FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS
        )
        permit_reason_snapshot = str(_FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON or "")
    else:
        if not bypass_scroll_xml_guards and _FOLLOWERS_VISUAL_XML_STALE_EXHAUSTED:
            log(
                "info",
                "followers_post_tap_scroll_prevented",
                source="_followers_scroll_list_forward",
                reason="followers_visual_xml_stale_exhausted",
            )
            _sd("failure_reason", "followers_visual_xml_stale_exhausted")
            _sd("whether_physical_swipe_attempted", False)
            return False
        if not bypass_scroll_xml_guards and (
            _FOLLOWERS_LAST_OPEN_DETECTION_METHOD == "visual_fallback"
            and _FOLLOWERS_LAST_ITER_CANDIDATE_COUNT == 0
            and not _FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS
        ):
            log(
                "info",
                "followers_post_tap_scroll_prevented",
                source="_followers_scroll_list_forward",
                reason="visual_fallback_zero_candidates_wait_for_xml_refresh",
            )
            _sd("failure_reason", "visual_fallback_zero_candidates_wait_for_xml_refresh")
            _sd("whether_physical_swipe_attempted", False)
            return False
    if bypass_scroll_xml_guards:
        _sd("bypass_scroll_xml_guards", True)
    log("info", "followers_list_scroll", direction="forward")
    _sd("whether_physical_swipe_attempted", True)
    scroll_ok = False
    fallback_fixed_micro_used = False
    if canonical_controlled or canonical_adaptive:
        started = time.perf_counter()
        try:
            w, h = d.window_size()
        except Exception:
            w, h = 1080, 2400
        current_xml = str(_LAST_FOLLOWERS_DETECT_HIERARCHY_XML or "")
        short_geometry = canonical_follow_scroll_geometry(w, h)
        max_forward_attempts = 3 if canonical_adaptive else 1
        _sd("max_forward_attempts", max_forward_attempts)
        _sd("short_fallback_preserved", True)
        _sd("forward_attempts", [])
        unsafe_anchor_loss = False

        for forward_attempt in range(1, max_forward_attempts + 1):
            before_surface = followers_list_continuation_from_hierarchy_xml(
                current_xml,
                flow="follow",
                viewport_height=h,
            )
            before_rows = list(before_surface.get("primary_row_ids") or [])
            before_fp = viewport_fingerprint(before_rows)
            if forward_attempt == 1 and canonical_adaptive:
                geometry = adaptive_follow_scroll_geometry(
                    w,
                    h,
                    list(before_surface.get("fully_visible_primary_row_centers_y") or []),
                    previous_actual_overlap=previous_actual_overlap,
                    partial_row_count=int(before_surface.get("partial_primary_row_count") or 0),
                )
                attempt_kind = "adaptive"
            else:
                geometry = dict(short_geometry)
                attempt_kind = "short_fallback" if forward_attempt == 2 else "bounded_short_recovery"
            if before_rows:
                _instagram_list_event(
                    "instagram_list_primary_rows_detected",
                    flow="follow",
                    account_id=account_id,
                    target_id=target_id,
                    run_id=run_id,
                    fingerprint_before=before_fp,
                    visible_primary_row_count=len(before_rows),
                    scroll_distance=0.0,
                    reason=f"pre_scroll_primary_viewport_{attempt_kind}",
                )
            _instagram_list_event(
                "instagram_list_scroll_started",
                flow="follow",
                account_id=account_id,
                target_id=target_id,
                run_id=run_id,
                fingerprint_before=before_fp,
                visible_primary_row_count=len(before_rows),
                scroll_distance=float(geometry["distance_ratio"]),
                reason=f"canonical_{attempt_kind}_attempt_{forward_attempt}",
                target_new_rows=int(geometry.get("target_new_rows") or 0),
                target_overlap_rows=int(geometry.get("target_overlap_rows") or 0),
                fully_visible_count=int(before_surface.get("fully_visible_primary_row_count") or 0),
                partial_row_count=int(before_surface.get("partial_primary_row_count") or 0),
                median_row_spacing_px=int(geometry.get("median_row_spacing_px") or 0),
                requested_ratio=float(geometry.get("distance_ratio") or 0.0),
                effective_ratio=float(geometry.get("distance_ratio") or 0.0),
                adaptive_adjustment_px=int(geometry.get("adaptive_adjustment_px") or 0),
                adaptive_adjustment=str(geometry.get("adaptive_adjustment_reason") or ""),
                fallback_reason=str(geometry.get("fallback_reason") or ""),
            )
            gesture_ok = False
            try:
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason=f"canonical_{attempt_kind}_follow_swipe",
                )
                d.swipe(
                    int(geometry["x"]),
                    int(geometry["y_start"]),
                    int(geometry["x"]),
                    int(geometry["y_end"]),
                    float(geometry["duration_s"]),
                )
                time.sleep(0.45 if forward_attempt < 3 else 0.60)
                gesture_ok = True
            except Exception:
                gesture_ok = False
            after_xml = followers_refresh_detect_hierarchy_cache(d) if gesture_ok else ""
            after_surface = followers_list_continuation_from_hierarchy_xml(
                after_xml,
                flow="follow",
                scroll_attempted=True,
                viewport_fingerprint_before=before_fp,
                viewport_height=h,
            )
            after_rows = list(after_surface.get("primary_row_ids") or [])
            continuity = compare_instagram_list_viewports(before_rows, after_rows)
            attempt_diag = {
                "attempt": forward_attempt,
                "kind": attempt_kind,
                "gesture_ok": gesture_ok,
                "distance_ratio": geometry["distance_ratio"],
                "distance_px": geometry["distance_px"],
                "fingerprint_before": continuity.fingerprint_before,
                "fingerprint_after": continuity.fingerprint_after,
                "visible_before": len(before_rows),
                "visible_after": len(after_rows),
                "fully_visible_before": int(before_surface.get("fully_visible_primary_row_count") or 0),
                "fully_visible_after": int(after_surface.get("fully_visible_primary_row_count") or 0),
                "partial_before": int(before_surface.get("partial_primary_row_count") or 0),
                "partial_after": int(after_surface.get("partial_primary_row_count") or 0),
                "overlap_count": continuity.overlap_count,
                "new_row_count": continuity.new_row_count,
                "reason": continuity.reason,
            }
            if scroll_diag_out is not None:
                scroll_diag_out["forward_attempts"].append(attempt_diag)
            _sd("forward_attempt_count", forward_attempt)
            _sd("viewport_fingerprint_before", continuity.fingerprint_before)
            _sd("viewport_fingerprint_after", continuity.fingerprint_after)
            _sd("visible_primary_row_count_before", len(before_rows))
            _sd("visible_primary_row_count_after", len(after_rows))
            _sd("fully_visible_count", int(before_surface.get("fully_visible_primary_row_count") or 0))
            _sd("fully_visible_count_after", int(after_surface.get("fully_visible_primary_row_count") or 0))
            _sd("partial_row_count", int(before_surface.get("partial_primary_row_count") or 0))
            _sd("partial_row_count_after", int(after_surface.get("partial_primary_row_count") or 0))
            _sd("target_new_rows", int(geometry.get("target_new_rows") or 0))
            _sd("target_overlap", int(geometry.get("target_overlap_rows") or 0))
            _sd("adaptive_adjustment", str(geometry.get("adaptive_adjustment_reason") or ""))
            _sd("adaptive_adjustment_px", int(geometry.get("adaptive_adjustment_px") or 0))
            _sd("fallback_reason", str(geometry.get("fallback_reason") or ""))
            _sd("overlap_count", continuity.overlap_count)
            _sd("new_primary_row_count", continuity.new_row_count)
            _sd("scroll_distance_ratio", geometry["distance_ratio"])
            _sd("scroll_distance_px", geometry["distance_px"])
            _sd("viewport_unchanged", continuity.unchanged)
            _sd("scroll_excessive", continuity.excessive)
            _sd("depth_advanced", continuity.continuity_proved)
            _sd("surface_state_after", str(after_surface.get("state") or ""))

            if continuity.continuity_proved:
                scroll_ok = True
                _instagram_list_event(
                    "instagram_list_viewport_overlap_verified",
                    flow="follow",
                    account_id=account_id,
                    target_id=target_id,
                    run_id=run_id,
                    fingerprint_before=continuity.fingerprint_before,
                    fingerprint_after=continuity.fingerprint_after,
                    visible_primary_row_count=len(after_rows),
                    overlap_count=continuity.overlap_count,
                    scroll_distance=float(geometry["distance_ratio"]),
                    reason=f"{attempt_kind}_{continuity.reason}",
                    elapsed_ms=(time.perf_counter() - started) * 1000.0,
                    fully_visible_count=int(after_surface.get("fully_visible_primary_row_count") or 0),
                    partial_row_count=int(after_surface.get("partial_primary_row_count") or 0),
                    actual_new_rows=int(continuity.new_row_count),
                    actual_overlap=int(continuity.overlap_count),
                    anchor_verified=bool(continuity.overlap_count > 0),
                    continuity_result=str(continuity.reason),
                    adaptive_adjustment=str(geometry.get("adaptive_adjustment_reason") or ""),
                    fallback_reason=str(geometry.get("fallback_reason") or ""),
                )
                break

            safe_surface_state = after_surface.get("state") in {
                InstagramListContinuationState.EXPAND_PRIMARY_LIST_AVAILABLE.value,
                InstagramListContinuationState.SUGGESTIONS_BOUNDARY_CONFIRMED.value,
            }
            if safe_surface_state:
                _sd("depth_advanced", False)
                scroll_ok = True
                break

            if continuity.excessive:
                _instagram_list_event(
                    "instagram_list_scroll_excessive",
                    flow="follow",
                    account_id=account_id,
                    target_id=target_id,
                    run_id=run_id,
                    fingerprint_before=continuity.fingerprint_before,
                    fingerprint_after=continuity.fingerprint_after,
                    visible_primary_row_count=len(after_rows),
                    overlap_count=0,
                    scroll_distance=float(geometry["distance_ratio"]),
                    reason="no_anchor_overlap_corrective_backstep",
                    elapsed_ms=(time.perf_counter() - started) * 1000.0,
                )
                try:
                    correction_distance = min(int(h * 0.18), int(geometry["distance_px"]))
                    correction_start = int(h * 0.38)
                    correction_end = min(int(h * 0.62), correction_start + correction_distance)
                    d.swipe(int(geometry["x"]), correction_start, int(geometry["x"]), correction_end, 0.34)
                    time.sleep(0.45)
                    corrected_xml = followers_refresh_detect_hierarchy_cache(d)
                    corrected_surface = followers_list_continuation_from_hierarchy_xml(
                        corrected_xml,
                        flow="follow",
                        scroll_attempted=True,
                        viewport_fingerprint_before=before_fp,
                        viewport_height=h,
                    )
                    corrected_rows = list(corrected_surface.get("primary_row_ids") or [])
                    corrected = compare_instagram_list_viewports(before_rows, corrected_rows)
                    _sd("corrective_backstep_used", True)
                    _sd("corrective_backstep_reason", corrected.reason)
                    _sd("viewport_fingerprint_after", corrected.fingerprint_after)
                    if corrected.continuity_proved:
                        _sd("overlap_count", corrected.overlap_count)
                        _sd("new_primary_row_count", corrected.new_row_count)
                        _sd("depth_advanced", True)
                        scroll_ok = True
                        current_xml = corrected_xml
                        break
                    if corrected.unchanged:
                        current_xml = corrected_xml
                    else:
                        unsafe_anchor_loss = True
                        _sd("failure_reason", "anchor_not_recovered_after_excessive_scroll")
                        break
                except Exception:
                    unsafe_anchor_loss = True
                    _sd("failure_reason", "corrective_backstep_failed")
                    break
            elif continuity.unchanged:
                current_xml = after_xml or current_xml
                _sd("failure_reason", f"viewport_unchanged_after_{attempt_kind}")
            else:
                # A transient empty/ambiguous dump must not consume depth. One
                # fresh XML-only reprobe may prove that the original anchor is
                # still intact, in which case the short fallback remains safe.
                reprobe_xml = followers_refresh_detect_hierarchy_cache(d)
                reprobe_surface = followers_list_continuation_from_hierarchy_xml(
                    reprobe_xml,
                    flow="follow",
                    viewport_height=h,
                )
                reprobe_rows = list(reprobe_surface.get("primary_row_ids") or [])
                reprobe = compare_instagram_list_viewports(before_rows, reprobe_rows)
                _sd("ambiguous_reprobe_used", True)
                _sd("ambiguous_reprobe_reason", reprobe.reason)
                if reprobe.unchanged:
                    current_xml = reprobe_xml
                    _sd("failure_reason", f"ambiguous_reprobe_restored_anchor_after_{attempt_kind}")
                else:
                    unsafe_anchor_loss = True
                    _sd("failure_reason", f"ambiguous_viewport_after_{attempt_kind}")
                    break

        if not scroll_ok:
            _sd("unsafe_anchor_loss", unsafe_anchor_loss)
            if not unsafe_anchor_loss:
                _sd("failure_reason", "adaptive_short_and_bounded_recovery_exhausted")
    elif micro_reposition:
        w, h = 0, 0
        try:
            w, h = d.window_size()
        except Exception:
            w, h = 1080, 1920
        _meta_ok = False
        _tap_ref: int | None = None
        _orig_h: int | None = None
        if isinstance(scroll_reposition_meta, dict) and scroll_reposition_meta:
            try:
                _tap_ref = int(scroll_reposition_meta.get("tap_y_ref_o"))
                _orig_h = int(scroll_reposition_meta.get("orig_h_o"))
                _meta_ok = _orig_h > 0 and _tap_ref > 0
            except (TypeError, ValueError):
                _meta_ok = False
        if _meta_ok and w > 0 and h > 0:
            tap_ratio = float(_tap_ref) / float(_orig_h)
            target_ratio = 0.30
            desired_shift_ratio = max(0.0, tap_ratio - target_ratio)
            gesture_distance_px = int(desired_shift_ratio * float(h) * 0.55)
            cap_min_px = int(h * 0.12)
            cap_max_px = int(h * 0.34)
            gesture_distance_px = max(cap_min_px, gesture_distance_px)
            gesture_distance_px = min(cap_max_px, gesture_distance_px)
            x = int(w // 2)
            y_start = int(h * 0.76)
            y_end = max(int(h * 0.28), y_start - gesture_distance_px)
            duration_s = 0.34
            try:
                log(
                    "info",
                    "followers_visual_dynamic_reposition_scroll_started",
                    source_profile_username=str(source_profile_username or ""),
                    tap_y_ref_o=int(_tap_ref),
                    orig_h_o=int(_orig_h),
                    tap_ratio=round(tap_ratio, 5),
                    target_ratio=target_ratio,
                    desired_shift_ratio=round(desired_shift_ratio, 5),
                    gesture_distance_px=int(gesture_distance_px),
                    y_start=int(y_start),
                    y_end=int(y_end),
                    duration_s=float(duration_s),
                    capped_min_px=int(cap_min_px),
                    capped_max_px=int(cap_max_px),
                    y_safe_bottom_o=int(scroll_reposition_meta.get("y_safe_bottom_o") or 0)
                    if isinstance(scroll_reposition_meta, dict)
                    else 0,
                    screen_w=int(w),
                    screen_h=int(h),
                )
            except Exception:
                pass
            try:
                d.swipe(x, y_start, x, y_end, duration_s)
                time.sleep(0.22)
                scroll_ok = True
            except Exception:
                scroll_ok = False
        else:
            fallback_fixed_micro_used = True
            try:
                x = int(w // 2)
                y_start = int(h * 0.66)
                y_end = int(h * 0.60)
                duration_s = 0.30
                swipe_distance_px = abs(int(y_end) - int(y_start))
                try:
                    log(
                        "info",
                        "followers_visual_micro_reposition_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        reason="unsafe_low_follow_cta_defer_fallback_fixed_micro",
                        x=x,
                        y_start=y_start,
                        y_end=y_end,
                        swipe_distance_px=int(swipe_distance_px),
                        duration_s=float(duration_s),
                        screen_w=int(w),
                        screen_h=int(h),
                    )
                except Exception:
                    pass
                d.swipe(x, y_start, x, y_end, duration_s)
                time.sleep(0.22)
                scroll_ok = True
            except Exception:
                scroll_ok = False
        try:
            log(
                "info",
                "followers_visual_dynamic_reposition_scroll_used",
                source_profile_username=str(source_profile_username or ""),
                scroll_succeeded=bool(scroll_ok),
                one_shot_consumed=True,
                fallback_fixed_micro_used=bool(fallback_fixed_micro_used),
            )
        except Exception:
            pass
        try:
            log(
                "info",
                "followers_visual_micro_reposition_scroll_used",
                source_profile_username=str(source_profile_username or ""),
                reason="unsafe_low_follow_cta_defer",
                scroll_succeeded=bool(scroll_ok),
                one_shot_consumed=True,
            )
        except Exception:
            pass
    elif zero_follow_spans_soft:
        _mode = ""
        _zf_soft_steps = int(getattr(config, "FOLLOWERS_LIST_PROGRESSIVE_SOFT_SCROLL_STEPS", 4) or 4)
        _zf_soft_steps = max(1, min(_zf_soft_steps, 6))
        try:
            rv = d(classNameMatches=".*RecyclerView.*")
            if rv.exists(timeout=0.25):
                _mode = "recyclerview"
                try:
                    log(
                        "info",
                        "followers_visual_zero_follow_spans_soft_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        permit_reason=permit_reason_snapshot,
                        profile="zero_follow_spans_soft",
                        mode=_mode,
                        steps=int(_zf_soft_steps),
                    )
                except Exception:
                    pass
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason="recyclerview_scroll_vert_forward_zero_follow_spans_soft",
                )
                rv.scroll.vert.forward(steps=int(_zf_soft_steps))
                time.sleep(0.22)
                scroll_ok = True
        except Exception:
            pass
        if not scroll_ok:
            try:
                w, h = d.window_size()
                y_start = int(h * 0.68)
                y_end = int(h * 0.48)
                duration_s = 0.28
                _mode = "fallback_swipe"
                try:
                    log(
                        "info",
                        "followers_visual_zero_follow_spans_soft_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        permit_reason=permit_reason_snapshot,
                        profile="zero_follow_spans_soft",
                        mode=_mode,
                        steps=None,
                        y_start=int(y_start),
                        y_end=int(y_end),
                        duration_s=float(duration_s),
                        screen_w=int(w),
                        screen_h=int(h),
                    )
                except Exception:
                    pass
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason="fallback_vertical_swipe_followers_list_zero_follow_spans_soft",
                )
                d.swipe(w // 2, y_start, w // 2, y_end, duration_s)
                time.sleep(0.22)
                scroll_ok = True
            except Exception:
                scroll_ok = False
        try:
            log(
                "info",
                "followers_visual_zero_follow_spans_soft_scroll_used",
                source_profile_username=str(source_profile_username or ""),
                scroll_succeeded=bool(scroll_ok),
                one_shot_consumed=True,
                permit_reason=permit_reason_snapshot,
                profile="zero_follow_spans_soft",
                mode=_mode or ("recyclerview" if scroll_ok else "unknown"),
            )
        except Exception:
            pass
    elif soft_followers_scroll:
        _mode = ""
        _distance_ratio = 0.25 if profile_req in {"soft_initial", "welcome_soft"} else 0.27
        _soft_steps = 4
        try:
            rv = d(classNameMatches=".*RecyclerView.*")
            if profile_req != "welcome_soft" and rv.exists(timeout=0.25):
                _mode = "recyclerview"
                try:
                    log(
                        "info",
                        "followers_list_soft_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        strategy=profile_req,
                        mode=_mode,
                        steps=int(_soft_steps),
                        distance_ratio=_distance_ratio,
                        expected_new_rows_min=7,
                    )
                except Exception:
                    pass
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason=f"recyclerview_scroll_vert_forward_{profile_req}",
                )
                rv.scroll.vert.forward(steps=int(_soft_steps))
                time.sleep(0.22)
                scroll_ok = True
        except Exception:
            pass
        if not scroll_ok:
            try:
                w, h = d.window_size()
                y_start = int(h * 0.66)
                y_end = int(h * (0.66 - _distance_ratio))
                duration_s = 0.24
                _mode = "fallback_swipe"
                try:
                    log(
                        "info",
                        "followers_list_soft_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        strategy=profile_req,
                        mode=_mode,
                        y_start=int(y_start),
                        y_end=int(y_end),
                        duration_s=float(duration_s),
                        distance_ratio=_distance_ratio,
                        screen_w=int(w),
                        screen_h=int(h),
                        expected_new_rows_min=7,
                    )
                except Exception:
                    pass
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason=f"fallback_vertical_swipe_followers_list_{profile_req}",
                )
                d.swipe(w // 2, y_start, w // 2, y_end, duration_s)
                time.sleep(0.22)
                scroll_ok = True
            except Exception:
                scroll_ok = False
        try:
            log(
                "info",
                "followers_list_soft_scroll_completed",
                source_profile_username=str(source_profile_username or ""),
                strategy=profile_req,
                scroll_succeeded=bool(scroll_ok),
                mode=_mode or ("recyclerview" if scroll_ok else "unknown"),
                distance_ratio=_distance_ratio,
                expected_new_rows_min=7,
            )
        except Exception:
            pass
    elif accelerated_skip_streak:
        _accel_steps = int(
            getattr(config, "FOLLOWERS_EXPLORATION_V1_ACCEL_RECYCLER_STEPS", 10) or 10
        )
        _accel_steps = max(4, min(_accel_steps, 14))
        _mode = ""
        try:
            rv = d(classNameMatches=".*RecyclerView.*")
            if rv.exists(timeout=0.25):
                _mode = "recyclerview"
                try:
                    log(
                        "info",
                        "followers_list_strong_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        strategy="strong_search",
                        mode=_mode,
                        steps=int(_accel_steps),
                        distance_ratio=0.56,
                    )
                    log(
                        "info",
                        "followers_exploration_accelerated_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        profile="accelerated_skip_streak",
                        mode=_mode,
                        steps=int(_accel_steps),
                    )
                except Exception:
                    pass
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason="recyclerview_scroll_vert_forward_accelerated_skip_streak",
                )
                rv.scroll.vert.forward(steps=int(_accel_steps))
                time.sleep(0.22)
                scroll_ok = True
        except Exception:
            pass
        if not scroll_ok:
            try:
                w, h = d.window_size()
                y_start = int(h * 0.78)
                y_end = int(h * 0.22)
                duration_s = 0.10
                _mode = "fallback_swipe"
                try:
                    log(
                        "info",
                        "followers_list_strong_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        strategy="strong_search",
                        mode=_mode,
                        y_start=int(y_start),
                        y_end=int(y_end),
                        duration_s=float(duration_s),
                        screen_w=int(w),
                        screen_h=int(h),
                        distance_ratio=0.56,
                    )
                    log(
                        "info",
                        "followers_exploration_accelerated_scroll_started",
                        source_profile_username=str(source_profile_username or ""),
                        profile="accelerated_skip_streak",
                        mode=_mode,
                        y_start=int(y_start),
                        y_end=int(y_end),
                        duration_s=float(duration_s),
                        screen_w=int(w),
                        screen_h=int(h),
                    )
                except Exception:
                    pass
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason="fallback_vertical_swipe_followers_list_accelerated_skip_streak",
                )
                d.swipe(w // 2, y_start, w // 2, y_end, duration_s)
                time.sleep(0.22)
                scroll_ok = True
            except Exception:
                scroll_ok = False
        try:
            log(
                "info",
                "followers_list_strong_scroll_completed",
                source_profile_username=str(source_profile_username or ""),
                strategy="strong_search",
                scroll_succeeded=bool(scroll_ok),
                mode=_mode or ("recyclerview" if scroll_ok else "unknown"),
                distance_ratio=0.56,
            )
            log(
                "info",
                "followers_exploration_accelerated_scroll_used",
                source_profile_username=str(source_profile_username or ""),
                scroll_succeeded=bool(scroll_ok),
                profile="accelerated_skip_streak",
                mode=_mode or ("recyclerview" if scroll_ok else "unknown"),
            )
        except Exception:
            pass
    else:
        try:
            rv = d(classNameMatches=".*RecyclerView.*")
            if rv.exists(timeout=0.25):
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason="recyclerview_scroll_vert_forward",
                )
                rv.scroll.vert.forward(steps=6)
                time.sleep(0.22)
                scroll_ok = True
        except Exception:
            pass
        if not scroll_ok:
            try:
                w, h = d.window_size()
                _followers_log_scroll_or_swipe_about_to_run(
                    d,
                    source_function="_followers_scroll_list_forward",
                    reason="fallback_vertical_swipe_followers_list",
                )
                d.swipe(w // 2, int(h * 0.72), w // 2, int(h * 0.32), 0.12)
                time.sleep(0.22)
                scroll_ok = True
            except Exception:
                scroll_ok = False
    if use_exploratory:
        _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_ONCE = False
        _FOLLOWERS_VISUAL_EXPLORATORY_SCROLL_REASON = ""
        try:
            log(
                "info",
                "followers_visual_exploratory_scroll_override_used",
                source="_followers_scroll_list_forward",
                reason=permit_reason_snapshot,
                exhausted_was_true=exhausted_was,
                fallback_zero_candidates_guard_would_block=fallback_guard_would_block,
                one_shot_consumed=True,
                scroll_succeeded=bool(scroll_ok),
            )
        except Exception:
            pass
    _sd("scroll_helper_succeeded", bool(scroll_ok))
    if scroll_diag_out is not None and not scroll_ok:
        scroll_diag_out.setdefault(
            "failure_reason",
            "recyclerview_and_fallback_swipe_failed",
        )
    return scroll_ok


def scroll_followers_list_forward(
    d: u2.Device,
    *,
    apply_exploratory_xml_override: bool = False,
    scroll_profile: str = "default",
    source_profile_username: str | None = None,
    scroll_reposition_meta: dict[str, Any] | None = None,
    bypass_post_tap_capture_gate: bool = False,
    bypass_scroll_xml_guards: bool = False,
    scroll_diag_out: dict[str, Any] | None = None,
    account_id: str = "",
    target_id: str = "",
    run_id: str = "",
    previous_actual_overlap: int | None = None,
) -> bool:
    """Bounded scroll on the followers RecyclerView (or fallback swipe).

    ``scroll_profile``: ``default`` | ``micro_reposition`` (unsafe-low-CTA defer) |
    ``zero_follow_spans_soft`` (exploratory defer after zero blue spans) |
    ``accelerated_skip_streak`` (adaptive V1: faster exit from low-yield visible zone) |
    ``welcome_soft`` (deterministic Golden 0.25-height Welcome scan gesture).
    ``canonical_adaptive`` (Follow-only measured row cadence, 3 attempts maximum).
    ``canonical_controlled`` (Follow-only viewport-relative gesture with overlap proof).

    ``bypass_post_tap_capture_gate`` / ``bypass_scroll_xml_guards`` are narrow escape
    hatches for runner paths that return to a followers list validated visually while XML
    gates (post-tap capture marker, xml-stale exhaustion, zero-candidate visual-fallback
    guard) would otherwise block scrolling.
    """
    return _followers_scroll_list_forward(
        d,
        apply_exploratory_xml_override=apply_exploratory_xml_override,
        scroll_profile=scroll_profile,
        source_profile_username=source_profile_username,
        scroll_reposition_meta=scroll_reposition_meta,
        bypass_post_tap_capture_gate=bypass_post_tap_capture_gate,
        bypass_scroll_xml_guards=bypass_scroll_xml_guards,
        scroll_diag_out=scroll_diag_out,
        account_id=account_id,
        target_id=target_id,
        run_id=run_id,
        previous_actual_overlap=previous_actual_overlap,
    )


def scroll_followers_list_backward(
    d: u2.Device,
    *,
    source_profile_username: str | None = None,
    scroll_steps: int = 1,
    scroll_profile: str = "default",
) -> bool:
    """Scroll followers list toward the scan-start zone (older rows / top of list).

    Narrow helper for Welcome list-native sender reposition after a forward scan scroll.
    """
    steps = max(1, int(scroll_steps))
    try:
        w, h = d.window_size()
    except Exception:
        w, h = 1080, 1920
    x = int(w // 2)
    compact = str(scroll_profile or "").strip().lower() == "compact"
    y_start = int(h * (0.38 if compact else 0.32))
    y_end = int(h * (0.63 if compact else 0.72))
    duration_s = 0.34
    ok_any = False
    for step_idx in range(steps):
        try:
            log(
                "info",
                "followers_list_scroll",
                direction="backward",
                step_index=step_idx + 1,
                step_total=steps,
                scroll_profile="compact" if compact else "default",
                distance_px=abs(int(y_end) - int(y_start)),
                distance_ratio=round(abs(int(y_end) - int(y_start)) / max(1, int(h)), 5),
                source_profile_username=str(source_profile_username or "") or None,
            )
            d.swipe(x, y_start, x, y_end, duration_s)
            time.sleep(0.35)
            ok_any = True
        except Exception:
            return False
    return ok_any


def _followers_fetch_hierarchy_xml_raw(d: u2.Device) -> str | None:
    try:
        try:
            return str(d.dump_hierarchy(compressed=False))
        except TypeError:
            return str(d.dump_hierarchy())
    except Exception:
        return None


def followers_dump_visible_nodes_for_debug(
    d: u2.Device,
    source_profile_username: str | None = None,
    *,
    hierarchy_xml: str | None = None,
) -> dict[str, Any]:
    """
    Parse accessibility XML for TextView / ImageView / Button-class nodes in the list band
    (center Y between 15% and 95% of screen height). No taps or scrolls (read-only).
    """
    try:
        h_scr = int(d.window_size()[1])
    except Exception:
        h_scr = 1920
    y_lo = int(h_scr * 0.15)
    y_hi = int(h_scr * 0.95)
    xmls = hierarchy_xml if hierarchy_xml is not None else _followers_fetch_hierarchy_xml_raw(d)
    out: dict[str, Any] = {
        "node_count": 0,
        "textview_count": 0,
        "button_count": 0,
        "imageview_count": 0,
        "sample_nodes": [],
        "nodes": [],
        "parse_error": None,
        "y_band": {"y_lo": y_lo, "y_hi": y_hi, "screen_h": h_scr},
    }
    if not xmls:
        out["parse_error"] = "no_hierarchy_xml"
        return out
    try:
        root = ET.fromstring(xmls)
    except Exception as e:
        out["parse_error"] = f"xml_parse:{e}"
        return out

    def _class_matches_list_node(cls: str) -> bool:
        c = (cls or "").lower()
        if "edittext" in c:
            return False
        return (
            "textview" in c
            or "imageview" in c
            or "imagebutton" in c
            or c.endswith("button")
            or ".button" in c
        )

    nodes_full: list[dict[str, Any]] = []
    for elem in root.iter():
        tag = str(elem.tag or "")
        if tag != "node" and not tag.endswith("}node"):
            continue
        cls = elem.get("class") or ""
        if not _class_matches_list_node(cls):
            continue
        b_raw = elem.get("bounds") or ""
        bd = _dm_parse_bounds_attr_xml(b_raw)
        if not bd:
            continue
        cy = (int(bd["top"]) + int(bd["bottom"])) // 2
        if cy <= y_lo or cy >= y_hi:
            continue
        node = {
            "className": cls,
            "text": (elem.get("text") or "")[:240],
            "resourceId": elem.get("resource-id") or "",
            "contentDescription": (elem.get("content-desc") or "")[:240],
            "bounds": dict(bd),
            "clickable": str(elem.get("clickable", "")).lower() == "true",
            "enabled": str(elem.get("enabled", "")).lower() != "false",
        }
        nodes_full.append(node)
        lc = cls.lower()
        if "textview" in lc:
            out["textview_count"] += 1
        elif "imageview" in lc or "imagebutton" in lc:
            out["imageview_count"] += 1
        elif "button" in lc:
            out["button_count"] += 1

    out["node_count"] = len(nodes_full)
    out["nodes"] = nodes_full
    out["sample_nodes"] = nodes_full[:45]
    pkg, act = _followers_pkg_activity_for_scroll_log(d)
    out["current_package"] = pkg
    out["current_activity"] = act
    out["source_profile_username"] = source_profile_username
    return out


def _followers_run_visual_open_xml_empty_diagnostic(
    d: u2.Device,
    *,
    source_profile_username: str,
    det_after: dict[str, Any],
) -> None:
    """
    Final capture + XML node summary when list was validated visually but handles are still missing.
    Sets _FOLLOWERS_ENGINE_STOP_REASON (no follow / scroll / candidate tap here).
    """
    global _FOLLOWERS_ENGINE_STOP_REASON
    engine_reason_at_entry = _FOLLOWERS_ENGINE_STOP_REASON
    cap: dict[str, Any] = {}
    try:
        cap = _followers_debug_capture(d, "followers_visual_open_xml_empty_final")
    except Exception as e:
        cap = {"screenshot_error": str(e)}
    hier_text: str | None = None
    try:
        xp = cap.get("xml_path")
        if xp:
            hier_text = Path(xp).read_text(encoding="utf-8")
    except Exception:
        hier_text = None
    if not hier_text:
        hier_text = _followers_fetch_hierarchy_xml_raw(d)

    dump = followers_dump_visible_nodes_for_debug(
        d,
        source_profile_username=source_profile_username,
        hierarchy_xml=hier_text,
    )
    pkg, act = _followers_pkg_activity_for_scroll_log(d)
    log(
        "info",
        "followers_candidate_node_dump",
        node_count=dump.get("node_count"),
        textview_count=dump.get("textview_count"),
        button_count=dump.get("button_count"),
        imageview_count=dump.get("imageview_count"),
        sample_nodes=dump.get("sample_nodes"),
        source_profile_username=source_profile_username,
        current_activity=act,
        current_package=pkg,
        parse_error=dump.get("parse_error"),
        y_band=dump.get("y_band"),
    )
    if (
        bool(getattr(config, "ENABLE_FOLLOWERS_VISUAL_CANDIDATE_DIAGNOSTIC", True))
        and _FOLLOWERS_LAST_OPEN_DETECTION_METHOD == "visual_fallback"
        and engine_reason_at_entry in FOLLOWERS_ENGINE_XML_STALE_EXIT_REASONS
        and int(det_after.get("candidate_username_count") or 0) == 0
    ):
        shot = cap.get("screenshot_path")
        if shot:
            followers_visual_candidate_diagnostic(
                d,
                screenshot_path=str(shot),
                source_profile_username=source_profile_username,
            )
    log(
        "error",
        "followers_visual_open_but_xml_empty_diagnostic",
        reason="visual_open_xml_empty",
        source_profile_username=source_profile_username,
        screenshot_path=cap.get("screenshot_path"),
        xml_path=cap.get("xml_path"),
        candidate_username_count=det_after.get("candidate_username_count"),
        visible_usernames_sample=det_after.get("visible_usernames_sample"),
        recycler_present=det_after.get("recycler_present"),
        scrollable_present=det_after.get("scrollable_present"),
        scrollable_count=det_after.get("scrollable_count"),
        current_screen_guess=det_after.get("current_screen_guess"),
        open_detection_method="visual_fallback",
        node_count=dump.get("node_count"),
        textview_count=dump.get("textview_count"),
        button_count=dump.get("button_count"),
        imageview_count=dump.get("imageview_count"),
    )
    _FOLLOWERS_ENGINE_STOP_REASON = "visual_open_xml_empty"


def _followers_row_tap_bounds(username_bounds: dict[str, Any]) -> dict[str, int]:
    """Expand username TextView bounds into a tappable row band (avatar + handle)."""
    if not username_bounds:
        return {}
    try:
        left = int(username_bounds["left"])
        right = int(username_bounds["right"])
        top = int(username_bounds["top"])
        bottom = int(username_bounds["bottom"])
    except (KeyError, TypeError, ValueError):
        return {}
    h = max(1, bottom - top)
    pad = max(16, h)
    return {
        "left": left,
        "right": right,
        "top": max(0, top - pad),
        "bottom": bottom + pad,
    }


def harvest_visible_followers_rows(
    d: u2.Device,
    *,
    source_profile_username: str,
    runtime_seen: set[str] | None = None,
    force_fresh_hierarchy: bool = False,
    screen_index: int = 0,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """
    Visible follower rows on the current followers list (no scroll).
    Same XML-first path as welcome_scan_producer (follow_list_username).
    """
    seen = runtime_seen if runtime_seen is not None else set()
    extraction_methods: list[str] = []
    hierarchy_source = "cached"
    rows: list[dict[str, Any]] = []
    hier = ""

    if force_fresh_hierarchy:
        hier = followers_refresh_detect_hierarchy_cache(d, screen_index=int(screen_index))
        hierarchy_source = "fresh_dump"
    elif _harvest_own_unified_xml_first_eligible(d):
        hier = _followers_resolve_detect_hierarchy_xml(d, None, live_incomplete=False)
        hierarchy_source = "cached"

    if hier and "follow_list_username" in hier:
        rows = _extract_own_unified_followers_usernames_from_hierarchy_xml(
            hier,
            source_profile_username=source_profile_username,
            runtime_seen=seen,
        )
        if rows:
            extraction_methods.append("own_unified_follow_list_username_xml")
        else:
            log(
                "info",
                "followers_harvest_own_unified_xml_empty",
                source_profile_username=source_profile_username,
                hierarchy_xml_len=len(hier),
                hierarchy_source=hierarchy_source,
            )

    if not rows and not force_fresh_hierarchy:
        hier = followers_refresh_detect_hierarchy_cache(d, screen_index=int(screen_index))
        hierarchy_source = "fresh_dump_retry"
        if hier and "follow_list_username" in hier:
            rows = _extract_own_unified_followers_usernames_from_hierarchy_xml(
                hier,
                source_profile_username=source_profile_username,
                runtime_seen=seen,
            )
            if rows:
                extraction_methods.append("own_unified_follow_list_username_xml")

    if not rows:
        rows = _iter_followers_candidates_collect(
            d,
            source_profile_username=source_profile_username,
            runtime_seen=seen,
        )
        if rows:
            extraction_methods.append("live_u2_textview_handle_regex")
            hierarchy_source = "live_u2"

    enriched: list[dict[str, Any]] = []
    for idx, row in enumerate(rows):
        item = dict(row)
        bounds = dict(item.get("bounds") or {})
        item["row_index"] = idx
        item["username_bounds"] = dict(bounds)
        tap_b = _followers_row_tap_bounds(bounds)
        item["tap_bounds"] = tap_b if tap_b else dict(bounds)
        if not item.get("extraction_source"):
            item["extraction_source"] = (
                extraction_methods[-1] if extraction_methods else "unknown"
            )
        item["screen_index"] = int(screen_index)
        item["hierarchy_source"] = hierarchy_source
        enriched.append(item)

    usernames = [str(r.get("username") or "").strip() for r in enriched if r.get("username")]
    meta = {
        "visible_rows_count": len(enriched),
        "usernames_count": len(usernames),
        "sample_usernames": usernames[:12],
        "extraction_methods": extraction_methods,
        "hierarchy_source": hierarchy_source,
        "hierarchy_xml_len": len(hier or ""),
        "screen_index": int(screen_index),
    }
    return enriched, meta


def harvest_visible_followers_usernames(
    d: u2.Device,
    *,
    source_profile_username: str,
    runtime_seen: set[str] | None = None,
    force_fresh_hierarchy: bool = False,
    screen_index: int = 0,
) -> tuple[list[str], dict[str, Any]]:
    """Visible follower handles (delegates to harvest_visible_followers_rows)."""
    rows, meta = harvest_visible_followers_rows(
        d,
        source_profile_username=source_profile_username,
        runtime_seen=runtime_seen,
        force_fresh_hierarchy=force_fresh_hierarchy,
        screen_index=screen_index,
    )
    usernames = [str(r.get("username") or "").strip() for r in rows if r.get("username")]
    return usernames, meta


def _collect_own_unified_followers_rows_from_hierarchy(
    d: u2.Device,
    *,
    source_profile_username: str,
    runtime_seen: set[str],
    hierarchy_source: str,
) -> list[dict[str, Any]]:
    """Harvest follow_list_username rows from cached or fresh hierarchy XML (Welcome-aligned)."""
    hier = _followers_resolve_detect_hierarchy_xml(d, None, live_incomplete=False)
    if hierarchy_source == "fresh_dump":
        hier = followers_refresh_detect_hierarchy_cache(d, screen_index=0)
    if not hier or "follow_list_username" not in hier:
        return []
    return _extract_own_unified_followers_usernames_from_hierarchy_xml(
        hier,
        source_profile_username=source_profile_username,
        runtime_seen=runtime_seen,
    )


def _iter_followers_candidates_collect(
    d: u2.Device,
    *,
    source_profile_username: str,
    runtime_seen: set[str],
) -> list[dict[str, Any]]:
    """Parse visible @handles from current UiAutomator tree (no scroll/tap)."""
    try:
        h = int(d.window_size()[1])
    except Exception:
        h = 1920
    y_min = int(h * 0.08)
    source_key = _normalize_handle(source_profile_username or "")
    by_user: dict[str, dict[str, Any]] = {}

    try:
        for el in d(className="android.widget.TextView").all():
            try:
                inf = el.info
                raw_t = (inf.get("text") or "").strip().lstrip("@")
                if not _FOLLOWERS_HANDLE_RE.match(raw_t):
                    continue
                key = _normalize_handle(raw_t)
                if not key or key == source_key:
                    continue
                b = inf.get("bounds") or {}
                cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
                if cy < y_min or cy > int(h * 0.96):
                    continue
                c = _followers_bounds_center(b)
                if c is None:
                    continue
                rid = str(inf.get("resourceName") or "") or None
                prev = by_user.get(key)
                if prev is None or cy < prev["row_center"][1]:
                    by_user[key] = {
                        "username": raw_t,
                        "bounds": dict(b),
                        "row_center": [c[0], c[1]],
                        "already_seen_runtime": key in runtime_seen,
                        "resource_id": rid,
                    }
            except Exception:
                continue
    except Exception:
        pass

    rows = sorted(by_user.values(), key=lambda r: (r["row_center"][1], r["username"]))
    for r in rows:
        log(
            "info",
            "followers_candidate_seen",
            username=r["username"],
            source_profile_username=source_profile_username,
            already_seen_runtime=bool(r["already_seen_runtime"]),
            resource_id=r.get("resource_id"),
        )
    return rows


def iter_followers_candidates(
    d: u2.Device,
    *,
    source_profile_username: str,
    runtime_seen: set[str],
    source_account_context: str | None = None,
) -> list[dict[str, Any]]:
    """
    Visible follower handles on the current followers list surface.
    After visual_fallback open, first empty parse triggers wait + triple hierarchy dump + re-detect (no scroll).
    """
    global _FOLLOWERS_VISUAL_XML_RECOVERY_ATTEMPTED
    global _FOLLOWERS_VISUAL_XML_STALE_EXHAUSTED
    global _FOLLOWERS_LAST_ITER_CANDIDATE_COUNT
    global _FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS
    global _FOLLOWERS_ENGINE_STOP_REASON

    try:
        _iter_pkg_meta = _followers_current_pkg_activity(d)
        _iter_current_pkg = _iter_pkg_meta.get("current_package")
    except Exception:
        _iter_current_pkg = None
    _iter_odm = str(_FOLLOWERS_LAST_OPEN_DETECTION_METHOD or "").strip() or None
    log(
        "info",
        "followers_iter_candidates_started",
        source_profile_username=source_profile_username,
        source_account_context=str(source_account_context or ""),
        current_package=str(_iter_current_pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or ""),
        open_detection_method=_iter_odm,
    )

    rows: list[dict[str, Any]] = []
    if _harvest_own_unified_xml_first_eligible(d):
        rows = _collect_own_unified_followers_rows_from_hierarchy(
            d,
            source_profile_username=source_profile_username,
            runtime_seen=runtime_seen,
            hierarchy_source="cached",
        )
        if rows:
            log(
                "info",
                "followers_iter_own_unified_xml_harvest",
                source_profile_username=source_profile_username,
                candidate_rows_parsed=len(rows),
                hierarchy_source="cached",
                open_detection_method=_iter_odm,
            )
        else:
            rows = _collect_own_unified_followers_rows_from_hierarchy(
                d,
                source_profile_username=source_profile_username,
                runtime_seen=runtime_seen,
                hierarchy_source="fresh_dump",
            )
            if rows:
                log(
                    "info",
                    "followers_iter_own_unified_xml_harvest",
                    source_profile_username=source_profile_username,
                    candidate_rows_parsed=len(rows),
                    hierarchy_source="fresh_dump",
                    open_detection_method=_iter_odm,
                )
            else:
                log(
                    "info",
                    "followers_iter_own_unified_xml_empty",
                    source_profile_username=source_profile_username,
                    open_detection_method=_iter_odm,
                )

    if not rows:
        rows = _iter_followers_candidates_collect(
            d, source_profile_username=source_profile_username, runtime_seen=runtime_seen
        )

    if (
        not rows
        and _FOLLOWERS_LAST_OPEN_DETECTION_METHOD == "visual_fallback"
        and not _FOLLOWERS_VISUAL_XML_RECOVERY_ATTEMPTED
    ):
        _FOLLOWERS_VISUAL_XML_RECOVERY_ATTEMPTED = True
        log(
            "info",
            "followers_candidates_retry_after_visual_match",
            source_profile_username=source_profile_username,
            open_detection_method="visual_fallback",
            wait_before_force_refresh_s=2.5,
        )
        time.sleep(2.5)
        followers_force_hierarchy_refresh(d, source_profile_username=source_profile_username)
        det_after = detect_followers_list_screen(
            d, source_profile_username=source_profile_username
        )
        rows = _iter_followers_candidates_collect(
            d, source_profile_username=source_profile_username, runtime_seen=runtime_seen
        )
        log(
            "info",
            "followers_candidates_retry_result",
            source_profile_username=source_profile_username,
            open_detection_method="visual_fallback",
            candidate_rows_parsed=len(rows),
            candidate_username_count=det_after.get("candidate_username_count"),
            visible_usernames_sample=det_after.get("visible_usernames_sample"),
            recycler_present=det_after.get("recycler_present"),
            scrollable_present=det_after.get("scrollable_present"),
            current_screen_guess=det_after.get("current_screen_guess"),
        )
        if not rows:
            _FOLLOWERS_VISUAL_XML_STALE_EXHAUSTED = True
            _FOLLOWERS_ENGINE_STOP_REASON = "followers_xml_still_stale_after_force_refresh"
            log(
                "error",
                "followers_xml_still_stale_after_force_refresh",
                source_profile_username=source_profile_username,
                open_detection_method="visual_fallback",
                candidate_username_count=det_after.get("candidate_username_count"),
                visible_usernames_sample=det_after.get("visible_usernames_sample"),
                recycler_present=det_after.get("recycler_present"),
                scrollable_present=det_after.get("scrollable_present"),
                current_screen_guess=det_after.get("current_screen_guess"),
                candidate_rows_parsed=0,
            )
            _followers_run_visual_open_xml_empty_diagnostic(
                d,
                source_profile_username=source_profile_username,
                det_after=det_after,
            )

    _FOLLOWERS_LAST_ITER_CANDIDATE_COUNT = len(rows)
    if rows:
        _FOLLOWERS_VISUAL_HAD_NONEMPTY_CANDIDATE_ROWS = True
    return rows


def _followers_open_success_payload(
    tap_diag: dict[str, Any],
    *,
    after_tap_det: dict[str, Any],
    last_det: dict[str, Any],
    open_method: str,
    pkg_meta: dict[str, Any],
    source_profile_username: str,
    profile_verified: bool,
) -> dict[str, Any]:
    _odm = str(last_det.get("open_detection_method") or "xml")
    _lvf = last_det.get("visual_fallback_detail") or {}
    if isinstance(_lvf, dict) and bool(_lvf.get("visual_match")):
        _odm = "visual_fallback"
    elif _odm == "xml":
        _atvf = (after_tap_det or {}).get("visual_fallback_detail") or {}
        if isinstance(_atvf, dict) and bool(_atvf.get("visual_match")):
            _odm = "visual_fallback"
    return {
        "source_profile_username": source_profile_username,
        "profile_verified": bool(profile_verified),
        "tap_x": tap_diag.get("tap_x"),
        "tap_y": tap_diag.get("tap_y"),
        "tap_method": tap_diag.get("tap_method"),
        "profile_stats_visible": tap_diag.get("profile_stats_visible"),
        "followers_stat_text_dump": tap_diag.get("followers_stat_text_dump"),
        "followers_stat_coordinate_retry": tap_diag.get("followers_stat_coordinate_retry"),
        "after_tap_screen_snapshot": after_tap_det,
        "last_poll_snapshot": last_det,
        "open_method": open_method,
        "current_package": pkg_meta.get("current_package"),
        "signals": last_det.get("signals"),
        "sample": last_det.get("visible_usernames_sample"),
        "open_detection_method": _odm,
    }


_FOLLOWERS_ENTRY_XML_FAMILIAR_EXACT_METHOD = (
    "hierarchy_xml_profile_header_followers_stacked_familiar_exact"
)
_FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_METHOD = "hierarchy_xml_content_desc_followers_metric"
_FOLLOWERS_ENTRY_XML_FAMILIAR_RID_SUFFIX = "profile_header_followers_stacked_familiar"
_FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_RE = re.compile(
    r"^\d+\s*followers$",
    re.IGNORECASE,
)
_FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_COMPACT_RE = re.compile(
    r"^\d+followers$",
    re.IGNORECASE,
)


def _resolve_profile_action_bar_title_for_entry(
    d: u2.Device,
    *,
    hierarchy_xml: str | None = None,
) -> str:
    """Own profile often uses action_bar_large_title_auto_size instead of action_bar_title."""
    for rid_pat, log_large in (
        (r".*:id/action_bar_title.*", False),
        (r".*:id/action_bar_large_title_auto_size$", True),
    ):
        try:
            ab = d(resourceIdMatches=rid_pat)
            if ab.exists(timeout=0.12):
                title = str(ab.get_text() or "").strip()
                if title:
                    if log_large:
                        log(
                            "info",
                            "followers_entry_profile_action_bar_large_title_resolved",
                            title=title[:120],
                            source="u2",
                        )
                    return title
        except Exception:
            continue
    hier = (hierarchy_xml or "").strip()
    if not hier:
        return ""
    try:
        try:
            root = ET.fromstring(hier)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{hier}</wrap>")
    except Exception:
        return ""
    for suffix in ("action_bar_large_title_auto_size", "action_bar_title"):
        for el in root.iter():
            rid = str(el.get("resource-id") or "")
            if suffix not in rid:
                continue
            title = str(el.get("text") or el.get("content-desc") or "").strip()
            if title:
                if suffix == "action_bar_large_title_auto_size":
                    log(
                        "info",
                        "followers_entry_profile_action_bar_large_title_resolved",
                        title=title[:120],
                        source="hierarchy_xml",
                    )
                return title
    return ""


def _followers_entry_v2_xml_hierarchy_parent_map(
    root: ET.Element,
) -> dict[ET.Element, ET.Element | None]:
    parent_map: dict[ET.Element, ET.Element | None] = {root: None}

    def _walk(el: ET.Element) -> None:
        for ch in list(el):
            parent_map[ch] = el
            _walk(ch)

    _walk(root)
    return parent_map


def _followers_entry_v2_action_bar_title_from_hierarchy_xml(hierarchy_xml: str) -> str:
    hier = (hierarchy_xml or "").strip()
    if not hier:
        return ""
    try:
        try:
            root = ET.fromstring(hier)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{hier}</wrap>")
    except Exception:
        return ""
    for suffix in ("action_bar_large_title_auto_size", "action_bar_title"):
        for el in root.iter():
            rid = str(el.get("resource-id") or "")
            if suffix not in rid:
                continue
            title = str(el.get("text") or el.get("content-desc") or "").strip()
            if title:
                return title
    return ""


def _followers_entry_v2_rid_is_familiar_followers_column(rid: str) -> bool:
    rl = str(rid or "").lower()
    return _FOLLOWERS_ENTRY_XML_FAMILIAR_RID_SUFFIX in rl


def _followers_entry_v2_xml_content_desc_is_followers_metric(cd: str) -> bool:
    raw = str(cd or "").strip()
    if not raw:
        return False
    if _FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_RE.match(raw):
        return True
    if _FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_COMPACT_RE.match(raw):
        return True
    norm = _follow_norm(raw)
    if _followers_reject_following_column_label(raw):
        return False
    if _followers_reject_posts_label(raw):
        return False
    return bool(
        _FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_RE.match(norm)
        or _FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_COMPACT_RE.match(norm.replace(" ", ""))
    )


def _followers_entry_v2_entry_title_gate_ok(
    *,
    source_profile_username: str,
    profile_action_bar_title: str,
    profile_verified: bool,
) -> bool:
    if not bool(profile_verified):
        return False
    abn = _normalize_handle(str(profile_action_bar_title or ""))
    srcn = _normalize_handle(str(source_profile_username or ""))
    return bool(abn and srcn and abn == srcn)


def _followers_entry_v2_xml_pick_clickable_bounds(
    el: ET.Element,
    parent_map: dict[ET.Element, ET.Element | None],
) -> dict[str, int] | None:
    if str(el.get("clickable") or "").lower() == "true":
        bd = _dm_parse_bounds_attr_xml(el.get("bounds"))
        if bd:
            return bd
    anc = _dm_nearest_clickable_xml_ancestor(el, parent_map)
    if anc is not None:
        bd = _dm_parse_bounds_attr_xml(anc.get("bounds"))
        if bd:
            return bd
    return _dm_parse_bounds_attr_xml(el.get("bounds"))


def _followers_entry_v2_xml_tap_in_familiar_followers_column(w: int, cx: int) -> bool:
    """
    Full-width familiar metrics (own profile): avatar left, three columns on the right.
    Followers center is ~47–72% screen width — stricter legacy 45% gate rejects valid taps.
    """
    if w <= 0:
        return True
    nx = float(cx) / float(w)
    if nx < 0.38:
        return False
    if nx > 0.76:
        return False
    return True


def _followers_entry_v2_xml_bounds_in_metrics_band(
    bd: dict[str, int],
    *,
    w: int,
    h: int,
) -> bool:
    try:
        cy = (int(bd["top"]) + int(bd["bottom"])) // 2
        cx = (int(bd["left"]) + int(bd["right"])) // 2
    except Exception:
        return False
    y_lo, y_hi = int(h * 0.10), int(h * 0.46)
    if cy < y_lo or cy > y_hi:
        return False
    if cx < int(w * 0.02) or cx > int(w * 0.98):
        return False
    return _followers_entry_v2_xml_tap_in_familiar_followers_column(int(w), cx)


def _followers_entry_v2_xml_bounds_to_raw_candidate(
    bd: dict[str, int],
    *,
    method: str,
    tap_source: str,
    detected: str,
    score: int,
) -> dict[str, Any]:
    left = int(bd["left"])
    top = int(bd["top"])
    right = int(bd["right"])
    bottom = int(bd["bottom"])
    cx = (left + right) // 2
    cy = (top + bottom) // 2
    return {
        "score": int(score),
        "cx": cx,
        "cy": cy,
        "tbounds": dict(bd),
        "method": method,
        "tap_source": tap_source,
        "detected": detected[:220],
        "stat_type": "followers",
        "semantic_followers_metric": True,
        "detail_signals": [
            method,
            tap_source,
            "profile_verified:true",
            "hierarchy_xml_familiar",
        ],
    }


def _followers_entry_v2_xml_familiar_followers_candidates(
    hierarchy_xml: str,
    *,
    w: int,
    h: int,
    source_profile_username: str,
    profile_verified: bool,
    profile_action_bar_title: str,
) -> list[dict[str, Any]]:
    """
    XML-first followers stat candidates from an already-captured entry hierarchy dump.
    Targets own-profile familiar metrics (profile_header_followers_stacked_familiar).
    """
    if not _followers_entry_v2_entry_title_gate_ok(
        source_profile_username=source_profile_username,
        profile_action_bar_title=profile_action_bar_title,
        profile_verified=profile_verified,
    ):
        return []
    hier = (hierarchy_xml or "").strip()
    if not hier:
        return []
    try:
        try:
            root = ET.fromstring(hier)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{hier}</wrap>")
    except Exception:
        return []
    parent_map = _followers_entry_v2_xml_hierarchy_parent_map(root)
    out: list[dict[str, Any]] = []
    seen_bounds: set[tuple[int, int, int, int]] = set()

    def _append_candidate(
        bd: dict[str, int],
        *,
        method: str,
        tap_source: str,
        detected: str,
        score: int,
    ) -> None:
        if not _followers_entry_v2_xml_bounds_in_metrics_band(bd, w=w, h=h):
            return
        key = (
            int(bd["left"]),
            int(bd["top"]),
            int(bd["right"]),
            int(bd["bottom"]),
        )
        if key in seen_bounds:
            return
        seen_bounds.add(key)
        out.append(
            _followers_entry_v2_xml_bounds_to_raw_candidate(
                bd,
                method=method,
                tap_source=tap_source,
                detected=detected,
                score=score,
            )
        )

    for el in root.iter():
        rid = str(el.get("resource-id") or "")
        if not _followers_entry_v2_rid_is_familiar_followers_column(rid):
            continue
        bd = _followers_entry_v2_xml_pick_clickable_bounds(el, parent_map)
        if not bd:
            continue
        _append_candidate(
            bd,
            method=_FOLLOWERS_ENTRY_XML_FAMILIAR_EXACT_METHOD,
            tap_source="hierarchy_xml_familiar_exact",
            detected=_FOLLOWERS_ENTRY_XML_FAMILIAR_RID_SUFFIX,
            score=12700,
        )
        break

    if out:
        return out

    for el in root.iter():
        cd = str(el.get("content-desc") or "").strip()
        if not _followers_entry_v2_xml_content_desc_is_followers_metric(cd):
            continue
        rid = str(el.get("resource-id") or "").lower()
        if "profile_header_following" in rid and "follower" not in rid:
            continue
        if "profile_header_post" in rid or "profile_header_posts" in rid:
            continue
        bd = _followers_entry_v2_xml_pick_clickable_bounds(el, parent_map)
        if not bd:
            continue
        _append_candidate(
            bd,
            method=_FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_METHOD,
            tap_source="hierarchy_xml_content_desc_followers",
            detected=cd[:220],
            score=11200,
        )
        break

    return out


def _followers_entry_fast_path_exact_xml_candidate(
    hierarchy_xml: str,
    *,
    w: int,
    h: int,
    source_profile_username: str,
    profile_verified: bool,
) -> tuple[dict[str, Any] | None, str]:
    """Return one exact XML followers metric candidate, or a fallback reason."""
    if not bool(profile_verified):
        return None, "profile_not_verified"
    hier = (hierarchy_xml or "").strip()
    if not hier:
        return None, "hierarchy_empty"
    profile_title = _followers_entry_v2_action_bar_title_from_hierarchy_xml(hier)
    if not _followers_entry_v2_entry_title_gate_ok(
        source_profile_username=source_profile_username,
        profile_action_bar_title=profile_title,
        profile_verified=True,
    ):
        return None, "source_profile_title_mismatch"
    try:
        try:
            root = ET.fromstring(hier)
        except ET.ParseError:
            root = ET.fromstring(f"<wrap>{hier}</wrap>")
    except Exception:
        return None, "hierarchy_parse_failed"
    parent_map = _followers_entry_v2_xml_hierarchy_parent_map(root)
    raw_candidates: list[dict[str, Any]] = []
    for el in root.iter():
        rid = str(el.get("resource-id") or "")
        if not _followers_entry_v2_rid_is_familiar_followers_column(rid):
            continue
        bd = _followers_entry_v2_xml_pick_clickable_bounds(el, parent_map)
        if not bd:
            continue
        if not _followers_entry_v2_xml_bounds_in_metrics_band(bd, w=int(w), h=int(h)):
            continue
        raw_candidates.append(
            _followers_entry_v2_xml_bounds_to_raw_candidate(
                bd,
                method=_FOLLOWERS_ENTRY_XML_FAMILIAR_EXACT_METHOD,
                tap_source="followers_entry_fast_path_xml_exact",
                detected=_FOLLOWERS_ENTRY_XML_FAMILIAR_RID_SUFFIX,
                score=12800,
            )
        )
    if not raw_candidates:
        return None, "exact_followers_metric_absent"
    unique: dict[tuple[int, int, int, int], dict[str, Any]] = {}
    for raw in raw_candidates:
        bd = dict(raw.get("tbounds") or {})
        try:
            key = (
                int(bd["left"]),
                int(bd["top"]),
                int(bd["right"]),
                int(bd["bottom"]),
            )
        except Exception:
            continue
        unique[key] = raw
    if len(unique) != 1:
        return None, "exact_followers_metric_ambiguous"
    candidate = _followers_entry_v2_public_candidate(next(iter(unique.values())))
    ok_metric, why_metric = _followers_entry_v2_entry_candidate_followers_metric_ok(
        candidate,
        w=int(w),
    )
    if not ok_metric:
        return None, why_metric or "metric_rejected"
    bd = dict(candidate.get("bounds") or {})
    try:
        tx = int(candidate.get("tap_x") or 0)
        ty = int(candidate.get("tap_y") or 0)
        left = int(bd.get("left", 0))
        top = int(bd.get("top", 0))
        right = int(bd.get("right", 0))
        bottom = int(bd.get("bottom", 0))
    except Exception:
        return None, "bounds_invalid"
    if right <= left or bottom <= top or tx <= 0 or ty <= 0:
        return None, "bounds_invalid"
    if tx < 0 or ty < 0 or tx > int(w) or ty > int(h):
        return None, "tap_outside_screen"
    return candidate, ""


_FOLLOWERS_ENTRY_V2_SOURCE_BY_METHOD: dict[str, str] = {
    "hierarchy_xml_profile_header_followers_stacked_familiar_exact": "xml_text",
    "hierarchy_xml_content_desc_followers_metric": "xml_text",
    "resource_id_profile_header_followers_stacked_familiar_exact": "xml_text",
    "resource_id_followers_stacked_familiar": "stats_band_structure",
    "text_label_with_count_block": "hybrid",
    "text_followers_label": "xml_text",
    "harvest_fused_followers_tap": "hybrid",
    "harvest_followers_label_only": "hybrid",
    "harvest_content_desc_followers_label": "vision_text",
    "geometry_followers_column_center": "stats_band_structure",
    "harvest_raw_clickable_followers_metric": "hybrid",
}


def _followers_entry_v2_confidence(score: int, method: str) -> float:
    if method == _FOLLOWERS_ENTRY_XML_FAMILIAR_EXACT_METHOD:
        return 0.97
    if method == _FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_METHOD:
        return 0.88
    if method == "resource_id_profile_header_followers_stacked_familiar_exact":
        return 0.97
    if method == "resource_id_followers_stacked_familiar":
        return 0.93
    if method == "text_label_with_count_block":
        return 0.86
    if method == "text_followers_label":
        return 0.79
    if method == "harvest_fused_followers_tap":
        return 0.84
    if method == "harvest_followers_label_only":
        return 0.72
    if method == "harvest_content_desc_followers_label":
        return 0.74
    if method == "geometry_followers_column_center":
        return 0.62
    if method == "harvest_raw_clickable_followers_metric":
        return 0.78
    if str(method).startswith("resource_id:"):
        return 0.71
    return min(0.91, max(0.38, float(score) / 12500.0))


def _followers_entry_v2_public_candidate(raw: dict[str, Any]) -> dict[str, Any]:
    method = str(raw.get("method") or "")
    src = _FOLLOWERS_ENTRY_V2_SOURCE_BY_METHOD.get(method, "hybrid")
    det_txt = str(raw.get("detected") or "").lower()
    if method == "text_followers_label" and (
        "abonn" in det_txt or "abonnés" in det_txt or "abonnes" in det_txt
    ):
        src = "vision_text"
    if method == "harvest_content_desc_followers_label":
        src = "vision_text"
    if method == "harvest_raw_clickable_followers_metric":
        src = "hybrid"
    tb = dict(raw.get("tbounds") or {})
    sigs: list[str] = [
        method,
        str(raw.get("detected") or ""),
        f"score:{int(raw.get('score') or 0)}",
        str(raw.get("tap_source") or ""),
    ]
    for xs in raw.get("detail_signals") or []:
        xs = str(xs).strip()
        if xs and xs not in sigs:
            sigs.append(xs)
    return {
        "source": src,
        "bounds": tb,
        "confidence": round(_followers_entry_v2_confidence(int(raw.get("score") or 0), method), 4),
        "tap_x": int(raw.get("cx") or 0),
        "tap_y": int(raw.get("cy") or 0),
        "signals": sigs,
        "method": method,
        **(
            {"stat_type": str(raw.get("stat_type")).strip()}
            if str(raw.get("stat_type") or "").strip()
            else {}
        ),
        **(
            {"semantic_followers_metric": True}
            if bool(raw.get("semantic_followers_metric"))
            else {}
        ),
        **(
            {"tap_source": str(raw.get("tap_source") or "").strip()[:80]}
            if str(raw.get("tap_source") or "").strip()
            else {}
        ),
    }


def _followers_collect_stat_entry_candidates_for_v2(
    d: u2.Device,
    *,
    w: int,
    h: int,
    source_profile_username: str = "",
    hierarchy_xml: str | None = None,
    profile_verified: bool = False,
    profile_screen_class: str = "",
    profile_action_bar_title: str = "",
) -> list[dict[str, Any]]:
    """Collect followers-stat tap candidates without middle-column or coordinate fallback."""
    y_lo, y_hi = int(h * 0.10), int(h * 0.46)
    x_max = int(w * 0.96)
    ideal_cx = int(w * 0.60)
    ly_lo, ly_hi = _followers_stat_strip_y_for_text_labels(h)
    raw: list[dict[str, Any]] = []

    profile_action_bar_title_resolved = str(profile_action_bar_title or "").strip()
    if not profile_action_bar_title_resolved:
        profile_action_bar_title_resolved = _resolve_profile_action_bar_title_for_entry(
            d,
            hierarchy_xml=hierarchy_xml,
        )

    hier_xml = (hierarchy_xml or "").strip()
    if hier_xml:
        try:
            for xml_cand in _followers_entry_v2_xml_familiar_followers_candidates(
                hier_xml,
                w=int(w),
                h=int(h),
                source_profile_username=str(source_profile_username or ""),
                profile_verified=bool(profile_verified),
                profile_action_bar_title=profile_action_bar_title_resolved,
            ):
                raw.append(xml_cand)
        except Exception:
            pass

    try:
        hv = followers_stats_surface_harvester_v2(
            d,
            w,
            h,
            source_profile_username=str(source_profile_username or ""),
            hierarchy_xml=hierarchy_xml,
            profile_verified=bool(profile_verified),
            profile_screen_class=str(profile_screen_class or ""),
            profile_action_bar_title=profile_action_bar_title_resolved,
        )
        for rmt in list(hv.get("raw_metric_taps") or [])[:6]:
            try:
                rmd = dict(rmt) if isinstance(rmt, dict) else {}
                bchk = dict(rmd.get("tbounds") or {})
                tcx_chk = int(rmd.get("cx") or 0)
                if not bool(rmd.get("semantic_followers_metric")) and not _followers_entry_v2_tap_center_in_followers_column(
                    int(w), tcx_chk, bchk
                ):
                    continue
                rmd["stat_type"] = "followers"
                raw.append(rmd)
            except Exception:
                continue
        for fus in list(hv.get("fused_followers") or [])[:6]:
            try:
                b = dict(fus.get("bounds") or {})
                tcx = int(fus.get("center_x") or 0)
                tcy = int(fus.get("center_y") or 0)
                if not b or tcx <= 0 or tcy <= 0:
                    continue
                if tcy < y_lo or tcy > y_hi or int(b.get("left", 0)) > x_max:
                    continue
                raw.append(
                    {
                        "score": 9000 - abs(tcx - ideal_cx) // 2,
                        "cx": tcx,
                        "cy": tcy,
                        "tbounds": b,
                        "method": "harvest_fused_followers_tap",
                        "tap_source": "harvester_v2_fusion",
                        "detected": (
                            f"{fus.get('text') or ''}|{fus.get('content_desc') or ''}"
                        )[:220],
                        "stat_type": "followers",
                    }
                )
            except Exception:
                continue
        fused_centers: list[tuple[int, int]] = []
        try:
            fused_centers = [
                (int(f.get("center_x") or 0), int(f.get("center_y") or 0))
                for f in (hv.get("fused_followers") or [])
            ]
        except Exception:
            fused_centers = []

        def _near_fused_centroid(tx: int, ty: int) -> bool:
            for fx, fy in fused_centers:
                if fx <= 0 or fy <= 0:
                    continue
                if abs(fx - tx) < int(w * 0.06) and abs(fy - ty) < int(h * 0.04):
                    return True
            return False

        for lab in list(hv.get("atoms") or [])[:24]:
            if str(lab.get("stat_type") or "") != "followers":
                continue
            b = dict(lab.get("bounds") or {})
            tcx = int(lab.get("center_x") or 0)
            tcy = int(lab.get("center_y") or 0)
            if not b or tcx <= 0 or tcy <= 0:
                continue
            if tcy < y_lo or tcy > y_hi or int(b.get("left", 0)) > x_max:
                continue
            has_txt = bool(str(lab.get("text") or "").strip())
            has_cd = bool(str(lab.get("content_desc") or "").strip())
            if not has_txt and has_cd:
                raw.append(
                    {
                        "score": 6400 - abs(tcx - ideal_cx) // 2,
                        "cx": tcx,
                        "cy": tcy,
                        "tbounds": b,
                        "method": "harvest_content_desc_followers_label",
                        "tap_source": "harvester_v2_content_desc",
                        "detected": str(lab.get("content_desc") or "")[:180],
                        "stat_type": "followers",
                    }
                )
            elif has_txt and not _near_fused_centroid(tcx, tcy):
                raw.append(
                    {
                        "score": 6300 - abs(tcx - ideal_cx) // 2,
                        "cx": tcx,
                        "cy": tcy,
                        "tbounds": b,
                        "method": "harvest_followers_label_only",
                        "tap_source": "harvester_v2_label_only",
                        "detected": str(lab.get("text") or "")[:180],
                        "stat_type": "followers",
                    }
                )
    except Exception:
        pass

    try:
        sel_exact = d(resourceId=PROFILE_HEADER_FOLLOWERS_STACKED_FAMILIAR_RID)
        if sel_exact.exists(timeout=0.35):
            for el in sel_exact.all():
                inf = _follow_safe_info(el)
                b = dict(inf.get("bounds") or {})
                try:
                    left = int(b.get("left", 0))
                    right = int(b.get("right", 0))
                    top = int(b.get("top", 0))
                    bottom = int(b.get("bottom", 0))
                except Exception:
                    continue
                if right <= left or bottom <= top:
                    continue
                cy_chk = _followers_bounds_center(b)
                if cy_chk is None:
                    continue
                _, cyy = cy_chk
                if cyy < y_lo or cyy > y_hi or left > x_max:
                    continue
                cx = (left + right) // 2
                cy = (top + bottom) // 2
                rw = right - left
                raw.append(
                    {
                        "score": 12500 + min(rw, 500),
                        "cx": cx,
                        "cy": cy,
                        "tbounds": b,
                        "method": "resource_id_profile_header_followers_stacked_familiar_exact",
                        "tap_source": "exact_rid_coordinate_tap",
                        "detected": "profile_header_followers_stacked_familiar",
                        "stat_type": "followers",
                    }
                )
                break
    except Exception:
        pass

    band = _collect_profile_stats_band_texts(d, w, h)
    numeric_row = [
        r
        for r in band
        if _STAT_NUMERIC_RE.match((r.get("text") or "").strip())
        and not _followers_reject_posts_label(r.get("text") or "")
        and not _followers_reject_following_column_label(r.get("text") or "")
    ]
    numeric_row.sort(key=lambda r: r["cx"])

    try:
        stacked = d(resourceIdMatches=r".*:id/profile_header_followers_stacked_familiar$")
        if stacked.exists(timeout=0.26):
            for el in stacked.all():
                inf = _follow_safe_info(el)
                b = inf.get("bounds") or {}
                c = _followers_bounds_center(b)
                if c is None:
                    continue
                _cx, cyy = c
                if cyy < y_lo or cyy > y_hi or int(b.get("left", 0)) > x_max:
                    continue
                rw = int(b.get("right", 0)) - int(b.get("left", 0))
                raw.append(
                    {
                        "score": 12000 + min(max(rw, 1), 500),
                        "cx": _cx,
                        "cy": cyy,
                        "tbounds": dict(b),
                        "method": "resource_id_followers_stacked_familiar",
                        "tap_source": "parent_block",
                        "detected": "profile_header_followers_stacked_familiar",
                        "stat_type": "followers",
                    }
                )
                break
    except Exception:
        pass

    try:
        for el in d(className="android.widget.TextView").all():
            inf = _follow_safe_info(el)
            raw_txt = (inf.get("text") or "").strip()
            cd_txt = str(inf.get("contentDescription") or "").strip()
            label_txt = raw_txt or cd_txt
            if not label_txt or not _followers_label_match(label_txt):
                continue
            b = inf.get("bounds") or {}
            cy = _followers_bounds_center(b)
            if cy is None:
                continue
            _cx, cyy = cy
            if cyy < y_lo or cyy > y_hi or int(b.get("left", 0)) > x_max:
                continue
            rw = int(b.get("right", 0)) - int(b.get("left", 0))
            if rw < 8:
                continue
            low = label_txt.lower()
            if "following" in low and "follower" not in low:
                continue
            rid_l = str(inf.get("resourceName") or "")
            if (
                "profile_header_familiar_followers" not in rid_l
                and "followers_stacked" not in rid_l
            ):
                if not (ly_lo <= cyy <= ly_hi):
                    continue

            pair: dict[str, Any] | None = None
            for r in band:
                rt = (r.get("raw_text") or r.get("text") or "").strip()
                if not _STAT_NUMERIC_RE.match(rt):
                    continue
                if _followers_reject_posts_label(rt) or _followers_reject_following_column_label(rt):
                    continue
                rcx, rcyy = int(r["cx"]), int(r["cyy"])
                if abs(rcx - _cx) > int(w * 0.09):
                    continue
                if rcyy >= cyy - 4:
                    continue
                if (cyy - rcyy) > int(h * 0.14):
                    continue
                pair = r
                break

            if pair is not None:
                mb = _followers_merge_bounds(b, pair.get("bounds") or {})
                mc = _followers_bounds_center(mb)
                if mc is None:
                    continue
                tcx, tcy = mc
                bw = int(mb.get("right", 0)) - int(mb.get("left", 0))
                score = 8500 - abs(tcx - ideal_cx) + min(bw, 400)
                raw.append(
                    {
                        "score": score,
                        "cx": tcx,
                        "cy": tcy,
                        "tbounds": dict(mb),
                        "method": "text_label_with_count_block",
                        "tap_source": "parent_block",
                        "detected": f"{(pair.get('raw_text') or pair.get('text') or '').strip()}|{label_txt}",
                        "stat_type": "followers",
                    }
                )
            else:
                score = 6200 - abs(_cx - ideal_cx) + min(rw, 320)
                raw.append(
                    {
                        "score": score,
                        "cx": _cx,
                        "cy": cyy,
                        "tbounds": dict(b),
                        "method": "text_followers_label",
                        "tap_source": "text_element",
                        "detected": label_txt,
                        "stat_type": "followers",
                    }
                )
    except Exception:
        pass

    rid_patterns = (
        r".*:id/.*follower.*count.*",
        r".*:id/.*followers.*count.*",
        r".*:id/.*stacked.*follower.*",
    )
    for pat in rid_patterns:
        try:
            for el in d(resourceIdMatches=pat).all():
                inf = _follow_safe_info(el)
                b = inf.get("bounds") or {}
                cy = _followers_bounds_center(b)
                if cy is None:
                    continue
                _cx, cyy = cy
                if cyy < y_lo or cyy > y_hi or int(b.get("left", 0)) > x_max:
                    continue
                rw = int(b.get("right", 0)) - int(b.get("left", 0))
                score = 5000 + rw * 100 - abs(_cx - ideal_cx) // 2
                try:
                    det_txt = (el.get_text() or "").strip()
                except Exception:
                    det_txt = ""
                raw.append(
                    {
                        "score": score,
                        "cx": _cx,
                        "cy": cyy,
                        "tbounds": dict(b),
                        "method": f"resource_id:{pat}",
                        "tap_source": "text_element",
                        "detected": det_txt or pat,
                        "stat_type": "followers",
                    }
                )
        except Exception:
            continue

    try:
        g_raw = _followers_entry_v2_geometry_followers_raw(int(w), int(h))
        g_pub = _followers_entry_v2_public_candidate(g_raw)
        g_cal = dict(g_pub)
        g_cal["confidence"] = round(0.54, 4)
        g_cal["calibration_confidence"] = round(0.54, 4)
        log(
            "info",
            "followers_entry_geometry_candidate_created",
            source_profile_username=str(source_profile_username or ""),
            candidate=g_cal,
            profile_verified=bool(profile_verified),
            profile_screen_class=str(profile_screen_class or "")[:120],
            allow_geometry_tap=bool(
                getattr(config, "FOLLOWERS_ENTRY_V2_ALLOW_GEOMETRY_TAP", False)
            ),
        )
        allow_geom = bool(getattr(config, "FOLLOWERS_ENTRY_V2_ALLOW_GEOMETRY_TAP", False))
        text_like = [
            r
            for r in raw
            if not str(r.get("method") or "").startswith("geometry_followers")
        ]
        if (
            allow_geom
            and bool(profile_verified)
            and not text_like
            and _followers_screen_class_is_profile_like(profile_screen_class)
        ):
            abn = _normalize_handle(str(profile_action_bar_title_resolved or ""))
            srcn = _normalize_handle(str(source_profile_username or ""))
            if abn and srcn and abn == srcn:
                raw.append(g_raw)
    except Exception:
        pass

    return raw


def detect_followers_entry_candidates(
    d: u2.Device,
    source_profile_username: str,
    pkg: str,
    *,
    width: int | None = None,
    height: int | None = None,
    hierarchy_xml: str | None = None,
    profile_verified: bool = False,
    profile_screen_class: str = "",
    profile_action_bar_title: str = "",
) -> list[dict[str, Any]]:
    """
    Hybrid followers-stat entry candidates (XML + stats band). No middle-column guess,
    no coordinate_fallback_middle_stats_column.
    """
    _ = pkg
    w = width or 1080
    h = height or 1920
    try:
        w, h = d.window_size()
    except Exception:
        pass
    resolved_title = str(profile_action_bar_title or "").strip()
    if not resolved_title:
        resolved_title = _resolve_profile_action_bar_title_for_entry(
            d,
            hierarchy_xml=hierarchy_xml,
        )
    raw = _followers_collect_stat_entry_candidates_for_v2(
        d,
        w=int(w),
        h=int(h),
        source_profile_username=source_profile_username,
        hierarchy_xml=hierarchy_xml,
        profile_verified=profile_verified,
        profile_screen_class=profile_screen_class,
        profile_action_bar_title=resolved_title,
    )
    out = [_followers_entry_v2_public_candidate(r) for r in raw]
    out.sort(key=lambda c: float(c.get("confidence") or 0.0), reverse=True)
    return out



def _followers_entry_v2_visual_signal_int(signals: Any, key: str) -> int | None:
    """Parse ``left_row_bands:21`` / ``right_blue_bands:3`` style entries from visual_signals."""
    if not isinstance(signals, (list, tuple)):
        return None
    prefix = f"{key}:"
    for raw in signals:
        s = str(raw)
        if s.startswith(prefix):
            try:
                return int(s.split(":", 1)[1].strip())
            except Exception:
                return None
    return None


def _followers_entry_v2_legacy_quality_reject_preview(
    det: dict[str, Any], tap_diag: dict[str, Any]
) -> str:
    """First legacy rejection label (for logs) if vision override were disabled."""
    if not bool(det.get("is_followers_list")):
        return "not_followers_list"
    if bool(det.get("strict_list_open")) or bool(det.get("title_match")):
        return "strict_or_title_ok"
    abn = _normalize_handle(str(det.get("action_bar_title") or ""))
    srcn = _normalize_handle(str(tap_diag.get("entry_v2_source_profile_username") or ""))
    handles = int(det.get("candidate_username_count") or 0)
    if (
        srcn
        and abn == srcn
        and handles < 2
        and not bool(det.get("title_match"))
        and not bool(det.get("strict_list_open"))
    ):
        return "same_action_bar_few_handles"
    reasons = det.get("relaxed_rules_matched") or []
    rs = ",".join(str(x) for x in reasons)
    if "D_" in rs and handles < 2 and not bool(det.get("profile_tabs_absent")):
        return "relaxed_d_weak_handles"
    return "legacy_fingerprint_or_relaxed"


def _followers_entry_v2_wrong_following_tab_evidence(
    d: u2.Device,
    det: dict[str, Any],
) -> tuple[bool, str, dict[str, Any]]:
    """
    True when the opened list surface is the **Following** (subscriptions) tab/chip,
    not **Followers**. Uses action bar, header text chips, and selected-tab probes.
    """
    vs: dict[str, Any] = {
        "title_match": bool(det.get("title_match")),
        "strict_list_open": bool(det.get("strict_list_open")),
        "open_detection_method": str(det.get("open_detection_method") or ""),
    }
    vf = det.get("visual_fallback_detail")
    if isinstance(vf, dict):
        vs["visual_match"] = bool(vf.get("visual_match"))
        vs["visual_signals"] = list((vf.get("visual_signals") or [])[:24])

    ab = str(det.get("action_bar_title") or "").strip()
    ab_l = ab.lower()
    if ab_l in ("following", "suivis", "abonnements", "siguiendo"):
        return True, ab[:160], {**vs, "reason": "action_bar_tab_title", "active_tab_text": ab[:160]}
    if "following" in ab_l and "follower" not in ab_l:
        if ab_l.startswith("following") or re.search(
            r"\b\d[\d,\.\s]*\s+following\b", ab_l, flags=re.I
        ):
            return True, ab[:160], {**vs, "reason": "action_bar_following_phrase", "active_tab_text": ab[:160]}

    for raw in list(det.get("visible_header_texts") or [])[:36]:
        t = str(raw).strip()
        if not t:
            continue
        tl = t.lower()
        if _followers_label_match(t):
            continue
        if re.search(r"\b\d[\d,\.\s]*\s+following\b", tl, flags=re.I) and "follower" not in tl:
            return True, t[:160], {**vs, "reason": "header_numeric_following_chip", "active_tab_text": t[:160]}
        if re.search(r"\b\d[\d,\.\s]*\s+suivis\b", tl, flags=re.I) and "abonné" not in tl:
            return True, t[:160], {**vs, "reason": "header_numeric_suivis_chip", "active_tab_text": t[:160]}
        if _followers_reject_following_column_label(t) and not re.search(
            r"follower", tl, flags=re.I
        ):
            return True, t[:160], {**vs, "reason": "header_following_label", "active_tab_text": t[:160]}

    tab_labels_selected = (
        ("Following", "Following"),
        ("Suivis", "Suivis"),
        ("Abonnements", "Abonnements"),
        ("Siguiendo", "Siguiendo"),
    )
    for probe, label in tab_labels_selected:
        try:
            el = d(text=probe, selected=True)
            if el.exists(timeout=0.055):
                return True, label, {**vs, "reason": "selected_tab_text", "active_tab_text": label}
        except Exception:
            continue
    try:
        el2 = d(textMatches=r"(?i).*\bfollowing\b.*", selected=True)
        if el2.exists(timeout=0.05):
            try:
                tx = str(el2.info.get("text") or el2.info.get("contentDescription") or "")[:120]
            except Exception:
                tx = "following_selected"
            if "follower" not in tx.lower():
                return True, tx, {**vs, "reason": "selected_following_pattern", "active_tab_text": tx}
    except Exception:
        pass
    return False, "", vs


def _followers_entry_v2_tap_center_in_followers_column(
    w: int, tcx: int, bounds: dict[str, Any] | None
) -> bool:
    """LTR profile stats strip: followers is the center column; reject far-left (posts) / far-right (following)."""
    try:
        bd = bounds if isinstance(bounds, dict) else {}
        cx = (int(bd.get("left", 0)) + int(bd.get("right", 0))) // 2 if bd else int(tcx)
    except Exception:
        cx = int(tcx)
    if w <= 0:
        return True
    sw = max(1, int(w))
    xf = cx / float(sw)
    if xf < 0.22:
        return False
    return int(cx) * 1000 < sw * 450


def _followers_entry_v2_entry_candidate_followers_metric_ok(
    c: dict[str, Any], *, w: int
) -> tuple[bool, str]:
    """Reject entry candidates that target the Following column or non-followers stat."""
    st = str(c.get("stat_type") or "").strip().lower()
    if st == "following":
        return False, "stat_type_following"
    if st in ("posts", "post"):
        return False, "stat_type_posts"
    if st and st != "followers":
        return False, f"stat_type_{st}"
    if bool(c.get("semantic_followers_metric")):
        return True, ""
    mlow = str(c.get("method") or "").lower()
    if mlow in (
        _FOLLOWERS_ENTRY_XML_FAMILIAR_EXACT_METHOD,
        _FOLLOWERS_ENTRY_XML_CD_FOLLOWERS_METHOD,
    ):
        return True, ""
    if "profile_header_following" not in mlow and (
        "profile_header_followers" in mlow or "followers_stacked_familiar" in mlow
    ):
        return True, ""
    tcx = int(c.get("tap_x") or 0)
    bd = dict(c.get("bounds") or {})
    if tcx > 0 and bd:
        if not _followers_entry_v2_tap_center_in_followers_column(int(w), tcx, bd):
            return False, "tap_outside_followers_column"
    m = str(c.get("method") or "").lower()
    if "profile_header_following" in mlow and "follower" not in mlow:
        return False, "resource_id_following_header"
    sigs = c.get("signals") or []
    if isinstance(sigs, list):
        for s in sigs:
            if not isinstance(s, str):
                continue
            if _followers_reject_following_column_label(s) and not _followers_label_match(s):
                return False, "signal_following_like"
    det_txt = ""
    for s in sigs:
        if isinstance(s, str) and not s.startswith("score:") and "resource_id" not in s.lower():
            det_txt = s
            break
    if det_txt and _followers_reject_following_column_label(det_txt) and not _followers_label_match(
        det_txt
    ):
        return False, "detected_following_like"
    return True, ""


def _followers_entry_v2_log_tab_validation_accepted(
    det: dict[str, Any],
    tap_diag: dict[str, Any],
    *,
    validation_tag: str,
) -> None:
    src_log = str(tap_diag.get("entry_v2_source_profile_username") or "")
    vf = (
        det.get("visual_fallback_detail")
        if isinstance(det.get("visual_fallback_detail"), dict)
        else {}
    )
    vs = list((vf.get("visual_signals") or [])[:20]) if vf else []
    log(
        "info",
        "followers_entry_tab_validation_accepted",
        source_profile_username=src_log,
        expected_tab="followers",
        active_tab_text=str(det.get("action_bar_title") or "")[:160],
        action_bar_title=str(det.get("action_bar_title") or "")[:120],
        visual_signals=vs,
        validation_tag=str(validation_tag or ""),
    )


def _followers_entry_v2_vision_followers_surface_confirmed(det: dict[str, Any]) -> bool:
    """
    RN / Compose followers list: strong screenshot signals even when XML lacks
    usernames / RecyclerView and the action bar still shows the source handle.
    Never true on ``visual_match`` alone — requires rows, search strip, blue bands, confidence.
    """
    if str(det.get("open_detection_method") or "") != "visual_fallback":
        return False
    vf = det.get("visual_fallback_detail")
    if not isinstance(vf, dict):
        return False
    if not bool(vf.get("visual_match")):
        return False
    conf = float(vf.get("visual_confidence") or 0.0)
    if conf < 0.82:
        return False
    rows = int(vf.get("visual_user_rows_detected") or 0)
    if rows < 12:
        return False
    if not bool(vf.get("visual_search_area_detected")):
        return False
    guess = str(det.get("current_screen_guess") or "").strip().lower()
    if guess and guess not in ("likely_profile", "followers_like", "unknown"):
        return False
    sigs = vf.get("visual_signals") or []
    if not any(str(x) == "search_strip" for x in sigs):
        return False
    rb = int(vf.get("visual_follow_button_count") or 0)
    rb_sig = _followers_entry_v2_visual_signal_int(sigs, "right_blue_bands")
    if rb_sig is not None:
        rb = max(rb, rb_sig)
    if rb < 2:
        return False
    lb_sig = _followers_entry_v2_visual_signal_int(sigs, "left_row_bands")
    if lb_sig is not None and lb_sig < 12:
        return False
    if lb_sig is not None and abs(int(lb_sig) - rows) > 5:
        return False
    return True


def _followers_entry_v2_post_tap_semantic_followers_context(
    tap_diag: dict[str, Any],
) -> bool:
    if not bool(tap_diag.get("entry_engine_v2")):
        return False
    if bool(tap_diag.get("semantic_followers_metric")):
        return True
    utm = str(
        tap_diag.get("entry_v2_underlying_candidate_method")
        or tap_diag.get("tap_method")
        or ""
    ).lower()
    return "harvest_raw_clickable_followers_metric" in utm


def _vf_followers_rendered_strong_list_structure_strong_no_visible_follow_cta(
    vf: dict[str, Any],
) -> bool:
    """
    Conservative branch: followers sheet chrome is very strong but no Follow pill was
    detected yet (list may need scroll before any followable CTA appears).
    """
    if not isinstance(vf, dict):
        return False
    if int(vf.get("visual_follow_button_count") or 0) != 0:
        return False
    if int(vf.get("visual_user_rows_detected") or 0) < 15:
        return False
    return True


def _followers_entry_v2_transition_visual_rendered_strong_gates(
    d: u2.Device,
    det: dict[str, Any],
    tap_diag: dict[str, Any],
) -> tuple[bool, str]:
    if not _followers_entry_v2_post_tap_semantic_followers_context(tap_diag):
        return False, "not_semantic_post_tap_context"
    vf = det.get("visual_fallback_detail")
    if not isinstance(vf, dict):
        return False, "no_visual_fallback_detail"
    bad_tab, _, _ = _followers_entry_v2_wrong_following_tab_evidence(d, det)
    if bad_tab:
        return False, "following_tab_active"
    try:
        from vision_validation_layer import vision_detect_danger_surface

        dang = vision_detect_danger_surface({"det": det if isinstance(det, dict) else {}})
    except Exception:
        dang = {"danger": False}
    if bool((dang or {}).get("danger")):
        return False, "danger_surface"
    if not bool(vf.get("visual_search_area_detected")):
        return False, "rendered_strong_gates_failed"
    sigs_raw = vf.get("visual_signals") or []
    if not any(str(x) == "search_strip" for x in sigs_raw):
        return False, "rendered_strong_gates_failed"
    if not bool(vf.get("visual_followers_title_hint")):
        return False, "rendered_strong_gates_failed"
    rows = int(vf.get("visual_user_rows_detected") or 0)
    fcb = int(vf.get("visual_follow_button_count") or 0)
    if fcb >= 1:
        if rows < 12:
            return False, "rendered_strong_gates_failed"
    elif _vf_followers_rendered_strong_list_structure_strong_no_visible_follow_cta(vf):
        pass
    else:
        return False, "rendered_strong_gates_failed"
    return True, "ok"


