def _mute_engine_v2_resolve_toggle_row(
    d: u2.Device,
    *,
    axis: str,
    labels: tuple[str, ...],
    ww: int,
) -> dict[str, Any]:
    out: dict[str, Any] = {
        "axis": axis,
        "label_found": False,
        "label_text": "",
        "row_bounds": None,
        "toggle_bounds": None,
        "toggle_state": "unknown",
    }
    el: Any | None = None
    for lab in labels:
        try:
            cand = d(text=lab)
            if cand.exists(timeout=0.12):
                el = cand
                out["label_text"] = str(lab)
                break
        except Exception:
            continue
    if el is None:
        return out
    out["label_found"] = True
    try:
        lb = el.info.get("bounds") or {}
        out["row_bounds"] = {
            "left": int(lb.get("left", 0)),
            "top": int(lb.get("top", 0)),
            "right": int(lb.get("right", 0)),
            "bottom": int(lb.get("bottom", 0)),
        }
    except Exception:
        pass
    chk = _visual_switch_checked_near_row(d, el)
    if chk is True:
        out["toggle_state"] = "on"
    elif chk is False:
        out["toggle_state"] = "off"
    cands = _mute_row_toggle_candidates_near_label(d, el)
    sw_el, sw_diag = _mute_row_toggle_pick_best(cands)
    if sw_el is not None:
        try:
            sb = sw_el.info.get("bounds") or {}
            out["toggle_bounds"] = {
                "left": int(sb.get("left", 0)),
                "top": int(sb.get("top", 0)),
                "right": int(sb.get("right", 0)),
                "bottom": int(sb.get("bottom", 0)),
            }
        except Exception:
            pass
        if out["toggle_state"] == "unknown" and isinstance(
            sw_diag.get("matched_toggle_checked"), bool
        ):
            out["toggle_state"] = "on" if sw_diag["matched_toggle_checked"] else "off"
    try:
        log(
            "info",
            "mute_toggle_row_detected",
            axis=axis,
            label_text=str(out.get("label_text") or "")[:40],
            row_bounds=out.get("row_bounds"),
            toggle_bounds=out.get("toggle_bounds"),
        )
        log(
            "info",
            "mute_toggle_state_resolved",
            axis=axis,
            toggle_state=str(out.get("toggle_state") or "unknown"),
            label_found=bool(out.get("label_found")),
        )
    except Exception:
        pass
    return out


def _mute_engine_v2_remaining_s(t0: float) -> float:
    return max(0.0, _MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S - (time.perf_counter() - t0))


def _mute_engine_v2_axis_remaining_s(axis_t0: float, axis_budget_s: float) -> float:
    return max(0.0, float(axis_budget_s or 0.0) - (time.perf_counter() - axis_t0))


def _mute_engine_v2_toggle_required_budget_s(
    *, want_posts: bool = True, want_stories: bool = True
) -> float:
    axes = int(bool(want_posts)) + int(bool(want_stories))
    if axes <= 0:
        return 0.0
    if axes == 1:
        return 0.82
    return float(MIN_MUTE_TOGGLE_STAGE_SAMSUNG_SAFE_REQUIRED_S)


def _mute_engine_v2_budget_starved_for_toggle(
    remaining_s: float,
    *,
    want_posts: bool = True,
    want_stories: bool = True,
) -> tuple[bool, float]:
    required = _mute_engine_v2_toggle_required_budget_s(
        want_posts=want_posts,
        want_stories=want_stories,
    )
    return float(remaining_s or 0.0) < required, required


def _mute_engine_v2_pre_toggle_wait_s(
    *,
    remaining_s: float,
    desired_s: float,
    required_toggle_s: float,
) -> float:
    spare = max(0.0, float(remaining_s or 0.0) - float(required_toggle_s or 0.0))
    return max(0.0, min(float(desired_s or 0.0), spare))


def _mute_engine_v2_toggle_stage_axis_deadline(
    toggle_stage_deadline: float,
    *,
    axes_remaining: int,
    t_all: float | None = None,
) -> float:
    """Per-axis deadline: reserve min budget for later axes (Stories after Posts)."""
    axes_left = max(1, int(axes_remaining))
    now = time.perf_counter()
    rem_wall = max(0.0, float(toggle_stage_deadline) - now)
    reserve_later = float(_MUTE_V2_PER_AXIS_TOGGLE_MIN_S) * max(0, axes_left - 1)
    usable = max(0.0, rem_wall - reserve_later)
    per_axis = max(float(_MUTE_V2_PER_AXIS_TOGGLE_MIN_S), usable / float(axes_left))
    deadline = now + per_axis
    if t_all is not None:
        rem_global = _mute_engine_v2_remaining_s(t_all)
        if rem_global > 0.12:
            deadline = min(deadline, now + rem_global)
    return min(float(toggle_stage_deadline), deadline)


def _mute_engine_v2_map_toggle_rsn(rsn: str) -> str:
    r = str(rsn or "").strip()
    if r == "budget":
        return "budget"
    if r == "toggle_label_not_found":
        return "label_missing"
    if r == "toggle_stage_wall_cap":
        return "mute_axis_budget_exhausted"
    if r.startswith("tap_failed"):
        return "tap_failed"
    if r in ("", "skipped"):
        return "skipped"
    return r or "unknown"


def _mute_engine_v2_axis_reason(axis: str, raw_reason: str, *, already_on: bool = False) -> str:
    prefix = "stories_axis" if str(axis or "") == "stories" else "posts_axis"
    r = str(raw_reason or "").strip()
    if already_on or r.startswith("already_on"):
        return f"{prefix}_skipped_already_muted"
    if r in ("", "skipped"):
        return "applied_or_verified"
    if r in ("budget", "mute_axis_budget_exhausted", "toggle_stage_wall_cap"):
        return f"{prefix}_skipped_budget_exhausted"
    if r == "toggle_label_not_found":
        return f"{prefix}_skipped_toggle_not_found"
    if r in ("state_invalid", "mute_toggles_sheet_not_confirmed"):
        return f"{prefix}_skipped_state_invalid"
    if r == "config_disabled":
        return f"{prefix}_skipped_config_disabled"
    return r


def _mute_engine_v2_missing_axis(
    *,
    want_posts: bool,
    want_stories: bool,
    posts_ok: bool,
    stories_ok: bool,
) -> str:
    missing: list[str] = []
    if want_posts and not posts_ok:
        missing.append("posts")
    if want_stories and not stories_ok:
        missing.append("stories")
    return ",".join(missing)


def _mute_engine_v2_classify_both_toggles_failure(
    *,
    want_posts: bool,
    want_stories: bool,
    posts_ok: bool,
    stories_ok: bool,
    tapped_p: bool,
    tapped_s: bool,
    already_p: bool,
    already_s: bool,
    rsn_p: str,
    rsn_s: str,
) -> tuple[str, str]:
    """
    Returns (abort_reason, failure_reason) for mute_engine_v2 when both axes were required
    and the combined outcome is failure (no partial success path).
    """
    mp = _mute_engine_v2_map_toggle_rsn(rsn_p)
    ms = _mute_engine_v2_map_toggle_rsn(rsn_s)
    if mp == "budget" or ms == "budget":
        return "mute_toggle_budget_starved", "mute_toggle_budget_starved"
    if mp == "label_missing" or ms == "label_missing":
        return "mute_toggle_label_missing", "mute_toggle_label_missing"
    vfail_p = bool(want_posts and tapped_p and not already_p and not posts_ok)
    vfail_s = bool(want_stories and tapped_s and not already_s and not stories_ok)
    if vfail_p or vfail_s:
        return "mute_toggle_verify_failed", "mute_toggle_verify_failed"
    if mp == "tap_failed" or ms == "tap_failed":
        return "mute_toggle_tap_failed", "mute_toggle_tap_failed"
    return "mute_toggle_failed", "mute_toggle_failed"


def _mute_engine_v2_classify_single_toggle_failure(
    *,
    want_posts: bool,
    want_stories: bool,
    posts_ok: bool,
    stories_ok: bool,
    tapped_p: bool,
    tapped_s: bool,
    already_p: bool,
    already_s: bool,
    rsn_p: str,
    rsn_s: str,
) -> tuple[str, str]:
    if want_posts and not want_stories:
        m = _mute_engine_v2_map_toggle_rsn(rsn_p)
        vfail = bool(tapped_p and not already_p and not posts_ok)
    elif want_stories and not want_posts:
        m = _mute_engine_v2_map_toggle_rsn(rsn_s)
        vfail = bool(tapped_s and not already_s and not stories_ok)
    else:
        return "mute_toggle_failed", "mute_toggle_failed"
    if m == "budget":
        return "mute_toggle_budget_starved", "mute_toggle_budget_starved"
    if m == "label_missing":
        return "mute_toggle_label_missing", "mute_toggle_label_missing"
    if vfail:
        return "mute_toggle_verify_failed", "mute_toggle_verify_failed"
    if m == "tap_failed":
        return "mute_toggle_tap_failed", "mute_toggle_tap_failed"
    return "mute_toggle_failed", "mute_toggle_failed"


def _mute_engine_v2_text_rejected(txt: str) -> bool:
    t = (txt or "").strip().lower()
    if not t:
        return True
    for sub in _MUTE_V2_REJECT_SUBSTR:
        if sub in t:
            return True
    if t in ("follow", "suivre", "seguir", "folgen", "abonar", "folgen"):
        return True
    return False


def _mute_engine_v2_following_header_text_ok(txt: str) -> bool:
    """True for profile header states: Following / Requested / localized, not Follow / Contact."""
    t = (txt or "").strip()
    if not t:
        return False
    low = t.lower()
    if "contact" in low or ("message" in low and "requested" not in low):
        return False
    if "follow back" in low or low in ("follow", "follow "):
        return False
    if low.startswith("follow ") and not low.startswith("following"):
        return False
    if _mute_engine_v2_text_rejected(t):
        return False
    for lab in _MUTE_V2_FOLLOWING_STATE_LABELS:
        ll = lab.lower()
        if low == ll or low.startswith(ll) or low.startswith(ll + " "):
            return True
    return False


def _mute_engine_v2_pick_following_cta(
    d: u2.Device,
    *,
    ww: int,
    wh: int,
    t0: float,
    visual_candidate_id: str = "",
    source_profile_username: str = "",
) -> tuple[Any | None, str]:
    rem = _mute_engine_v2_remaining_s(t0)
    vcid = str(visual_candidate_id or "").strip()
    src = str(source_profile_username or "").strip()
    base_log: dict[str, Any] = {
        "visual_candidate_id": vcid,
        "source_profile_username": src,
        "window_w": int(ww),
        "window_h": int(wh),
        "budget_remaining_s": round(float(rem), 4),
    }
    if rem <= 0.1:
        try:
            log(
                "warning",
                "mute_engine_v2_following_button_search_budget_starved",
                **base_log,
            )
        except Exception:
            pass
    log("info", "mute_engine_v2_following_button_search_started", **base_log)
    ex_to = max(0.05, min(0.14, rem * 0.32))
    y_header_max = int(wh * 0.52)
    y_header_min = int(wh * 0.07)

    def _element_passes(el: Any, *, pick_reason: str) -> tuple[Any | None, str]:
        try:
            raw_txt = str(el.info.get("text") or "").strip()
            cd = str(el.info.get("contentDescription") or "").strip()
            rid = str(el.info.get("resourceName") or el.info.get("resourceId") or "")
            b = el.info.get("bounds") or {}
        except Exception:
            return None, ""
        merged = raw_txt or cd
        rl = rid.lower()
        if "contact" in rl or "message" in rl or "invite" in rl:
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="resource_id_blocked",
                candidate_text=merged[:120],
                resource_id=rid[:160],
                pick_reason=pick_reason,
            )
            return None, ""
        if not _mute_engine_v2_following_header_text_ok(merged):
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="not_following_state_label",
                candidate_text=merged[:120],
                content_desc=cd[:120],
                pick_reason=pick_reason,
            )
            return None, ""
        try:
            cy = (int(b.get("top", 0)) + int(b.get("bottom", 0))) // 2
            rx = int(b.get("right", 0))
        except Exception:
            return None, ""
        if cy < y_header_min or cy > y_header_max:
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="y_outside_header_cta_band",
                cy=int(cy),
                pick_reason=pick_reason,
            )
            return None, ""
        if rx < int(ww * 0.16):
            log(
                "info",
                "mute_engine_v2_following_button_rejected",
                **base_log,
                reason="too_far_left",
                pick_reason=pick_reason,
            )
            return None, ""
        log(
            "info",
            "mute_engine_v2_following_button_candidate",
            **base_log,
            pick_reason=pick_reason,
            candidate_text=merged[:120],
            bounds={
                "left": b.get("left"),
                "top": b.get("top"),
                "right": b.get("right"),
                "bottom": b.get("bottom"),
            },
        )
        return el, pick_reason

    for lab in _MUTE_V2_FOLLOWING_STATE_LABELS:
        if _mute_engine_v2_remaining_s(t0) < 0.05:
            break
        try:
            el = d(text=lab)
            if not el.exists(timeout=ex_to):
                continue
            try:
                raw_txt = str(el.info.get("text") or "").strip()
            except Exception:
                raw_txt = lab
            if raw_txt != lab and _normalize_handle(raw_txt) != _normalize_handle(lab):
                if not _mute_engine_v2_following_header_text_ok(raw_txt):
                    log(
                        "info",
                        "mute_engine_v2_following_button_rejected",
                        **base_log,
                        reason="exact_label_text_mismatch",
                        candidate_text=raw_txt[:120],
                        expected_label=lab,
                        pick_reason=f"text_exact:{lab}",
                    )
                    continue
            if _mute_engine_v2_text_rejected(raw_txt):
                continue
            picked, pr = _element_passes(el, pick_reason=f"text_exact:{lab}")
            if picked is not None:
                return picked, pr
        except Exception:
            continue

    for probe_name, factory in (
        ("textStartsWith_Following", lambda: d(textStartsWith="Following")),
        ("textContains_Following", lambda: d(textContains="Following")),
    ):
        if _mute_engine_v2_remaining_s(t0) < 0.06:
            break
        try:
            sel = factory()
            if not sel.exists(timeout=ex_to):
                continue
            for el in sel.all()[:12]:
                picked, pr = _element_passes(el, pick_reason=probe_name)
                if picked is not None:
                    return picked, pr
        except Exception:
            continue

    try:
        sel = d(descriptionContains="Following")
        if sel.exists(timeout=max(0.05, ex_to * 0.9)):
            for el in sel.all()[:8]:
                picked, pr = _element_passes(el, pick_reason="descriptionContains:Following")
                if picked is not None:
                    return picked, pr
    except Exception:
        pass

    try:
        for el in d(classNameMatches=r".*(Button|TextView)", clickable=True).all()[:55]:
            try:
                raw_txt = str(el.info.get("text") or "").strip()
                cd = str(el.info.get("contentDescription") or "").strip()
                merged = raw_txt or cd
            except Exception:
                continue
            if not merged or not _mute_engine_v2_following_header_text_ok(merged):
                continue
            picked, pr = _element_passes(el, pick_reason="clickable_header_band_scan")
            if picked is not None:
                return picked, pr
    except Exception:
        pass

    log(
        "warning",
        "mute_engine_v2_following_button_rejected",
        **base_log,
        reason="exhausted_search_no_cta",
    )
    return None, ""


_MUTE_V2_DANGEROUS_SCREEN_GUESS_FRAGMENTS: tuple[str, ...] = (
    "story",
    "reel",
    "comment",
    "composer",
    "direct",
    "feed",
    "explore",
    "inbox",
)


def _mute_engine_v2_build_lightweight_profile_det(
    d: u2.Device,
    *,
    det_hint: dict[str, Any] | None,
    pkg: str,
) -> dict[str, Any]:
    """Minimal ``det`` for mute V2 when follow state + title already prove target profile (skips heavy XML)."""
    out: dict[str, Any] = {
        "is_followers_list": False,
        "strict_list_open": False,
        "relaxed_list_open": False,
        "action_bar_title": "",
        "current_screen_guess": "likely_profile",
        "profile_tabs_absent": False,
        "candidate_username_count": 0,
        "visible_header_texts": [],
        "current_package": None,
        "current_activity": None,
        "current_package_expected": str(pkg or "").strip(),
    }
    hint = det_hint if isinstance(det_hint, dict) else {}
    ab = str(hint.get("action_bar_title") or "").strip()
    try:
        cur = d.app_current() or {}
        out["current_package"] = cur.get("package")
        out["current_activity"] = cur.get("activity")
    except Exception:
        pass
    try:
        ab_el = d(resourceIdMatches=r".*:id/action_bar_title.*")
        if ab_el.exists(timeout=0.11):
            live = str(ab_el.get_text() or "").strip()
            if live:
                ab = live
    except Exception:
        pass
    out["action_bar_title"] = ab
    cg = str(hint.get("current_screen_guess") or "").strip()
    if cg:
        out["current_screen_guess"] = cg
    return out


def _mute_engine_v2_following_label_visible_quick(
    d: u2.Device, *, timeout_s: float
) -> bool:
    wt = max(0.04, min(0.09, float(timeout_s)))
    for lab in _MUTE_V2_FOLLOWING_STATE_LABELS:
        try:
            if d(text=lab).exists(timeout=wt):
                return True
        except Exception:
            continue
    return False


def _mute_engine_v2_keyboard_focus_edit_text(d: u2.Device, *, timeout_s: float) -> bool:
    try:
        wt = max(0.03, min(0.07, float(timeout_s)))
        ed = d(className="android.widget.EditText", focused=True)
        return bool(ed.exists(timeout=wt))
    except Exception:
        return False


def _mute_engine_v2_truly_dangerous_surface(
    d: u2.Device,
    *,
    pkg: str,
    nav: dict[str, Any],
    det: dict[str, Any],
    fp: dict[str, Any] | None,
    overlay: dict[str, Any],
    remaining_s: float,
) -> tuple[bool, str]:
    """
    Surfaces that must block mute regardless of inline "Suggested for you" on profile.
    """
    from navigation_engine import NavigationEngineState

    if bool(overlay.get("likely_mute_toggle_sheet")):
        return False, ""

    rem = max(0.06, float(remaining_s))
    st = str(nav.get("state") or "")

    exp = str(pkg or "").strip()
    try:
        cur = d.app_current() or {}
        fg = str(cur.get("package") or "")
    except Exception:
        fg = ""
    if exp and fg and fg != exp:
        return True, "wrong_foreground_package"

    if st in (
        NavigationEngineState.LAUNCHER_WRONG_SURFACE.value,
        NavigationEngineState.INSTAGRAM_CLOSED.value,
    ):
        return True, f"bad_nav_state:{st}"

    guess = str(det.get("current_screen_guess") or "").lower()
    if guess:
        for frag in _MUTE_V2_DANGEROUS_SCREEN_GUESS_FRAGMENTS:
            if frag in guess:
                return True, f"screen_guess_drift:{frag}"

    if _mute_engine_v2_keyboard_focus_edit_text(d, timeout_s=min(0.07, rem * 0.12)):
        return True, "keyboard_focus_edittext"

    sc = str((fp or {}).get("screen_class") or "").strip().lower()
    if sc in ("search_like", "followers_list", "followers_list_strong"):
        return True, f"fingerprint_screen_class:{sc}"

    return False, ""


def _mute_engine_v2_resolve_effective_candidate_username(
    *,
    follower_username: str,
    action_bar_title: str,
    source_profile_username: str,
    det_hint: dict[str, Any] | None,
    visual_candidate_id: str,
) -> tuple[str, str]:
    """
    Handle for the opened profile row. ``follower_username`` may be empty in visual mode;
    fall back to action bar / hint / id-shaped handles.
    """
    fu = str(follower_username or "").strip()
    if fu:
        return fu, "follower_username"
    ab = str(action_bar_title or "").strip()
    src = str(source_profile_username or "").strip()
    if ab and src and _normalize_handle(ab) != _normalize_handle(src):
        return ab, "action_bar_title_fallback"
    if ab and not src:
        return ab, "action_bar_title_fallback"
    hint = det_hint if isinstance(det_hint, dict) else {}
    for key in (
        "follower_username",
        "candidate_username",
        "visual_candidate_username",
        "target_username",
        "opened_profile_username",
        "profile_username",
    ):
        v = str(hint.get(key) or "").strip()
        if v and (not src or _normalize_handle(v) != _normalize_handle(src)):
            return v, f"det_hint:{key}"
    vcid = str(visual_candidate_id or "").strip()
    if vcid and re.match(r"^[A-Za-z0-9._]{1,30}$", vcid):
        if not src or _normalize_handle(vcid) != _normalize_handle(src):
            return vcid, "visual_candidate_id"
    return "", "unresolved"


def _post_follow_mute_perf_summary_payload(
    *,
    timings: dict[str, Any],
    result: str,
    skip_reason: str | None,
    budget_s: float,
    effective_total_budget_s: float,
    toggle_stage_required_budget_s: float,
) -> dict[str, Any]:
    t = dict(timings or {})

    def _first_present(*keys: str) -> Any:
        for key in keys:
            if key in t and t.get(key) is not None:
                return t.get(key)
        return None

    return {
        "total_ms": t.get("mute_total_ms"),
        "sheet_open_ms": _first_present(
            "open_mute_sheet_ms",
            "following_cta_open_sheet_ms",
            "sheet_open_ms",
        ),
        "labels_detect_ms": _first_present(
            "labels_detect_ms",
            "mute_sheet_labels_ms",
            "label_probe_ms",
        ),
        "toggle_ms": round(
            float(t.get("toggle_posts_ms") or 0.0)
            + float(t.get("toggle_stories_ms") or 0.0),
            2,
        ),
        "result": str(result or ""),
        "skip_reason": str(skip_reason or ""),
        "budget_s": budget_s,
        "effective_total_budget_s": effective_total_budget_s,
        "toggle_stage_required_budget_s": toggle_stage_required_budget_s,
        "sheet_dismiss_ms": _first_present("sheet_dismiss_ms", "mute_sheet_dismiss_ms"),
    }


def _mute_engine_v2_mute_sheet_still_visible(d: u2.Device) -> bool:
    try:
        return bool(_mute_engine_v2_is_mute_toggles_sheet(d))
    except Exception:
        return False


def _mute_engine_v2_fast_sheet_closed_profile_proof(d: u2.Device) -> tuple[bool, dict[str, Any]]:
    """Cheap post-back proof that mute sheets are gone and the profile surface is back."""
    t0 = time.perf_counter()
    out: dict[str, Any] = {
        "duration_ms": 0.0,
        "toggles_visible": False,
        "following_options_marker_visible": False,
        "profile_marker_visible": False,
        "action_bar_visible": False,
        "profile_tabs_visible": False,
        "reason": "",
    }
    try:
        out["toggles_visible"] = bool(_quick_mute_sheet_visible_guard(d))
    except Exception:
        out["toggles_visible"] = False
    if bool(out["toggles_visible"]):
        out["reason"] = "mute_toggles_still_visible"
        out["duration_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
        return False, out
    try:
        following_marker = (
            _mute_engine_v2_u2_text_exists(d, text="Unfollow", timeout_s=0.01)
            or _mute_engine_v2_u2_text_exists(d, text_contains="Close friend", timeout_s=0.01)
            or _mute_engine_v2_u2_text_exists(d, text="Add to favorites", timeout_s=0.01)
        )
    except Exception:
        following_marker = False
    out["following_options_marker_visible"] = bool(following_marker)
    if bool(following_marker):
        out["reason"] = "following_options_still_visible"
        out["duration_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
        return False, out
    try:
        action_bar_visible = bool(
            d(resourceIdMatches=r".*:id/action_bar_title.*").exists(timeout=0.04)
            or d(resourceIdMatches=r".*:id/action_bar_large_title_auto_size$").exists(timeout=0.04)
        )
    except Exception:
        action_bar_visible = False
    out["action_bar_visible"] = bool(action_bar_visible)
    profile_tabs_visible = False
    if not action_bar_visible:
        try:
            profile_tabs_visible = bool(_followers_profile_tabs_visible(d))
        except Exception:
            profile_tabs_visible = False
    out["profile_tabs_visible"] = bool(profile_tabs_visible)
    out["profile_marker_visible"] = bool(action_bar_visible or profile_tabs_visible)
    if not bool(out["profile_marker_visible"]):
        out["reason"] = "profile_surface_not_confirmed"
        out["duration_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
        return False, out
    out["reason"] = "sheet_absent_profile_visible"
    out["duration_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
    return True, out


def _mute_engine_v2_dismiss_mute_sheet(
    d: u2.Device,
    *,
    visual_candidate_id: str = "",
    source_profile_username: str = "",
) -> tuple[bool, float]:
    """Dismiss mute bottom sheet before post-follow like / return CT."""
    t0 = time.perf_counter()
    try:
        log(
            "info",
            "mute_sheet_dismiss_started",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
        )
    except Exception:
        pass
    if not _mute_engine_v2_mute_sheet_still_visible(d):
        ms = round((time.perf_counter() - t0) * 1000.0, 2)
        try:
            log(
                "info",
                "mute_sheet_dismiss_completed",
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                already_gone=True,
                elapsed_ms=ms,
            )
        except Exception:
            pass
        return True, ms
    ok = False
    for attempt in (1, 2):
        try:
            d.press("back")
            time.sleep(0.24 if attempt == 1 else 0.2)
        except Exception:
            pass
        if not _mute_engine_v2_mute_sheet_still_visible(d):
            ok = True
            break
    ms = round((time.perf_counter() - t0) * 1000.0, 2)
    if ok:
        try:
            log(
                "info",
                "mute_sheet_dismiss_completed",
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                elapsed_ms=ms,
            )
        except Exception:
            pass
    else:
        try:
            log(
                "warning",
                "mute_sheet_dismiss_failed",
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                elapsed_ms=ms,
            )
        except Exception:
            pass
    return ok, ms


def _mute_engine_v2_surface_unstable(
    d: u2.Device,
    *,
    nav: dict[str, Any],
    overlay: dict[str, Any],
    det: dict[str, Any],
    fp: dict[str, Any] | None,
    follower_username: str,
    follow_state_after: str,
    pkg: str,
    budget_remaining_s: float,
    visual_candidate_id: str = "",
    source_profile_username: str = "",
    det_hint: dict[str, Any] | None = None,
    follow_header_snapshot: str = "",
) -> tuple[bool, str]:
    from navigation_engine import NavigationEngineState

    st = str(nav.get("state") or "")
    allowed = frozenset(
        {
            NavigationEngineState.PROFILE.value,
            NavigationEngineState.CANDIDATE_PROFILE.value,
            NavigationEngineState.PRIVATE_PROFILE.value,
        }
    )
    if st not in allowed:
        return True, f"navigation_not_profile:{st}"
    ab = str(det.get("action_bar_title") or "").strip()
    if not ab:
        return True, "empty_action_bar_title"

    rem_b = max(0.08, float(budget_remaining_s))
    dangerous, dwhy = _mute_engine_v2_truly_dangerous_surface(
        d,
        pkg=pkg,
        nav=nav,
        det=det,
        fp=fp,
        overlay=overlay,
        remaining_s=rem_b,
    )

    ov_sug = bool(overlay.get("suggested_for_you"))
    ov_dis = bool(overlay.get("discover_people"))
    if ov_sug or ov_dis:
        ovt = (
            "both"
            if (ov_sug and ov_dis)
            else ("suggested_for_you" if ov_sug else "discover_people")
        )
        fu_raw = str(follower_username or "").strip()
        src_stripped = str(source_profile_username or "").strip()
        eff, res_src = _mute_engine_v2_resolve_effective_candidate_username(
            follower_username=fu_raw,
            action_bar_title=ab,
            source_profile_username=src_stripped,
            det_hint=det_hint,
            visual_candidate_id=str(visual_candidate_id or ""),
        )
        log(
            "info",
            "mute_engine_v2_effective_candidate_handle_resolved",
            follower_username=fu_raw,
            action_bar_title=ab[:120],
            source_profile_username=src_stripped[:120],
            effective_candidate_username=str(eff or "")[:120],
            resolution_source=res_src,
            visual_candidate_id=str(visual_candidate_id or ""),
        )

        fs_low = str(follow_state_after or "").strip().lower()
        fhs = str(follow_header_snapshot or "").strip().lower()
        fs_from_state = fs_low in ("following", "requested")
        fs_from_header = fhs in ("following", "requested")
        fs_vis = (
            fs_from_state
            or fs_from_header
            or _mute_engine_v2_following_label_visible_quick(
                d, timeout_s=min(0.11, rem_b * 0.28)
            )
        )

        src_norm = _normalize_handle(src_stripped) if src_stripped else ""
        ab_norm = _normalize_handle(ab)
        on_candidate_not_owner = bool(ab) and (not src_norm or ab_norm != src_norm)

        title_ok_explicit = bool(fu_raw) and bool(ab) and (
            _normalize_handle(fu_raw) == ab_norm
        )
        profile_overlay_safe = (
            st in allowed
            and not dangerous
            and fs_vis
            and on_candidate_not_owner
            and (not bool(fu_raw) or title_ok_explicit)
        )

        gate_title_source = ""
        if profile_overlay_safe:
            if bool(fu_raw) and title_ok_explicit:
                gate_title_source = "follower_username_match"
            else:
                gate_title_source = "action_bar_title_fallback"

        base_common: dict[str, Any] = {
            "overlay_type": ovt,
            "action_bar_title": ab[:120],
            "navigation_state": st,
            "following_visible": bool(fs_vis),
            "dangerous_surface": bool(dangerous),
            "dangerous_reason": dwhy or "",
            "visual_candidate_id": str(visual_candidate_id or ""),
            "source_profile_username": src_stripped[:120],
            "follower_username": fu_raw,
            "effective_candidate_username": str(eff or "")[:120],
            "effective_resolution_source": res_src,
        }
        log("info", "mute_engine_v2_overlay_surface_detected", **base_common)

        if dangerous:
            log(
                "warning",
                "mute_engine_v2_overlay_surface_rejected",
                **base_common,
                allow_mute=False,
                safe_profile_overlay_surface=False,
                rejection_reason="dangerous_context",
            )
            return True, dwhy if dwhy else "dangerous_context"

        if profile_overlay_safe:
            log(
                "info",
                "mute_engine_v2_overlay_surface_allowed",
                **base_common,
                allow_mute=True,
                safe_profile_overlay_surface=True,
                profile_gate_title_ok=True,
                profile_gate_title_source=gate_title_source,
            )
        else:
            log(
                "warning",
                "mute_engine_v2_overlay_surface_rejected",
                **base_common,
                allow_mute=False,
                safe_profile_overlay_surface=False,
                rejection_reason="overlay_suggestion_profile_gate_failed",
                profile_gate_title_ok=bool(title_ok_explicit),
                profile_gate_following_visible=bool(fs_vis),
                profile_gate_on_candidate_not_owner=bool(on_candidate_not_owner),
                profile_gate_follow_header_snapshot=fhs[:32],
            )
            return True, "overlay_suggestion_surface"
    elif dangerous:
        return True, dwhy if dwhy else "dangerous_context"

    if overlay.get("notification_prompt") or overlay.get("turn_on_notifications"):
        return True, "overlay_system_prompt"
    if overlay.get("likely_mute_toggle_sheet"):
        try:
            p0 = bool(d(text="Posts").exists(timeout=0.04)) or bool(
                d(text="Publications").exists(timeout=0.04)
            )
            s0 = bool(d(text="Stories").exists(timeout=0.04))
        except Exception:
            p0 = s0 = False
        if not (p0 and s0):
            return True, "mute_sheet_partial_or_unknown"

    return False, ""


def _mute_engine_v2_tap_toggle_short(
    d: u2.Device,
    labels: tuple[str, ...],
    ww: int,
    t0: float,
    *,
    axis: str = "",
    visual_candidate_id: str = "",
    source_profile_username: str = "",
    axis_budget_s: float | None = None,
    timing_meta: dict[str, Any] | None = None,
) -> tuple[bool, bool, str]:
    """Returns (tapped_or_already_on, is_already_on, reason)."""
    rem = (
        _mute_engine_v2_axis_remaining_s(t0, float(axis_budget_s))
        if axis_budget_s is not None
        else _mute_engine_v2_remaining_s(t0)
    )
    if rem < 0.08:
        return False, False, "budget"
    t_resolve = time.perf_counter()
    row = _mute_engine_v2_resolve_toggle_row(
        d, axis=str(axis or ""), labels=labels, ww=int(ww)
    )
    if timing_meta is not None:
        timing_meta["resolve_row_ms"] = round((time.perf_counter() - t_resolve) * 1000.0, 2)
    if not bool(row.get("label_found")):
        return False, False, "toggle_label_not_found"
    if str(row.get("toggle_state") or "") == "on":
        if timing_meta is not None:
            timing_meta["tap_source"] = "already_on_row"
        return True, True, "already_on_row"
    row_bounds = row.get("row_bounds") or {}
    toggle_bounds = row.get("toggle_bounds")
    row_reusable = False
    if isinstance(row_bounds, dict) and (
        toggle_bounds is None or str(row.get("toggle_state") or "") == "unknown"
    ):
        try:
            rl = int(row_bounds["left"])
            rt = int(row_bounds["top"])
            rr = int(row_bounds["right"])
            rb = int(row_bounds["bottom"])
            row_reusable = (
                rr > rl
                and rb > rt
                and rl >= 0
                and rt >= 0
                and rr <= int(ww) + 4
                and (rr - rl) >= 24
                and (rb - rt) >= 24
            )
        except Exception:
            row_reusable = False
    if row_reusable:
        try:
            tx = int((int(row_bounds["left"]) + int(row_bounds["right"])) // 2)
            ty = int((int(row_bounds["top"]) + int(row_bounds["bottom"])) // 2)
            t_tap = time.perf_counter()
            d.click(tx, ty)
            if timing_meta is not None:
                timing_meta["tap_ms"] = round((time.perf_counter() - t_tap) * 1000.0, 2)
                timing_meta["row_reused"] = True
                timing_meta["tap_source"] = "row_bounds_reused"
        except Exception as e:
            return False, False, f"tap_failed:{e}"
        try:
            log(
                "info",
                "mute_axis_tap_sent",
                axis=str(axis or "")[:20],
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                label_text=str(row.get("label_text") or "")[:40],
                toggle_bounds=row.get("toggle_bounds"),
                tap_source="row_bounds_reused",
                row_reused=True,
            )
        except Exception:
            pass
        return True, False, ""
    sw_el: Any | None = None
    for lab in labels:
        try:
            cand = d(text=lab)
            if cand.exists(timeout=0.1):
                cands = _mute_row_toggle_candidates_near_label(d, cand)
                sw_el, _diag = _mute_row_toggle_pick_best(cands)
                if sw_el is not None:
                    break
        except Exception:
            continue
    try:
        if sw_el is not None:
            t_tap = time.perf_counter()
            sw_el.click()
            if timing_meta is not None:
                timing_meta["tap_ms"] = round((time.perf_counter() - t_tap) * 1000.0, 2)
                timing_meta["row_reused"] = False
                timing_meta["tap_source"] = "switch_bounds"
        else:
            tb = row.get("toggle_bounds") or row.get("row_bounds") or {}
            if tb:
                tx = int((int(tb["left"]) + int(tb["right"])) // 2)
                ty = int((int(tb["top"]) + int(tb["bottom"])) // 2)
                t_tap = time.perf_counter()
                d.click(tx, ty)
                if timing_meta is not None:
                    timing_meta["tap_ms"] = round((time.perf_counter() - t_tap) * 1000.0, 2)
                    timing_meta["row_reused"] = False
                    timing_meta["tap_source"] = "fallback"
            else:
                t_tap = time.perf_counter()
                tapped, already, rsn, _el = _visual_tap_toggle_row_for_label(d, labels, ww)
                if timing_meta is not None:
                    timing_meta["tap_ms"] = round((time.perf_counter() - t_tap) * 1000.0, 2)
                    timing_meta["row_reused"] = False
                    timing_meta["tap_source"] = "fallback"
                return tapped, already, rsn
    except Exception as e:
        return False, False, f"tap_failed:{e}"
    try:
        log(
            "info",
            "mute_axis_tap_sent",
            axis=str(axis or "")[:20],
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            label_text=str(row.get("label_text") or "")[:40],
            toggle_bounds=row.get("toggle_bounds"),
            tap_source=(timing_meta or {}).get("tap_source", ""),
            row_reused=bool((timing_meta or {}).get("row_reused")),
        )
    except Exception:
        pass
    return True, False, ""


def _mute_engine_v2_compact_axis_toggle(
    d: u2.Device,
    *,
    axis: str,
    labels: tuple[str, ...],
    ww: int,
    t0: float,
    toggle_stage_deadline: float,
    visual_candidate_id: str = "",
    source_profile_username: str = "",
    axis_budget_s: float | None = None,
) -> tuple[bool, bool, bool, str, float]:
    """
    Compact Posts/Stories toggle: XML verify-first, minimal live polling, no structure diag.
    Returns (axis_ok, tap_attempted, already_on, raw_reason, elapsed_ms).
    """
    if time.perf_counter() >= toggle_stage_deadline:
        if axis == "stories" and (
            _mute_engine_v2_u2_text_exists(d, text="Stories")
            or _mute_engine_v2_u2_text_exists(d, text="Historias")
        ):
            toggle_stage_deadline = time.perf_counter() + min(
                0.65, float(_MUTE_V2_PER_AXIS_TOGGLE_MIN_S)
            )
        else:
            return False, False, False, "mute_axis_budget_exhausted", 0.0
    t_ax = time.perf_counter()
    pre_xml_ms = 0.0
    resolve_row_ms = 0.0
    tap_ms = 0.0
    post_xml_verify_ms = 0.0
    row_reused = False
    tap_source = ""

    def _emit_toggle_timing(duration_ms: float, *, source_override: str = "") -> None:
        try:
            log(
                "info",
                "mute_toggle_timing_completed",
                axis=str(axis or "")[:20],
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                row_reused=bool(row_reused),
                tap_source=str(source_override or tap_source or "fallback")[:40],
                pre_xml_ms=pre_xml_ms,
                resolve_row_ms=resolve_row_ms,
                tap_ms=tap_ms,
                post_xml_verify_ms=post_xml_verify_ms,
                duration_ms=duration_ms,
            )
        except Exception:
            pass

    t_pre_xml = time.perf_counter()
    xml_on, _xml_fields = _mute_engine_v2_verify_toggle_on_from_xml_dump(d, axis=axis)
    pre_xml_ms = round((time.perf_counter() - t_pre_xml) * 1000.0, 2)
    if xml_on is True:
        elapsed_ms = round((time.perf_counter() - t_ax) * 1000.0, 2)
        _emit_toggle_timing(elapsed_ms, source_override="already_on_xml")
        return True, False, True, "already_on_xml", elapsed_ms
    timing_meta: dict[str, Any] = {}
    tapped, already, rsn = _mute_engine_v2_tap_toggle_short(
        d,
        labels,
        ww,
        t0,
        axis=axis,
        visual_candidate_id=visual_candidate_id,
        source_profile_username=source_profile_username,
        axis_budget_s=axis_budget_s,
        timing_meta=timing_meta,
    )
    resolve_row_ms = float(timing_meta.get("resolve_row_ms") or 0.0)
    tap_ms = float(timing_meta.get("tap_ms") or 0.0)
    row_reused = bool(timing_meta.get("row_reused"))
    tap_source = str(timing_meta.get("tap_source") or "")
    tap_attempted = bool(tapped and not already)
    if already:
        elapsed_ms = round((time.perf_counter() - t_ax) * 1000.0, 2)
        _emit_toggle_timing(elapsed_ms, source_override=tap_source or "already_on_row")
        return True, False, True, rsn or "already_on", elapsed_ms
    if not tapped:
        elapsed_ms = round((time.perf_counter() - t_ax) * 1000.0, 2)
        _emit_toggle_timing(elapsed_ms, source_override=tap_source or "fallback")
        return False, False, False, rsn or "toggle_label_not_found", elapsed_ms
    settle_s = min(
        float(_MUTE_V2_TOGGLE_POST_TAP_SETTLE_S),
        max(
            0.04,
            (
                _mute_engine_v2_axis_remaining_s(t0, float(axis_budget_s))
                if axis_budget_s is not None
                else _mute_engine_v2_remaining_s(t0)
            )
            * 0.12,
        ),
    )
    if settle_s >= 0.03:
        time.sleep(settle_s)
    t_post_xml = time.perf_counter()
    xml_after, _xml_after_fields = _mute_engine_v2_verify_toggle_on_from_xml_dump(d, axis=axis)
    post_xml_verify_ms = round((time.perf_counter() - t_post_xml) * 1000.0, 2)
    elapsed_ms = round((time.perf_counter() - t_ax) * 1000.0, 2)
    if xml_after is True:
        _emit_toggle_timing(elapsed_ms)
        return True, tap_attempted, False, rsn, elapsed_ms
    if time.perf_counter() >= toggle_stage_deadline:
        _emit_toggle_timing(elapsed_ms)
        return False, tap_attempted, False, "mute_axis_budget_exhausted", elapsed_ms
    rem_v = (
        _mute_engine_v2_axis_remaining_s(t0, float(axis_budget_s))
        if axis_budget_s is not None
        else _mute_engine_v2_remaining_s(t0)
    )
    vto = min(0.28, max(0.1, rem_v * 0.22))
    ok_live, vmeta = _visual_verify_toggle_on_for_labels_detailed(d, labels, timeout_s=vto)
    if ok_live:
        elapsed_ms = round((time.perf_counter() - t_ax) * 1000.0, 2)
        _emit_toggle_timing(elapsed_ms)
        return True, tap_attempted, False, rsn, elapsed_ms
    try:
        if _mute_engine_v2_toggle_verify_xml_fallback_maybe(
            d,
            axis=axis,
            vmeta=vmeta,
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
        ):
            elapsed_ms = round((time.perf_counter() - t_ax) * 1000.0, 2)
            _emit_toggle_timing(elapsed_ms)
            return True, tap_attempted, False, rsn, elapsed_ms
    except Exception:
        pass
    elapsed_ms = round((time.perf_counter() - t_ax) * 1000.0, 2)
    _emit_toggle_timing(elapsed_ms)
    return False, tap_attempted, False, rsn or "verify_failed", elapsed_ms


def _post_follow_like_precheck_mute_sheet(
    d: u2.Device,
    *,
    visual_candidate_id: str = "",
    source_profile_username: str = "",
    follower_username: str = "",
) -> dict[str, Any]:
    """
    Before grid detect: ensure mute sheet is not blocking the profile grid.
     """
    t0 = time.perf_counter()
    out: dict[str, Any] = {
        "sheet_visible": False,
        "dismissed": False,
        "still_open": False,
        "skip_like": False,
        "skip_reason": "",
        "precheck_ms": 0.0,
    }
    proof_ok, proof, proof_age_ms, proof_reject = _validate_post_mute_sheet_closed_proof(
        source_profile_username=source_profile_username,
        candidate_username=follower_username,
        visual_candidate_id=visual_candidate_id,
    )
    if proof_ok:
        if _quick_mute_sheet_visible_guard(d):
            _clear_post_mute_sheet_closed_proof_stash()
            proof_reject = "quick_guard_sheet_visible"
            _post_mute_sheet_closed_proof_reject(
                event="post_follow_like_sheet_closed_proof_rejected",
                source_profile_username=source_profile_username,
                candidate_username=follower_username,
                visual_candidate_id=visual_candidate_id,
                reject_reason=proof_reject,
                proof_age_ms=proof_age_ms,
                action_bar_title=str(proof.get("action_bar_title") or ""),
                duration_ms=round((time.perf_counter() - t0) * 1000.0, 2),
                fallback_used=True,
            )
        else:
            out["precheck_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
            out["proof_reused"] = True
            out["used_cached_context"] = True
            try:
                log(
                    "info",
                    "post_follow_like_sheet_closed_proof_reused",
                    visual_candidate_id=visual_candidate_id,
                    source_profile_username=source_profile_username,
                    candidate_username=_normalize_handle(str(follower_username or "")),
                    expected_username=_normalize_handle(str(follower_username or "")),
                    proof_age_ms=proof_age_ms,
                    sheet_closed=True,
                    action_bar_title=str(proof.get("action_bar_title") or ""),
                    used_cached_context=True,
                    reject_reason="",
                    duration_ms=out["precheck_ms"],
                    fallback_used=False,
                )
                log(
                    "info",
                    "like_precheck_sheet_visible",
                    visual_candidate_id=visual_candidate_id,
                    source_profile_username=source_profile_username,
                    follower_username=follower_username,
                    sheet_visible=False,
                    used_cached_context=True,
                    proof_age_ms=proof_age_ms,
                )
                log(
                    "info",
                    "mute_sheet_visible_before_like",
                    visual_candidate_id=visual_candidate_id,
                    source_profile_username=source_profile_username,
                    follower_username=follower_username,
                    sheet_visible=False,
                    used_cached_context=True,
                    proof_age_ms=proof_age_ms,
                )
            except Exception:
                pass
            return out
    else:
        _post_mute_sheet_closed_proof_reject(
            event="post_follow_like_sheet_closed_proof_rejected",
            source_profile_username=source_profile_username,
            candidate_username=follower_username,
            visual_candidate_id=visual_candidate_id,
            reject_reason=proof_reject,
            proof_age_ms=proof_age_ms,
            action_bar_title=str((proof or {}).get("action_bar_title") or ""),
            duration_ms=round((time.perf_counter() - t0) * 1000.0, 2),
            fallback_used=True,
        )
    try:
        visible = bool(_post_follow_overlay_ui_hints(d).get("likely_mute_toggle_sheet"))
    except Exception:
        visible = _mute_engine_v2_mute_sheet_still_visible(d)
    out["sheet_visible"] = visible
    try:
        log(
            "info",
            "like_precheck_sheet_visible",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=follower_username,
            sheet_visible=visible,
        )
        log(
            "info",
            "mute_sheet_visible_before_like",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=follower_username,
            sheet_visible=visible,
        )
    except Exception:
        pass
    if not visible:
        out["precheck_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
        return out
    dismissed, _dms = _mute_engine_v2_dismiss_mute_sheet(
        d,
        visual_candidate_id=visual_candidate_id,
        source_profile_username=source_profile_username,
    )
    out["dismissed"] = bool(dismissed)
    still = _mute_engine_v2_mute_sheet_still_visible(d)
    out["still_open"] = bool(still)
    out["precheck_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
    if dismissed and not still:
        try:
            log(
                "info",
                "like_precheck_sheet_dismissed",
                visual_candidate_id=visual_candidate_id,
                source_profile_username=source_profile_username,
                follower_username=follower_username,
                precheck_ms=out["precheck_ms"],
            )
        except Exception:
            pass
        return out
    out["skip_like"] = True
    out["skip_reason"] = "mute_sheet_still_open"
    try:
        log(
            "warning",
            "like_precheck_sheet_still_open",
            visual_candidate_id=visual_candidate_id,
            source_profile_username=source_profile_username,
            follower_username=follower_username,
            precheck_ms=out["precheck_ms"],
        )
    except Exception:
        pass
    return out


def _post_follow_like_precheck_surface(
    d: u2.Device,
    *,
    source_profile_username: str = "",
    follower_username: str = "",
    visual_candidate_id: str = "",
    continuity_evidence: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Fast post-follow like surface gate; never probes the grid on a wrong surface."""
    t0 = time.perf_counter()
    src = str(source_profile_username or "").strip()
    cand = str(follower_username or "").strip().lstrip("@")
    out: dict[str, Any] = {
        "skip_like": False,
        "skip_reason": "",
        "followers_list_visible": False,
        "profile_candidate_visible": False,
        "grid_tab_visible": False,
        "suggested_overlay_visible": False,
        "precheck_ms": 0.0,
        "action_bar_title": "",
    }
    continuity = dict(continuity_evidence or {})
    if bool(continuity.get("validated")) and _normalize_handle(
        str(continuity.get("username") or "")
    ) == _normalize_handle(cand):
        out["followers_list_visible"] = False
        out["profile_candidate_visible"] = True
        out["action_bar_title"] = str(continuity.get("action_bar_title") or cand)
        out["candidate_context_reused"] = True
    else:
        try:
            out["followers_list_visible"] = bool(
                is_followers_list_surface_quick(d, source_profile_username=src)
            )
        except Exception:
            out["followers_list_visible"] = False
        try:
            ab = str(read_current_profile_username_for_follow_gate(d) or "").strip().lstrip("@")
            out["action_bar_title"] = ab
            out["profile_candidate_visible"] = bool(
                ab and cand and _normalize_handle(ab) == _normalize_handle(cand)
            )
        except Exception:
            out["profile_candidate_visible"] = False
    if bool(out["followers_list_visible"]) and not bool(out["profile_candidate_visible"]):
        out["skip_like"] = True
        out["skip_reason"] = "followers_list_visible_before_like"
    if not bool(out["skip_like"]) and not bool(out["profile_candidate_visible"]):
        out["skip_like"] = True
        out["skip_reason"] = "candidate_profile_not_visible_before_like"
    try:
        hints = _post_follow_likes_grid_ui_surface_hints(
            d,
            source_profile_username=src,
            follower_username=cand,
            visual_candidate_id=visual_candidate_id,
        )
        out["grid_tab_visible"] = bool(hints.get("profile_tabs_visible"))
        out["suggested_overlay_visible"] = bool(
            hints.get("suggested_for_you") or hints.get("discover_people")
        )
    except Exception:
        pass
    out["precheck_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
    try:
        log(
            "info",
            "post_follow_like_surface_precheck",
            visual_candidate_id=str(visual_candidate_id or ""),
            source_profile_username=src,
            follower_username=cand,
            **out,
        )
    except Exception:
        pass
    return out


def run_mute_engine_v2(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    visual_candidate_id: str,
    follower_username: str,
    follow_state_after: str,
    det_hint: dict[str, Any] | None,
) -> dict[str, Any]:
    """
    Short, non-exploratory mute after verified follow. No return_to_followers_list,
    no hierarchy refresh, no profile reopen, no scroll/swipe recovery.
    """
    from navigation_engine import NavigationEngineState, observe_instagram_state

    t_all = time.perf_counter()
    timings: dict[str, float] = {}
    vcid = str(visual_candidate_id or "").strip()
    src = str(source_profile_username or "").strip()
    log_account_id = ""
    log_run_id = ""
    try:
        import supabase_client as _mute_supabase_client  # local import avoids a hard nav dependency

        log_account_id = str(getattr(_mute_supabase_client, "_LOG_CONTEXT_ACCOUNT_ID", "") or "")
        log_run_id = str(getattr(_mute_supabase_client, "_LOG_CONTEXT_RUN_ID", "") or "")
    except Exception:
        log_account_id = ""
        log_run_id = ""
    pkg = str(pkg or getattr(config, "INSTAGRAM_PACKAGE", "") or "")
    fs_after = str(follow_state_after or "").strip()
    want_posts = bool(getattr(config, "VISUAL_MUTE_POSTS_AFTER_FOLLOW", True))
    want_stories = bool(getattr(config, "VISUAL_MUTE_STORIES_AFTER_FOLLOW", True))
    toggle_required_budget_s = _mute_engine_v2_toggle_required_budget_s(
        want_posts=want_posts,
        want_stories=want_stories,
    )
    raw_inv = False
    try:
        raw_inv = bool(_visual_raw_follow_invite_visible_quick(d))
    except Exception:
        raw_inv = False

    log(
        "info",
        "mute_engine_v2_started",
        visual_candidate_id=vcid,
        source_profile_username=src,
        follower_username=str(follower_username or "").strip(),
        follow_state_after=fs_after,
        budget_s=_MUTE_ENGINE_V2_BUDGET_S,
        effective_total_budget_s=_MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S,
        following_cta_reserved_budget_s=MIN_FOLLOWING_CTA_SEARCH_BUDGET_S,
        toggle_stage_reserved_budget_s=MIN_MUTE_TOGGLE_STAGE_BUDGET_S,
        toggle_stage_required_budget_s=toggle_required_budget_s,
        want_posts=want_posts,
        want_stories=want_stories,
    )

    def _emit_mute_perf_summary(
        *,
        result: str,
        skip_reason: str | None = None,
        confirmed_sheet_level: str = "",
    ) -> None:
        try:
            _dismiss_ok, _dismiss_ms = _mute_engine_v2_dismiss_mute_sheets_level_aware(
                d,
                visual_candidate_id=vcid,
                source_profile_username=src,
                confirmed_sheet_level=confirmed_sheet_level,
            )
            timings["sheet_dismiss_ms"] = _dismiss_ms
            timings["mute_sheet_dismiss_ok"] = bool(_dismiss_ok)
        except Exception:
            pass
        try:
            payload = _post_follow_mute_perf_summary_payload(
                timings={
                    **dict(timings),
                    "mute_total_ms": timings.get("mute_total_ms")
                    or round((time.perf_counter() - t_all) * 1000.0, 2),
                },
                result=result,
                skip_reason=skip_reason,
                budget_s=_MUTE_ENGINE_V2_BUDGET_S,
                effective_total_budget_s=_MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S,
                toggle_stage_required_budget_s=toggle_required_budget_s,
            )
            log(
                "info",
                "post_follow_mute_perf_summary",
                visual_candidate_id=vcid,
                source_profile_username=src,
                follower_username=str(follower_username or "").strip(),
                **payload,
            )
        except Exception:
            pass

    def _abort(reason: str, *, fr: str | None = None, **log_extra: Any) -> dict[str, Any]:
        timings["mute_total_ms"] = round((time.perf_counter() - t_all) * 1000, 2)
        _log_payload: dict[str, Any] = {
            "visual_candidate_id": vcid,
            "source_profile_username": src,
            "reason": reason,
            "failure_reason": fr or reason,
            "timings_ms": dict(timings),
        }
        if log_extra:
            _log_payload.update({k: v for k, v in log_extra.items() if v is not None})
        log(
            "warning",
            "mute_engine_v2_safe_abort",
            **_log_payload,
        )
        _emit_mute_perf_summary(result="safe_abort", skip_reason=fr or reason)
        _out: dict[str, Any] = {
            "ok": False,
            "partial": False,
            "skipped": False,
            "failure_reason": fr or reason,
            "outcome": "safe_abort",
            "abort_reason": reason,
            "mute_engine_v2": True,
            "timings_ms": dict(timings),
        }
        if log_extra:
            _out["mute_v2_abort_detail"] = {
                k: v for k, v in log_extra.items() if v is not None and not str(k).startswith("_")
            }
        return _out

    if _mute_engine_v2_remaining_s(t_all) < 0.25:
        return _abort("mute_budget_exceeded", fr="mute_budget_exceeded")

    t_obs = time.perf_counter()
    light_profile_det = False
    det: dict[str, Any] = {}
    fu2 = str(follower_username or "").strip()
    fs_low = str(follow_state_after or "").strip().lower()
    if fs_low in ("following", "requested") and fu2:
        try:
            det_try = _mute_engine_v2_build_lightweight_profile_det(
                d, det_hint=det_hint, pkg=pkg
            )
            ab_try = str(det_try.get("action_bar_title") or "").strip()
            if ab_try and _normalize_handle(ab_try) == _normalize_handle(fu2):
                det = det_try
                light_profile_det = True
        except Exception:
            pass
    if not light_profile_det:
        try:
            det = detect_followers_list_screen(d, source_profile_username=src)
        except Exception:
            det = {}
    timings["mute_engine_v2_screen_det_ms"] = round(
        (time.perf_counter() - t_obs) * 1000, 2
    )
    if isinstance(det_hint, dict) and det_hint:
        if not str(det.get("action_bar_title") or "").strip():
            abh = str(det_hint.get("action_bar_title") or "").strip()
            if abh:
                det = {**det, "action_bar_title": abh}
        if not str(det.get("current_screen_guess") or "").strip():
            cg = str(det_hint.get("current_screen_guess") or "").strip()
            if cg:
                det = {**det, "current_screen_guess": cg}

    ab_live = str(det.get("action_bar_title") or "").strip()
    eff_early, res_early = _mute_engine_v2_resolve_effective_candidate_username(
        follower_username=fu2,
        action_bar_title=ab_live,
        source_profile_username=src,
        det_hint=det_hint if isinstance(det_hint, dict) else None,
        visual_candidate_id=vcid,
    )
    trusted_eff_fp = False
    if str(res_early or "") == "follower_username" and str(eff_early or "").strip():
        trusted_eff_fp = True
    elif (
        str(res_early or "") == "action_bar_title_fallback"
        and str(eff_early or "").strip()
        and ab_live
        and src
        and _normalize_handle(ab_live) != _normalize_handle(src)
    ):
        trusted_eff_fp = True

    try:
        log(
            "info",
            "mute_engine_v2_early_effective_candidate_handle_resolved",
            visual_candidate_id=vcid,
            follower_username=fu2[:120] if fu2 else "",
            action_bar_title=ab_live[:120],
            effective_candidate_username=str(eff_early or "")[:120],
            resolution_source=str(res_early or ""),
            trusted_for_fast_path=bool(trusted_eff_fp),
            source_profile_username=src[:120] if src else "",
        )
    except Exception:
        pass

    handle_fp_match = (
        fu2 if fu2 else (str(eff_early or "").strip() if trusted_eff_fp else "")
    ).strip()
    if (
        not light_profile_det
        and fs_low in ("following", "requested")
        and handle_fp_match
        and trusted_eff_fp
    ):
        try:
            det_try2 = _mute_engine_v2_build_lightweight_profile_det(
                d, det_hint=det_hint, pkg=pkg
            )
            ab_try2 = str(det_try2.get("action_bar_title") or "").strip()
            if ab_try2 and _normalize_handle(ab_try2) == _normalize_handle(handle_fp_match):
                det = det_try2
                light_profile_det = True
                if isinstance(det_hint, dict) and det_hint:
                    if not str(det.get("action_bar_title") or "").strip():
                        abh2 = str(det_hint.get("action_bar_title") or "").strip()
                        if abh2:
                            det = {**det, "action_bar_title": abh2}
                    if not str(det.get("current_screen_guess") or "").strip():
                        cg2 = str(det_hint.get("current_screen_guess") or "").strip()
                        if cg2:
                            det = {**det, "current_screen_guess": cg2}
        except Exception:
            pass

    ab_live = str(det.get("action_bar_title") or "").strip()

    nav_ctx: dict[str, Any] = {
        "phase": "mute_engine_v2",
        "visual_candidate_id": vcid,
        "source_profile_username": src,
        "det": det,
        "disable_followers_visual_fallback": True,
    }
    mute_preflight_fast = False
    src_norm = _normalize_handle(src) if src else ""
    ab_norm = _normalize_handle(ab_live) if ab_live else ""
    on_candidate_not_owner = bool(ab_live) and (not src_norm or ab_norm != src_norm)
    try:
        following_chip = _mute_engine_v2_following_label_visible_quick(d, timeout_s=0.16)
    except Exception:
        following_chip = False
    if (
        fs_low in ("following", "requested")
        and following_chip
        and ab_live
        and on_candidate_not_owner
    ):
        mute_preflight_fast = True

    following_clicked_fast_path = False
    following_method = ""
    fast_path_pre_action_budget_reserved_s = float(_MUTE_V2_PRE_ACTION_RESERVED_S)
    try:
        log(
            "info",
            "mute_pre_action_budget_reserved",
            visual_candidate_id=vcid,
            source_profile_username=src,
            reserved_s=round(fast_path_pre_action_budget_reserved_s, 4),
            remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
            fast_path_candidate=bool(mute_preflight_fast),
        )
    except Exception:
        pass

    if mute_preflight_fast:
        try:
            ww_fast, wh_fast = d.window_size()
        except Exception:
            ww_fast, wh_fast = 1080, 2400
        try:
            log(
                "info",
                "mute_fast_path_following_cta_available",
                visual_candidate_id=vcid,
                source_profile_username=src,
                action_bar_title=ab_live[:120],
                follower_username=fu2[:120] if fu2 else "",
                following_visible=True,
                candidate_profile_confirmed=True,
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
            )
        except Exception:
            pass
        btn_fast, following_method = _mute_engine_v2_pick_following_cta(
            d,
            ww=int(ww_fast),
            wh=int(wh_fast),
            t0=t_all,
            visual_candidate_id=vcid,
            source_profile_username=src,
        )
        if btn_fast is not None:
            try:
                btn_fast.click()
                following_clicked_fast_path = True
                timings["following_fast_path_tap_ms"] = round(
                    (time.perf_counter() - t_obs) * 1000.0, 2
                )
                log(
                    "info",
                    "mute_fast_path_following_cta_used",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    method=following_method,
                    remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
                )
                time.sleep(0.12)
            except Exception as e:
                return _abort("following_click_failed", fr=str(e))
        elif _mute_engine_v2_remaining_s(t_all) < fast_path_pre_action_budget_reserved_s:
            log(
                "warning",
                "mute_budget_starved_before_cta_only_if_no_cta",
                visual_candidate_id=vcid,
                source_profile_username=src,
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
                following_visible=True,
                reason="following_cta_pick_failed_fast_path_budget_low",
            )
            return _abort(
                "following_button_not_found_fast_path",
                fr="following_button_not_found_fast_path",
            )

    t_nav = time.perf_counter()
    if following_clicked_fast_path:
        nav = {
            "state": NavigationEngineState.PROFILE.value,
            "confidence": 0.9,
            "reason": "mute_v2_following_cta_fast_path_clicked_skip_observe",
            "signals": {"mute_v2_following_cta_fast_path": True},
            "xml_guess": str(det.get("current_screen_guess") or ""),
            "visual_guess": "",
            "foreground_package": pkg,
        }
        try:
            log(
                "info",
                "mute_observe_state_skipped_fast_path",
                visual_candidate_id=vcid,
                source_profile_username=src,
                action_bar_title=ab_live[:120],
                reason="following_cta_already_clicked",
            )
        except Exception:
            pass
    elif mute_preflight_fast:
        nav = {
            "state": NavigationEngineState.PROFILE.value,
            "confidence": 0.86,
            "reason": "mute_v2_preflight_profile_following_visible_short_circuit",
            "signals": {"mute_v2_fast_observe": True},
            "xml_guess": str(det.get("current_screen_guess") or ""),
            "visual_guess": "",
            "foreground_package": pkg,
        }
        try:
            log(
                "info",
                "mute_engine_v2_observe_short_circuited",
                visual_candidate_id=vcid,
                source_profile_username=src,
                navigation_state=str(nav.get("state") or ""),
                light_profile_det=bool(light_profile_det),
                action_bar_title=ab_live[:120],
                follow_state_after=fs_low,
                note="skip_observe_instagram_state_following_label_visible",
            )
        except Exception:
            pass
    else:
        try:
            nav = observe_instagram_state(
                d,
                expected_package=pkg,
                last_known_state=NavigationEngineState.CANDIDATE_PROFILE.value,
                context=nav_ctx,
            )
        except Exception as e:
            nav = {"state": "UNKNOWN", "confidence": 0.0, "reason": str(e)}
    timings["observe_nav_ms"] = round((time.perf_counter() - t_nav) * 1000, 2)

    nav_st = str(nav.get("state") or "")
    safe_fp_fast = (
        bool(mute_preflight_fast)
        and bool(light_profile_det)
        and nav_st == NavigationEngineState.PROFILE.value
        and fs_low in ("following", "requested")
        and bool(handle_fp_match)
        and bool(ab_live)
        and _normalize_handle(handle_fp_match) == _normalize_handle(ab_live)
    )

    t_ov = time.perf_counter()
    if following_clicked_fast_path:
        overlay = {}
        fp = {
            "fingerprint_id": "mute_fast_path_following_cta_clicked",
            "screen_class": "profile_like",
        }
        try:
            log(
                "info",
                "mute_overlay_fp_skipped_fast_path",
                visual_candidate_id=vcid,
                source_profile_username=src,
                reason="following_cta_already_clicked",
            )
        except Exception:
            pass
    else:
        overlay = _post_follow_overlay_ui_hints(d)
    if following_clicked_fast_path:
        pass
    elif safe_fp_fast:
        fp = _post_follow_screen_fingerprint_mute_v2_fast(
            d,
            nav_state=nav_st,
            det=det,
            action_bar_title=ab_live,
            follow_header_state=fs_low,
        )
        try:
            log(
                "info",
                "mute_engine_v2_fast_fingerprint_used",
                visual_candidate_id=vcid,
                source_profile_username=src,
                action_bar_title=ab_live[:120],
                follower_username=fu2[:120] if fu2 else "",
                effective_candidate_username=handle_fp_match[:120] if handle_fp_match else "",
                follow_state_after=fs_low,
                reason="post_follow_verified_safe_context",
            )
        except Exception:
            pass
    else:
        fp = _post_follow_screen_fingerprint(
            d, nav_state=nav_st, det=det
        )
        try:
            log(
                "info",
                "mute_engine_v2_full_fingerprint_used",
                visual_candidate_id=vcid,
                source_profile_username=src,
                navigation_state=nav_st,
                mute_preflight_fast=bool(mute_preflight_fast),
                light_profile_det=bool(light_profile_det),
                follow_state_after=fs_low,
            )
        except Exception:
            pass
    timings["mute_engine_v2_overlay_fp_ms"] = round(
        (time.perf_counter() - t_ov) * 1000, 2
    )
    fhs = ""
    if following_clicked_fast_path or safe_fp_fast:
        fhs = fs_low
    else:
        try:
            fhs = str(_follow_ui_state_snapshot(d) or "").strip()
        except Exception:
            fhs = ""
    ui_snapshot = {
        "action_bar_title": str(det.get("action_bar_title") or "")[:120],
        "visible_header_texts": list((det.get("visible_header_texts") or [])[:14]),
        "raw_follow_invite_visible": raw_inv,
        "follow_header_snapshot": fhs,
        "fingerprint_id": fp.get("fingerprint_id"),
        "screen_class": fp.get("screen_class"),
        "light_profile_det": light_profile_det,
    }
    log(
        "info",
        "mute_engine_v2_state_observed",
        visual_candidate_id=vcid,
        source_profile_username=src,
        navigation_state=str(nav.get("state") or ""),
        navigation_confidence=float(nav.get("confidence") or 0.0),
        xml_guess=str(nav.get("xml_guess") or det.get("current_screen_guess") or ""),
        **ui_snapshot,
    )
    timings["observe_state_ms"] = round((time.perf_counter() - t_obs) * 1000, 2)
    log(
        "info",
        "post_follow_mute_state_entered",
        account_id=log_account_id,
        run_id=log_run_id,
        target_username=str(follower_username or "").strip(),
        visual_candidate_id=vcid,
        source_profile_username=src,
        state="post_follow_profile_opened",
        navigation_state=str(nav.get("state") or ""),
        reason="profile_state_observed",
    )

    if (not following_clicked_fast_path) and not _vision_validation_mute_engine_surface(
        screenshot_path="",
        det=det,
        nav=nav,
        overlay=overlay,
        fp=fp if isinstance(fp, dict) else {},
        follow_header_snapshot=fhs,
        follow_state_after=fs_after,
        visual_candidate_id=vcid,
        source_profile_username=src,
    ):
        return _abort(
            "vision_validation_mute_surface_rejected",
            fr="vision_validation_mute_surface_rejected",
        )

    if not following_clicked_fast_path:
        bad, why = _mute_engine_v2_surface_unstable(
            d,
            nav=nav,
            overlay=overlay,
            det=det,
            fp=fp if isinstance(fp, dict) else None,
            follower_username=follower_username,
            follow_state_after=follow_state_after,
            pkg=pkg,
            budget_remaining_s=_mute_engine_v2_remaining_s(t_all),
            visual_candidate_id=vcid,
            source_profile_username=src,
            det_hint=det_hint if isinstance(det_hint, dict) else None,
            follow_header_snapshot=fhs,
        )
        if bad:
            return _abort("unstable_post_follow_surface", fr=why)

    try:
        ww, wh = d.window_size()
    except Exception:
        ww, wh = 1080, 2400

    skip_following = False
    sheet_level_pre = "unknown"
    sheet_meta_pre: dict[str, Any] = {}
    following_cta_tapped = bool(following_clicked_fast_path)
    try:
        sheet_level_pre, sheet_meta_pre = _mute_engine_v2_detect_sheet_level(d)
        _mute_engine_v2_log_sheet_detect_timing(
            visual_candidate_id=vcid,
            source_profile_username=src,
            phase="precheck",
            sheet_level=sheet_level_pre,
            meta=sheet_meta_pre if isinstance(sheet_meta_pre, dict) else {},
        )
        log(
            "info",
            "mute_sheet_level_detected",
            visual_candidate_id=vcid,
            source_profile_username=src,
            sheet_level=sheet_level_pre,
            phase="precheck",
            **{k: bool(v) for k, v in sheet_meta_pre.items()},
        )
        if sheet_level_pre == "mute_toggles":
            skip_following = True
            log(
                "info",
                "mute_engine_v2_sheet_detected",
                visual_candidate_id=vcid,
                source_profile_username=src,
                phase="precheck",
                sheet_level="mute_toggles",
                note="mute_toggles_already_visible_skip_following_tap",
            )
    except Exception:
        pass

    t_follow = time.perf_counter()
    if not skip_following and not following_clicked_fast_path:
        _eff_total = float(_MUTE_ENGINE_V2_EFFECTIVE_TOTAL_S)
        _obs_cap = max(0.0, _eff_total - float(MIN_FOLLOWING_CTA_SEARCH_BUDGET_S))
        _rem_cta = _mute_engine_v2_remaining_s(t_all)
        _starved_pre_cta, _req_pre_cta = _mute_engine_v2_budget_starved_for_toggle(
            _rem_cta,
            want_posts=want_posts,
            want_stories=want_stories,
        )
        if _starved_pre_cta:
            try:
                log(
                    "warning",
                    "mute_budget_starved_before_cta_only_if_no_cta",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    remaining_budget_s=round(float(_rem_cta), 4),
                    required_toggle_budget_s=round(float(_req_pre_cta), 4),
                    following_visible=False,
                )
            except Exception:
                pass
            return _abort(
                "mute_toggle_budget_starved",
                fr="mute_toggle_budget_starved",
                remaining_budget_s=round(float(_rem_cta), 4),
                required_toggle_budget_s=round(float(_req_pre_cta), 4),
                phase="before_following_cta",
                posts_visible=False,
                stories_visible=False,
            )
        try:
            log(
                "info",
                "mute_engine_v2_budget_allocated",
                visual_candidate_id=vcid,
                source_profile_username=src,
                total_budget_s=round(_eff_total, 4),
                observe_budget_s=round(_obs_cap, 4),
                following_cta_reserved_budget_s=float(MIN_FOLLOWING_CTA_SEARCH_BUDGET_S),
                toggle_stage_reserved_budget_s=float(MIN_MUTE_TOGGLE_STAGE_BUDGET_S),
                toggle_stage_required_budget_s=round(float(toggle_required_budget_s), 4),
                budget_remaining_before_cta_s=round(float(_rem_cta), 4),
                mute_preflight_fast_observe=bool(mute_preflight_fast),
            )
        except Exception:
            pass
        btn, following_method = _mute_engine_v2_pick_following_cta(
            d,
            ww=ww,
            wh=wh,
            t0=t_all,
            visual_candidate_id=vcid,
            source_profile_username=src,
        )
        if btn is None:
            log(
                "warning",
                "mute_engine_v2_following_button_missing",
                visual_candidate_id=vcid,
                source_profile_username=src,
                navigation_state=str(nav.get("state") or ""),
                action_bar_title=str(det.get("action_bar_title") or "")[:120],
                budget_remaining_s=round(float(_mute_engine_v2_remaining_s(t_all)), 4),
            )
            _rem_post = _mute_engine_v2_remaining_s(t_all)
            if _rem_post <= 0.1:
                return _abort(
                    "following_button_search_budget_exhausted",
                    fr="following_button_search_budget_exhausted",
                )
            return _abort("following_button_not_found", fr="following_button_not_found")
        log(
            "info",
            "mute_engine_v2_following_button_detected",
            visual_candidate_id=vcid,
            source_profile_username=src,
            method=following_method,
        )
        try:
            btn.click()
            following_cta_tapped = True
        except Exception as e:
            return _abort("following_click_failed", fr=str(e))
        _sleep_following = _mute_engine_v2_pre_toggle_wait_s(
            remaining_s=_mute_engine_v2_remaining_s(t_all),
            desired_s=min(0.38, max(0.12, _mute_engine_v2_remaining_s(t_all) * 0.25)),
            required_toggle_s=toggle_required_budget_s,
        )
        if _sleep_following >= 0.02:
            time.sleep(_sleep_following)

    timings["following_detect_ms"] = round((time.perf_counter() - t_follow) * 1000, 2)

    if _mute_engine_v2_remaining_s(t_all) < 0.2:
        return _abort("mute_budget_exceeded", fr="mute_budget_exceeded")

    t_sheet = time.perf_counter()
    sheet_level = "unknown"
    sheet_meta: dict[str, Any] = {}
    fast_mute_row_clicked = False
    if following_cta_tapped and not skip_following:
        if sheet_level_pre == "following_options" and _mute_engine_v2_sheet_meta_has_exact_mute(
            sheet_meta_pre
        ):
            fast_row, fast_row_meta = _mute_engine_v2_find_mute_row_from_confirmed_following_options(
                d,
                ww=int(ww),
                wh=int(wh),
            )
        else:
            fast_row, fast_row_meta = (
                None,
                {
                    "duration_ms": 0.0,
                    "found": False,
                    "ambiguous": False,
                    "candidate_count": 0,
                    "reason": "exact_mute_sheet_probe_not_confirmed",
                    "selector_source": "",
                },
            )
        try:
            log(
                "info",
                "mute_row_find_timing_completed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                duration_ms=float(fast_row_meta.get("duration_ms") or 0.0),
                found=bool(fast_row is not None),
                ambiguous=bool(fast_row_meta.get("ambiguous")),
                candidate_count=int(fast_row_meta.get("candidate_count") or 0),
                reason=str(fast_row_meta.get("reason") or ""),
                selector_source=str(fast_row_meta.get("selector_source") or ""),
                label=str(fast_row_meta.get("label") or "")[:80],
                bounds_safe=fast_row_meta.get("bounds_safe"),
                bounds=fast_row_meta.get("bounds"),
                click_method=str(fast_row_meta.get("click_method") or ""),
                exact_candidate_count_source=str(
                    fast_row_meta.get("exact_candidate_count_source") or ""
                ),
                source="fast_exact_mute_after_following_tap",
            )
        except Exception:
            pass
        if fast_row is not None and not bool(fast_row_meta.get("ambiguous")):
            try:
                log(
                    "info",
                    "mute_following_options_fast_mute_row_found",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    reason=str(fast_row_meta.get("reason") or ""),
                    selector_source=str(fast_row_meta.get("selector_source") or ""),
                    label=str(fast_row_meta.get("label") or "")[:80],
                    bounds_safe=fast_row_meta.get("bounds_safe"),
                    bounds=fast_row_meta.get("bounds"),
                    click_method=str(fast_row_meta.get("click_method") or ""),
                    duration_ms=float(fast_row_meta.get("duration_ms") or 0.0),
                )
                fast_row.click()
                fast_mute_row_clicked = True
                log(
                    "info",
                    "mute_following_options_fast_mute_row_tapped",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    selector_source=str(fast_row_meta.get("selector_source") or ""),
                    label=str(fast_row_meta.get("label") or "")[:80],
                    click_method=str(fast_row_meta.get("click_method") or "uiobject_click"),
                    remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
                )
            except Exception:
                fast_mute_row_clicked = False
        if fast_mute_row_clicked:
            _sleep_fast_sheet = _mute_engine_v2_pre_toggle_wait_s(
                remaining_s=_mute_engine_v2_remaining_s(t_all),
                desired_s=0.18,
                required_toggle_s=float(toggle_required_budget_s),
            )
            if _sleep_fast_sheet >= 0.02:
                time.sleep(_sleep_fast_sheet)
            sheet_level, sheet_meta = _mute_engine_v2_detect_sheet_level(d)
            _mute_engine_v2_log_sheet_detect_timing(
                visual_candidate_id=vcid,
                source_profile_username=src,
                phase="fast_mute_row_confirm",
                sheet_level=sheet_level,
                meta=sheet_meta if isinstance(sheet_meta, dict) else {},
            )
            if sheet_level != "mute_toggles":
                fast_mute_row_clicked = False
                log(
                    "warning",
                    "mute_following_options_fast_mute_row_fallback",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    reason="mute_toggles_not_confirmed_after_fast_row_tap",
                    sheet_level=sheet_level,
                )
    if not fast_mute_row_clicked:
        sheet_level, sheet_meta = _mute_engine_v2_detect_sheet_level(d)
        _mute_engine_v2_log_sheet_detect_timing(
            visual_candidate_id=vcid,
            source_profile_username=src,
            phase="after_following_tap",
            sheet_level=sheet_level,
            meta=sheet_meta if isinstance(sheet_meta, dict) else {},
        )
    if not skip_following:
        if fast_mute_row_clicked:
            pass
        elif sheet_level == "following_options":
            try:
                log(
                    "info",
                    "mute_following_options_to_enter_subsheet_gap_ms",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    duration_ms=round((time.perf_counter() - t_sheet) * 1000.0, 2),
                    sheet_level=sheet_level,
                )
            except Exception:
                pass
            entered, enter_rsn = _mute_engine_v2_enter_mute_subsheet_from_following_options(
                d,
                visual_candidate_id=vcid,
                source_profile_username=src,
                toggle_required_budget_s=float(toggle_required_budget_s),
                t_all=t_all,
            )
            if not entered:
                return _abort(
                    "mute_subsheet_enter_failed",
                    fr=str(enter_rsn or "mute_subsheet_enter_failed"),
                )
            sheet_level, sheet_meta = _mute_engine_v2_detect_sheet_level(d)
            _mute_engine_v2_log_sheet_detect_timing(
                visual_candidate_id=vcid,
                source_profile_username=src,
                phase="post_enter_subsheet",
                sheet_level=sheet_level,
                meta=sheet_meta if isinstance(sheet_meta, dict) else {},
            )
        elif sheet_level != "mute_toggles":
            try:
                log(
                    "info",
                    "mute_following_options_to_enter_subsheet_gap_ms",
                    visual_candidate_id=vcid,
                    source_profile_username=src,
                    duration_ms=round((time.perf_counter() - t_sheet) * 1000.0, 2),
                    sheet_level=sheet_level,
                )
            except Exception:
                pass
            entered, enter_rsn = _mute_engine_v2_enter_mute_subsheet_from_following_options(
                d,
                visual_candidate_id=vcid,
                source_profile_username=src,
                toggle_required_budget_s=float(toggle_required_budget_s),
                t_all=t_all,
            )
            if not entered:
                return _abort(
                    "mute_sheet_level_unknown_after_following_tap",
                    fr=str(enter_rsn or "mute_sheet_level_unknown_after_following_tap"),
                    sheet_level=sheet_level,
                )
            sheet_level, sheet_meta = _mute_engine_v2_detect_sheet_level(d)
            _mute_engine_v2_log_sheet_detect_timing(
                visual_candidate_id=vcid,
                source_profile_username=src,
                phase="post_enter_subsheet_unknown_fallback",
                sheet_level=sheet_level,
                meta=sheet_meta if isinstance(sheet_meta, dict) else {},
            )

    timings["mute_sheet_open_ms"] = round((time.perf_counter() - t_sheet) * 1000, 2)

    if sheet_level != "mute_toggles" or not _mute_engine_v2_is_mute_toggles_sheet(d):
        return _abort(
            "mute_toggles_sheet_not_confirmed",
            fr="mute_toggles_sheet_not_confirmed",
            sheet_level=sheet_level,
        )

    posts_v = bool(sheet_meta.get("posts_label")) or _mute_engine_v2_u2_text_exists(
        d, text="Posts"
    )
    stories_v = bool(sheet_meta.get("stories_label")) or _mute_engine_v2_u2_text_exists(
        d, text="Stories"
    )
    if not posts_v and not stories_v:
        return _abort("posts_or_stories_labels_missing", fr="posts_or_stories_labels_missing")

    log(
        "info",
        "mute_sheet_level_detected",
        visual_candidate_id=vcid,
        source_profile_username=src,
        sheet_level="mute_toggles",
        posts_visible=posts_v,
        stories_visible=stories_v,
        notes_visible=bool(sheet_meta.get("notes_label")),
    )
    log(
        "info",
        "mute_engine_v2_sheet_detected",
        visual_candidate_id=vcid,
        source_profile_username=src,
        sheet_level="mute_toggles",
        posts_visible=posts_v,
        stories_visible=stories_v,
    )
    log(
        "info",
        "post_follow_mute_state_entered",
        account_id=log_account_id,
        run_id=log_run_id,
        target_username=str(follower_username or "").strip(),
        visual_candidate_id=vcid,
        source_profile_username=src,
        state="mute_menu_opened",
        posts_visible=posts_v,
        stories_visible=stories_v,
        reason="mute_toggles_sheet_confirmed",
    )

    _rem_toggle_stage = _mute_engine_v2_remaining_s(t_all)
    timings["toggle_stage_remaining_budget_s"] = round(_rem_toggle_stage, 4)
    timings["toggle_stage_reserved_budget_s"] = float(MIN_MUTE_TOGGLE_STAGE_BUDGET_S)
    timings["toggle_stage_required_budget_s"] = round(float(toggle_required_budget_s), 4)
    _toggle_starved, _req_toggle_floor = _mute_engine_v2_budget_starved_for_toggle(
        _rem_toggle_stage,
        want_posts=want_posts,
        want_stories=want_stories,
    )
    if _toggle_starved and _rem_toggle_stage < _MUTE_V2_POST_SHEET_TRUE_STARVED_S:
        return _abort(
            "mute_toggle_budget_starved",
            fr="mute_toggle_budget_starved",
            remaining_budget_s=round(_rem_toggle_stage, 4),
            required_toggle_budget_s=round(_req_toggle_floor, 4),
            phase="post_sheet_pre_toggle",
            posts_visible=posts_v,
            stories_visible=stories_v,
        )
    if _toggle_starved:
        log(
            "info",
            "mute_engine_v2_toggle_stage_floor_bypassed_after_sheet_visible",
            visual_candidate_id=vcid,
            source_profile_username=src,
            remaining_budget_s=round(_rem_toggle_stage, 4),
            required_toggle_budget_s=round(_req_toggle_floor, 4),
            posts_visible=posts_v,
            stories_visible=stories_v,
            reason="labels_visible_try_compact_axis_sequence",
        )
    try:
        log(
            "info",
            "mute_engine_v2_toggle_stage_entered",
            visual_candidate_id=vcid,
            source_profile_username=src,
            remaining_budget_s=round(_rem_toggle_stage, 4),
            required_toggle_budget_s=round(float(toggle_required_budget_s), 4),
            reserved_toggle_budget_s=float(MIN_MUTE_TOGGLE_STAGE_BUDGET_S),
        )
    except Exception:
        pass

    posts_labels = ("Posts", "Publications")
    stories_labels = ("Stories", "Historias", "Storie")

    posts_ok = not want_posts
    stories_ok = not want_stories
    posts_tapped = False
    stories_tapped = False
    tapped_p = False
    already_p = False
    rsn_p = "skipped"
    tapped_s = False
    already_s = False
    rsn_s = "skipped"
    t_toggle_stage = time.perf_counter()
    toggle_stage_deadline = t_toggle_stage + float(_MUTE_V2_TOGGLE_STAGE_WALL_CAP_S)
    _axes_wanted = int(bool(want_posts)) + int(bool(want_stories))
    _axis_budget_default_s = (
        float(_MUTE_V2_TOGGLE_STAGE_WALL_CAP_S) / float(max(1, _axes_wanted))
    )
    posts_budget_s = max(float(_MUTE_V2_PER_AXIS_TOGGLE_MIN_S), _axis_budget_default_s)
    stories_budget_s = max(float(_MUTE_V2_PER_AXIS_TOGGLE_MIN_S), _axis_budget_default_s)
    timings["posts_budget_s"] = round(float(posts_budget_s), 4) if want_posts else 0.0
    timings["stories_budget_s"] = round(float(stories_budget_s), 4) if want_stories else 0.0
    timings["total_mute_budget_s"] = round(float(_MUTE_V2_TOGGLE_STAGE_WALL_CAP_S), 4)
    posts_axis_reason = (
        "pending" if want_posts else _mute_engine_v2_axis_reason("posts", "config_disabled")
    )
    stories_axis_reason = (
        "pending" if want_stories else _mute_engine_v2_axis_reason("stories", "config_disabled")
    )

    def _axis_log_base(axis: str, axis_budget_s: float, axis_t0: float) -> dict[str, Any]:
        return {
            "account_id": log_account_id,
            "run_id": log_run_id,
            "target_username": str(follower_username or "").strip(),
            "visual_candidate_id": vcid,
            "source_profile_username": src,
            "axis": axis,
            "axis_budget_s": round(float(axis_budget_s), 4),
            "elapsed_s": round(max(0.0, time.perf_counter() - axis_t0), 4),
        }

    def _emit_axis_skipped(
        axis: str,
        *,
        axis_budget_s: float,
        reason: str,
        toggle_seen: bool = False,
        verified: bool = False,
        axis_t0: float | None = None,
    ) -> None:
        _t = axis_t0 if axis_t0 is not None else time.perf_counter()
        log(
            "info",
            "post_follow_mute_axis_skipped",
            **_axis_log_base(axis, axis_budget_s, _t),
            toggle_seen=bool(toggle_seen),
            toggle_tapped=False,
            verified=bool(verified),
            reason=reason,
        )

    def _emit_final_mute_state(reason: str) -> None:
        log(
            "info",
            "post_follow_mute_final_state",
            account_id=log_account_id,
            run_id=log_run_id,
            target_username=str(follower_username or "").strip(),
            visual_candidate_id=vcid,
            source_profile_username=src,
            muted_posts=bool(posts_ok),
            muted_stories=bool(stories_ok),
            mute_posts_attempted=bool(posts_tapped),
            mute_stories_attempted=bool(stories_tapped),
            posts_axis_reason=posts_axis_reason,
            stories_axis_reason=stories_axis_reason,
            reason=reason,
        )

    if not want_posts:
        _emit_axis_skipped(
            "posts",
            axis_budget_s=0.0,
            reason=posts_axis_reason,
            toggle_seen=bool(posts_v),
            verified=True,
        )
    if not want_stories:
        _emit_axis_skipped(
            "stories",
            axis_budget_s=0.0,
            reason=stories_axis_reason,
            toggle_seen=bool(stories_v),
            verified=True,
        )

    # Posts before Stories when both required; per-axis wall slice so neither axis starves the other.
    _axes_left = _axes_wanted

    def _run_axis_with_deadline(
        axis: str,
        labels: tuple[str, ...],
        *,
        want_axis: bool,
        ok_ref: list[bool],
        tapped_ref: list[bool],
        already_ref: list[bool],
        rsn_ref: list[str],
        timing_key: str,
        started_event: str,
        completed_event: str,
    ) -> None:
        nonlocal _axes_left, posts_axis_reason, stories_axis_reason
        if not want_axis:
            return
        axis_deadline = _mute_engine_v2_toggle_stage_axis_deadline(
            toggle_stage_deadline,
            axes_remaining=max(1, _axes_left),
            t_all=None,
        )
        _axes_left = max(0, _axes_left - 1)
        axis_budget_s = posts_budget_s if axis == "posts" else stories_budget_s
        axis_t0 = time.perf_counter()
        toggle_seen = bool(posts_v) if axis == "posts" else bool(stories_v)
        observed_state = "posts_toggle_observed" if axis == "posts" else "stories_toggle_observed"
        completed_state = (
            "posts_toggle_applied_or_already_ok"
            if axis == "posts"
            else "stories_toggle_applied_or_already_ok"
        )
        if not toggle_seen:
            reason = _mute_engine_v2_axis_reason(axis, "toggle_label_not_found")
            if axis == "posts":
                posts_axis_reason = reason
            else:
                stories_axis_reason = reason
            rsn_ref[0] = "toggle_label_not_found"
            _emit_axis_skipped(
                axis,
                axis_budget_s=axis_budget_s,
                reason=reason,
                toggle_seen=False,
                verified=False,
                axis_t0=axis_t0,
            )
            timings[timing_key] = round((time.perf_counter() - axis_t0) * 1000.0, 2)
            return
        log(
            "info",
            "post_follow_mute_state_entered",
            account_id=log_account_id,
            run_id=log_run_id,
            target_username=str(follower_username or "").strip(),
            visual_candidate_id=vcid,
            source_profile_username=src,
            state=observed_state,
            axis=axis,
            axis_budget_s=round(float(axis_budget_s), 4),
            toggle_seen=True,
            reason="toggle_label_observed",
        )
        try:
            log(
                "info",
                started_event,
                visual_candidate_id=vcid,
                source_profile_username=src,
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
                axis_deadline_in_s=round(
                    max(0.0, axis_deadline - time.perf_counter()), 4
                ),
            )
            log(
                "info",
                "post_follow_mute_axis_started",
                **_axis_log_base(axis, axis_budget_s, axis_t0),
                toggle_seen=True,
                toggle_tapped=False,
                verified=False,
                reason="axis_started",
            )
        except Exception:
            pass
        axis_ok, tap_att, already_on, raw_rsn, elapsed_ms = _mute_engine_v2_compact_axis_toggle(
            d,
            axis=axis,
            labels=labels,
            ww=ww,
            t0=axis_t0,
            toggle_stage_deadline=axis_deadline,
            visual_candidate_id=vcid,
            source_profile_username=src,
            axis_budget_s=axis_budget_s,
        )
        ok_ref[0] = bool(axis_ok)
        tapped_ref[0] = bool(tap_att)
        already_ref[0] = bool(already_on)
        rsn_ref[0] = str(raw_rsn or "")
        axis_reason = _mute_engine_v2_axis_reason(axis, raw_rsn, already_on=bool(already_on))
        if axis == "posts":
            posts_axis_reason = axis_reason
        else:
            stories_axis_reason = axis_reason
        timings[timing_key] = float(elapsed_ms)
        verified = bool(axis_ok)
        log(
            "info",
            "mute_axis_result",
            visual_candidate_id=vcid,
            source_profile_username=src,
            axis=axis,
            done=bool(axis_ok),
            tap_attempted=bool(tap_att),
            already_on=bool(already_on),
            verified=verified,
            reason=_mute_engine_v2_map_toggle_rsn(raw_rsn),
            raw_reason=raw_rsn,
            elapsed_ms=elapsed_ms,
            remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
        )
        event_name = (
            "post_follow_mute_axis_completed"
            if bool(axis_ok)
            else "post_follow_mute_axis_skipped"
        )
        log(
            "info" if bool(axis_ok) else "warning",
            event_name,
            **_axis_log_base(axis, axis_budget_s, axis_t0),
            toggle_seen=True,
            toggle_tapped=bool(tap_att),
            verified=verified,
            reason=axis_reason,
            raw_reason=str(raw_rsn or ""),
        )
        if bool(axis_ok):
            log(
                "info",
                "post_follow_mute_state_entered",
                account_id=log_account_id,
                run_id=log_run_id,
                target_username=str(follower_username or "").strip(),
                visual_candidate_id=vcid,
                source_profile_username=src,
                state=completed_state,
                axis=axis,
                axis_budget_s=round(float(axis_budget_s), 4),
                toggle_seen=True,
                toggle_tapped=bool(tap_att),
                verified=True,
                reason=axis_reason,
            )
        try:
            log(
                "info",
                completed_event,
                visual_candidate_id=vcid,
                source_profile_username=src,
                axis_ok=bool(axis_ok),
                toggle_raw_reason=raw_rsn,
                tap_attempted=bool(tap_att),
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
            )
        except Exception:
            pass

    _posts_ok_box = [posts_ok]
    _posts_tapped_box = [False]
    _already_p_box = [already_p]
    _rsn_p_box = [rsn_p]
    _run_axis_with_deadline(
        "posts",
        posts_labels,
        want_axis=want_posts,
        ok_ref=_posts_ok_box,
        tapped_ref=_posts_tapped_box,
        already_ref=_already_p_box,
        rsn_ref=_rsn_p_box,
        timing_key="toggle_posts_ms",
        started_event="mute_engine_v2_posts_toggle_started",
        completed_event="mute_engine_v2_posts_toggle_completed",
    )
    posts_ok = _posts_ok_box[0]
    posts_tapped = bool(_posts_tapped_box[0])
    already_p = _already_p_box[0]
    rsn_p = _rsn_p_box[0]
    tapped_p = bool(posts_tapped)

    _stories_ok_box = [stories_ok]
    _stories_tapped_box = [False]
    _already_s_box = [already_s]
    _rsn_s_box = [rsn_s]
    _run_axis_with_deadline(
        "stories",
        stories_labels,
        want_axis=want_stories,
        ok_ref=_stories_ok_box,
        tapped_ref=_stories_tapped_box,
        already_ref=_already_s_box,
        rsn_ref=_rsn_s_box,
        timing_key="toggle_stories_ms",
        started_event="mute_engine_v2_stories_toggle_started",
        completed_event="mute_engine_v2_stories_toggle_completed",
    )
    stories_ok = _stories_ok_box[0]
    stories_tapped = bool(_stories_tapped_box[0])
    already_s = _already_s_box[0]
    rsn_s = _rsn_s_box[0]
    tapped_s = bool(stories_tapped)

    timings["mute_total_ms"] = round((time.perf_counter() - t_all) * 1000, 2)

    if want_posts and want_stories:
        if posts_ok and stories_ok:
            _emit_mute_perf_summary(
                result="success",
                skip_reason="",
                confirmed_sheet_level="mute_toggles",
            )
            _emit_final_mute_state("final_mute_state_verified")
            log(
                "info",
                "mute_engine_v2_success",
                visual_candidate_id=vcid,
                source_profile_username=src,
                timings_ms=dict(timings),
            )
            log(
                "info",
                "post_follow_mute_completed",
                visual_candidate_id=vcid,
                source_profile_username=src,
                posts_done=True,
                stories_done=True,
                reason="success",
                timings_ms=dict(timings),
            )
            log(
                "info",
                "mute_completed_all_axes",
                visual_candidate_id=vcid,
                source_profile_username=src,
                posts_done=True,
                stories_done=True,
                sheet_dismiss_ok=bool(timings.get("mute_sheet_dismiss_ok")),
                sheet_dismiss_ms=timings.get("sheet_dismiss_ms"),
            )
            return {
                "ok": True,
                "partial": False,
                "skipped": False,
                "failure_reason": None,
                "outcome": "success",
                "abort_reason": None,
                "mute_engine_v2": True,
                "posts_verified": True,
                "stories_verified": True,
                "posts_tapped": posts_tapped,
                "stories_tapped": stories_tapped,
                "muted_posts": True,
                "muted_stories": True,
                "mute_posts_attempted": bool(posts_tapped),
                "mute_stories_attempted": bool(stories_tapped),
                "posts_axis_reason": posts_axis_reason,
                "stories_axis_reason": stories_axis_reason,
                "mute_row_label": "",
                "timings_ms": dict(timings),
            }
        if posts_ok or stories_ok:
            missing_axis = _mute_engine_v2_missing_axis(
                want_posts=want_posts,
                want_stories=want_stories,
                posts_ok=bool(posts_ok),
                stories_ok=bool(stories_ok),
            )
            _emit_mute_perf_summary(
                result="partial_success",
                skip_reason="mute_partial_one_toggle",
            )
            _emit_final_mute_state("final_mute_state_verified")
            log(
                "warning",
                "mute_engine_v2_partial_success",
                visual_candidate_id=vcid,
                source_profile_username=src,
                posts_verified=bool(posts_ok),
                stories_verified=bool(stories_ok),
                timings_ms=dict(timings),
            )
            log(
                "warning",
                "post_follow_mute_partial",
                visual_candidate_id=vcid,
                source_profile_username=src,
                posts_done=bool(posts_ok),
                stories_done=bool(stories_ok),
                missing_axis=missing_axis,
                reason="mute_partial_one_toggle",
                posts_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_p),
                stories_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_s),
                timings_ms=dict(timings),
            )
            log(
                "warning",
                "mute_partial_missing_axis",
                visual_candidate_id=vcid,
                source_profile_username=src,
                missing_axis=missing_axis,
                posts_done=bool(posts_ok),
                stories_done=bool(stories_ok),
                posts_tap_attempted=bool(posts_tapped),
                stories_tap_attempted=bool(stories_tapped),
                posts_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_p),
                stories_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_s),
                remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4),
                sheet_dismiss_ok=bool(timings.get("mute_sheet_dismiss_ok")),
                sheet_dismiss_ms=timings.get("mute_sheet_dismiss_ms"),
            )
            return {
                "ok": True,
                "partial": True,
                "skipped": False,
                "failure_reason": "mute_partial_one_toggle",
                "outcome": "partial_success",
                "abort_reason": None,
                "mute_engine_v2": True,
                "posts_verified": bool(posts_ok),
                "stories_verified": bool(stories_ok),
                "missing_axis": missing_axis,
                "posts_tapped": posts_tapped,
                "stories_tapped": stories_tapped,
                "muted_posts": bool(posts_ok),
                "muted_stories": bool(stories_ok),
                "mute_posts_attempted": bool(posts_tapped),
                "mute_stories_attempted": bool(stories_tapped),
                "posts_axis_reason": posts_axis_reason,
                "stories_axis_reason": stories_axis_reason,
                "timings_ms": dict(timings),
            }
        _ab_reason, _fail_reason = _mute_engine_v2_classify_both_toggles_failure(
            want_posts=want_posts,
            want_stories=want_stories,
            posts_ok=posts_ok,
            stories_ok=stories_ok,
            tapped_p=tapped_p,
            tapped_s=tapped_s,
            already_p=already_p,
            already_s=already_s,
            rsn_p=rsn_p,
            rsn_s=rsn_s,
        )
        _emit_final_mute_state("final_mute_state_verified")
        return _abort(
            _ab_reason,
            fr=_fail_reason,
            posts_verified=False,
            stories_verified=False,
            posts_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_p),
            stories_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_s),
            posts_toggle_raw_reason=rsn_p,
            stories_toggle_raw_reason=rsn_s,
            posts_tap_attempted=bool(posts_tapped),
            stories_tap_attempted=bool(stories_tapped),
            remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4)
            if _ab_reason == "mute_toggle_budget_starved"
            else None,
            required_toggle_budget_s=round(float(toggle_required_budget_s), 4)
            if _ab_reason == "mute_toggle_budget_starved"
            else None,
            phase="toggle_execution"
            if _ab_reason == "mute_toggle_budget_starved"
            else None,
            posts_visible=posts_v if _ab_reason == "mute_toggle_budget_starved" else None,
            stories_visible=stories_v if _ab_reason == "mute_toggle_budget_starved" else None,
        )

    # only one of want_posts / want_stories
    if (want_posts and posts_ok) or (want_stories and stories_ok):
        _emit_mute_perf_summary(
            result="success",
            skip_reason="",
            confirmed_sheet_level="mute_toggles",
        )
        _emit_final_mute_state("final_mute_state_verified")
        log(
            "info",
            "mute_engine_v2_success",
            visual_candidate_id=vcid,
            source_profile_username=src,
            timings_ms=dict(timings),
        )
        log(
            "info",
            "post_follow_mute_completed",
            visual_candidate_id=vcid,
            source_profile_username=src,
            posts_done=bool(posts_ok),
            stories_done=bool(stories_ok),
            reason="success",
            timings_ms=dict(timings),
        )
        log(
            "info",
            "mute_completed_all_axes",
            visual_candidate_id=vcid,
            source_profile_username=src,
            posts_done=bool(posts_ok),
            stories_done=bool(stories_ok),
            sheet_dismiss_ok=bool(timings.get("mute_sheet_dismiss_ok")),
            sheet_dismiss_ms=timings.get("sheet_dismiss_ms"),
        )
        return {
            "ok": True,
            "partial": False,
            "skipped": False,
            "failure_reason": None,
            "outcome": "success",
            "abort_reason": None,
            "mute_engine_v2": True,
            "posts_verified": bool(posts_ok),
            "stories_verified": bool(stories_ok),
            "posts_tapped": posts_tapped,
            "stories_tapped": stories_tapped,
            "muted_posts": bool(posts_ok),
            "muted_stories": bool(stories_ok),
            "mute_posts_attempted": bool(posts_tapped),
            "mute_stories_attempted": bool(stories_tapped),
            "posts_axis_reason": posts_axis_reason,
            "stories_axis_reason": stories_axis_reason,
            "timings_ms": dict(timings),
        }
    _ab2, _fr2 = _mute_engine_v2_classify_single_toggle_failure(
        want_posts=want_posts,
        want_stories=want_stories,
        posts_ok=posts_ok,
        stories_ok=stories_ok,
        tapped_p=tapped_p,
        tapped_s=tapped_s,
        already_p=already_p,
        already_s=already_s,
        rsn_p=rsn_p,
        rsn_s=rsn_s,
    )
    _emit_final_mute_state("final_mute_state_verified")
    return _abort(
        _ab2,
        fr=_fr2,
        posts_verified=bool(posts_ok),
        stories_verified=bool(stories_ok),
        posts_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_p),
        stories_toggle_reason=_mute_engine_v2_map_toggle_rsn(rsn_s),
        posts_toggle_raw_reason=rsn_p,
        stories_toggle_raw_reason=rsn_s,
        posts_tap_attempted=bool(posts_tapped),
        stories_tap_attempted=bool(stories_tapped),
        remaining_budget_s=round(_mute_engine_v2_remaining_s(t_all), 4)
        if _ab2 == "mute_toggle_budget_starved"
        else None,
        required_toggle_budget_s=round(float(toggle_required_budget_s), 4)
        if _ab2 == "mute_toggle_budget_starved"
        else None,
        phase="toggle_execution" if _ab2 == "mute_toggle_budget_starved" else None,
        posts_visible=posts_v if _ab2 == "mute_toggle_budget_starved" else None,
        stories_visible=stories_v if _ab2 == "mute_toggle_budget_starved" else None,
    )


def _post_follow_post_likes_count_from_range(spec: str) -> int:
    """Parse likes count range (e.g. '1-1', '2-3') and return one random target in band."""
    raw = str(spec or "1-1").strip()
    lo, hi = 1, 1
    if "-" in raw:
        parts = raw.split("-", 1)
        try:
            lo = max(0, int(parts[0].strip()))
            hi = max(lo, int(parts[1].strip()))
        except (TypeError, ValueError):
            lo, hi = 1, 1
    else:
        try:
            lo = hi = max(0, int(raw))
        except (TypeError, ValueError):
            lo = hi = 1
    if hi <= lo:
        return lo
    return int(random.randint(lo, hi))


def _ui_story_or_highlight_viewer_detected(d: u2.Device) -> tuple[bool, str]:
    """Best-effort guard for story/highlight viewers after a post-open tap."""
    probes = (
        ("textMatches", {"textMatches": r"(?i)^\s*(reply|send message|message)\s*$"}, 0.08),
        (
            "descriptionMatches",
            {"descriptionMatches": r"(?i).*(reply|send message|story controls|story viewer).*"},
            0.08,
        ),
        (
            "textMatches",
            {"textMatches": r"(?i).*(story|highlight).*"},
            0.04,
        ),
        (
            "descriptionMatches",
            {"descriptionMatches": r"(?i).*(story|highlight).*"},
            0.04,
        ),
    )
    for selector_kind, selector_kwargs, timeout_s in probes:
        try:
            if d(**selector_kwargs).exists(timeout=float(timeout_s)) is True:
                return True, f"{selector_kind}:story_highlight_viewer"
        except Exception:
            continue
    return False, ""


def _post_open_snapshot_audit_signals(
    d: u2.Device,
    *,
    snapshot_xml: str,
    proof_method: str,
) -> dict[str, Any]:
    """Resolve post-open safety signals from one fresh hierarchy snapshot."""
    try:
        root = ET.fromstring(str(snapshot_xml or ""))
    except ET.ParseError:
        return {"ok": False, "reason": "snapshot_xml_invalid"}

    story_detected = False
    story_method = "snapshot_clear"
    facebook_detected = False
    facebook_method = "snapshot_clear"
    for el in root.iter():
        text_raw = str(el.attrib.get("text") or "").strip().lower()
        desc_raw = str(el.attrib.get("content-desc") or "").strip().lower()
        values = (text_raw, desc_raw)
        if any(
            value in ("reply", "send message", "message")
            or "story controls" in value
            or "story viewer" in value
            or "highlight viewer" in value
            for value in values
            if value
        ):
            story_detected = True
            story_method = "snapshot_story_highlight_marker"
        if any(
            marker in value
            for value in values
            for marker in _FACEBOOK_SHARED_CONTENT_MARKERS
            if value
        ):
            facebook_detected = True
            facebook_method = "snapshot_facebook_shared_banner"

    semantic_nodes = _hierarchy_collect_like_semantic_nodes(snapshot_xml)
    trusted_liked = any(_ui_proof_trusted_action_button_liked(node, d) for node in semantic_nodes)
    trusted_not_liked = any(
        _ui_proof_trusted_action_button_not_liked(node, d) for node in semantic_nodes
    )
    proof_is_not_liked = proof_method.endswith(
        _TRUSTED_POST_FOLLOW_OPEN_NOT_LIKED_RID_SUFFIX
    ) or proof_method in _TRUSTED_POST_FOLLOW_OPEN_NOT_LIKED_EXACT_SIGNALS
    if proof_is_not_liked and trusted_liked:
        return {
            "ok": False,
            "reason": "snapshot_like_state_contradiction",
            "conflicting_signals": ["open_proof_not_liked", "snapshot_liked"],
        }
    if not proof_is_not_liked and not trusted_not_liked:
        return {"ok": False, "reason": "snapshot_like_signal_ambiguous"}

    return {
        "ok": True,
        "story_detected": story_detected,
        "story_method": story_method,
        "facebook_detected": facebook_detected,
        "facebook_method": facebook_method,
        "like_surface_ok": True,
        "like_surface_method": f"reused:{proof_method}",
        "like_signal": "not_liked" if proof_is_not_liked else "like_action_available",
        "story_signal": "detected" if story_detected else "clear",
        "facebook_signal": "detected" if facebook_detected else "clear",
    }


def _post_open_surface_audits(
    d: u2.Device,
    *,
    pkg: str,
    source_profile_username: str,
    follower_username: str,
) -> dict[str, Any]:
    """Reuse fresh open evidence or run the existing post-open safety probes."""
    t0 = time.perf_counter()
    ok, stash, proof_age_ms, reject_reason = _validate_post_follow_open_like_proof_stash(
        source_profile_username=source_profile_username,
        expected_follower_username=follower_username,
    )
    snapshot_age_ms = proof_age_ms
    snapshot_signals: dict[str, Any] = {}
    if ok and stash:
        captured_at = float(stash.get("post_open_snapshot_captured_at_monotonic") or 0.0)
        snapshot_age_ms = round((time.perf_counter() - captured_at) * 1000.0, 2)
        if captured_at <= 0:
            reject_reason = "snapshot_timestamp_missing"
        elif snapshot_age_ms > float(_POST_FOLLOW_OPEN_LIKE_PROOF_TTL_MS):
            reject_reason = "snapshot_stale"
        else:
            snapshot_signals = _post_open_snapshot_audit_signals(
                d,
                snapshot_xml=str(stash.get("post_open_snapshot_xml") or ""),
                proof_method=str(stash.get("proof_method") or ""),
            )
            if not bool(snapshot_signals.get("ok")):
                reject_reason = str(snapshot_signals.get("reason") or "snapshot_ambiguous")

    if ok and stash and bool(snapshot_signals.get("ok")):
        log(
            "info",
            "post_open_evidence_reused",
            viewer_detect_path=str(stash.get("viewer_detect_path") or ""),
            snapshot_age_ms=snapshot_age_ms,
            like_signal=snapshot_signals.get("like_signal"),
            story_signal=snapshot_signals.get("story_signal"),
            facebook_signal=snapshot_signals.get("facebook_signal"),
        )
        out = {
            **snapshot_signals,
            "reused_snapshot": True,
            "extra_dump_count": 0,
            "snapshot_age_ms": snapshot_age_ms,
        }
    else:
        log(
            "info",
            "post_open_evidence_reprobe_required",
            reason=reject_reason or "open_evidence_unavailable",
            snapshot_age_ms=snapshot_age_ms,
            conflicting_signals=snapshot_signals.get("conflicting_signals") or [],
        )
        story_detected, story_method = _ui_story_or_highlight_viewer_detected(d)
        like_surface_ok, like_surface_method = _ui_post_viewer_like_action_bar_exploitable(
            d,
            pkg=pkg,
        )
        fresh_hierarchy = _dump_post_viewer_hierarchy(d)
        facebook_detected, facebook_method = (
            _ui_post_viewer_facebook_shared_content_detected(
                d,
                hierarchy=fresh_hierarchy,
            )
        )
        out = {
            "story_detected": story_detected,
            "story_method": story_method,
            "facebook_detected": facebook_detected,
            "facebook_method": facebook_method,
            "like_surface_ok": like_surface_ok,
            "like_surface_method": like_surface_method,
            "reused_snapshot": False,
            "extra_dump_count": 1,
            "snapshot_age_ms": snapshot_age_ms,
        }

    out["elapsed_ms"] = round((time.perf_counter() - t0) * 1000.0, 2)
    log(
        "info",
        "post_open_audits_completed",
        reused_snapshot=bool(out.get("reused_snapshot")),
        extra_dump_count=int(out.get("extra_dump_count") or 0),
        elapsed_ms=out["elapsed_ms"],
    )
    return out


